CREATE FUNCTION active_community_effect(expected_community_id text, expected_user_id text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM communities AS community
      JOIN community_memberships AS membership
        ON membership.community_id = community.community_id
       AND membership.user_id = expected_user_id
       AND membership.status = 'member'
     WHERE community.community_id = expected_community_id
       AND community.status = 'active'
  )
$$;

CREATE FUNCTION active_owned_community_persona(expected_account_id text, expected_persona_id text, expected_community_id text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM personas AS persona
      JOIN persona_community_bindings AS binding
        ON binding.persona_id = persona.persona_id
       AND binding.community_id = expected_community_id
     WHERE persona.account_id = expected_account_id
       AND persona.persona_id = expected_persona_id
       AND persona.status = 'active'
  )
$$;

