    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $_$
DECLARE
  session hns_root_import_sessions%ROWTYPE;
  ownership_result community_creation_ceremony_results%ROWTYPE;
  job hns_authority_provision_jobs%ROWTYPE;
  database_now TIMESTAMPTZ := clock_timestamp();
BEGIN
  SELECT * INTO session
    FROM hns_root_import_sessions
   WHERE actor_id = input_actor_id
     AND creation_intent_id = input_creation_intent_id
     AND hns_root_import_sessions.root_import_session_id = input_root_import_session_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'not_found'::TEXT, NULL::TEXT, NULL::BIGINT;
    RETURN;
  END IF;
  IF session.status = 'provisioning' THEN
    SELECT * INTO job
      FROM hns_authority_provision_jobs
     WHERE provision_job_id = session.provision_job_id
     FOR SHARE;
    IF session.provision_idempotency_key = input_idempotency_key
      AND session.provision_poll_request_sha256 = input_poll_request_sha256
      AND session.ownership_result_sha256 = input_ownership_result_sha256
      AND session.provision_job_id = input_provision_job_id
      AND job.request_bytes = input_provision_request_bytes
      AND job.request_sha256 = input_provision_request_sha256
    THEN
      RETURN QUERY SELECT 'replayed'::TEXT, session.root_import_session_id, session.revision;
    ELSE
      RETURN QUERY SELECT 'conflict'::TEXT, session.root_import_session_id, session.revision;
    END IF;
    RETURN;
  END IF;
  IF session.status <> 'awaiting_ownership'
    OR session.revision <> input_expected_revision
    OR session.expires_at <= database_now
    OR session.provision_job_id IS DISTINCT FROM input_provision_job_id
    OR input_poll_request_sha256 !~ '^[0-9a-f]{64}$'
    OR input_ownership_result_sha256 !~ '^[0-9a-f]{64}$'
    OR input_provision_request_sha256 !~ '^[0-9a-f]{64}$'
    OR encode(sha256(input_provision_request_bytes), 'hex')
       <> input_provision_request_sha256
  THEN
    RETURN QUERY SELECT 'conflict'::TEXT, session.root_import_session_id, session.revision;
    RETURN;
  END IF;
  SELECT * INTO ownership_result
    FROM community_creation_ceremony_results
   WHERE ceremony_intent_id = session.ceremony_intent_id
     AND namespace_session_id = session.namespace_session_id
   FOR SHARE;
  IF NOT FOUND
    OR ownership_result.outcome_status <> 'satisfied'
    OR ownership_result.result_hash <> input_ownership_result_sha256
  THEN
    RETURN QUERY SELECT 'conflict'::TEXT, session.root_import_session_id, session.revision;
    RETURN;
  END IF;
  -- Unverified sessions deliberately do not reserve a root. Serialize the
  -- proof-to-provision transition so only a verified owner can claim it.
  PERFORM pg_advisory_xact_lock(hashtextextended('hns-root-import:' || session.root_label, 0));
  UPDATE hns_authority_provision_jobs AS stale_job
     SET state = 'failed', leased_by = NULL, lease_expires_at = NULL,
         failure_code = 'session_expired', completed_at = database_now,
         updated_at = database_now
    FROM hns_root_import_sessions AS stale_session
   WHERE stale_session.root_label = session.root_label
     AND stale_session.root_import_session_id <> session.root_import_session_id
     AND stale_session.status = 'provisioning'
     AND stale_session.expires_at <= database_now
     AND stale_job.root_import_session_id = stale_session.root_import_session_id
     AND (
       stale_job.state = 'queued'
       OR (stale_job.state = 'leased' AND stale_job.lease_expires_at <= database_now)
     );
  UPDATE hns_root_import_observation_jobs AS stale_job
     SET state = 'failed', leased_by = NULL, lease_expires_at = NULL,
         failure_code = 'session_expired', completed_at = database_now,
         updated_at = database_now
    FROM hns_root_import_sessions AS stale_session
   WHERE stale_session.root_label = session.root_label
     AND stale_session.root_import_session_id <> session.root_import_session_id
     AND stale_session.status = 'observing'
     AND stale_session.expires_at <= database_now
     AND stale_job.root_import_session_id = stale_session.root_import_session_id
     AND (
       stale_job.state = 'queued'
       OR (stale_job.state = 'leased' AND stale_job.lease_expires_at <= database_now)
     );
  UPDATE hns_root_import_sessions AS stale_session
     SET status = 'expired', revision = stale_session.revision + 1,
         updated_at = database_now
   WHERE stale_session.root_label = session.root_label
     AND stale_session.root_import_session_id <> session.root_import_session_id
     AND stale_session.expires_at <= database_now
     AND (
       stale_session.status IN ('awaiting_owner_update', 'ready')
       OR (
         stale_session.status = 'provisioning'
         AND EXISTS (
           SELECT 1 FROM hns_authority_provision_jobs AS stale_job
            WHERE stale_job.root_import_session_id = stale_session.root_import_session_id
              AND stale_job.state = 'failed'
              AND stale_job.failure_code = 'session_expired'
         )
       )
       OR (
         stale_session.status = 'observing'
         AND EXISTS (
           SELECT 1 FROM hns_root_import_observation_jobs AS stale_job
            WHERE stale_job.root_import_session_id = stale_session.root_import_session_id
              AND stale_job.state = 'failed'
              AND stale_job.failure_code = 'session_expired'
         )
       )
     );
  IF EXISTS (
       SELECT 1
         FROM hns_root_import_sessions AS other
        WHERE other.root_label = session.root_label
          AND other.root_import_session_id <> session.root_import_session_id
          AND other.status IN (
            'provisioning', 'awaiting_owner_update', 'observing', 'ready', 'activated'
          )
     )
    OR EXISTS (
       SELECT 1 FROM hns_dns_zone_activation_current
        WHERE canonical_root = session.root_label
     )
    OR EXISTS (
       SELECT 1 FROM community_canonical_route_bindings
        WHERE family = 'hns' AND root_label = session.root_label
          AND route_lifecycle_status = 'active'
     )
    OR EXISTS (
       SELECT 1 FROM community_handle_sale_namespace_activation_current
        WHERE family = 'hns' AND canonical_root = session.root_label
     )
    OR EXISTS (
       SELECT 1
         FROM operator_managed_root_registry_current AS current_registry
        WHERE operator_managed_registry_has_active_root(
          current_registry.registry_reference,
          current_registry.registry_version,
          current_registry.registry_digest,
          session.root_label
        )
     )
  THEN
    RETURN QUERY SELECT 'conflict'::TEXT, session.root_import_session_id, session.revision;
    RETURN;
  END IF;
  INSERT INTO hns_authority_provision_jobs (
    provision_job_id, root_import_session_id, operation_kind,
    request_bytes, request_sha256, state
  ) VALUES (
    input_provision_job_id, session.root_import_session_id, 'provision_root_v1',
    input_provision_request_bytes, input_provision_request_sha256, 'queued'
  );
  UPDATE hns_root_import_sessions
     SET status = 'provisioning', revision = session.revision + 1,
         provision_idempotency_key = input_idempotency_key,
         provision_poll_request_sha256 = input_poll_request_sha256,
         ownership_result_sha256 = input_ownership_result_sha256,
         updated_at = database_now
   WHERE hns_root_import_sessions.root_import_session_id = session.root_import_session_id;
  RETURN QUERY SELECT 'provisioning'::TEXT, session.root_import_session_id, session.revision + 1;
END;
$_$;

CREATE FUNCTION begin_hns_root_import_provision_v2(input_actor_id text, input_creation_intent_id text, input_root_import_session_id text, input_expected_revision bigint, input_idempotency_key text, input_poll_request_sha256 text, input_authorization_kind text, input_authorization_sha256 text, input_name_proof_result_bytes bytea, input_name_proof_message_sha256 text, input_name_proof_signature_sha256 text, input_provision_job_id text, input_provision_request_bytes bytea, input_provision_request_sha256 text) RETURNS TABLE(outcome text, root_import_session_id text, session_revision bigint)
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $_$
DECLARE
  session hns_root_import_sessions%ROWTYPE;
  ownership_result community_creation_ceremony_results%ROWTYPE;
  proof hns_root_import_name_proof_observations%ROWTYPE;
  proof_document JSONB;
  job hns_authority_provision_jobs%ROWTYPE;
  database_now TIMESTAMPTZ := clock_timestamp();
BEGIN
  SELECT * INTO session
    FROM hns_root_import_sessions
   WHERE actor_id = input_actor_id
     AND creation_intent_id = input_creation_intent_id
     AND hns_root_import_sessions.root_import_session_id = input_root_import_session_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'not_found'::TEXT, NULL::TEXT, NULL::BIGINT;
    RETURN;
  END IF;
  IF session.status = 'provisioning' THEN
    SELECT * INTO job
      FROM hns_authority_provision_jobs
     WHERE provision_job_id = session.provision_job_id
     FOR SHARE;
    SELECT * INTO proof
      FROM hns_root_import_name_proof_observations
     WHERE hns_root_import_name_proof_observations.root_import_session_id =
           session.root_import_session_id
     FOR SHARE;
    IF session.provision_idempotency_key = input_idempotency_key
      AND session.provision_poll_request_sha256 = input_poll_request_sha256
      AND session.provision_authorization_kind = input_authorization_kind
      AND session.provision_authorization_sha256 = input_authorization_sha256
      AND session.provision_job_id = input_provision_job_id
      AND job.request_bytes = input_provision_request_bytes
      AND job.request_sha256 = input_provision_request_sha256
      AND (
        (
          input_authorization_kind = 'namespace_ownership'
          AND input_name_proof_result_bytes IS NULL
          AND input_name_proof_message_sha256 IS NULL
          AND input_name_proof_signature_sha256 IS NULL
        )
        OR (
          input_authorization_kind = 'hns_name_signature'
          AND proof.proof_result_sha256 = input_authorization_sha256
          AND proof.message_sha256 = input_name_proof_message_sha256
          AND proof.signature_sha256 = input_name_proof_signature_sha256
          AND proof.result_bytes = input_name_proof_result_bytes
        )
      )
    THEN
      RETURN QUERY SELECT 'replayed'::TEXT, session.root_import_session_id, session.revision;
    ELSE
      RETURN QUERY SELECT 'conflict'::TEXT, session.root_import_session_id, session.revision;
    END IF;
    RETURN;
  END IF;
  IF session.status <> 'awaiting_ownership'
    OR session.revision <> input_expected_revision
    OR session.expires_at <= database_now
    OR session.provision_job_id IS DISTINCT FROM input_provision_job_id
    OR input_poll_request_sha256 !~ '^[0-9a-f]{64}$'
    OR input_authorization_kind NOT IN ('namespace_ownership', 'hns_name_signature')
    OR input_authorization_sha256 !~ '^[0-9a-f]{64}$'
    OR input_provision_request_sha256 !~ '^[0-9a-f]{64}$'
    OR encode(sha256(input_provision_request_bytes), 'hex')
       <> input_provision_request_sha256
  THEN
    RETURN QUERY SELECT 'conflict'::TEXT, session.root_import_session_id, session.revision;
    RETURN;
  END IF;

  IF input_authorization_kind = 'namespace_ownership' THEN
    IF input_name_proof_result_bytes IS NOT NULL
      OR input_name_proof_message_sha256 IS NOT NULL
      OR input_name_proof_signature_sha256 IS NOT NULL
    THEN
      RETURN QUERY SELECT 'conflict'::TEXT, session.root_import_session_id, session.revision;
      RETURN;
    END IF;
    SELECT * INTO ownership_result
      FROM community_creation_ceremony_results
     WHERE ceremony_intent_id = session.ceremony_intent_id
       AND namespace_session_id = session.namespace_session_id
     FOR SHARE;
    IF NOT FOUND
      OR ownership_result.outcome_status <> 'satisfied'
      OR ownership_result.result_hash <> input_authorization_sha256
    THEN
      RETURN QUERY SELECT 'conflict'::TEXT, session.root_import_session_id, session.revision;
      RETURN;
    END IF;
  ELSE
    IF input_name_proof_result_bytes IS NULL
      OR octet_length(input_name_proof_result_bytes) NOT BETWEEN 1 AND 1024
      OR encode(sha256(input_name_proof_result_bytes), 'hex')
           <> input_authorization_sha256
      OR input_name_proof_message_sha256 !~ '^[0-9a-f]{64}$'
      OR input_name_proof_signature_sha256 !~ '^[0-9a-f]{64}$'
      OR NOT EXISTS (
        SELECT 1 FROM namespace_ownership_sessions AS ownership_session
         WHERE ownership_session.namespace_session_id = session.namespace_session_id
           AND ownership_session.actor_id = session.actor_id
           AND ownership_session.status = 'pending'
           AND ownership_session.expires_at > database_now
      )
    THEN
      RETURN QUERY SELECT 'conflict'::TEXT, session.root_import_session_id, session.revision;
      RETURN;
    END IF;
    BEGIN
      proof_document := convert_from(input_name_proof_result_bytes, 'UTF8')::JSONB;
    EXCEPTION WHEN OTHERS THEN
      RETURN QUERY SELECT 'conflict'::TEXT, session.root_import_session_id, session.revision;
      RETURN;
    END;
    IF jsonb_typeof(proof_document) <> 'object' THEN
      RETURN QUERY SELECT 'conflict'::TEXT, session.root_import_session_id, session.revision;
      RETURN;
    END IF;
    IF (SELECT count(*) FROM jsonb_object_keys(proof_document)) <> 6
      OR proof_document ->> 'version' <> 'pirate-hns-root-import-name-proof-result-v1'
      OR proof_document ->> 'root_label' <> session.root_label
      OR proof_document ->> 'message_sha256' <> input_name_proof_message_sha256
      OR proof_document ->> 'signature_sha256' <> input_name_proof_signature_sha256
      OR proof_document -> 'safe' <> 'true'::JSONB
      OR proof_document -> 'verified' <> 'true'::JSONB
    THEN
      RETURN QUERY SELECT 'conflict'::TEXT, session.root_import_session_id, session.revision;
      RETURN;
    END IF;
  END IF;

  -- Root reservation starts only after either durable namespace ownership or
  -- an exact safe name-signature result has been verified.
  PERFORM pg_advisory_xact_lock(hashtextextended('hns-root-import:' || session.root_label, 0));
  UPDATE hns_authority_provision_jobs AS stale_job
     SET state = 'failed', leased_by = NULL, lease_expires_at = NULL,
         failure_code = 'session_expired', completed_at = database_now,
         updated_at = database_now
    FROM hns_root_import_sessions AS stale_session
   WHERE stale_session.root_label = session.root_label
     AND stale_session.root_import_session_id <> session.root_import_session_id
     AND stale_session.status = 'provisioning'
     AND stale_session.expires_at <= database_now
     AND stale_job.root_import_session_id = stale_session.root_import_session_id
     AND (
       stale_job.state = 'queued'
       OR (stale_job.state = 'leased' AND stale_job.lease_expires_at <= database_now)
     );
  UPDATE hns_root_import_observation_jobs AS stale_job
     SET state = 'failed', leased_by = NULL, lease_expires_at = NULL,
         failure_code = 'session_expired', completed_at = database_now,
         updated_at = database_now
    FROM hns_root_import_sessions AS stale_session
   WHERE stale_session.root_label = session.root_label
     AND stale_session.root_import_session_id <> session.root_import_session_id
     AND stale_session.status = 'observing'
     AND stale_session.expires_at <= database_now
     AND stale_job.root_import_session_id = stale_session.root_import_session_id
     AND (
       stale_job.state = 'queued'
       OR (stale_job.state = 'leased' AND stale_job.lease_expires_at <= database_now)
     );
  UPDATE hns_root_import_sessions AS stale_session
     SET status = 'expired', revision = stale_session.revision + 1,
         updated_at = database_now
   WHERE stale_session.root_label = session.root_label
     AND stale_session.root_import_session_id <> session.root_import_session_id
     AND stale_session.expires_at <= database_now
     AND (
       stale_session.status IN ('awaiting_owner_update', 'ready')
       OR (
         stale_session.status = 'provisioning'
         AND EXISTS (
           SELECT 1 FROM hns_authority_provision_jobs AS stale_job
            WHERE stale_job.root_import_session_id = stale_session.root_import_session_id
              AND stale_job.state = 'failed'
              AND stale_job.failure_code = 'session_expired'
         )
       )
       OR (
         stale_session.status = 'observing'
         AND EXISTS (
           SELECT 1 FROM hns_root_import_observation_jobs AS stale_job
            WHERE stale_job.root_import_session_id = stale_session.root_import_session_id
              AND stale_job.state = 'failed'
              AND stale_job.failure_code = 'session_expired'
         )
       )
     );
  IF EXISTS (
       SELECT 1
         FROM hns_root_import_sessions AS other
        WHERE other.root_label = session.root_label
          AND other.root_import_session_id <> session.root_import_session_id
          AND other.status IN (
            'provisioning', 'awaiting_owner_update', 'observing', 'ready', 'activated'
          )
     )
    OR EXISTS (
       SELECT 1 FROM hns_dns_zone_activation_current
        WHERE canonical_root = session.root_label
     )
    OR EXISTS (
       SELECT 1 FROM community_canonical_route_bindings
        WHERE family = 'hns' AND root_label = session.root_label
          AND route_lifecycle_status = 'active'
     )
    OR EXISTS (
       SELECT 1 FROM community_handle_sale_namespace_activation_current
        WHERE family = 'hns' AND canonical_root = session.root_label
     )
    OR EXISTS (
       SELECT 1
         FROM operator_managed_root_registry_current AS current_registry
        WHERE operator_managed_registry_has_active_root(
          current_registry.registry_reference,
          current_registry.registry_version,
          current_registry.registry_digest,
          session.root_label
        )
     )
  THEN
    RETURN QUERY SELECT 'conflict'::TEXT, session.root_import_session_id, session.revision;
    RETURN;
  END IF;

  IF input_authorization_kind = 'hns_name_signature' THEN
    INSERT INTO hns_root_import_name_proof_observations (
      proof_result_sha256, root_import_session_id, actor_id, root_label,
      message_sha256, signature_sha256, result_bytes, safe, verified, verified_at
    ) VALUES (
      input_authorization_sha256, session.root_import_session_id, session.actor_id,
      session.root_label, input_name_proof_message_sha256,
      input_name_proof_signature_sha256, input_name_proof_result_bytes,
      TRUE, TRUE, database_now
    );
  END IF;
  INSERT INTO hns_authority_provision_jobs (
    provision_job_id, root_import_session_id, operation_kind,
    request_bytes, request_sha256, state
  ) VALUES (
    input_provision_job_id, session.root_import_session_id, 'provision_root_v1',
    input_provision_request_bytes, input_provision_request_sha256, 'queued'
  );
  UPDATE hns_root_import_sessions
     SET status = 'provisioning', revision = session.revision + 1,
         provision_idempotency_key = input_idempotency_key,
         provision_poll_request_sha256 = input_poll_request_sha256,
         provision_authorization_kind = input_authorization_kind,
         provision_authorization_sha256 = input_authorization_sha256,
         ownership_result_sha256 = CASE input_authorization_kind
           WHEN 'namespace_ownership' THEN input_authorization_sha256
           ELSE NULL
         END,
         updated_at = database_now
   WHERE hns_root_import_sessions.root_import_session_id = session.root_import_session_id;
  RETURN QUERY SELECT 'provisioning'::TEXT, session.root_import_session_id, session.revision + 1;
END;
$_$;

CREATE FUNCTION can_account_view_content_rating_v1(target_account_id text, target_rating text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT CASE
    WHEN target_rating = 'general' THEN TRUE
    WHEN target_rating = 'adult_18' AND target_account_id IS NOT NULL
      THEN current_account_age_capability_v1(target_account_id) = 'adult_18'
    ELSE FALSE
  END;
$$;

CREATE FUNCTION change_hns_community_app_host_status_v1(input_operation_id text, input_idempotency_key text, input_request_hash text, input_app_host_activation_id text, input_expected_activation_generation bigint, input_target_status text, input_reason_code text) RETURNS TABLE(outcome text, app_host_activation_id text, app_host_activation_generation bigint, status text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  replay hns_community_app_host_operations%ROWTYPE;
  current_record hns_community_app_host_activation_current%ROWTYPE;
  prior hns_community_app_host_activation_revisions%ROWTYPE;
  route RECORD;
  dns_current hns_dns_zone_activation_current%ROWTYPE;
  dns_revision hns_dns_zone_activation_revisions%ROWTYPE;
  database_now TIMESTAMPTZ := clock_timestamp();
  new_generation BIGINT := input_expected_activation_generation + 1;
  next_route_kind TEXT;
  next_route_reference TEXT;
  next_route_generation BIGINT;
BEGIN
  SELECT * INTO replay FROM hns_community_app_host_operations AS operation
   WHERE operation.idempotency_key = input_idempotency_key;
  IF FOUND THEN
    IF replay.operation_kind <> 'transition' OR replay.operation_id <> input_operation_id
      OR replay.request_hash <> input_request_hash
      OR replay.app_host_activation_id <> input_app_host_activation_id
      OR replay.expected_activation_generation <> input_expected_activation_generation
      OR replay.target_status <> input_target_status THEN
      RAISE EXCEPTION 'HNS app-host transition idempotency conflict';
    END IF;
    RETURN QUERY SELECT 'replayed'::TEXT, replay.app_host_activation_id,
      replay.result_activation_generation, replay.target_status;
    RETURN;
  END IF;
  SELECT * INTO current_record FROM hns_community_app_host_activation_current AS current_authority
   WHERE current_authority.app_host_activation_id = input_app_host_activation_id FOR UPDATE;
  IF NOT FOUND OR current_record.current_generation <> input_expected_activation_generation THEN
    RAISE EXCEPTION 'HNS app-host generation fence does not match';
  END IF;
  SELECT * INTO prior FROM hns_community_app_host_activation_revisions AS revision
   WHERE revision.app_host_activation_id = input_app_host_activation_id
     AND revision.app_host_activation_generation = input_expected_activation_generation;
  IF prior.status = 'revoked'
    OR NOT ((prior.status = 'active' AND input_target_status IN ('active', 'suspended', 'revoked'))
      OR (prior.status = 'suspended' AND input_target_status IN ('active', 'revoked'))) THEN
    RAISE EXCEPTION 'HNS app-host transition is not allowed';
  END IF;
  next_route_kind := prior.route_authority_kind;
  next_route_reference := prior.route_authority_reference;
  next_route_generation := prior.route_authority_generation;
  IF input_target_status = 'active' THEN
    SELECT * INTO route FROM effective_route_authority_v2(prior.community_id, database_now)
     WHERE route_binding_id = prior.route_binding_id;
    next_route_kind := route.route_authority_kind;
    next_route_reference := CASE WHEN route.route_authority_kind = 'verified_namespace_v1'
      THEN route.verified_evidence_ref ELSE route.authority_reference END;
    next_route_generation := CASE WHEN route.route_authority_kind = 'verified_namespace_v1'
      THEN route.binding_generation ELSE route.authority_generation END;
    SELECT * INTO dns_current FROM hns_dns_zone_activation_current AS current_authority
     WHERE current_authority.canonical_root = prior.canonical_root FOR SHARE;
    SELECT * INTO dns_revision FROM hns_dns_zone_activation_revisions AS revision
     WHERE revision.dns_zone_activation_id = dns_current.dns_zone_activation_id
       AND revision.dns_zone_activation_generation = dns_current.current_generation;
    IF route.community_id IS NULL OR dns_current.dns_zone_activation_id IS NULL
      OR dns_revision.status <> 'active' THEN
      RAISE EXCEPTION 'HNS app-host restoration authority is unavailable';
    END IF;
  ELSE
    dns_current.dns_zone_activation_id := prior.dns_zone_activation_id;
    dns_current.current_generation := prior.dns_zone_activation_generation;
    dns_revision.gateway_deployment_reference := prior.gateway_deployment_reference;
  END IF;
  INSERT INTO hns_community_app_host_activation_revisions (
    app_host_activation_id, app_host_activation_generation, normalized_host,
    canonical_root, community_id, route_binding_id, route_authority_kind,
    route_authority_reference, route_authority_generation, dns_zone_activation_id,
    dns_zone_activation_generation, gateway_deployment_reference, status,
    reason_code, activated_at, suspended_at, revoked_at
  ) VALUES (
    prior.app_host_activation_id, new_generation, prior.normalized_host,
    prior.canonical_root, prior.community_id, prior.route_binding_id,
    next_route_kind, next_route_reference, next_route_generation,
    dns_current.dns_zone_activation_id, dns_current.current_generation,
    dns_revision.gateway_deployment_reference, input_target_status,
    CASE WHEN input_target_status = 'active' THEN NULL ELSE input_reason_code END,
    prior.activated_at,
    CASE WHEN input_target_status = 'suspended' THEN database_now ELSE NULL END,
    CASE WHEN input_target_status = 'revoked' THEN database_now ELSE NULL END
  );
  UPDATE hns_community_app_host_activation_current AS current_authority
     SET current_generation = new_generation, updated_at = database_now
   WHERE current_authority.app_host_activation_id = input_app_host_activation_id;
  INSERT INTO hns_community_app_host_operations VALUES (
    input_operation_id, 'transition', input_idempotency_key, input_request_hash,
    input_app_host_activation_id, input_expected_activation_generation,
    input_target_status, new_generation, database_now
  );
  SET CONSTRAINTS ALL IMMEDIATE;
  RETURN QUERY SELECT 'changed'::TEXT, input_app_host_activation_id,
    new_generation, input_target_status;
END;
$$;

CREATE FUNCTION change_hns_dns_zone_activation_status_v1(input_operation_id text, input_idempotency_key text, input_request_hash text, input_dns_zone_activation_id text, input_expected_activation_generation bigint, input_target_status text, input_reason_code text) RETURNS TABLE(outcome text, activation_id text, activation_generation bigint, status text)
    LANGUAGE plpgsql
    AS $$
DECLARE
  replay hns_dns_zone_lifecycle_operations%ROWTYPE;
  current_record hns_dns_zone_activation_current%ROWTYPE;
  prior hns_dns_zone_activation_revisions%ROWTYPE;
  database_now TIMESTAMPTZ := clock_timestamp();
  new_generation BIGINT := input_expected_activation_generation + 1;
BEGIN
  SELECT * INTO replay FROM hns_dns_zone_lifecycle_operations AS operation
   WHERE operation.idempotency_key = input_idempotency_key;
  IF FOUND THEN
    IF replay.operation_id <> input_operation_id OR replay.request_hash <> input_request_hash
      OR replay.dns_zone_activation_id <> input_dns_zone_activation_id
      OR replay.expected_activation_generation <> input_expected_activation_generation
      OR replay.target_status <> input_target_status OR replay.reason_code <> input_reason_code THEN
      RAISE EXCEPTION 'HNS DNS lifecycle idempotency conflict';
    END IF;
    RETURN QUERY SELECT 'replayed'::TEXT, replay.dns_zone_activation_id,
      replay.result_activation_generation, replay.target_status;
    RETURN;
  END IF;

  SELECT * INTO current_record FROM hns_dns_zone_activation_current AS current_authority
   WHERE current_authority.dns_zone_activation_id = input_dns_zone_activation_id FOR UPDATE;
  IF NOT FOUND OR current_record.current_generation <> input_expected_activation_generation THEN
    RAISE EXCEPTION 'HNS DNS lifecycle generation fence does not match';
  END IF;
  SELECT * INTO prior FROM hns_dns_zone_activation_revisions AS revision
   WHERE revision.dns_zone_activation_id = input_dns_zone_activation_id
     AND revision.dns_zone_activation_generation = input_expected_activation_generation;
  IF prior.status = 'revoked'
    OR NOT ((prior.status = 'active' AND input_target_status IN ('suspended', 'revoked'))
      OR (prior.status = 'suspended' AND input_target_status IN ('active', 'revoked'))) THEN
    RAISE EXCEPTION 'HNS DNS lifecycle transition is not allowed';
  END IF;

  INSERT INTO hns_dns_zone_activation_revisions (
    dns_zone_activation_id, dns_zone_activation_generation,
    activation_document_bytes, activation_document_digest, canonical_root,
    dns_authority_kind, dns_authority_reference, dns_authority_generation,
    pirate_dns_authority_inventory_reference, pirate_dns_authority_inventory_version,
    pirate_dns_authority_inventory_digest, zone_revision, zone_bytes, zone_bytes_digest,
    dnssec_keyset_reference, dnssec_keyset_version, gateway_deployment_reference,
    gateway_certificate_spki_sha256, stable_chain_delegation_snapshot_reference,
    stable_chain_delegation_snapshot_digest, status, reason_code, activated_at,
    suspended_at, revoked_at
  ) SELECT
    prior.dns_zone_activation_id, new_generation,
    prior.activation_document_bytes, prior.activation_document_digest, prior.canonical_root,
    prior.dns_authority_kind, prior.dns_authority_reference, prior.dns_authority_generation,
    prior.pirate_dns_authority_inventory_reference,
    prior.pirate_dns_authority_inventory_version,
    prior.pirate_dns_authority_inventory_digest, prior.zone_revision, prior.zone_bytes,
    prior.zone_bytes_digest, prior.dnssec_keyset_reference, prior.dnssec_keyset_version,
    prior.gateway_deployment_reference, prior.gateway_certificate_spki_sha256,
    prior.stable_chain_delegation_snapshot_reference,
    prior.stable_chain_delegation_snapshot_digest, input_target_status,
    CASE WHEN input_target_status = 'active' THEN NULL ELSE input_reason_code END,
    prior.activated_at,
    CASE WHEN input_target_status = 'suspended' THEN database_now ELSE NULL END,
    CASE WHEN input_target_status = 'revoked' THEN database_now ELSE NULL END;

  UPDATE hns_dns_zone_activation_current AS current_authority
     SET current_generation = new_generation, updated_at = database_now
   WHERE current_authority.dns_zone_activation_id = input_dns_zone_activation_id;
  INSERT INTO hns_dns_zone_lifecycle_operations VALUES (
    input_operation_id, input_idempotency_key, input_request_hash,
    input_dns_zone_activation_id, input_expected_activation_generation,
    input_target_status, input_reason_code, new_generation, database_now
  );
  SET CONSTRAINTS ALL IMMEDIATE;
  RETURN QUERY SELECT 'changed'::TEXT, input_dns_zone_activation_id,
    new_generation, input_target_status;
END;
$$;

CREATE FUNCTION claim_hns_authority_provision_job_v1(input_executor_id text, input_lease_seconds integer) RETURNS TABLE(provision_job_id text, root_import_session_id text, operation_kind text, request_bytes bytea, request_sha256 text, lease_fence bigint, lease_expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE
  candidate hns_authority_provision_jobs%ROWTYPE;
  expired_session_record hns_root_import_sessions%ROWTYPE;
  database_now TIMESTAMPTZ := clock_timestamp();
BEGIN
  IF btrim(input_executor_id) <> input_executor_id
    OR octet_length(input_executor_id) NOT BETWEEN 1 AND 256
    OR input_executor_id ~ '[[:cntrl:]]'
    OR input_lease_seconds NOT BETWEEN 4 AND 60
  THEN
    RAISE EXCEPTION 'invalid HNS authority provision claim';
  END IF;

  SELECT job.* INTO candidate
    FROM hns_authority_provision_jobs AS job
    JOIN hns_root_import_sessions AS expired_session
      ON expired_session.root_import_session_id = job.root_import_session_id
   WHERE (
       job.state = 'queued'
       OR (job.state = 'leased' AND job.lease_expires_at <= database_now)
     )
     AND expired_session.status = 'provisioning'
     AND expired_session.expires_at <= database_now
   ORDER BY job.created_at, job.provision_job_id
   FOR UPDATE OF job SKIP LOCKED
   LIMIT 1;
  IF FOUND THEN
    SELECT * INTO expired_session_record
      FROM hns_root_import_sessions
     WHERE hns_root_import_sessions.root_import_session_id = candidate.root_import_session_id
     FOR UPDATE;
    UPDATE hns_authority_provision_jobs AS job
       SET state = 'failed', leased_by = NULL, lease_expires_at = NULL,
           failure_code = 'session_expired', completed_at = database_now,
           updated_at = database_now
     WHERE job.provision_job_id = candidate.provision_job_id;
    UPDATE hns_root_import_sessions AS expired_session
       SET status = 'expired', revision = expired_session_record.revision + 1,
           updated_at = database_now
     WHERE expired_session.root_import_session_id = expired_session_record.root_import_session_id;
  END IF;

  SELECT job.* INTO candidate
    FROM hns_authority_provision_jobs AS job
    JOIN hns_root_import_sessions AS session
      ON session.root_import_session_id = job.root_import_session_id
    LEFT JOIN community_creation_ceremony_results AS ownership_result
      ON ownership_result.ceremony_intent_id = session.ceremony_intent_id
     AND ownership_result.namespace_session_id = session.namespace_session_id
    LEFT JOIN hns_root_import_name_proof_observations AS proof
      ON proof.root_import_session_id = session.root_import_session_id
   WHERE job.attempt_count < 5
     AND (
       job.state = 'queued'
       OR (job.state = 'leased' AND job.lease_expires_at <= database_now)
     )
     AND session.status = 'provisioning'
     AND session.expires_at > database_now
     AND (
       (
         session.provision_authorization_kind = 'namespace_ownership'
         AND session.provision_authorization_sha256 = ownership_result.result_hash
         AND session.ownership_result_sha256 = ownership_result.result_hash
         AND ownership_result.outcome_status = 'satisfied'
       )
       OR (
         session.provision_authorization_kind = 'hns_name_signature'
         AND session.provision_authorization_sha256 = proof.proof_result_sha256
         AND session.ownership_result_sha256 IS NULL
         AND proof.safe IS TRUE
         AND proof.verified IS TRUE
       )
     )
   ORDER BY job.created_at, job.provision_job_id
   FOR UPDATE OF job SKIP LOCKED
   LIMIT 1;
  IF NOT FOUND THEN RETURN; END IF;

  UPDATE hns_authority_provision_jobs AS job
     SET state = 'leased',
         attempt_count = candidate.attempt_count + 1,
         lease_fence = candidate.lease_fence + 1,
         leased_by = input_executor_id,
         lease_expires_at = database_now + (input_lease_seconds * interval '1 second'),
         failure_code = NULL,
         updated_at = database_now
   WHERE job.provision_job_id = candidate.provision_job_id
  RETURNING job.provision_job_id, job.root_import_session_id,
            job.operation_kind, job.request_bytes, job.request_sha256,
            job.lease_fence, job.lease_expires_at
       INTO provision_job_id, root_import_session_id, operation_kind,
            request_bytes, request_sha256, lease_fence, lease_expires_at;
  RETURN NEXT;
END;
$$;

CREATE FUNCTION claim_hns_root_import_observation_job_v1(input_executor_id text, input_lease_seconds integer) RETURNS TABLE(observation_job_id text, root_import_session_id text, operation_kind text, request_bytes bytea, request_sha256 text, publish_plan_bytes bytea, publish_plan_sha256 text, provision_result_bytes bytea, provision_result_sha256 text, lease_fence bigint, lease_expires_at timestamp with time zone)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE
  candidate hns_root_import_observation_jobs%ROWTYPE;
  teardown hns_root_import_teardown_jobs%ROWTYPE;
  session hns_root_import_sessions%ROWTYPE;
  provision hns_authority_provision_jobs%ROWTYPE;
  database_now TIMESTAMPTZ := clock_timestamp();
BEGIN
  IF btrim(input_executor_id) <> input_executor_id
    OR octet_length(input_executor_id) NOT BETWEEN 1 AND 256
    OR input_executor_id ~ '[[:cntrl:]]'
    OR input_lease_seconds NOT BETWEEN 4 AND 60
  THEN
    RAISE EXCEPTION 'invalid HNS root observation claim';
  END IF;

  SELECT job.* INTO teardown
    FROM hns_root_import_teardown_jobs AS job
    JOIN hns_root_import_sessions AS cleanup_session
      ON cleanup_session.root_import_session_id = job.root_import_session_id
   WHERE job.attempt_count < 20
     AND (
       job.state = 'waiting'
       OR (job.state = 'leased' AND job.lease_expires_at <= database_now)
     )
     AND (
       cleanup_session.status IN ('failed', 'expired')
       OR (
         cleanup_session.status IN ('awaiting_owner_update', 'observing', 'ready')
         AND cleanup_session.expires_at <= database_now
       )
     )
   ORDER BY job.created_at, job.teardown_job_id
   FOR UPDATE OF job SKIP LOCKED
   LIMIT 1;
  IF FOUND THEN
    SELECT * INTO session
      FROM hns_root_import_sessions
     WHERE hns_root_import_sessions.root_import_session_id = teardown.root_import_session_id
     FOR UPDATE;
    SELECT * INTO provision
      FROM hns_authority_provision_jobs
     WHERE provision_job_id = session.provision_job_id;
    IF provision.state <> 'completed' THEN
      RAISE EXCEPTION 'HNS root teardown provision authority is unavailable';
    END IF;
    UPDATE hns_root_import_teardown_jobs AS job
       SET state = 'leased', attempt_count = teardown.attempt_count + 1,
           lease_fence = teardown.lease_fence + 1, leased_by = input_executor_id,
           lease_expires_at = database_now + input_lease_seconds * interval '1 second',
           failure_code = NULL, updated_at = database_now
     WHERE job.teardown_job_id = teardown.teardown_job_id;
    RETURN QUERY SELECT
      teardown.teardown_job_id, teardown.root_import_session_id,
      'teardown_root_v1'::TEXT, provision.request_bytes, provision.request_sha256,
      provision.publish_plan_bytes, provision.publish_plan_sha256,
      provision.result_bytes, provision.result_sha256,
      teardown.lease_fence + 1,
      database_now + input_lease_seconds * interval '1 second';
    RETURN;
  END IF;

  SELECT job.* INTO teardown
    FROM hns_root_import_teardown_jobs AS job
    JOIN hns_root_import_sessions AS cleanup_session
      ON cleanup_session.root_import_session_id = job.root_import_session_id
   WHERE job.attempt_count >= 20
     AND (
       job.state = 'waiting'
       OR (job.state = 'leased' AND job.lease_expires_at <= database_now)
     )
     AND (
       cleanup_session.status IN ('failed', 'expired')
       OR (
         cleanup_session.status IN ('awaiting_owner_update', 'observing', 'ready')
         AND cleanup_session.expires_at <= database_now
       )
     )
   ORDER BY job.created_at, job.teardown_job_id
   FOR UPDATE OF job SKIP LOCKED
   LIMIT 1;
  IF FOUND THEN
    SELECT * INTO session
      FROM hns_root_import_sessions
     WHERE hns_root_import_sessions.root_import_session_id = teardown.root_import_session_id
     FOR UPDATE;
    UPDATE hns_root_import_teardown_jobs AS job
       SET state = 'failed', leased_by = NULL, lease_expires_at = NULL,
           failure_code = 'zone_teardown_attempts_exhausted', completed_at = database_now,
           updated_at = database_now
     WHERE job.teardown_job_id = teardown.teardown_job_id;
    IF session.status NOT IN ('failed', 'expired') THEN
      UPDATE hns_root_import_sessions AS exhausted_session
         SET status = 'expired', revision = session.revision + 1,
             updated_at = database_now
       WHERE exhausted_session.root_import_session_id = session.root_import_session_id;
    END IF;
  END IF;

  SELECT job.* INTO candidate
    FROM hns_root_import_observation_jobs AS job
    JOIN hns_root_import_sessions AS selected_session
      ON selected_session.root_import_session_id = job.root_import_session_id
   WHERE job.attempt_count >= 20
     AND (
       job.state = 'queued'
       OR (job.state = 'leased' AND job.lease_expires_at <= database_now)
     )
     AND selected_session.status = 'observing'
     AND selected_session.expires_at > database_now
   ORDER BY job.created_at, job.observation_job_id
   FOR UPDATE OF job SKIP LOCKED
   LIMIT 1;
  IF FOUND THEN
    SELECT * INTO session
      FROM hns_root_import_sessions
     WHERE hns_root_import_sessions.root_import_session_id = candidate.root_import_session_id
     FOR UPDATE;
    UPDATE hns_root_import_observation_jobs AS job
       SET state = 'failed', leased_by = NULL, lease_expires_at = NULL,
           failure_code = 'observation_attempts_exhausted', completed_at = database_now,
           updated_at = database_now
     WHERE job.observation_job_id = candidate.observation_job_id;
    UPDATE hns_root_import_sessions AS exhausted_session
       SET status = 'failed', revision = session.revision + 1,
           updated_at = database_now
     WHERE exhausted_session.root_import_session_id = session.root_import_session_id;
  END IF;

  SELECT job.* INTO candidate
    FROM hns_root_import_observation_jobs AS job
    JOIN hns_root_import_sessions AS selected_session
      ON selected_session.root_import_session_id = job.root_import_session_id
   WHERE job.attempt_count < 20
     AND (
       job.state = 'queued'
       OR (job.state = 'leased' AND job.lease_expires_at <= database_now)
     )
     AND selected_session.status = 'observing'
     AND selected_session.expires_at > database_now
   ORDER BY job.created_at, job.observation_job_id
   FOR UPDATE OF job SKIP LOCKED
   LIMIT 1;
  IF NOT FOUND THEN RETURN; END IF;
  SELECT * INTO session
    FROM hns_root_import_sessions
   WHERE hns_root_import_sessions.root_import_session_id = candidate.root_import_session_id;
  SELECT * INTO provision
    FROM hns_authority_provision_jobs
   WHERE provision_job_id = session.provision_job_id;
  IF provision.state <> 'completed' THEN
    RAISE EXCEPTION 'HNS root observation provision authority is unavailable';
  END IF;
  UPDATE hns_root_import_observation_jobs AS job
     SET state = 'leased', attempt_count = candidate.attempt_count + 1,
         lease_fence = candidate.lease_fence + 1,
         leased_by = input_executor_id,
         lease_expires_at = database_now + input_lease_seconds * interval '1 second',
         failure_code = NULL, updated_at = database_now
   WHERE job.observation_job_id = candidate.observation_job_id;
  RETURN QUERY SELECT
    candidate.observation_job_id, candidate.root_import_session_id,
    candidate.operation_kind, candidate.request_bytes, candidate.request_sha256,
    provision.publish_plan_bytes, provision.publish_plan_sha256,
    provision.result_bytes, provision.result_sha256,
    candidate.lease_fence + 1,
    database_now + input_lease_seconds * interval '1 second';
END;
$$;

CREATE FUNCTION community_handle_sales_creator_grant_id_v1(input_community_id text, input_account_id text) RETURNS text
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  SELECT 'handle_sales_grant_' || encode(
    sha256(
      convert_to('pirate-handle-sales-authority-grant-v1', 'UTF8')
      || decode('00', 'hex')
      || convert_to(input_community_id, 'UTF8')
      || decode('00', 'hex')
      || convert_to(input_account_id, 'UTF8')
    ),
    'hex'
  )
$$;

CREATE FUNCTION community_moderation_policy_preimage_v1(input_community_id text, input_policy_revision_id text) RETURNS text
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  SELECT format(
    '["community-moderation-policy-v1",%s,%s,%s,%s,%s,[%s]]',
    to_json(revision.community_id)::text,
    to_json(revision.policy_revision_id)::text,
    revision.revision,
    to_json(revision.platform_floor_revision_id)::text,
    to_json(revision.platform_floor_hash)::text,
    string_agg(
      format('[%s,%s]', to_json(category.category)::text, to_json(category.decision)::text),
      ',' ORDER BY moderation_policy_category_ordinal_v1(category.category)
    )
  )
  FROM community_moderation_policy_revisions AS revision
  JOIN community_moderation_policy_category_decisions AS category
    ON category.community_id = revision.community_id
   AND category.policy_revision_id = revision.policy_revision_id
  WHERE revision.community_id = input_community_id
    AND revision.policy_revision_id = input_policy_revision_id
  GROUP BY
    revision.community_id,
    revision.policy_revision_id,
    revision.revision,
    revision.platform_floor_revision_id,
    revision.platform_floor_hash;
$$;

CREATE FUNCTION create_community_moderation_policy_revision_v1(input_account_id text, input_community_id text, input_expected_policy_revision text, input_decisions jsonb) RETURNS community_moderation_policy_update_result_v1
    LANGUAGE plpgsql
    AS $$
DECLARE
  current_revision community_moderation_policy_current%ROWTYPE;
  floor_revision moderation_platform_floor_current%ROWTYPE;
  next_revision BIGINT;
  next_revision_id TEXT;
  next_preimage TEXT;
  next_hash TEXT;
  created_at TIMESTAMPTZ;
BEGIN
  PERFORM 1 FROM communities WHERE community_id = input_community_id FOR UPDATE;
  IF NOT FOUND OR NOT has_community_moderation_capability_v1(
    input_account_id,
    input_community_id,
    'moderation.act'
  ) THEN
    RETURN ('not_found', NULL)::community_moderation_policy_update_result_v1;
  END IF;
  SELECT * INTO current_revision
    FROM community_moderation_policy_current
   WHERE community_id = input_community_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN ('not_found', NULL)::community_moderation_policy_update_result_v1;
  END IF;
  IF current_revision.policy_revision_id <> input_expected_policy_revision THEN
    RETURN ('conflict', current_revision.policy_revision_id)::community_moderation_policy_update_result_v1;
  END IF;
  IF jsonb_typeof(input_decisions) <> 'object'
    OR (SELECT count(*) FROM jsonb_object_keys(input_decisions)) <> 13
    OR EXISTS (
      SELECT 1
        FROM jsonb_each_text(input_decisions) AS choice(category, decision)
       WHERE moderation_policy_category_ordinal_v1(choice.category) IS NULL
          OR moderation_policy_decision_severity_v1(choice.decision) IS NULL
    )
    OR EXISTS (
      SELECT 1
        FROM moderation_platform_floor_category_decisions AS floor_choice
       WHERE floor_choice.policy_revision_id = (
         SELECT policy_revision_id FROM moderation_platform_floor_current WHERE singleton
       )
         AND moderation_policy_decision_severity_v1(input_decisions ->> floor_choice.category)
           < moderation_policy_decision_severity_v1(floor_choice.decision)
    )
  THEN
    RETURN ('constraint', NULL)::community_moderation_policy_update_result_v1;
  END IF;
  SELECT * INTO floor_revision
    FROM moderation_platform_floor_current
   WHERE singleton
   FOR SHARE;
  SELECT revision + 1 INTO next_revision
    FROM community_moderation_policy_revisions
   WHERE community_id = input_community_id
     AND policy_revision_id = current_revision.policy_revision_id;
  IF next_revision IS NULL THEN
    RETURN ('not_found', NULL)::community_moderation_policy_update_result_v1;
  END IF;
  next_revision_id := 'community-moderation-policy:' || input_community_id || ':r' || next_revision;
  SELECT format(
    '["community-moderation-policy-v1",%s,%s,%s,%s,%s,[%s]]',
    to_json(input_community_id)::text,
    to_json(next_revision_id)::text,
    next_revision,
    to_json(floor_revision.policy_revision_id)::text,
    to_json(floor_revision.policy_hash)::text,
    string_agg(
      format('[%s,%s]', to_json(choice.category)::text, to_json(choice.decision)::text),
      ',' ORDER BY moderation_policy_category_ordinal_v1(choice.category)
    )
  ) INTO next_preimage
  FROM jsonb_each_text(input_decisions) AS choice(category, decision);
  next_hash := encode(sha256(convert_to(next_preimage, 'UTF8')), 'hex');
  created_at := clock_timestamp();
  INSERT INTO community_moderation_policy_revisions (
    community_id, policy_revision_id, revision,
    platform_floor_revision_id, platform_floor_hash,
    policy_preimage, policy_hash, created_at
  ) VALUES (
    input_community_id, next_revision_id, next_revision,
    floor_revision.policy_revision_id, floor_revision.policy_hash,
    next_preimage, next_hash, created_at
  );
  INSERT INTO community_moderation_policy_category_decisions (
    community_id, policy_revision_id, category, decision
  )
  SELECT input_community_id, next_revision_id, choice.category, choice.decision
    FROM jsonb_each_text(input_decisions) AS choice(category, decision);
  UPDATE community_moderation_policy_current
     SET policy_revision_id = next_revision_id,
         policy_hash = next_hash,
         updated_at = created_at
   WHERE community_id = input_community_id;
  RETURN ('updated', next_revision_id)::community_moderation_policy_update_result_v1;
END;
$$;

CREATE FUNCTION current_account_age_capability_v1(target_account_id text) RETURNS text
    LANGUAGE sql STABLE
    AS $_$
  SELECT CASE WHEN EXISTS (
    SELECT 1
      FROM assertions AS assertion
      JOIN evidence_receipts AS receipt
        ON receipt.evidence_receipt_id = assertion.evidence_receipt_id
       AND receipt.user_id = assertion.user_id
      JOIN proof_sessions AS session
        ON session.proof_session_id = receipt.proof_session_id
       AND session.actor_id = assertion.user_id
       AND session.status = 'completed'
       AND session.completed_at = session.terminal_at
       AND session.intent_id = 'platform.document.age-18'
       AND session.method = 'document'
       AND session.scope_kind = 'issuer_rp_scope'
       AND session.issuer_rp_scope = 'pirate-social'
       AND session.issuer_rp_action_scope IS NULL
       AND session.requested_requirements = '[{"claim_id":"age.minimum","minimum_age":"18"},{"claim_id":"credential.subject_unique"},{"claim_id":"document.valid"}]'::jsonb
       AND session.requested_claim_ids = '["age.minimum","credential.subject_unique","document.valid"]'::jsonb
      JOIN assertion_bindings AS binding
        ON binding.binding_group_id = assertion.binding_group_id
       AND binding.user_id = assertion.user_id
       AND binding.binding_mode = 'same_subject'
       AND binding.subject_key_id = assertion.subject_key_id
      JOIN active_subject_key_bindings AS active_binding
        ON active_binding.subject_key_id = assertion.subject_key_id
       AND active_binding.user_id = assertion.user_id
       AND active_binding.binding_event_id = binding.subject_binding_event_id
       AND active_binding.binding_epoch = binding.subject_binding_epoch
     WHERE assertion.user_id = target_account_id
       AND assertion.claim_id = 'age.minimum'
       AND assertion.assurance = 'document_zk'
       AND receipt.provider_id IN ('self.pass', 'self.enterprise', 'zkpassport')
       AND receipt.subject_key_id = assertion.subject_key_id
       AND assertion.assertion_value ? 'minimum_age'
       AND assertion.assertion_value->>'minimum_age' ~ '^(0|[1-9][0-9]*)$'
       AND (assertion.assertion_value->>'minimum_age')::NUMERIC >= 18
       AND (assertion.expires_at IS NULL OR assertion.expires_at > clock_timestamp())
       AND (receipt.expires_at IS NULL OR receipt.expires_at > clock_timestamp())
       AND EXISTS (
         SELECT 1
           FROM assertions AS credential
           JOIN evidence_receipts AS credential_receipt
             ON credential_receipt.evidence_receipt_id = credential.evidence_receipt_id
            AND credential_receipt.proof_session_id = session.proof_session_id
            AND credential_receipt.user_id = assertion.user_id
            AND credential_receipt.subject_key_id = assertion.subject_key_id
          WHERE credential.user_id = assertion.user_id
            AND credential.binding_group_id = assertion.binding_group_id
            AND credential.subject_key_id = assertion.subject_key_id
            AND credential.claim_id = 'credential.subject_unique'
            AND credential.assertion_value = '{"subject_unique":true}'::jsonb
            AND credential.assurance = 'document_zk'
            AND (credential.expires_at IS NULL OR credential.expires_at > clock_timestamp())
            AND (credential_receipt.expires_at IS NULL OR credential_receipt.expires_at > clock_timestamp())
       )
       AND EXISTS (
         SELECT 1
           FROM assertions AS document
           JOIN evidence_receipts AS document_receipt
             ON document_receipt.evidence_receipt_id = document.evidence_receipt_id
            AND document_receipt.proof_session_id = session.proof_session_id
            AND document_receipt.user_id = assertion.user_id
            AND document_receipt.subject_key_id = assertion.subject_key_id
          WHERE document.user_id = assertion.user_id
            AND document.binding_group_id = assertion.binding_group_id
            AND document.subject_key_id = assertion.subject_key_id
            AND document.claim_id = 'document.valid'
            AND document.assertion_value = '{"valid":true}'::jsonb
            AND document.assurance = 'document_zk'
            AND (document.expires_at IS NULL OR document.expires_at > clock_timestamp())
            AND (document_receipt.expires_at IS NULL OR document_receipt.expires_at > clock_timestamp())
       )
       AND NOT EXISTS (
         SELECT 1
           FROM LATERAL (
             SELECT event.outcome
               FROM assertion_revalidation_events AS event
              WHERE event.assertion_id = assertion.assertion_id
                AND event.user_id = assertion.user_id
           ORDER BY event.observed_at DESC, event.created_at DESC,
                    event.assertion_revalidation_event_id DESC
              LIMIT 1
           ) AS latest
          WHERE latest.outcome <> 'accepted'
       )
       AND NOT EXISTS (
         SELECT 1
           FROM assertions AS sibling
           JOIN LATERAL (
             SELECT event.outcome
               FROM assertion_revalidation_events AS event
              WHERE event.assertion_id = sibling.assertion_id
                AND event.user_id = sibling.user_id
           ORDER BY event.observed_at DESC, event.created_at DESC,
                    event.assertion_revalidation_event_id DESC
              LIMIT 1
           ) AS latest ON TRUE
          WHERE sibling.user_id = assertion.user_id
            AND sibling.binding_group_id = assertion.binding_group_id
            AND latest.outcome <> 'accepted'
       )
  ) THEN 'adult_18' ELSE 'general' END;
$_$;

CREATE FUNCTION current_hns_sale_namespace_dependency_v1(input_community_id text, input_namespace_authority_reference text, input_namespace_authority_generation bigint, input_dns_zone_activation_id text, input_dns_zone_activation_generation bigint, database_now timestamp with time zone) RETURNS TABLE(canonical_root text, display_root text, namespace_authority_current boolean, dns_zone_current boolean, dns_delegation_current boolean)
    LANGUAGE sql STABLE
    AS $$
  WITH authority AS (
    SELECT evidence.root_label,
           evidence.root_label_display,
           evidence.binding_generation,
           evidence.expires_at,
           evidence.origin,
           binding.community_id AS bound_community_id,
           attachment.community_id AS attachment_community_id
      FROM community_route_ownership_evidence AS evidence
      JOIN communities AS community
        ON community.community_id = input_community_id
       AND community.status = 'active'
      LEFT JOIN community_canonical_route_bindings AS binding
        ON binding.verified_evidence_ref = evidence.evidence_ref
      LEFT JOIN community_route_attachment_ceremony_attempts AS ceremony
        ON ceremony.ceremony_intent_id = evidence.route_attachment_ceremony_intent_id
      LEFT JOIN community_route_attachment_intents AS attachment
        ON attachment.attachment_intent_id = ceremony.attachment_intent_id
     WHERE evidence.evidence_ref = input_namespace_authority_reference
       AND evidence.family = 'hns'
       AND evidence.binding_generation = input_namespace_authority_generation
       AND evidence.expires_at IS NOT NULL
       AND evidence.expires_at > database_now
       AND (
         binding.community_id = input_community_id
         OR (evidence.origin = 'route_attachment'
           AND attachment.community_id = input_community_id)
       )
  ),
  dns AS (
    SELECT revision.*,
           inventory.published_at AS inventory_published_at,
           inventory.expires_at AS inventory_expires_at
      FROM hns_dns_zone_activation_current AS current_dns
      JOIN hns_dns_zone_activation_revisions AS revision
        ON revision.dns_zone_activation_id = current_dns.dns_zone_activation_id
       AND revision.dns_zone_activation_generation = current_dns.current_generation
      JOIN hns_authority_inventories AS inventory
        ON inventory.authority_inventory_reference
            = revision.pirate_dns_authority_inventory_reference
       AND inventory.authority_inventory_version
            = revision.pirate_dns_authority_inventory_version
       AND inventory.authority_inventory_digest
            = revision.pirate_dns_authority_inventory_digest
     WHERE current_dns.dns_zone_activation_id = input_dns_zone_activation_id
       AND current_dns.current_generation = input_dns_zone_activation_generation
       AND revision.status = 'active'
       AND inventory.published_at <= database_now
       AND inventory.expires_at > database_now
  ),
  health AS (
    SELECT observation.*
      FROM hns_dns_zone_health_observations AS observation
     WHERE observation.dns_zone_activation_id = input_dns_zone_activation_id
       AND observation.activation_generation = input_dns_zone_activation_generation
     ORDER BY observation.health_generation DESC
     LIMIT 1
  )
  SELECT authority.root_label,
         authority.root_label_display,
         TRUE,
         COALESCE(dns.canonical_root = authority.root_label, FALSE),
         COALESCE(
           dns.canonical_root = authority.root_label
           AND health.valid_until > database_now
           AND health.delegation_matches
           AND health.ds_authenticates_zone
           AND health.retained_zone_digest_matches
           AND health.gateway_healthy
           AND health.stable_chain_delegation_snapshot_reference
               = dns.stable_chain_delegation_snapshot_reference
           AND health.stable_chain_delegation_snapshot_digest
               = dns.stable_chain_delegation_snapshot_digest
           AND health.observed_dnssec_keyset_reference = dns.dnssec_keyset_reference
           AND health.observed_dnssec_keyset_version = dns.dnssec_keyset_version
           AND health.observed_zone_bytes_digest = dns.zone_bytes_digest
           AND health.observed_gateway_deployment_reference
               = dns.gateway_deployment_reference
           AND health.observed_gateway_certificate_spki_sha256
               = dns.gateway_certificate_spki_sha256,
           FALSE
         )
    FROM authority
    LEFT JOIN dns ON dns.canonical_root = authority.root_label
    LEFT JOIN health ON TRUE
   WHERE database_now IS NOT NULL
$$;

CREATE FUNCTION data_registration_pins_are_ready(operation_id text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1 FROM data_registration_artifacts artifact
    WHERE artifact.registration_operation_id = operation_id
      AND artifact.artifact_kind = 'canonical_audio'
  )
  AND EXISTS (
    SELECT 1 FROM data_registration_artifacts artifact
    WHERE artifact.registration_operation_id = operation_id
      AND artifact.artifact_kind = 'ip_metadata'
  )
  AND EXISTS (
    SELECT 1 FROM data_registration_artifacts artifact
    WHERE artifact.registration_operation_id = operation_id
      AND artifact.artifact_kind = 'nft_metadata'
  )
  AND NOT EXISTS (
    SELECT 1
    FROM data_registration_artifacts artifact
    WHERE artifact.registration_operation_id = operation_id
      AND NOT EXISTS (
        SELECT 1
        FROM data_registration_pin_verifications primary_pin
        JOIN data_registration_pin_verifications gateway
          ON gateway.registration_operation_id = primary_pin.registration_operation_id
         AND gateway.artifact_id = primary_pin.artifact_id
         AND gateway.role = 'independent_gateway'
         AND gateway.outcome = 'verified'
         AND gateway.cid = primary_pin.cid
         AND gateway.canonical_sha256 = primary_pin.canonical_sha256
         AND gateway.byte_length = primary_pin.byte_length
         AND gateway.provider_id <> primary_pin.provider_id
        WHERE primary_pin.registration_operation_id = operation_id
          AND primary_pin.artifact_id = artifact.artifact_id
          AND primary_pin.role = 'primary'
          AND primary_pin.provider_id = 'filebase'
          AND primary_pin.outcome = 'verified'
          AND primary_pin.canonical_sha256 = artifact.canonical_sha256
          AND primary_pin.byte_length = artifact.byte_length
      )
  );
$$;

CREATE FUNCTION decrement_handle_account_offering_grant_counter_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE handle_account_offering_grant_counters
     SET active_grant_count = active_grant_count - 1,
         updated_at = NEW.updated_at
   WHERE account_id = OLD.owner_account_id
     AND offering_id = OLD.offering_id
     AND active_grant_count > 0;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'active handle grant counter is missing';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION default_public_handle_persona() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.owner_persona_id IS NULL THEN
    SELECT persona.persona_id
      INTO NEW.owner_persona_id
      FROM personas AS persona
     WHERE persona.account_id = NEW.owner_user_id
       AND persona.is_first_persona;
  END IF;
  IF NEW.owner_persona_id IS NULL THEN
    RAISE EXCEPTION 'public handle requires an owned persona';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION default_text_post_rating_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.post_type IN ('text', 'song') THEN
    NEW.author_declared_rating := COALESCE(NEW.author_declared_rating, 'general');
    NEW.content_rating := COALESCE(NEW.content_rating, 'general');
  ELSIF NEW.author_declared_rating IS NOT NULL OR NEW.content_rating IS NOT NULL THEN
    RAISE EXCEPTION 'unrated post type cannot carry a content rating';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION effective_active_route(expected_community_id text, database_now timestamp with time zone) RETURNS TABLE(community_id text, route_binding_id text, family text, root_label text, root_label_display text, path_segment text, href text, verified_evidence_ref text, binding_generation bigint, evidence_expires_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path FROM CURRENT
    AS $$
  SELECT community.community_id,
         binding.route_binding_id,
         binding.family,
         binding.root_label,
         binding.root_label_display,
         binding.path_segment,
         binding.href,
         binding.verified_evidence_ref,
         binding.binding_generation,
         evidence.expires_at
    FROM communities AS community
    JOIN community_canonical_route_bindings AS binding
      ON community.canonical_route_binding_id = binding.route_binding_id
     AND community.community_id = binding.community_id
    JOIN community_route_ownership_evidence AS evidence
      ON evidence.evidence_ref = binding.verified_evidence_ref
   WHERE (expected_community_id IS NULL OR community.community_id = expected_community_id)
     AND database_now IS NOT NULL
     AND community.status = 'active'
     AND binding.route_authority_kind = 'verified_namespace_v1'
     AND binding.route_lifecycle_status = 'active'
     AND binding.ownership_status = 'verified'
     AND binding.verified_evidence_ref IS NOT NULL
     AND evidence.family = binding.family
     AND evidence.root_label = binding.root_label
     AND evidence.root_label_display = binding.root_label_display
     AND evidence.path_segment = binding.path_segment
     AND evidence.binding_generation = binding.binding_generation
     AND evidence.expires_at IS NOT NULL
     AND evidence.expires_at > database_now
$$;

CREATE FUNCTION is_community_route_root_label(route_family text, root_label text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    AS $_$
  SELECT CASE route_family
    WHEN 'hns' THEN
      octet_length(root_label) BETWEEN 1 AND 63
      AND root_label ~ '^[a-z0-9](?:[a-z0-9_-]{0,61}[a-z0-9])?$'
      AND root_label NOT IN ('example', 'invalid', 'local', 'localhost', 'test')
    WHEN 'spaces' THEN
      octet_length(root_label) BETWEEN 1 AND 62
      AND root_label ~ '^[a-z0-9-]+$'
      AND CASE
        WHEN left(root_label, 4) = 'xn--' AND octet_length(root_label) > 4
          THEN substring(root_label FROM 5)
        ELSE root_label
      END ~ '^[a-z0-9]+(?:-[a-z0-9]+)*$'
    ELSE FALSE
  END;
$_$;

CREATE FUNCTION is_community_route_root_label_display(root_label_display text) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  SELECT octet_length(root_label_display) BETWEEN 1 AND 255
    AND root_label_display = btrim(root_label_display)
    AND root_label_display !~ '[[:cntrl:]]'
    AND position('@' IN root_label_display) = 0
    AND position('.' IN root_label_display) = 0
    AND position('%' IN root_label_display) = 0
    AND position('/' IN root_label_display) = 0
    AND position(E'\\' IN root_label_display) = 0;
$$;

CREATE FUNCTION is_handle_sales_identifier_v1(input_value text, maximum_bytes integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT input_value IS NOT NULL
    AND btrim(input_value) <> ''
    AND input_value = btrim(input_value)
    AND octet_length(input_value) <= maximum_bytes
    AND input_value !~ '[[:cntrl:]]'
$$;

CREATE TABLE community_handle_sale_namespace_activation_revisions (
    sale_namespace_activation_id text NOT NULL,
    sale_namespace_activation_generation bigint NOT NULL,
    sale_namespace_activation_hash text NOT NULL,
    community_id text NOT NULL,
    family text NOT NULL,
    canonical_root text NOT NULL,
    display_root text NOT NULL,
    namespace_authority_kind text NOT NULL,
    namespace_authority_reference text NOT NULL,
    namespace_authority_generation bigint NOT NULL,
    serving_kind text NOT NULL,
    dns_zone_activation_id text NOT NULL,
    dns_zone_activation_generation bigint NOT NULL,
    root_replacement_kind text NOT NULL,
    dedicated_root_replacement_confirmed boolean NOT NULL,
    status text NOT NULL,
    reason_code text,
    actor_account_id text NOT NULL,
    authority_grant_id text NOT NULL,
    created_at timestamp with time zone NOT NULL,
    activated_at timestamp with time zone,
    suspended_at timestamp with time zone,
    revoked_at timestamp with time zone,
    recorded_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT community_handle_sale_namesp_dedicated_root_replacement_c_check CHECK ((dedicated_root_replacement_confirmed IS TRUE)),
    CONSTRAINT community_handle_sale_namespace__namespace_authority_kind_check CHECK ((namespace_authority_kind = 'verified_namespace_v1'::text)),
    CONSTRAINT community_handle_sale_namespace_act_root_replacement_kind_check CHECK ((root_replacement_kind = 'dedicated_root_replace_v1'::text)),
    CONSTRAINT community_handle_sale_namespace_activation_identity_check CHECK ((is_handle_sales_identifier_v1(sale_namespace_activation_id, 128) AND ((sale_namespace_activation_generation >= 1) AND (sale_namespace_activation_generation <= '9007199254740991'::bigint)) AND (sale_namespace_activation_hash ~ '^[0-9a-f]{64}$'::text) AND is_community_route_root_label('hns'::text, canonical_root) AND is_community_route_root_label_display(display_root) AND (canonical_root <> 'pirate'::text) AND is_handle_sales_identifier_v1(namespace_authority_reference, 512) AND ((namespace_authority_generation >= 1) AND (namespace_authority_generation <= '9007199254740991'::bigint)) AND is_handle_sales_identifier_v1(dns_zone_activation_id, 256) AND ((dns_zone_activation_generation BETWEEN 1 AND '9007199254740991'::bigint)))),
    CONSTRAINT community_handle_sale_namespace_activation_r_serving_kind_check CHECK ((serving_kind = 'hns_dns_zone_activation_v1'::text)),
    CONSTRAINT community_handle_sale_namespace_activation_revisio_family_check CHECK ((family = 'hns'::text)),
    CONSTRAINT community_handle_sale_namespace_activation_revisio_status_check CHECK ((status = ANY (ARRAY['pending'::text, 'active'::text, 'suspended'::text, 'revoked'::text]))),
    CONSTRAINT community_handle_sale_namespace_activation_status_shape CHECK ((((status = 'pending'::text) AND (reason_code IS NULL) AND (activated_at IS NULL) AND (suspended_at IS NULL) AND (revoked_at IS NULL)) OR ((status = 'active'::text) AND (reason_code IS NULL) AND (activated_at IS NOT NULL) AND (suspended_at IS NULL) AND (revoked_at IS NULL)) OR ((status = 'suspended'::text) AND is_handle_sales_identifier_v1(reason_code, 128) AND (activated_at IS NOT NULL) AND (suspended_at IS NOT NULL) AND (revoked_at IS NULL)) OR ((status = 'revoked'::text) AND is_handle_sales_identifier_v1(reason_code, 128) AND (activated_at IS NOT NULL) AND (revoked_at IS NOT NULL)))),
    CONSTRAINT community_handle_sale_namespace_activation_time_order CHECK (((recorded_at >= created_at) AND ((activated_at IS NULL) OR (activated_at >= created_at)) AND ((suspended_at IS NULL) OR (suspended_at >= activated_at)) AND ((revoked_at IS NULL) OR (revoked_at >= activated_at))))
);

CREATE FUNCTION effective_community_handle_sale_namespace_v1(input_sale_namespace_activation_id text, database_now timestamp with time zone) RETURNS SETOF community_handle_sale_namespace_activation_revisions
    LANGUAGE sql STABLE
    AS $$
  SELECT revision.*
    FROM community_handle_sale_namespace_activation_current AS current_activation
    JOIN community_handle_sale_namespace_activation_revisions AS revision
      ON revision.sale_namespace_activation_id
          = current_activation.sale_namespace_activation_id
     AND revision.sale_namespace_activation_generation
          = current_activation.current_generation
    JOIN LATERAL current_hns_sale_namespace_dependency_v1(
      revision.community_id,
      revision.namespace_authority_reference,
      revision.namespace_authority_generation,
      revision.dns_zone_activation_id,
      revision.dns_zone_activation_generation,
      database_now
    ) AS dependency ON TRUE
   WHERE current_activation.sale_namespace_activation_id
       = input_sale_namespace_activation_id
     AND revision.status = 'active'
     AND dependency.canonical_root = revision.canonical_root
     AND dependency.display_root = revision.display_root
     AND dependency.namespace_authority_current
     AND dependency.dns_zone_current
     AND dependency.dns_delegation_current
$$;

CREATE FUNCTION effective_public_community_route_v2(expected_community_id text, database_now timestamp with time zone) RETURNS TABLE(community_id text, route_binding_id text, family text, root_label text, root_label_display text, authority_route_key_v1 text, public_path_segment text, public_href text, route_authority_kind text, authority_reference text, authority_generation bigint, verified_evidence_ref text, binding_generation bigint, evidence_expires_at timestamp with time zone)
    LANGUAGE sql STABLE
    AS $_$
  SELECT route.community_id,
         route.route_binding_id,
         route.family,
         route.root_label,
         route.root_label_display,
         route.path_segment,
         binding.public_path_segment_v2,
         binding.public_href_v2,
         route.route_authority_kind,
         route.authority_reference,
         route.authority_generation,
         route.verified_evidence_ref,
         route.binding_generation,
         route.evidence_expires_at
    FROM effective_route_authority_v2(expected_community_id, database_now) AS route
    JOIN community_canonical_route_bindings AS binding
      ON binding.route_binding_id = route.route_binding_id
     AND binding.community_id = route.community_id
     AND binding.family = route.family
     AND binding.root_label = route.root_label
     AND binding.path_segment = route.path_segment
   WHERE route.family <> 'hns'
      OR (
        route.root_label <> 'pirate'
        AND route.root_label !~ '^community_[0-9a-f]{8}-[0-9a-f]{4}-4[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$'
      )
$_$;

CREATE FUNCTION effective_route_authority_v2(expected_community_id text, database_now timestamp with time zone) RETURNS TABLE(community_id text, route_binding_id text, family text, root_label text, root_label_display text, path_segment text, href text, route_authority_kind text, authority_reference text, authority_generation bigint, verified_evidence_ref text, binding_generation bigint, evidence_expires_at timestamp with time zone)
    LANGUAGE sql STABLE
    SET search_path FROM CURRENT
    AS $$
  SELECT verified.community_id,
         verified.route_binding_id,
         verified.family,
         verified.root_label,
         verified.root_label_display,
         verified.path_segment,
         verified.href,
         'verified_namespace_v1'::TEXT,
         NULL::TEXT,
         NULL::BIGINT,
         verified.verified_evidence_ref,
         verified.binding_generation,
         verified.evidence_expires_at
    FROM effective_active_route(expected_community_id, database_now) AS verified
  UNION ALL
  SELECT community.community_id,
         binding.route_binding_id,
         binding.family,
         binding.root_label,
         binding.root_label_display,
         binding.path_segment,
         binding.href,
         binding.route_authority_kind,
         binding.authority_reference,
         binding.authority_generation,
         NULL::TEXT,
         binding.binding_generation,
         NULL::TIMESTAMPTZ
    FROM communities AS community
    JOIN community_canonical_route_bindings AS binding
      ON binding.route_binding_id = community.canonical_route_binding_id
     AND binding.community_id = community.community_id
    JOIN operator_managed_route_activations AS activation
      ON activation.operator_route_activation_id = binding.authority_reference
     AND activation.operator_route_activation_generation = binding.authority_generation
     AND activation.community_id = binding.community_id
     AND activation.route_binding_id = binding.route_binding_id
     AND activation.family = binding.family
     AND activation.canonical_root = binding.root_label
     AND activation.canonical_path_segment = binding.path_segment
     AND activation.status = 'active'
   WHERE (expected_community_id IS NULL OR community.community_id = expected_community_id)
     AND database_now IS NOT NULL
     AND community.status = 'active'
     AND binding.route_authority_kind = 'operator_managed_route_v1'
     AND binding.route_lifecycle_status = 'active'
     AND binding.ownership_status <> 'verified'
     AND binding.verified_evidence_ref IS NULL
$$;

CREATE FUNCTION enforce_song_rating_projection_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  post_rating TEXT;
  declared_rating TEXT;
BEGIN
  SELECT post.content_rating, post.author_declared_rating
    INTO post_rating, declared_rating
    FROM posts AS post
   WHERE post.community_id = NEW.community_id
     AND post.post_id = NEW.post_id
     AND post.post_type = 'song';
  IF post_rating IS NULL
     OR NEW.content_rating <> post_rating
     OR NEW.content_rating <> (
       SELECT submission.resulting_content_rating
         FROM media_post_submissions AS submission
        WHERE submission.community_id = NEW.community_id
          AND submission.submission_id = NEW.submission_id
          AND submission.operation_id = NEW.operation_id
     )
     OR declared_rating <> (
       SELECT submission.author_declared_rating
         FROM media_post_submissions AS submission
        WHERE submission.community_id = NEW.community_id
          AND submission.submission_id = NEW.submission_id
          AND submission.operation_id = NEW.operation_id
     ) THEN
    RAISE EXCEPTION 'song rating projection disagrees with durable authority';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION enforce_text_rating_ancestry_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  parent_rating TEXT;
BEGIN
  IF NEW.parent_comment_id IS NULL THEN
    SELECT post.content_rating INTO parent_rating
      FROM posts AS post
     WHERE post.community_id = NEW.community_id
       AND post.post_id = NEW.post_id
       AND post.post_type = 'text';
  ELSE
    SELECT parent.content_rating INTO parent_rating
      FROM comments AS parent
     WHERE parent.community_id = NEW.community_id
       AND parent.comment_id = NEW.parent_comment_id;
  END IF;
  IF parent_rating = 'adult_18' THEN
    NEW.content_rating := 'adult_18';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION enqueue_hns_root_import_teardown_job_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
BEGIN
  IF NEW.state = 'completed' AND OLD.state <> 'completed' THEN
    INSERT INTO hns_root_import_teardown_jobs (
      teardown_job_id, root_import_session_id
    ) VALUES (
      'teardown_' || encode(sha256(convert_to(NEW.root_import_session_id, 'UTF8')), 'hex'),
      NEW.root_import_session_id
    ) ON CONFLICT (root_import_session_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION ensure_handle_persona_public_footprint_v1(input_persona_id text, input_occurred_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    AS $$
BEGIN
  UPDATE handle_persona_public_linkage_states
     SET public_linkage_generation = CASE
           WHEN public_linkage_generation = 0 THEN 1
           ELSE public_linkage_generation
         END,
         updated_at = GREATEST(updated_at, input_occurred_at)
   WHERE persona_id = input_persona_id;
END;
$$;

CREATE FUNCTION finalize_dance_attempt_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  next_state TEXT;
BEGIN
  next_state := CASE NEW.grade_outcome
    WHEN 'scored' THEN 'completed'
    WHEN 'rejected' THEN 'rejected'
    ELSE 'processing_failed'
  END;
  UPDATE dance_attempts SET
    state = next_state,
    terminal_evidence_digest = NEW.evidence_digest,
    terminal_at = NEW.completed_at
   WHERE attempt_id = NEW.attempt_id AND state = 'grading_pending';
  IF NOT FOUND THEN RAISE EXCEPTION 'Dance attempt terminal transition lost'; END IF;
  UPDATE dance_sessions SET
    state = next_state,
    terminal_at = NEW.completed_at,
    version = version + 1
   WHERE session_id = NEW.session_id AND state = 'grading_pending';
  IF NOT FOUND THEN RAISE EXCEPTION 'Dance session terminal transition lost'; END IF;
  UPDATE dance_attempt_outbox SET
    state = 'delivered', claim_owner = NULL, lease_expires_at = NULL,
    next_eligible_at = NULL, delivered_at = NEW.completed_at,
    failure_code = NULL, updated_at = NEW.completed_at
   WHERE attempt_id = NEW.attempt_id AND state = 'running'
     AND claim_owner = NEW.claim_owner AND claim_fence = NEW.claim_fence
     AND lease_expires_at > clock_timestamp();
  IF NOT FOUND THEN RAISE EXCEPTION 'Dance outbox terminal fence lost'; END IF;
  INSERT INTO dance_media_cleanup_operations (
    cleanup_operation_id, session_id, artifact_kind, private_artifact_ref
  ) SELECT
    'dance-cleanup-' || encode(sha256(convert_to(
      NEW.session_id || ':raw_video:' || upload.private_object_key, 'UTF8')), 'hex'),
    NEW.session_id, 'raw_video', upload.private_object_key
  FROM dance_upload_reservations upload
  WHERE upload.session_id = NEW.session_id AND upload.state = 'sealed'
  ON CONFLICT (session_id, artifact_kind, private_artifact_ref) DO NOTHING;
  IF NOT FOUND THEN RAISE EXCEPTION 'Dance raw-media cleanup was not scheduled'; END IF;
  RETURN NULL;
END
$$;

CREATE FUNCTION finalize_hns_authority_provision_job_v1(input_provision_job_id text, input_executor_id text, input_lease_fence bigint, input_request_sha256 text, input_outcome text, input_publish_plan_bytes bytea, input_publish_plan_sha256 text, input_result_bytes bytea, input_result_sha256 text, input_failure_code text) RETURNS TABLE(outcome text, root_import_session_id text, session_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $_$
DECLARE
  job hns_authority_provision_jobs%ROWTYPE;
  session hns_root_import_sessions%ROWTYPE;
  database_now TIMESTAMPTZ := clock_timestamp();
  terminal_failure BOOLEAN;
BEGIN
  IF input_outcome NOT IN ('completed', 'retry', 'failed')
    OR input_request_sha256 !~ '^[0-9a-f]{64}$'
  THEN
    RAISE EXCEPTION 'invalid HNS authority provision finalization';
  END IF;
  SELECT * INTO job
    FROM hns_authority_provision_jobs
   WHERE provision_job_id = input_provision_job_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'not_found'::TEXT, NULL::TEXT, NULL::BIGINT;
    RETURN;
  END IF;
  SELECT * INTO session
    FROM hns_root_import_sessions
   WHERE hns_root_import_sessions.root_import_session_id = job.root_import_session_id
   FOR UPDATE;
  IF job.state IN ('completed', 'failed') THEN
    IF (
      job.state = 'completed'
      AND input_outcome = 'completed'
      AND job.request_sha256 = input_request_sha256
      AND job.publish_plan_bytes = input_publish_plan_bytes
      AND job.publish_plan_sha256 = input_publish_plan_sha256
      AND job.result_bytes = input_result_bytes
      AND job.result_sha256 = input_result_sha256
      AND input_failure_code IS NULL
    ) OR (
      job.state = 'failed'
      AND input_outcome = 'failed'
      AND job.request_sha256 = input_request_sha256
      AND input_publish_plan_bytes IS NULL
      AND input_publish_plan_sha256 IS NULL
      AND input_result_bytes IS NULL
      AND input_result_sha256 IS NULL
      AND job.failure_code = input_failure_code
    ) THEN
      RETURN QUERY SELECT 'replayed'::TEXT, session.root_import_session_id, session.revision;
    ELSE
      RETURN QUERY SELECT 'conflict'::TEXT, session.root_import_session_id, session.revision;
    END IF;
    RETURN;
  END IF;
  IF job.state <> 'leased'
    OR job.leased_by <> input_executor_id
    OR job.lease_fence <> input_lease_fence
    OR job.lease_expires_at <= database_now
    OR job.request_sha256 <> input_request_sha256
    OR session.status <> 'provisioning'
    OR session.expires_at <= database_now
  THEN
    RETURN QUERY SELECT 'lost'::TEXT, session.root_import_session_id, session.revision;
    RETURN;
  END IF;

  IF input_outcome = 'completed' THEN
    IF input_publish_plan_bytes IS NULL
      OR input_publish_plan_sha256 IS NULL
      OR input_result_bytes IS NULL
      OR input_result_sha256 IS NULL
      OR octet_length(input_publish_plan_bytes) NOT BETWEEN 1 AND 1048576
      OR input_publish_plan_sha256 !~ '^[0-9a-f]{64}$'
      OR encode(sha256(input_publish_plan_bytes), 'hex') <> input_publish_plan_sha256
      OR octet_length(input_result_bytes) NOT BETWEEN 1 AND 1048576
      OR input_result_sha256 !~ '^[0-9a-f]{64}$'
      OR encode(sha256(input_result_bytes), 'hex') <> input_result_sha256
      OR input_failure_code IS NOT NULL
    THEN
      RAISE EXCEPTION 'invalid completed HNS authority provision result';
    END IF;
    UPDATE hns_authority_provision_jobs
       SET state = 'completed', leased_by = NULL, lease_expires_at = NULL,
           publish_plan_bytes = input_publish_plan_bytes,
           publish_plan_sha256 = input_publish_plan_sha256,
           result_bytes = input_result_bytes, result_sha256 = input_result_sha256,
           completed_at = database_now, updated_at = database_now
     WHERE hns_authority_provision_jobs.provision_job_id = input_provision_job_id;
    UPDATE hns_root_import_sessions
       SET status = 'awaiting_owner_update', revision = session.revision + 1,
           publish_plan_bytes = input_publish_plan_bytes,
           publish_plan_sha256 = input_publish_plan_sha256,
           updated_at = database_now
     WHERE hns_root_import_sessions.root_import_session_id = session.root_import_session_id;
    RETURN QUERY
      SELECT 'completed'::TEXT, session.root_import_session_id, session.revision + 1;
    RETURN;
  END IF;
  IF input_publish_plan_bytes IS NOT NULL
    OR input_publish_plan_sha256 IS NOT NULL
    OR input_result_bytes IS NOT NULL
    OR input_result_sha256 IS NOT NULL
    OR input_failure_code IS NULL
    OR btrim(input_failure_code) <> input_failure_code
    OR octet_length(input_failure_code) NOT BETWEEN 1 AND 128
    OR input_failure_code ~ '[[:cntrl:]]'
  THEN
    RAISE EXCEPTION 'invalid failed HNS authority provision result';
  END IF;
  terminal_failure := input_outcome = 'failed' OR job.attempt_count >= 5;
  IF terminal_failure THEN
    UPDATE hns_authority_provision_jobs
       SET state = 'failed', leased_by = NULL, lease_expires_at = NULL,
           failure_code = input_failure_code,
           completed_at = database_now, updated_at = database_now
     WHERE hns_authority_provision_jobs.provision_job_id = input_provision_job_id;
    UPDATE hns_root_import_sessions
       SET status = 'failed', revision = session.revision + 1,
           updated_at = database_now
     WHERE hns_root_import_sessions.root_import_session_id = session.root_import_session_id;
    RETURN QUERY
      SELECT 'failed'::TEXT, session.root_import_session_id, session.revision + 1;
  ELSE
    UPDATE hns_authority_provision_jobs
       SET state = 'queued', leased_by = NULL, lease_expires_at = NULL,
           failure_code = input_failure_code, updated_at = database_now
     WHERE hns_authority_provision_jobs.provision_job_id = input_provision_job_id;
    RETURN QUERY SELECT 'retry'::TEXT, session.root_import_session_id, session.revision;
  END IF;
END;
$_$;

CREATE FUNCTION finalize_hns_dns_zone_activation_v1(input_operation_id text, input_fence_token bigint, input_activation_document_bytes bytea, input_dns_zone_activation_id text, input_canonical_root text, input_dns_authority_kind text, input_dns_authority_reference text, input_dns_authority_generation bigint, input_inventory_reference text, input_inventory_version text, input_inventory_digest text, input_zone_revision bigint, input_zone_bytes bytea, input_zone_bytes_digest text, input_dnssec_keyset_reference text, input_dnssec_keyset_version text, input_gateway_deployment_reference text, input_gateway_certificate_spki_sha256 text, input_delegation_snapshot_reference text, input_delegation_snapshot_digest text) RETURNS TABLE(outcome text, dns_zone_activation_id text, activation_generation bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
  operation hns_dns_zone_activation_operations%ROWTYPE;
  current_record hns_dns_zone_activation_current%ROWTYPE;
  prior_revision hns_dns_zone_activation_revisions%ROWTYPE;
  result_revision hns_dns_zone_activation_revisions%ROWTYPE;
  inventory hns_authority_inventories%ROWTYPE;
  activation_document JSONB;
  database_now TIMESTAMPTZ := clock_timestamp();
  new_generation BIGINT;
BEGIN
  activation_document := convert_from(input_activation_document_bytes, 'UTF8')::JSONB;
  IF activation_document IS DISTINCT FROM jsonb_build_object(
    'version', 'pirate-hns-dns-zone-activation-document-v1',
    'dns_zone_activation_id', input_dns_zone_activation_id,
    'canonical_root', input_canonical_root,
    'dns_authority', jsonb_build_array(
      input_dns_authority_kind,
      input_dns_authority_reference,
      input_dns_authority_generation
    ),
    'pirate_dns_authority_inventory', jsonb_build_array(
      input_inventory_reference,
      input_inventory_version,
      input_inventory_digest
    ),
    'zone', jsonb_build_array(input_zone_revision, input_zone_bytes_digest),
    'dnssec_keyset', jsonb_build_array(
      input_dnssec_keyset_reference,
      input_dnssec_keyset_version
    ),
    'gateway', jsonb_build_array(
      input_gateway_deployment_reference,
      input_gateway_certificate_spki_sha256
    ),
    'stable_chain_delegation_snapshot', jsonb_build_array(
      input_delegation_snapshot_reference,
      input_delegation_snapshot_digest
    )
  ) THEN
    RAISE EXCEPTION 'HNS DNS activation document does not match its authority fields';
  END IF;

  SELECT * INTO operation
    FROM hns_dns_zone_activation_operations AS stored_operation
   WHERE stored_operation.operation_id = input_operation_id
   FOR UPDATE;
  IF NOT FOUND OR operation.dns_zone_activation_id <> input_dns_zone_activation_id
    OR operation.activation_document_digest <> encode(sha256(input_activation_document_bytes), 'hex') THEN
    RAISE EXCEPTION 'HNS DNS activation finalizer authority mismatch';
  END IF;

  IF operation.state = 'finalized' THEN
    SELECT * INTO result_revision
      FROM hns_dns_zone_activation_revisions AS revision
     WHERE revision.dns_zone_activation_id = operation.dns_zone_activation_id
       AND revision.dns_zone_activation_generation = operation.result_activation_generation;
    IF NOT FOUND
      OR result_revision.activation_document_bytes IS DISTINCT FROM input_activation_document_bytes
      OR result_revision.canonical_root <> input_canonical_root
      OR result_revision.dns_authority_reference <> input_dns_authority_reference
      OR result_revision.zone_bytes IS DISTINCT FROM input_zone_bytes
      OR result_revision.gateway_deployment_reference <> input_gateway_deployment_reference
      OR result_revision.stable_chain_delegation_snapshot_digest <> input_delegation_snapshot_digest THEN
      RAISE EXCEPTION 'HNS DNS activation replay does not match retained authority';
    END IF;
    RETURN QUERY SELECT 'replayed'::TEXT, operation.dns_zone_activation_id,
      operation.result_activation_generation;
    RETURN;
  END IF;

  IF operation.state <> 'reserved'
    OR operation.fence_token <> input_fence_token
    OR operation.lease_expires_at <= database_now THEN
    RAISE EXCEPTION 'HNS DNS activation finalizer lost its lease or fence';
  END IF;

  SELECT * INTO inventory
    FROM hns_authority_inventories AS retained_inventory
   WHERE retained_inventory.authority_inventory_reference = input_inventory_reference
     AND retained_inventory.authority_inventory_version = input_inventory_version
     AND retained_inventory.authority_inventory_digest = input_inventory_digest
   FOR SHARE;
  IF NOT FOUND OR inventory.published_at > database_now OR inventory.expires_at <= database_now THEN
    RAISE EXCEPTION 'HNS DNS activation inventory is unavailable';
  END IF;

  SELECT * INTO current_record
    FROM hns_dns_zone_activation_current AS current_authority
   WHERE current_authority.dns_zone_activation_id = input_dns_zone_activation_id
      OR current_authority.canonical_root = input_canonical_root
   FOR UPDATE;
  IF operation.expected_activation_generation = 0 THEN
    IF FOUND THEN
      RAISE EXCEPTION 'HNS DNS activation root already has authority';
    END IF;
  ELSE
    IF NOT FOUND
      OR current_record.dns_zone_activation_id <> input_dns_zone_activation_id
      OR current_record.canonical_root <> input_canonical_root
      OR current_record.current_generation <> operation.expected_activation_generation THEN
      RAISE EXCEPTION 'HNS DNS activation generation fence does not match';
    END IF;
    SELECT * INTO prior_revision
      FROM hns_dns_zone_activation_revisions AS revision
     WHERE revision.dns_zone_activation_id = current_record.dns_zone_activation_id
       AND revision.dns_zone_activation_generation = current_record.current_generation;
    IF prior_revision.status = 'revoked' OR input_zone_revision <= prior_revision.zone_revision THEN
      RAISE EXCEPTION 'HNS DNS activation rotation is not monotonic';
    END IF;
  END IF;

  new_generation := operation.expected_activation_generation + 1;
  INSERT INTO hns_dns_zone_activation_revisions (
    dns_zone_activation_id, dns_zone_activation_generation,
    activation_document_bytes, activation_document_digest, canonical_root,
    dns_authority_kind, dns_authority_reference, dns_authority_generation,
    pirate_dns_authority_inventory_reference, pirate_dns_authority_inventory_version,
    pirate_dns_authority_inventory_digest, zone_revision, zone_bytes, zone_bytes_digest,
    dnssec_keyset_reference, dnssec_keyset_version, gateway_deployment_reference,
    gateway_certificate_spki_sha256, stable_chain_delegation_snapshot_reference,
    stable_chain_delegation_snapshot_digest, status, activated_at
  ) VALUES (
    input_dns_zone_activation_id, new_generation,
    input_activation_document_bytes, operation.activation_document_digest, input_canonical_root,
    input_dns_authority_kind, input_dns_authority_reference, input_dns_authority_generation,
    input_inventory_reference, input_inventory_version, input_inventory_digest,
    input_zone_revision, input_zone_bytes, input_zone_bytes_digest,
    input_dnssec_keyset_reference, input_dnssec_keyset_version,
    input_gateway_deployment_reference, input_gateway_certificate_spki_sha256,
    input_delegation_snapshot_reference, input_delegation_snapshot_digest,
    'active', database_now
  );

  IF operation.expected_activation_generation = 0 THEN
    INSERT INTO hns_dns_zone_activation_current (
      dns_zone_activation_id, canonical_root, current_generation, updated_at
    ) VALUES (input_dns_zone_activation_id, input_canonical_root, new_generation, database_now);
  ELSE
    UPDATE hns_dns_zone_activation_current AS current_authority
       SET current_generation = new_generation, updated_at = database_now
     WHERE current_authority.dns_zone_activation_id = input_dns_zone_activation_id;
  END IF;

  UPDATE hns_dns_zone_activation_operations AS stored_operation
     SET state = 'finalized', result_activation_generation = new_generation,
         finalized_at = database_now, updated_at = database_now
   WHERE stored_operation.operation_id = input_operation_id;
  SET CONSTRAINTS ALL IMMEDIATE;
  RETURN QUERY SELECT 'activated'::TEXT, input_dns_zone_activation_id, new_generation;
END;
$$;

CREATE FUNCTION finalize_hns_root_import_observation_job_v1(input_observation_job_id text, input_executor_id text, input_lease_fence bigint, input_request_sha256 text, input_outcome text, input_result_bytes bytea, input_result_sha256 text, input_failure_code text) RETURNS TABLE(outcome text, root_import_session_id text, session_revision bigint)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $_$
DECLARE
  job hns_root_import_observation_jobs%ROWTYPE;
  teardown hns_root_import_teardown_jobs%ROWTYPE;
  session hns_root_import_sessions%ROWTYPE;
  provision hns_authority_provision_jobs%ROWTYPE;
  database_now TIMESTAMPTZ := clock_timestamp();
BEGIN
  IF input_outcome NOT IN ('ready', 'retry', 'failed') THEN
    RAISE EXCEPTION 'invalid HNS root observation finalization';
  END IF;
  SELECT * INTO teardown
    FROM hns_root_import_teardown_jobs
   WHERE teardown_job_id = input_observation_job_id
   FOR UPDATE;
  IF FOUND THEN
    SELECT * INTO session
      FROM hns_root_import_sessions
     WHERE hns_root_import_sessions.root_import_session_id = teardown.root_import_session_id
     FOR UPDATE;
    SELECT * INTO provision
      FROM hns_authority_provision_jobs
     WHERE provision_job_id = session.provision_job_id
     FOR SHARE;
    IF teardown.state IN ('completed', 'failed', 'cancelled') THEN
      IF teardown.state = 'completed'
        AND input_outcome = 'failed'
        AND input_request_sha256 = provision.request_sha256
        AND input_result_bytes IS NULL
        AND input_result_sha256 IS NULL
        AND input_failure_code = 'session_expired'
      THEN
        RETURN QUERY SELECT 'replayed'::TEXT, session.root_import_session_id, session.revision;
      ELSE
        RETURN QUERY SELECT 'conflict'::TEXT, session.root_import_session_id, session.revision;
      END IF;
      RETURN;
    END IF;
    IF teardown.state <> 'leased'
      OR teardown.leased_by <> input_executor_id
      OR teardown.lease_fence <> input_lease_fence
      OR teardown.lease_expires_at <= database_now
      OR provision.request_sha256 <> input_request_sha256
      OR NOT (
        session.status IN ('failed', 'expired')
        OR (
          session.status IN ('awaiting_owner_update', 'observing', 'ready')
          AND session.expires_at <= database_now
        )
      )
      OR input_outcome = 'ready'
      OR input_result_bytes IS NOT NULL
      OR input_result_sha256 IS NOT NULL
      OR input_failure_code IS NULL
      OR btrim(input_failure_code) <> input_failure_code
      OR octet_length(input_failure_code) NOT BETWEEN 1 AND 128
      OR input_failure_code ~ '[[:cntrl:]]'
    THEN
      RETURN QUERY SELECT 'lost'::TEXT, session.root_import_session_id, session.revision;
      RETURN;
    END IF;
    IF input_outcome = 'retry' AND teardown.attempt_count < 20 THEN
      UPDATE hns_root_import_teardown_jobs
         SET state = 'waiting', leased_by = NULL, lease_expires_at = NULL,
             failure_code = input_failure_code, updated_at = database_now
       WHERE teardown_job_id = input_observation_job_id;
      RETURN QUERY SELECT 'retry'::TEXT, session.root_import_session_id, session.revision;
      RETURN;
    END IF;
    IF input_outcome = 'failed' AND input_failure_code = 'session_expired' THEN
      UPDATE hns_root_import_teardown_jobs
         SET state = 'completed', leased_by = NULL, lease_expires_at = NULL,
             failure_code = NULL, completed_at = database_now, updated_at = database_now
       WHERE teardown_job_id = input_observation_job_id;
      UPDATE hns_root_import_observation_jobs AS observation
         SET state = 'failed', leased_by = NULL, lease_expires_at = NULL,
             failure_code = 'session_expired', completed_at = database_now,
             updated_at = database_now
       WHERE observation.root_import_session_id = session.root_import_session_id
         AND observation.state IN ('queued', 'leased');
      IF session.status NOT IN ('failed', 'expired') THEN
        UPDATE hns_root_import_sessions
           SET status = 'expired', revision = session.revision + 1,
               updated_at = database_now
         WHERE hns_root_import_sessions.root_import_session_id = session.root_import_session_id;
        RETURN QUERY SELECT 'failed'::TEXT, session.root_import_session_id,
                            session.revision + 1;
      ELSE
        RETURN QUERY SELECT 'failed'::TEXT, session.root_import_session_id, session.revision;
      END IF;
      RETURN;
    END IF;
    UPDATE hns_root_import_teardown_jobs
       SET state = 'failed', leased_by = NULL, lease_expires_at = NULL,
           failure_code = CASE
             WHEN teardown.attempt_count >= 20 THEN 'zone_teardown_attempts_exhausted'
             ELSE input_failure_code
           END,
           completed_at = database_now, updated_at = database_now
     WHERE teardown_job_id = input_observation_job_id;
    IF session.status NOT IN ('failed', 'expired') THEN
      UPDATE hns_root_import_sessions
         SET status = 'expired', revision = session.revision + 1,
             updated_at = database_now
       WHERE hns_root_import_sessions.root_import_session_id = session.root_import_session_id;
      RETURN QUERY SELECT 'failed'::TEXT, session.root_import_session_id,
                          session.revision + 1;
    ELSE
      RETURN QUERY SELECT 'failed'::TEXT, session.root_import_session_id, session.revision;
    END IF;
    RETURN;
  END IF;
  SELECT * INTO job
    FROM hns_root_import_observation_jobs
   WHERE observation_job_id = input_observation_job_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'not_found'::TEXT, NULL::TEXT, NULL::BIGINT;
    RETURN;
  END IF;
  SELECT * INTO session
    FROM hns_root_import_sessions
   WHERE hns_root_import_sessions.root_import_session_id = job.root_import_session_id
   FOR UPDATE;
  IF job.state IN ('completed', 'failed') THEN
    IF job.state = 'completed'
      AND input_outcome = 'ready'
      AND job.request_sha256 = input_request_sha256
      AND job.result_bytes = input_result_bytes
      AND job.result_sha256 = input_result_sha256
      AND input_failure_code IS NULL
    THEN
      RETURN QUERY SELECT 'replayed'::TEXT, session.root_import_session_id, session.revision;
    ELSE
      RETURN QUERY SELECT 'conflict'::TEXT, session.root_import_session_id, session.revision;
    END IF;
    RETURN;
  END IF;
  IF job.state <> 'leased'
    OR job.leased_by <> input_executor_id
    OR job.lease_fence <> input_lease_fence
    OR job.lease_expires_at <= database_now
    OR job.request_sha256 <> input_request_sha256
    OR session.status <> 'observing'
    OR session.expires_at <= database_now
  THEN
    RETURN QUERY SELECT 'lost'::TEXT, session.root_import_session_id, session.revision;
    RETURN;
  END IF;
  IF input_outcome = 'ready' THEN
    IF input_result_bytes IS NULL
      OR input_result_sha256 !~ '^[0-9a-f]{64}$'
      OR encode(sha256(input_result_bytes), 'hex') <> input_result_sha256
      OR input_failure_code IS NOT NULL
    THEN
      RAISE EXCEPTION 'invalid ready HNS root observation result';
    END IF;
    UPDATE hns_root_import_observation_jobs
       SET state = 'completed', leased_by = NULL, lease_expires_at = NULL,
           result_bytes = input_result_bytes, result_sha256 = input_result_sha256,
           failure_code = NULL, completed_at = database_now, updated_at = database_now
     WHERE observation_job_id = input_observation_job_id;
    UPDATE hns_root_import_sessions
       SET status = 'ready', revision = session.revision + 1,
           readiness_result_bytes = input_result_bytes,
           readiness_result_sha256 = input_result_sha256,
           updated_at = database_now
     WHERE hns_root_import_sessions.root_import_session_id = session.root_import_session_id;
    RETURN QUERY SELECT 'ready'::TEXT, session.root_import_session_id, session.revision + 1;
    RETURN;
  END IF;
  IF input_result_bytes IS NOT NULL OR input_result_sha256 IS NOT NULL
    OR input_failure_code IS NULL
    OR btrim(input_failure_code) <> input_failure_code
    OR octet_length(input_failure_code) NOT BETWEEN 1 AND 128
    OR input_failure_code ~ '[[:cntrl:]]'
  THEN
    RAISE EXCEPTION 'invalid failed HNS root observation result';
  END IF;
  IF input_outcome = 'failed' OR job.attempt_count >= 20 THEN
    UPDATE hns_root_import_observation_jobs
       SET state = 'failed', leased_by = NULL, lease_expires_at = NULL,
           failure_code = CASE
             WHEN job.attempt_count >= 20 THEN 'observation_attempts_exhausted'
             ELSE input_failure_code
           END,
           completed_at = database_now, updated_at = database_now
     WHERE observation_job_id = input_observation_job_id;
    UPDATE hns_root_import_sessions
       SET status = 'failed', revision = session.revision + 1,
           updated_at = database_now
     WHERE hns_root_import_sessions.root_import_session_id = session.root_import_session_id;
    RETURN QUERY SELECT 'failed'::TEXT, session.root_import_session_id, session.revision + 1;
  ELSE
    UPDATE hns_root_import_observation_jobs
       SET state = 'queued', leased_by = NULL, lease_expires_at = NULL,
           failure_code = input_failure_code, updated_at = database_now
     WHERE observation_job_id = input_observation_job_id;
    RETURN QUERY SELECT 'retry'::TEXT, session.root_import_session_id, session.revision;
  END IF;
END;
$_$;

CREATE FUNCTION finalize_hns_root_import_ownership_v1(input_actor_id text, input_creation_intent_id text, input_root_import_session_id text, input_expected_revision bigint, input_ownership_status text, input_ownership_result_sha256 text) RETURNS TABLE(outcome text, root_import_session_id text, session_revision bigint)
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $_$
DECLARE
  session hns_root_import_sessions%ROWTYPE;
  ownership_result community_creation_ceremony_results%ROWTYPE;
  target_status TEXT;
  database_now TIMESTAMPTZ := clock_timestamp();
BEGIN
  IF input_ownership_status NOT IN ('rejected', 'expired')
    OR input_ownership_result_sha256 !~ '^[0-9a-f]{64}$'
  THEN
    RAISE EXCEPTION 'invalid HNS root-import ownership finalization';
  END IF;
  target_status := CASE input_ownership_status WHEN 'expired' THEN 'expired' ELSE 'failed' END;
  SELECT * INTO session
    FROM hns_root_import_sessions
   WHERE actor_id = input_actor_id
     AND creation_intent_id = input_creation_intent_id
     AND hns_root_import_sessions.root_import_session_id = input_root_import_session_id
   FOR UPDATE;
  IF NOT FOUND THEN
    RETURN QUERY SELECT 'not_found'::TEXT, NULL::TEXT, NULL::BIGINT;
    RETURN;
  END IF;
  IF session.status IN ('failed', 'expired') THEN
    IF session.status = target_status
      AND session.ownership_result_sha256 = input_ownership_result_sha256
    THEN
      RETURN QUERY SELECT 'replayed'::TEXT, session.root_import_session_id, session.revision;
    ELSE
      RETURN QUERY SELECT 'conflict'::TEXT, session.root_import_session_id, session.revision;
    END IF;
    RETURN;
  END IF;
  SELECT * INTO ownership_result
    FROM community_creation_ceremony_results
   WHERE ceremony_intent_id = session.ceremony_intent_id
     AND namespace_session_id = session.namespace_session_id
   FOR SHARE;
  IF session.status NOT IN ('awaiting_ownership', 'awaiting_owner_update')
    OR session.revision <> input_expected_revision
    OR session.ownership_result_sha256 IS NOT NULL
    OR ownership_result.result_hash <> input_ownership_result_sha256
    OR ownership_result.outcome_status <> target_status
  THEN
    RETURN QUERY SELECT 'conflict'::TEXT, session.root_import_session_id, session.revision;
    RETURN;
  END IF;
  UPDATE hns_root_import_sessions
     SET status = target_status, revision = session.revision + 1,
         ownership_result_sha256 = input_ownership_result_sha256,
         updated_at = database_now
   WHERE hns_root_import_sessions.root_import_session_id = session.root_import_session_id;
  RETURN QUERY SELECT target_status, session.root_import_session_id, session.revision + 1;
END;
$_$;

CREATE FUNCTION gates_v2_active_binding_projection_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF pg_trigger_depth() < 2 THEN
    RAISE EXCEPTION 'active subject key bindings are trigger-maintained'
      USING ERRCODE = '23514', CONSTRAINT = 'active_subject_key_bindings_projection_only';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION gates_v2_append_only_guard() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION '% is append-only', TG_TABLE_NAME
    USING ERRCODE = '23514', CONSTRAINT = 'gates_v2_append_only';
END;
$$;

CREATE FUNCTION gates_v2_project_subject_key_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO active_subject_key_bindings (
    subject_key_id,
    binding_event_id,
    binding_epoch,
    user_id,
    activated_at,
    updated_at
  ) VALUES (
    NEW.subject_key_id,
    NEW.binding_event_id,
    NEW.binding_epoch,
    NEW.user_id,
    NEW.bound_at,
    now()
  )
  ON CONFLICT (subject_key_id) DO UPDATE SET
    binding_event_id = EXCLUDED.binding_event_id,
    binding_epoch = EXCLUDED.binding_epoch,
    user_id = EXCLUDED.user_id,
    activated_at = EXCLUDED.activated_at,
    updated_at = now();
  RETURN NEW;
END;
$$;

CREATE FUNCTION gates_v2_require_terminal_completion_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status <> 'pending' AND NOT EXISTS (
    SELECT 1
      FROM proof_session_completion_events
     WHERE proof_session_id = NEW.proof_session_id
       AND actor_id = NEW.actor_id
       AND terminal_status = NEW.status
       AND idempotency_key = NEW.completion_idempotency_key
       AND result_hash = NEW.completion_result_hash
       AND terminal_at = NEW.terminal_at
  ) THEN
    RAISE EXCEPTION 'terminal proof session requires its matching completion event'
      USING ERRCODE = '23514', CONSTRAINT = 'proof_sessions_terminal_completion_event';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION gates_v2_validate_assertion_binding() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  binding_mode_value TEXT;
  binding_subject_key_id TEXT;
  binding_receipt_id TEXT;
  binding_event_id TEXT;
  binding_epoch BIGINT;
  receipt_subject_key_id TEXT;
  receipt_binding_event_id TEXT;
  receipt_binding_epoch BIGINT;
BEGIN
  SELECT
      binding_mode,
      subject_key_id,
      evidence_receipt_id,
      subject_binding_event_id,
      subject_binding_epoch
    INTO
      binding_mode_value,
      binding_subject_key_id,
      binding_receipt_id,
      binding_event_id,
      binding_epoch
    FROM assertion_bindings
   WHERE binding_group_id = NEW.binding_group_id
     AND user_id = NEW.user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'assertion binding group is missing or belongs to another user'
      USING ERRCODE = '23503';
  END IF;

  SELECT subject_key_id, subject_binding_event_id, subject_binding_epoch
    INTO receipt_subject_key_id, receipt_binding_event_id, receipt_binding_epoch
    FROM evidence_receipts
   WHERE evidence_receipt_id = NEW.evidence_receipt_id
     AND user_id = NEW.user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'assertion evidence receipt is missing or belongs to another user'
      USING ERRCODE = '23503';
  END IF;

  IF NEW.subject_key_id IS DISTINCT FROM receipt_subject_key_id THEN
    RAISE EXCEPTION 'assertion subject key must match its evidence receipt subject key'
      USING ERRCODE = '23514', CONSTRAINT = 'assertions_receipt_subject_match';
  END IF;

  IF binding_mode_value = 'same_subject'
    AND (
      NEW.subject_key_id IS DISTINCT FROM binding_subject_key_id
      OR binding_event_id IS DISTINCT FROM receipt_binding_event_id
      OR binding_epoch IS DISTINCT FROM receipt_binding_epoch
    ) THEN
    RAISE EXCEPTION 'assertion subject binding must match its receipt binding epoch'
      USING ERRCODE = '23514', CONSTRAINT = 'assertions_same_subject_binding_match';
  END IF;

  IF binding_mode_value = 'same_receipt'
    AND NEW.evidence_receipt_id IS DISTINCT FROM binding_receipt_id THEN
    RAISE EXCEPTION 'assertion receipt must match its same-receipt binding anchor'
      USING ERRCODE = '23514', CONSTRAINT = 'assertions_same_receipt_binding_match';
  END IF;

  RETURN NEW;
END;
$$;

CREATE FUNCTION gates_v2_validate_evidence_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  session_record proof_sessions%ROWTYPE;
  subject_record subject_keys%ROWTYPE;
  active_binding active_subject_key_bindings%ROWTYPE;
BEGIN
  SELECT * INTO session_record
    FROM proof_sessions
   WHERE proof_session_id = NEW.proof_session_id
     AND actor_id = NEW.user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'evidence receipt session is missing or belongs to another user'
      USING ERRCODE = '23503';
  END IF;

  IF NEW.provider_id IS DISTINCT FROM session_record.provider_id
    OR NEW.provider_configuration_kind IS DISTINCT FROM session_record.provider_configuration_kind
    OR NEW.provider_configuration_ref IS DISTINCT FROM session_record.provider_configuration_ref
    OR NEW.provider_configuration_version IS DISTINCT FROM session_record.provider_configuration_version
    OR NEW.issuer IS DISTINCT FROM session_record.issuer
    OR NEW.method IS DISTINCT FROM session_record.method
    OR NEW.scope_kind IS DISTINCT FROM session_record.scope_kind
    OR NEW.issuer_rp_scope IS DISTINCT FROM session_record.issuer_rp_scope
    OR NEW.issuer_rp_action_scope IS DISTINCT FROM session_record.issuer_rp_action_scope
    OR NEW.protocol_version IS DISTINCT FROM session_record.protocol_version
    OR NEW.environment IS DISTINCT FROM session_record.environment THEN
    RAISE EXCEPTION 'evidence receipt metadata must match its proof session'
      USING ERRCODE = '23514', CONSTRAINT = 'evidence_receipts_session_metadata_match';
  END IF;

  IF NEW.subject_key_id IS NOT NULL THEN
    SELECT * INTO subject_record
      FROM subject_keys
     WHERE subject_key_id = NEW.subject_key_id;

    IF NOT FOUND THEN
      RAISE EXCEPTION 'evidence receipt subject key is missing'
        USING ERRCODE = '23503';
    END IF;

    IF NEW.issuer IS DISTINCT FROM subject_record.issuer
      OR NEW.method IS DISTINCT FROM subject_record.method
      OR NEW.scope_kind IS DISTINCT FROM subject_record.scope_kind
      OR NEW.issuer_rp_scope IS DISTINCT FROM subject_record.issuer_rp_scope
      OR NEW.issuer_rp_action_scope IS DISTINCT FROM subject_record.issuer_rp_action_scope THEN
      RAISE EXCEPTION 'evidence receipt metadata must match its subject key'
        USING ERRCODE = '23514', CONSTRAINT = 'evidence_receipts_subject_metadata_match';
    END IF;

    SELECT * INTO active_binding
      FROM active_subject_key_bindings
     WHERE subject_key_id = NEW.subject_key_id;

    IF NOT FOUND
      OR active_binding.binding_event_id IS DISTINCT FROM NEW.subject_binding_event_id
      OR active_binding.binding_epoch IS DISTINCT FROM NEW.subject_binding_epoch
      OR active_binding.user_id IS DISTINCT FROM NEW.user_id THEN
      RAISE EXCEPTION 'evidence receipt must use the active subject binding epoch'
        USING ERRCODE = '23514', CONSTRAINT = 'evidence_receipts_active_binding_match';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

CREATE FUNCTION gates_v2_validate_proof_session_completion_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  session_record proof_sessions%ROWTYPE;
BEGIN
  SELECT * INTO session_record
    FROM proof_sessions
   WHERE proof_session_id = NEW.proof_session_id
     AND actor_id = NEW.actor_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'completion event session is missing or belongs to another actor'
      USING ERRCODE = '23503';
  END IF;

  IF session_record.status IS DISTINCT FROM NEW.terminal_status
    OR session_record.completion_idempotency_key IS DISTINCT FROM NEW.idempotency_key
    OR session_record.completion_result_hash IS DISTINCT FROM NEW.result_hash
    OR session_record.terminal_at IS DISTINCT FROM NEW.terminal_at THEN
    RAISE EXCEPTION 'completion event must match the terminal proof session'
      USING ERRCODE = '23514', CONSTRAINT = 'proof_session_completion_events_session_match';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION gates_v2_validate_proof_session_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'proof sessions cannot be deleted'
      USING ERRCODE = '23514', CONSTRAINT = 'proof_sessions_lifecycle';
  END IF;

  IF jsonb_typeof(NEW.requested_requirements) IS DISTINCT FROM 'array'
    OR jsonb_array_length(NEW.requested_requirements) = 0
    OR EXISTS (
      SELECT 1
        FROM jsonb_array_elements(NEW.requested_requirements) AS requirement(value)
       WHERE jsonb_typeof(requirement.value) IS DISTINCT FROM 'object'
          OR jsonb_typeof(requirement.value -> 'claim_id') IS DISTINCT FROM 'string'
          OR btrim(requirement.value ->> 'claim_id') = ''
    )
    OR (
      SELECT count(*)
        FROM jsonb_array_elements(NEW.requested_requirements)
    ) IS DISTINCT FROM (
      SELECT count(DISTINCT requirement.value ->> 'claim_id')
        FROM jsonb_array_elements(NEW.requested_requirements) AS requirement(value)
    )
    OR (
      SELECT jsonb_agg(requirement.value -> 'claim_id' ORDER BY requirement.ordinality)
        FROM jsonb_array_elements(NEW.requested_requirements)
          WITH ORDINALITY AS requirement(value, ordinality)
    ) IS DISTINCT FROM NEW.requested_claim_ids THEN
    RAISE EXCEPTION 'proof-session requirements must project exactly to requested claims'
      USING ERRCODE = '23514', CONSTRAINT = 'proof_sessions_requested_requirements_projection';
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'pending' THEN
      RAISE EXCEPTION 'proof sessions must begin pending'
        USING ERRCODE = '23514', CONSTRAINT = 'proof_sessions_lifecycle';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.proof_session_id IS DISTINCT FROM OLD.proof_session_id
    OR NEW.actor_id IS DISTINCT FROM OLD.actor_id
    OR NEW.intent_id IS DISTINCT FROM OLD.intent_id
    OR NEW.request_hash IS DISTINCT FROM OLD.request_hash
    OR NEW.provider_id IS DISTINCT FROM OLD.provider_id
    OR NEW.provider_configuration_kind IS DISTINCT FROM OLD.provider_configuration_kind
    OR NEW.provider_configuration_ref IS DISTINCT FROM OLD.provider_configuration_ref
    OR NEW.provider_configuration_version IS DISTINCT FROM OLD.provider_configuration_version
    OR NEW.method IS DISTINCT FROM OLD.method
    OR NEW.issuer IS DISTINCT FROM OLD.issuer
    OR NEW.scope_kind IS DISTINCT FROM OLD.scope_kind
    OR NEW.issuer_rp_scope IS DISTINCT FROM OLD.issuer_rp_scope
    OR NEW.issuer_rp_action_scope IS DISTINCT FROM OLD.issuer_rp_action_scope
    OR NEW.request_mode IS DISTINCT FROM OLD.request_mode
    OR NEW.protocol_version IS DISTINCT FROM OLD.protocol_version
    OR NEW.environment IS DISTINCT FROM OLD.environment
    OR NEW.upstream_session_ref IS DISTINCT FROM OLD.upstream_session_ref
    OR NEW.requested_requirements IS DISTINCT FROM OLD.requested_requirements
    OR NEW.requested_claim_ids IS DISTINCT FROM OLD.requested_claim_ids
    OR NEW.subject_binding_intent IS DISTINCT FROM OLD.subject_binding_intent
    OR NEW.started_at IS DISTINCT FROM OLD.started_at
    OR NEW.expires_at IS DISTINCT FROM OLD.expires_at
    OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'proof session identity is immutable'
      USING ERRCODE = '23514', CONSTRAINT = 'proof_sessions_lifecycle';
  END IF;

  IF OLD.status <> 'pending' THEN
    RAISE EXCEPTION 'terminal proof sessions are immutable'
      USING ERRCODE = '23514', CONSTRAINT = 'proof_sessions_lifecycle';
  END IF;

  IF NEW.status = 'pending' THEN
    RETURN NEW;
  END IF;

  IF NEW.status NOT IN ('completed', 'failed', 'expired') THEN
    RAISE EXCEPTION 'invalid proof session transition'
      USING ERRCODE = '23514', CONSTRAINT = 'proof_sessions_lifecycle';
  END IF;

  RETURN NEW;
END;
$$;

CREATE FUNCTION gates_v2_validate_reward_subject_consumption() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  authority reward_uniqueness_authorities%ROWTYPE;
  subject_record subject_keys%ROWTYPE;
BEGIN
  SELECT * INTO authority
    FROM reward_uniqueness_authorities
   WHERE campaign_id = NEW.campaign_id;
  SELECT * INTO subject_record
    FROM subject_keys
   WHERE subject_key_id = NEW.subject_key_id;

  IF authority.issuer IS DISTINCT FROM subject_record.issuer
    OR authority.method IS DISTINCT FROM subject_record.method
    OR authority.scope_kind IS DISTINCT FROM subject_record.scope_kind
    OR authority.issuer_rp_scope IS DISTINCT FROM subject_record.issuer_rp_scope
    OR authority.issuer_rp_action_scope IS DISTINCT FROM subject_record.issuer_rp_action_scope THEN
    RAISE EXCEPTION 'reward subject must match the campaign uniqueness authority'
      USING ERRCODE = '23514', CONSTRAINT = 'reward_subject_consumptions_authority_match';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION gates_v2_validate_subject_key_binding_event() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  current_binding active_subject_key_bindings%ROWTYPE;
  session_record proof_sessions%ROWTYPE;
BEGIN
  PERFORM 1
    FROM subject_keys
   WHERE subject_key_id = NEW.subject_key_id
   FOR UPDATE;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'subject key binding refers to a missing subject key'
      USING ERRCODE = '23503';
  END IF;

  SELECT * INTO session_record
    FROM proof_sessions
   WHERE proof_session_id = NEW.proof_session_id
     AND actor_id = NEW.user_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION 'subject key binding session is missing or belongs to another actor'
      USING ERRCODE = '23503';
  END IF;

  IF session_record.status <> 'pending'
    OR NEW.bound_at < session_record.started_at
    OR NEW.bound_at >= session_record.expires_at THEN
    RAISE EXCEPTION 'subject key binding requires a live pending proof session'
      USING ERRCODE = '23514', CONSTRAINT = 'subject_key_binding_events_live_session';
  END IF;

  SELECT * INTO current_binding
    FROM active_subject_key_bindings
   WHERE subject_key_id = NEW.subject_key_id
   FOR UPDATE;

  IF NOT FOUND THEN
    IF NEW.binding_epoch <> 1
      OR NEW.binding_kind <> 'initial'
      OR session_record.subject_binding_intent <> 'establish'
      OR NEW.previous_binding_event_id IS NOT NULL THEN
      RAISE EXCEPTION 'first subject key binding must be initial epoch 1'
        USING ERRCODE = '23514', CONSTRAINT = 'subject_key_binding_events_sequence';
    END IF;
  ELSE
    IF NEW.binding_epoch <> current_binding.binding_epoch + 1
      OR NEW.binding_kind <> 'recovery'
      OR session_record.subject_binding_intent <> 'recover'
      OR NEW.previous_binding_event_id IS DISTINCT FROM current_binding.binding_event_id
      OR NEW.user_id = current_binding.user_id
      OR NEW.bound_at < current_binding.activated_at THEN
      RAISE EXCEPTION 'subject key recovery must advance the active binding exactly once'
        USING ERRCODE = '23514', CONSTRAINT = 'subject_key_binding_events_sequence';
    END IF;
  END IF;

  RETURN NEW;
END;
$$;

CREATE FUNCTION grade_study_answer_v1(candidate_answer jsonb, stored_answer_key jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT CASE stored_answer_key->>'kind'
    WHEN 'single_select' THEN
      candidate_answer->>'choice_key' = stored_answer_key->>'correct_choice_key'
    WHEN 'text_response' THEN EXISTS (
      SELECT 1
        FROM jsonb_array_elements_text(stored_answer_key->'accepted_answers') AS accepted(value)
       WHERE regexp_replace(lower(btrim(candidate_answer->>'text')), '\s+', ' ', 'g')
           = regexp_replace(lower(btrim(accepted.value)), '\s+', ' ', 'g')
    )
    ELSE false
  END
$$;

CREATE FUNCTION guard_account_language_preferences_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.account_id IS DISTINCT FROM NEW.account_id
     OR NEW.revision <> OLD.revision + 1
     OR NEW.updated_at <= OLD.updated_at THEN
    RAISE EXCEPTION 'language preference update requires stable account and next revision';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_account_minimum_age_attestation_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'UPDATE' AND ROW(NEW.account_id, NEW.version, NEW.minimum_age, NEW.affirmed)
      IS DISTINCT FROM ROW(OLD.account_id, OLD.version, OLD.minimum_age, OLD.affirmed) THEN
    RAISE EXCEPTION 'minimum-age attestation is immutable';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.attested_at <> OLD.attested_at THEN
    RAISE EXCEPTION 'minimum-age attestation timestamp is immutable';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_account_streak_clock() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'account streak clocks cannot be deleted';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = NEW.timezone) THEN
    RAISE EXCEPTION 'account streak timezone is unknown';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF NEW.account_id IS DISTINCT FROM OLD.account_id
       OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
      RAISE EXCEPTION 'account streak clock identity is immutable';
    END IF;
    IF NEW.timezone IS NOT DISTINCT FROM OLD.timezone THEN
      RAISE EXCEPTION 'account streak timezone updates must change the timezone';
    END IF;
    IF NEW.timezone_updated_at < OLD.next_change_allowed_at
       OR NEW.timezone_updated_at > clock_timestamp() THEN
      RAISE EXCEPTION 'account streak timezone change is outside its prospective window';
    END IF;
  ELSIF NEW.timezone_updated_at > clock_timestamp() THEN
    RAISE EXCEPTION 'account streak timezone pin cannot begin in the future';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_account_streak_timezone_action() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'account streak timezone actions are append-only';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = NEW.result_timezone) THEN
    RAISE EXCEPTION 'account streak timezone action is unknown';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_activity_qualification() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  study_record study_sessions%ROWTYPE;
  study_v2_record RECORD;
  karaoke_session_record karaoke_sessions%ROWTYPE;
  karaoke_attempt_record karaoke_attempts%ROWTYPE;
  karaoke_policy_document JSONB;
  karaoke_policy_kind TEXT;
  expected_evidence JSONB;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'activity qualifications are append-only';
  END IF;
  IF NEW.activity_key = 'study' THEN
    SELECT session.account_id, session.persona_id, session.community_id, session.post_id,
           session.audio_revision, session.qualification_policy_revision,
           session.timezone, session.status, session.completed_at,
           count(item.session_item_id)::bigint AS qualifying_exercise_count,
           count(item.session_item_id) FILTER (WHERE EXISTS (
             SELECT 1 FROM study_attempts_v2 attempt
              WHERE attempt.session_item_id=item.session_item_id
           ))::bigint AS presented_count,
           count(item.session_item_id) FILTER (WHERE EXISTS (
             SELECT 1 FROM study_attempts_v2 attempt
              WHERE attempt.session_item_id=item.session_item_id
                AND attempt.attempt_number=1 AND attempt.outcome='correct'
           ))::bigint AS first_pass_correct
      INTO study_v2_record
     FROM study_sessions_v2 session
      JOIN study_session_items_v2 item ON item.session_id=session.session_id
     WHERE session.session_id=NEW.study_session_id
     GROUP BY session.session_id;
    IF study_v2_record.account_id IS NOT NULL THEN
      expected_evidence := jsonb_build_object(
        'kind', 'study_session_first_pass_v2',
        'qualifying_exercise_count', study_v2_record.qualifying_exercise_count,
        'first_pass_correct', study_v2_record.first_pass_correct,
        'required_correct', greatest(
          1, ceil((7 * study_v2_record.qualifying_exercise_count)::numeric / 10)::bigint
        )
      );
      IF study_v2_record.status <> 'completed'
         OR study_v2_record.presented_count <> study_v2_record.qualifying_exercise_count
         OR study_v2_record.first_pass_correct < greatest(
           1, ceil((7 * study_v2_record.qualifying_exercise_count)::numeric / 10)::bigint
         )
         OR ROW(
           NEW.account_id, NEW.persona_id, NEW.community_id, NEW.post_id,
           NEW.audio_revision, NEW.qualification_policy_version_id,
           NEW.score_bps, NEW.qualified_at, NEW.streak_day, NEW.evidence_summary
         ) IS DISTINCT FROM ROW(
           study_v2_record.account_id, study_v2_record.persona_id,
           study_v2_record.community_id, study_v2_record.post_id,
           study_v2_record.audio_revision, study_v2_record.qualification_policy_revision,
           ((10000 * study_v2_record.first_pass_correct)
             / study_v2_record.qualifying_exercise_count)::integer,
           study_v2_record.completed_at,
           (study_v2_record.completed_at AT TIME ZONE study_v2_record.timezone)::date,
           expected_evidence
         ) THEN
        RAISE EXCEPTION 'Study v2 qualification is not exact reducer output';
      END IF;
      RETURN NEW;
    END IF;

    SELECT * INTO study_record FROM study_sessions
     WHERE session_id = NEW.study_session_id FOR SHARE;
    expected_evidence := jsonb_build_object(
      'kind', 'study_session_first_pass_v2',
      'qualifying_exercise_count', study_record.qualifying_exercise_count,
      'first_pass_correct', study_record.first_pass_correct,
      'required_correct', study_record.required_correct
    );
    IF study_record.session_id IS NULL OR study_record.status <> 'completed'
       OR study_record.first_pass_correct < study_record.required_correct
       OR ROW(
         NEW.account_id, NEW.persona_id, NEW.community_id, NEW.post_id,
         NEW.audio_revision, NEW.qualification_policy_version_id,
         NEW.score_bps, NEW.qualified_at, NEW.streak_day, NEW.evidence_summary
       ) IS DISTINCT FROM ROW(
         study_record.account_id, study_record.persona_id,
         study_record.community_id, study_record.post_id,
         study_record.audio_revision, study_record.qualification_policy_version_id,
         study_record.score_bps, study_record.completed_at,
         study_record.streak_day, expected_evidence
       ) THEN
      RAISE EXCEPTION 'Study qualification is not exact reducer output';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.activity_key = 'karaoke' THEN
    SELECT * INTO karaoke_session_record FROM karaoke_sessions
     WHERE session_id = NEW.karaoke_session_id
       AND attempt_id = NEW.karaoke_attempt_id FOR SHARE;
    SELECT * INTO karaoke_attempt_record FROM karaoke_attempts
     WHERE session_id = NEW.karaoke_session_id
       AND attempt_id = NEW.karaoke_attempt_id FOR SHARE;
    SELECT policy_kind, policy_document INTO karaoke_policy_kind, karaoke_policy_document
      FROM qualification_policy_versions
     WHERE qualification_policy_version_id = karaoke_session_record.qualification_policy_version_id
       AND activity_key = 'karaoke';
    IF karaoke_session_record.session_id IS NULL
       OR karaoke_session_record.status <> 'completed'
       OR karaoke_attempt_record.completion_reason <> 'completed'
       OR karaoke_attempt_record.scored_line_count < 5
       OR karaoke_attempt_record.coverage_bps < 8500
       OR karaoke_attempt_record.final_score_bps < 7000
       OR (
         karaoke_policy_kind = 'karaoke_qualification_v2'
         AND NOT (karaoke_policy_document->'eligible_playback_kinds'
           ? karaoke_session_record.playback_kind)
       )
       OR ROW(
         NEW.account_id, NEW.persona_id, NEW.community_id, NEW.post_id,
         NEW.audio_revision, NEW.qualification_policy_version_id,
         NEW.score_bps, NEW.qualified_at, NEW.streak_day, NEW.evidence_summary
       ) IS DISTINCT FROM ROW(
         karaoke_session_record.account_id, karaoke_session_record.persona_id,
         karaoke_session_record.community_id, karaoke_session_record.post_id,
         karaoke_session_record.audio_revision,
         karaoke_session_record.qualification_policy_version_id,
         karaoke_attempt_record.final_score_bps, karaoke_attempt_record.completed_at,
         (karaoke_attempt_record.completed_at AT TIME ZONE karaoke_session_record.timezone)::date,
         karaoke_attempt_record.evidence_summary
       ) THEN
      RAISE EXCEPTION 'Karaoke qualification is not exact reducer output';
    END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'reserved activities cannot produce qualifications';
END
$$;

CREATE FUNCTION guard_activity_registry_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'activity registry entries cannot be deleted';
  END IF;
  IF NEW.activity_key IS DISTINCT FROM OLD.activity_key
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'activity registry identity is immutable';
  END IF;
  IF NEW.updated_at < OLD.updated_at THEN
    RAISE EXCEPTION 'activity registry time cannot move backward';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_asset_bonus_leg_asset() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  asset_record reward_asset_whitelist%ROWTYPE;
BEGIN
  IF NEW.kind <> 'asset_bonus' THEN
    RETURN NEW;
  END IF;
  SELECT * INTO asset_record
    FROM reward_asset_whitelist
   WHERE chain_id = NEW.chain_id AND token_address = NEW.token_address
   FOR SHARE;
  IF asset_record.token_address IS NULL
     OR asset_record.asset_kind <> 'bonus_asset'
     OR asset_record.environment NOT IN ('test', 'staging')
     OR asset_record.decimals <> NEW.token_decimals
     OR asset_record.symbol <> NEW.token_symbol
     OR asset_record.policy_version <> NEW.asset_policy_version THEN
    RAISE EXCEPTION 'asset bonus leg requires exact active bonus asset';
  END IF;
  IF TG_OP = 'INSERT' AND asset_record.status <> 'active' THEN
    RAISE EXCEPTION 'asset bonus leg requires exact active bonus asset';
  END IF;
  IF TG_OP = 'UPDATE' AND ROW(NEW.token_symbol, NEW.asset_policy_version)
      IS DISTINCT FROM ROW(OLD.token_symbol, OLD.asset_policy_version) THEN
    RAISE EXCEPTION 'asset bonus leg terms are immutable';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_comment_publication_rating_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  resource_rating TEXT;
BEGIN
  SELECT comment.content_rating INTO resource_rating
    FROM comments AS comment
   WHERE comment.community_id = NEW.community_id
     AND comment.comment_id = NEW.comment_id;
  IF resource_rating IS NULL THEN
    RAISE EXCEPTION 'comment projection rating disagrees with resource';
  END IF;
  NEW.content_rating := resource_rating;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_community_canonical_route_binding_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  authority_changed BOOLEAN;
  operator_promotion BOOLEAN;
  owner_recovery_refresh BOOLEAN := FALSE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'community canonical route binding is immutable';
  END IF;

  IF ROW(
    NEW.route_binding_id, NEW.community_id, NEW.family, NEW.root_label,
    NEW.root_label_display, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.route_binding_id, OLD.community_id, OLD.family, OLD.root_label,
    OLD.root_label_display, OLD.created_at
  ) THEN
    RAISE EXCEPTION 'community canonical route identity is immutable';
  END IF;

  operator_promotion :=
    OLD.route_authority_kind = 'operator_managed_route_v1'
    AND OLD.authority_reference IS NOT NULL
    AND OLD.authority_generation IS NOT NULL
    AND NEW.route_authority_kind = 'verified_namespace_v1'
    AND NEW.authority_reference IS NULL
    AND NEW.authority_generation IS NULL
    AND OLD.route_lifecycle_status = 'active'
    AND NEW.route_lifecycle_status = 'active'
    AND OLD.ownership_status <> 'verified'
    AND OLD.verified_evidence_ref IS NULL
    AND NEW.ownership_status = 'verified'
    AND NEW.verified_evidence_ref IS NOT NULL;

  IF ROW(NEW.route_authority_kind, NEW.authority_reference)
       IS DISTINCT FROM ROW(OLD.route_authority_kind, OLD.authority_reference)
    AND NOT operator_promotion
  THEN
    RAISE EXCEPTION 'community canonical route identity is immutable';
  END IF;

  authority_changed := ROW(
    NEW.ownership_status, NEW.route_lifecycle_status, NEW.verified_evidence_ref,
    NEW.route_authority_kind, NEW.authority_reference, NEW.authority_generation
  ) IS DISTINCT FROM ROW(
    OLD.ownership_status, OLD.route_lifecycle_status, OLD.verified_evidence_ref,
    OLD.route_authority_kind, OLD.authority_reference, OLD.authority_generation
  );

  IF NOT authority_changed AND NEW.binding_generation = OLD.binding_generation + 1 THEN
    SELECT EXISTS (
      SELECT 1
        FROM community_route_revalidation_completion_attempts AS attempt
       WHERE attempt.operation_mode = 'same_root_recovery'
         AND attempt.route_binding_id = OLD.route_binding_id
         AND attempt.expected_binding_generation = OLD.binding_generation
         AND attempt.state = 'consumed'
         AND attempt.consumption_kind <> 'stale_cas'
         AND attempt.terminal_at IS NOT NULL
    ) INTO owner_recovery_refresh;
  END IF;

  IF authority_changed AND NEW.binding_generation <> OLD.binding_generation + 1 THEN
    RAISE EXCEPTION 'community canonical route generation must advance exactly once';
  END IF;
  IF NOT authority_changed
    AND NEW.binding_generation <> OLD.binding_generation
    AND NOT owner_recovery_refresh
  THEN
    RAISE EXCEPTION 'community canonical route generation cannot advance without authority change';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_community_canonical_route_reference() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.canonical_route_binding_id IS NOT NULL
    AND NEW.canonical_route_binding_id IS DISTINCT FROM OLD.canonical_route_binding_id THEN
    RAISE EXCEPTION 'community canonical route cannot be rebound or cleared';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_community_commerce_policy_revision_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(
    NEW.community_id, NEW.policy_version, NEW.source_revision, NEW.issued_by,
    NEW.effective_at
  ) IS DISTINCT FROM ROW(
    OLD.community_id, OLD.policy_version, OLD.source_revision, OLD.issued_by,
    OLD.effective_at
  ) THEN
    RAISE EXCEPTION 'community commerce policy revision identity is immutable';
  END IF;

  IF OLD.superseded_at IS NOT NULL
    AND NEW.superseded_at IS DISTINCT FROM OLD.superseded_at THEN
    RAISE EXCEPTION 'community commerce policy revision supersession is immutable';
  END IF;

  IF NEW.superseded_at IS NOT NULL AND NEW.superseded_at < OLD.effective_at THEN
    RAISE EXCEPTION 'community commerce policy revision supersession precedes effectiveness';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_community_creation_contract_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.creation_contract_version <> OLD.creation_contract_version THEN
    RAISE EXCEPTION 'community creation contract version is immutable';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_community_creation_intent_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(
    NEW.intent_id,
    NEW.actor_id,
    NEW.create_idempotency_key,
    NEW.create_request_hash,
    NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.intent_id,
    OLD.actor_id,
    OLD.create_idempotency_key,
    OLD.create_request_hash,
    OLD.created_at
  ) THEN
    RAISE EXCEPTION 'community creation intent identity is immutable';
  END IF;

  IF OLD.status IN (
    'committed',
    'quota_exceeded',
    'gate_unsupported',
    'expired',
    'cancelled'
  ) THEN
    RAISE EXCEPTION 'terminal community creation intent is immutable';
  END IF;

  IF NEW.revision <> OLD.revision + 1 THEN
    RAISE EXCEPTION 'community creation intent revision must advance exactly once';
  END IF;

  IF NOT (
    (OLD.status = 'draft' AND NEW.status IN (
      'draft',
      'verification_required',
      'commit_ready',
      'quota_exceeded',
      'gate_unsupported',
      'expired',
      'cancelled'
    ))
    OR (OLD.status = 'verification_required' AND NEW.status IN (
      'draft',
      'verification_required',
      'commit_ready',
      'quota_exceeded',
      'gate_unsupported',
      'expired',
      'cancelled'
    ))
    OR (OLD.status = 'commit_ready' AND NEW.status IN (
      'draft',
      'verification_required',
      'commit_ready',
      'committed',
      'quota_exceeded',
      'gate_unsupported',
      'expired',
      'cancelled'
    ))
  ) THEN
    RAISE EXCEPTION 'community creation intent transition is not allowed: % -> %',
      OLD.status,
      NEW.status;
  END IF;

  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_community_creation_requirement_state_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  binding_changed BOOLEAN;
BEGIN
  IF ROW(NEW.intent_id, NEW.actor_id, NEW.requirement_kind, NEW.created_at)
    IS DISTINCT FROM
    ROW(OLD.intent_id, OLD.actor_id, OLD.requirement_kind, OLD.created_at) THEN
    RAISE EXCEPTION 'community creation requirement identity is immutable';
  END IF;

  binding_changed := ROW(
    NEW.requirement_hash,
    NEW.provider_id,
    NEW.provider_binding_hash,
    NEW.provider_configuration_kind,
    NEW.provider_configuration_ref,
    NEW.provider_configuration_version,
    NEW.route_family,
    NEW.route_root_label,
    NEW.route_root_label_display,
    NEW.route_path_segment
  ) IS DISTINCT FROM ROW(
    OLD.requirement_hash,
    OLD.provider_id,
    OLD.provider_binding_hash,
    OLD.provider_configuration_kind,
    OLD.provider_configuration_ref,
    OLD.provider_configuration_version,
    OLD.route_family,
    OLD.route_root_label,
    OLD.route_root_label_display,
    OLD.route_path_segment
  );

  IF binding_changed THEN
    IF NEW.status <> 'unmet'
      OR NEW.generation <> OLD.generation
      OR NEW.current_ceremony_intent_id IS NOT NULL
      OR NEW.satisfied_at IS NOT NULL THEN
      RAISE EXCEPTION 'changed requirement binding must invalidate current evidence';
    END IF;
    RETURN NEW;
  END IF;

  IF NOT (
    (
      OLD.status IN ('unmet', 'failed', 'expired')
      AND NEW.status = 'pending'
      AND NEW.generation = OLD.generation + 1
      AND NEW.current_ceremony_intent_id IS NOT NULL
      AND NEW.satisfied_at IS NULL
    )
    OR (
      OLD.status = 'pending'
      AND NEW.status IN ('satisfied', 'failed', 'expired')
      AND NEW.generation = OLD.generation
      AND NEW.current_ceremony_intent_id = OLD.current_ceremony_intent_id
    )
  ) THEN
    RAISE EXCEPTION 'community creation requirement transition is not allowed: % -> %',
      OLD.status,
      NEW.status;
  END IF;

  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_community_handle_offering_current_change_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  revision community_handle_offering_revisions%ROWTYPE;
  prior_revision community_handle_offering_revisions%ROWTYPE;
  other_revision community_handle_offering_revisions%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'community handle offering current pointer cannot be deleted';
  END IF;
  SELECT * INTO revision
    FROM community_handle_offering_revisions
   WHERE offering_id = NEW.offering_id
     AND offering_revision = NEW.current_revision;
  IF revision.offering_id IS NULL
    OR NEW.community_id <> revision.community_id
    OR NEW.sale_namespace_activation_id <> revision.sale_namespace_activation_id
    OR NEW.status <> revision.status
    OR NEW.label_scope_kind <> revision.label_scope_kind
    OR NEW.exact_label IS DISTINCT FROM revision.exact_label THEN
    RAISE EXCEPTION 'community handle offering current pointer does not match revision';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    SELECT * INTO prior_revision
      FROM community_handle_offering_revisions
     WHERE offering_id = OLD.offering_id
       AND offering_revision = OLD.current_revision;
    IF NEW.offering_id <> OLD.offering_id
      OR NEW.community_id <> OLD.community_id
      OR NEW.current_revision <> OLD.current_revision + 1
      OR NEW.updated_at <= OLD.updated_at
      OR prior_revision.status = 'retired' THEN
      RAISE EXCEPTION 'community handle offering current generation is fenced';
    END IF;
  END IF;
  IF NEW.status = 'active' THEN
    SELECT active_revision.* INTO other_revision
      FROM community_handle_offering_current AS other_current
      JOIN community_handle_offering_revisions AS active_revision
        ON active_revision.offering_id = other_current.offering_id
       AND active_revision.offering_revision = other_current.current_revision
     WHERE other_current.sale_namespace_activation_id = NEW.sale_namespace_activation_id
       AND other_current.status = 'active'
       AND other_current.offering_id <> NEW.offering_id
     LIMIT 1;
    IF other_revision.offering_id IS NOT NULL AND (
      other_revision.reserved_labels_id <> revision.reserved_labels_id
      OR other_revision.reserved_labels_revision <> revision.reserved_labels_revision
    ) THEN
      RAISE EXCEPTION 'active handle offerings require one reserved-label authority';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_community_handle_sale_namespace_current_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  revision community_handle_sale_namespace_activation_revisions%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'community handle sale-namespace current authority cannot be deleted';
  END IF;
  SELECT * INTO revision
    FROM community_handle_sale_namespace_activation_revisions
   WHERE sale_namespace_activation_id = NEW.sale_namespace_activation_id
     AND sale_namespace_activation_generation = NEW.current_generation;
  IF revision.sale_namespace_activation_id IS NULL
    OR revision.family <> NEW.family
    OR revision.canonical_root <> NEW.canonical_root
    OR revision.community_id <> NEW.community_id THEN
    RAISE EXCEPTION 'community handle sale-namespace current revision does not match';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    NEW.sale_namespace_activation_id <> OLD.sale_namespace_activation_id
    OR NEW.family <> OLD.family
    OR NEW.canonical_root <> OLD.canonical_root
    OR NEW.community_id <> OLD.community_id
    OR NEW.current_generation <> OLD.current_generation + 1
    OR NEW.updated_at <= OLD.updated_at
  ) THEN
    RAISE EXCEPTION 'community handle sale-namespace current generation is fenced';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_community_handle_sales_authority_grant_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'community handle-sales authority grant cannot be deleted';
  END IF;
  IF ROW(
    NEW.grant_id,
    NEW.community_id,
    NEW.principal_account_id,
    NEW.authority,
    NEW.source_kind,
    NEW.source_policy_ref,
    NEW.granted_at,
    NEW.granted_by_account_id
  ) IS DISTINCT FROM ROW(
    OLD.grant_id,
    OLD.community_id,
    OLD.principal_account_id,
    OLD.authority,
    OLD.source_kind,
    OLD.source_policy_ref,
    OLD.granted_at,
    OLD.granted_by_account_id
  ) THEN
    RAISE EXCEPTION 'community handle-sales authority grant identity is immutable';
  END IF;
  IF OLD.status = 'revoked' AND NEW IS DISTINCT FROM OLD THEN
    RAISE EXCEPTION 'revoked community handle-sales authority grant is terminal';
  END IF;
  IF OLD.status = 'active' AND NEW.status <> 'revoked' THEN
    RAISE EXCEPTION 'community handle-sales authority grant transition is invalid';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_community_moderation_action_v2_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target_case community_moderation_cases_v2%ROWTYPE;
  submission text_content_submissions%ROWTYPE;
  rating TEXT;
  age_capability TEXT;
BEGIN
  SELECT * INTO target_case
    FROM community_moderation_cases_v2
   WHERE community_id = NEW.community_id AND case_ref = NEW.case_ref
   FOR UPDATE;
  IF NOT FOUND OR target_case.visibility <> 'owner'
    OR target_case.view_state NOT IN ('open', 'hidden') THEN
    RAISE EXCEPTION 'moderation case is not owner-actionable';
  END IF;
  IF NOT has_community_moderation_capability_v1(
    NEW.actor_user_id, NEW.community_id, 'moderation.act'
  ) THEN
    RAISE EXCEPTION 'moderation action requires active owner authority';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM community_role_assignments AS assignment
     WHERE assignment.role_assignment_id = NEW.owner_role_assignment_id
       AND assignment.community_id = NEW.community_id
       AND assignment.account_id = NEW.actor_user_id
       AND assignment.role = 'owner' AND assignment.status = 'active'
  ) THEN
    RAISE EXCEPTION 'moderation action owner snapshot is invalid';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM personas AS persona
     WHERE persona.persona_id = NEW.presenting_persona_id
       AND persona.account_id = NEW.actor_user_id
       AND persona.status = 'active'
  ) THEN
    RAISE EXCEPTION 'moderation action presenting persona is invalid';
  END IF;

  SELECT * INTO submission
    FROM text_content_submissions
   WHERE community_id = target_case.community_id
     AND submission_id = target_case.submission_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'moderation action submission is missing';
  END IF;
  rating := NEW.before_rating;
  IF COALESCE(submission.resulting_content_rating, 'adult_18') <> rating
    AND NOT (
      NEW.action = 'approve_as_adult_18'
      AND submission.resulting_content_rating = NEW.after_rating
    ) THEN
    RAISE EXCEPTION 'moderation action submission rating is stale';
  END IF;
  age_capability := current_account_age_capability_v1(NEW.actor_user_id);
  IF NEW.resolved_age_capability <> age_capability THEN
    RAISE EXCEPTION 'moderation action age capability snapshot is stale';
  END IF;
  IF NEW.expected_case_revision <> target_case.case_revision
    OR NEW.before_view_state <> target_case.view_state
    OR NEW.before_target_status <> target_case.target_status
    OR NEW.before_rating <> rating THEN
    RAISE EXCEPTION 'moderation action case revision is stale';
  END IF;
  IF submission.platform_policy_revision_id <> NEW.platform_policy_revision_id
    OR submission.platform_policy_hash <> NEW.platform_policy_hash
    OR submission.community_policy_revision_id <> NEW.community_policy_revision_id
    OR submission.community_policy_hash <> NEW.community_policy_hash
    OR submission.evidence_ref IS DISTINCT FROM NEW.evidence_ref THEN
    RAISE EXCEPTION 'moderation action policy evidence snapshot is invalid';
  END IF;
  IF NEW.action = 'approve_as_general'
    AND submission.author_declared_rating = 'adult_18' THEN
    RAISE EXCEPTION 'adult author declaration cannot be approved as general';
  END IF;
  IF (
    NEW.action = 'approve_as_adult_18'
    OR (rating = 'adult_18' AND NEW.action IN ('dismiss_report', 'restore'))
  ) AND age_capability <> 'adult_18' THEN
    RAISE EXCEPTION 'moderation action requires adult capability';
  END IF;

  IF NOT (
    (NEW.action IN ('approve_as_general', 'approve_as_adult_18')
      AND target_case.view_state = 'open'
      AND target_case.target_status = 'held'
      AND NEW.after_view_state = 'resolved'
      AND NEW.after_target_status = 'published'
      AND NEW.after_rating = CASE NEW.action
        WHEN 'approve_as_adult_18' THEN 'adult_18' ELSE rating END)
    OR (NEW.action = 'reject'
      AND target_case.view_state = 'open'
      AND target_case.target_status = 'held'
      AND NEW.after_view_state = 'resolved'
      AND NEW.after_target_status = 'blocked'
      AND NEW.after_rating = rating)
    OR (NEW.action = 'dismiss_report'
      AND target_case.view_state = 'open'
      AND target_case.target_status = 'published'
      AND target_case.source IN ('member_report', 'mixed')
      AND NEW.after_view_state = 'resolved'
      AND NEW.after_target_status = 'published'
      AND NEW.after_rating = rating)
    OR (NEW.action = 'hide'
      AND target_case.view_state = 'open'
      AND target_case.target_status = 'published'
      AND NEW.after_view_state = 'hidden'
      AND NEW.after_target_status = 'hidden'
      AND NEW.after_rating = rating)
    OR (NEW.action = 'raise_rating_to_adult_18'
      AND target_case.view_state = 'open'
      AND target_case.target_status = 'published'
      AND rating = 'general'
      AND NEW.after_view_state = 'resolved'
      AND NEW.after_target_status = 'published'
      AND NEW.after_rating = 'adult_18')
    OR (NEW.action = 'restore'
      AND target_case.view_state = 'hidden'
      AND target_case.target_status = 'hidden'
      AND NEW.after_view_state = 'resolved'
      AND NEW.after_target_status = 'published'
      AND NEW.after_rating = rating)
  ) THEN
    RAISE EXCEPTION 'moderation action is outside the closed state matrix';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_community_moderation_case_v2_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(
    NEW.case_ref,
    NEW.community_id,
    NEW.submission_id,
    NEW.target_type,
    NEW.source,
    NEW.visibility,
    NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.case_ref,
    OLD.community_id,
    OLD.submission_id,
    OLD.target_type,
    OLD.source,
    OLD.visibility,
    OLD.created_at
  ) THEN
    RAISE EXCEPTION 'community moderation case identity is immutable';
  END IF;
  IF OLD.visibility <> 'owner'
    OR OLD.view_state NOT IN ('open', 'hidden')
    OR NEW.case_revision <> OLD.case_revision + 1
    OR NEW.updated_at <= OLD.updated_at
    OR NEW.last_action_id IS NULL
    OR NOT EXISTS (
      SELECT 1
        FROM community_moderation_actions_v2 AS action
       WHERE action.action_id = NEW.last_action_id
         AND action.community_id = OLD.community_id
         AND action.case_ref = OLD.case_ref
         AND action.expected_case_revision = OLD.case_revision
         AND action.before_view_state = OLD.view_state
         AND action.after_view_state = NEW.view_state
         AND action.before_target_status = OLD.target_status
         AND action.after_target_status = NEW.target_status
         AND action.created_at = NEW.updated_at
    )
  THEN
    RAISE EXCEPTION 'community moderation case transition lacks its exact action';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_community_moderation_policy_current_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  prior_revision BIGINT;
  next_revision BIGINT;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'community moderation policy current pointer cannot be deleted';
  END IF;
  IF NEW.community_id IS DISTINCT FROM OLD.community_id THEN
    RAISE EXCEPTION 'community moderation policy current identity is immutable';
  END IF;
  IF NEW.updated_at <= OLD.updated_at THEN
    RAISE EXCEPTION 'community moderation policy current timestamp must advance';
  END IF;

  SELECT revision INTO prior_revision
    FROM community_moderation_policy_revisions
   WHERE community_id = OLD.community_id
     AND policy_revision_id = OLD.policy_revision_id;
  SELECT revision INTO next_revision
    FROM community_moderation_policy_revisions
   WHERE community_id = NEW.community_id
     AND policy_revision_id = NEW.policy_revision_id
     AND policy_hash = NEW.policy_hash;
  IF next_revision IS NULL OR next_revision <= prior_revision THEN
    RAISE EXCEPTION 'community moderation policy current revision must advance';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_community_purchase_funding_journal_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(
    NEW.operation_id, NEW.community_id, NEW.actor_id, NEW.quote_id, NEW.purchase_id,
    NEW.policy_version, NEW.chain_id, NEW.token_contract, NEW.token_decimals,
    NEW.expected_sender, NEW.expected_recipient, NEW.expected_amount_atomic,
    NEW.required_confirmations
  ) IS DISTINCT FROM ROW(
    OLD.operation_id, OLD.community_id, OLD.actor_id, OLD.quote_id, OLD.purchase_id,
    OLD.policy_version, OLD.chain_id, OLD.token_contract, OLD.token_decimals,
    OLD.expected_sender, OLD.expected_recipient, OLD.expected_amount_atomic,
    OLD.required_confirmations
  ) THEN
    RAISE EXCEPTION 'community purchase funding identity is immutable';
  END IF;

  IF NEW.version = OLD.version THEN
    IF ROW(
      NEW.state, NEW.snapshot, NEW.failure_tag, NEW.failure_reason,
      NEW.funding_receipt_status,
      NEW.funding_transaction_hash, NEW.funding_log_index,
      NEW.funding_observation_id
    ) IS DISTINCT FROM ROW(
      OLD.state, OLD.snapshot, OLD.failure_tag, OLD.failure_reason,
      OLD.funding_receipt_status,
      OLD.funding_transaction_hash, OLD.funding_log_index,
      OLD.funding_observation_id
    ) THEN
      RAISE EXCEPTION 'journal state change requires a new version';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.version <> OLD.version + 1 THEN
    RAISE EXCEPTION 'journal version must advance exactly once';
  END IF;

  IF NOT (
    (OLD.state = 'planned' AND NEW.state IN (
      'dormant_unobserved', 'confirming', 'confirmed', 'reverted',
      'reclaimable_failed'
    ))
    OR (OLD.state = 'dormant_unobserved'
      AND NEW.state IN ('confirming', 'confirmed', 'reverted'))
    OR (OLD.state = 'confirming'
      AND NEW.state IN ('confirming', 'confirmed', 'reverted', 'reconciliation_required'))
    OR (OLD.state = 'confirmed' AND NEW.state IN ('confirmed', 'reconciliation_required'))
    OR (OLD.state = 'reverted' AND NEW.state IN ('reverted', 'reconciliation_required'))
    OR (OLD.state = 'reclaimable_failed' AND NEW.state = 'planned')
    OR (OLD.state = 'reconciliation_required'
      AND NEW.state IN ('confirming', 'confirmed', 'reverted'))
  ) THEN
    RAISE EXCEPTION 'journal transition is not allowed: % -> %', OLD.state, NEW.state;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_community_purchase_funding_plan_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(
    NEW.quote_id, NEW.community_id, NEW.actor_id, NEW.buyer_wallet_address,
    NEW.buyer_chain_id, NEW.purchase_id, NEW.policy_version, NEW.chain_id, NEW.token_contract,
    NEW.token_decimals, NEW.treasury_address, NEW.amount_atomic,
    NEW.required_confirmations, NEW.quoted_at, NEW.expires_at
  ) IS DISTINCT FROM ROW(
    OLD.quote_id, OLD.community_id, OLD.actor_id, OLD.buyer_wallet_address,
    OLD.buyer_chain_id, OLD.purchase_id, OLD.policy_version, OLD.chain_id, OLD.token_contract,
    OLD.token_decimals, OLD.treasury_address, OLD.amount_atomic,
    OLD.required_confirmations, OLD.quoted_at, OLD.expires_at
  ) THEN
    RAISE EXCEPTION 'community purchase funding plan terms are immutable';
  END IF;

  IF OLD.status = 'active' THEN
    IF NEW.status IN ('active', 'cancelled') AND NEW.operation_id IS NULL THEN
      RETURN NEW;
    END IF;
    IF NEW.status = 'bound'
      AND OLD.operation_id IS NULL AND NEW.operation_id IS NOT NULL THEN
      RETURN NEW;
    END IF;
  END IF;

  IF OLD.status = 'bound'
    AND NEW.status = 'bound'
    AND NEW.operation_id IS NOT DISTINCT FROM OLD.operation_id THEN
    RETURN NEW;
  END IF;

  IF OLD.status = 'cancelled' AND NEW.status = 'cancelled' AND NEW.operation_id IS NULL THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'community purchase funding plan transition is not allowed: % -> %',
    OLD.status, NEW.status;
END;
$$;

CREATE FUNCTION guard_community_purchase_quote_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(
    NEW.quote_id, NEW.purchase_id, NEW.community_id, NEW.actor_id, NEW.listing_id,
    NEW.policy_version, NEW.buyer_wallet_address, NEW.buyer_chain_id, NEW.chain_id,
    NEW.token_contract, NEW.token_decimals, NEW.treasury_address, NEW.amount_atomic,
    NEW.required_confirmations, NEW.quoted_at, NEW.expires_at
  ) IS DISTINCT FROM ROW(
    OLD.quote_id, OLD.purchase_id, OLD.community_id, OLD.actor_id, OLD.listing_id,
    OLD.policy_version, OLD.buyer_wallet_address, OLD.buyer_chain_id, OLD.chain_id,
    OLD.token_contract, OLD.token_decimals, OLD.treasury_address, OLD.amount_atomic,
    OLD.required_confirmations, OLD.quoted_at, OLD.expires_at
  ) THEN
    RAISE EXCEPTION 'community purchase quote terms are immutable';
  END IF;

  IF OLD.eligibility_snapshot_id IS NOT NULL
    AND NEW.eligibility_snapshot_id IS DISTINCT FROM OLD.eligibility_snapshot_id THEN
    RAISE EXCEPTION 'community purchase quote snapshot binding is immutable';
  END IF;
  IF OLD.pricing_snapshot_id IS NOT NULL
    AND NEW.pricing_snapshot_id IS DISTINCT FROM OLD.pricing_snapshot_id THEN
    RAISE EXCEPTION 'community purchase quote snapshot binding is immutable';
  END IF;
  IF OLD.verification_snapshot_id IS NOT NULL
    AND NEW.verification_snapshot_id IS DISTINCT FROM OLD.verification_snapshot_id THEN
    RAISE EXCEPTION 'community purchase quote snapshot binding is immutable';
  END IF;
  IF OLD.route_snapshot_id IS NOT NULL
    AND NEW.route_snapshot_id IS DISTINCT FROM OLD.route_snapshot_id THEN
    RAISE EXCEPTION 'community purchase quote snapshot binding is immutable';
  END IF;
  IF OLD.allocation_snapshot_id IS NOT NULL
    AND NEW.allocation_snapshot_id IS DISTINCT FROM OLD.allocation_snapshot_id THEN
    RAISE EXCEPTION 'community purchase quote snapshot binding is immutable';
  END IF;
  IF OLD.settlement_snapshot_id IS NOT NULL
    AND NEW.settlement_snapshot_id IS DISTINCT FROM OLD.settlement_snapshot_id THEN
    RAISE EXCEPTION 'community purchase quote snapshot binding is immutable';
  END IF;
  IF OLD.donation_snapshot_id IS NOT NULL
    AND NEW.donation_snapshot_id IS DISTINCT FROM OLD.donation_snapshot_id THEN
    RAISE EXCEPTION 'community purchase quote snapshot binding is immutable';
  END IF;

  IF OLD.status = 'active' AND NEW.status IN ('active', 'bound', 'cancelled', 'expired') THEN
    RETURN NEW;
  END IF;
  IF OLD.status = NEW.status THEN
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'community purchase quote transition is not allowed: % -> %', OLD.status, NEW.status;
END;
$$;

CREATE FUNCTION guard_community_role_assignment_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.role = 'owner' AND OLD.status = 'active'
    AND (
      TG_OP = 'DELETE'
      OR NEW.role IS DISTINCT FROM 'owner'
      OR NEW.status IS DISTINCT FROM 'active'
      OR NEW.community_id IS DISTINCT FROM OLD.community_id
    )
  THEN
    PERFORM 1
      FROM communities
     WHERE community_id = OLD.community_id
     FOR UPDATE;

    IF NOT EXISTS (
      SELECT 1
        FROM community_role_assignments AS replacement
       WHERE replacement.community_id = OLD.community_id
         AND replacement.role = 'owner'
         AND replacement.status = 'active'
         AND replacement.role_assignment_id <> OLD.role_assignment_id
    ) THEN
      RAISE EXCEPTION 'community cannot be left without an active owner';
    END IF;
  END IF;

  IF TG_OP = 'UPDATE' AND ROW(
    NEW.role_assignment_id,
    NEW.community_id,
    NEW.account_id,
    NEW.role,
    NEW.assigned_at
  ) IS DISTINCT FROM ROW(
    OLD.role_assignment_id,
    OLD.community_id,
    OLD.account_id,
    OLD.role,
    OLD.assigned_at
  ) THEN
    RAISE EXCEPTION 'community role assignment identity is immutable';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_community_route_active_lease_renewal() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  db_now TIMESTAMPTZ := clock_timestamp();
  community_record communities%ROWTYPE;
  binding_record community_canonical_route_bindings%ROWTYPE;
  evidence_record community_route_ownership_evidence%ROWTYPE;
  identity_record community_route_hns_control_identities%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'active lease renewals cannot be deleted';
  END IF;
  IF TG_OP = 'INSERT' THEN
    NEW.created_at := db_now;
    NEW.updated_at := db_now;
    SELECT * INTO community_record FROM communities
     WHERE community_id = NEW.community_id FOR UPDATE;
    SELECT * INTO binding_record FROM community_canonical_route_bindings
     WHERE route_binding_id = NEW.route_binding_id
       AND community_id = NEW.community_id FOR UPDATE;
    SELECT * INTO evidence_record FROM community_route_ownership_evidence
     WHERE evidence_ref = NEW.expected_verified_evidence_ref FOR SHARE;
    SELECT * INTO identity_record FROM community_route_hns_control_identities
     WHERE evidence_ref = NEW.expected_verified_evidence_ref FOR SHARE;
    IF community_record.community_id IS NULL
      OR community_record.status <> 'active'
      OR community_record.canonical_route_binding_id IS DISTINCT FROM NEW.route_binding_id
      OR binding_record.route_binding_id IS NULL
      OR binding_record.binding_generation IS DISTINCT FROM NEW.expected_binding_generation
      OR binding_record.verified_evidence_ref IS DISTINCT FROM NEW.expected_verified_evidence_ref
      OR binding_record.ownership_status <> 'verified'
      OR binding_record.route_lifecycle_status <> 'active'
      OR evidence_record.evidence_ref IS NULL
      OR evidence_record.binding_generation IS DISTINCT FROM NEW.expected_binding_generation
      OR evidence_record.evidence_digest IS DISTINCT FROM NEW.expected_evidence_digest
      OR evidence_record.expires_at IS NULL OR evidence_record.expires_at <= db_now
      OR evidence_record.family IS DISTINCT FROM NEW.family
      OR evidence_record.root_label IS DISTINCT FROM NEW.root_label
      OR evidence_record.root_label_display IS DISTINCT FROM NEW.root_label_display
      OR evidence_record.path_segment IS DISTINCT FROM NEW.path_segment
      OR evidence_record.provider_id IS DISTINCT FROM NEW.provider_id
      OR evidence_record.provider_binding_hash IS DISTINCT FROM NEW.provider_binding_hash
      OR evidence_record.provider_configuration_version
           IS DISTINCT FROM NEW.provider_configuration_version
      OR identity_record.evidence_ref IS NULL
      OR identity_record.control_identity_digest
           IS DISTINCT FROM NEW.expected_control_identity_digest
      OR identity_record.chain_authority_digest
           IS DISTINCT FROM NEW.expected_chain_authority_digest
      OR identity_record.provider_evidence_ref
           IS DISTINCT FROM NEW.prior_provider_evidence_ref
      OR NEW.status <> 'pending'
    THEN
      RAISE EXCEPTION 'active lease renewal does not match effective route authority';
    END IF;
    RETURN NEW;
  END IF;

  IF ROW(
    NEW.active_lease_renewal_id, NEW.community_id, NEW.route_binding_id,
    NEW.principal_kind, NEW.principal_id, NEW.expected_binding_generation,
    NEW.expected_verified_evidence_ref, NEW.expected_evidence_digest,
    NEW.expected_control_identity_digest, NEW.expected_chain_authority_digest,
    NEW.prior_provider_evidence_ref, NEW.requirement_hash, NEW.provider_id,
    NEW.provider_binding_hash, NEW.provider_configuration_kind,
    NEW.provider_configuration_reference, NEW.provider_configuration_version,
    NEW.provider_configuration_digest, NEW.protocol_version, NEW.environment,
    NEW.family, NEW.root_label, NEW.root_label_display, NEW.path_segment, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.active_lease_renewal_id, OLD.community_id, OLD.route_binding_id,
    OLD.principal_kind, OLD.principal_id, OLD.expected_binding_generation,
    OLD.expected_verified_evidence_ref, OLD.expected_evidence_digest,
    OLD.expected_control_identity_digest, OLD.expected_chain_authority_digest,
    OLD.prior_provider_evidence_ref, OLD.requirement_hash, OLD.provider_id,
    OLD.provider_binding_hash, OLD.provider_configuration_kind,
    OLD.provider_configuration_reference, OLD.provider_configuration_version,
    OLD.provider_configuration_digest, OLD.protocol_version, OLD.environment,
    OLD.family, OLD.root_label, OLD.root_label_display, OLD.path_segment, OLD.created_at
  ) THEN
    RAISE EXCEPTION 'active lease renewal authority is immutable';
  END IF;
  IF OLD.status = 'pending'
    AND NEW.status IN ('completed', 'failed')
    AND NEW.terminal_at IS NOT NULL
    AND NEW.terminal_at <= db_now
  THEN
    NEW.updated_at := db_now;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'active lease renewal transition is not allowed';
END;
$$;

CREATE FUNCTION guard_community_route_active_lease_renewal_attempt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  db_now TIMESTAMPTZ := date_trunc('milliseconds', clock_timestamp());
  renewal_record community_route_active_lease_renewals%ROWTYPE;
  consumed_count INTEGER;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'active lease renewal attempts cannot be deleted';
  END IF;
  SELECT * INTO renewal_record
    FROM community_route_active_lease_renewals
   WHERE active_lease_renewal_id = COALESCE(
     NEW.active_lease_renewal_id, OLD.active_lease_renewal_id
   ) FOR UPDATE;
  IF renewal_record.active_lease_renewal_id IS NULL THEN
    RAISE EXCEPTION 'active lease renewal attempt lacks its operation';
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.created_at := db_now;
    NEW.updated_at := db_now;
    SELECT count(*)::integer INTO consumed_count
      FROM community_route_active_lease_renewal_attempts
     WHERE active_lease_renewal_id = NEW.active_lease_renewal_id
       AND state = 'consumed';
    IF renewal_record.status <> 'pending'
      OR NEW.route_binding_id IS DISTINCT FROM renewal_record.route_binding_id
      OR NEW.expected_binding_generation
           IS DISTINCT FROM renewal_record.expected_binding_generation
      OR NEW.attempt_number IS DISTINCT FROM consumed_count + 1
      OR consumed_count >= 3
      OR NEW.state <> 'leased'
      OR NEW.fence_token <> 1
      OR NEW.lease_expires_at <= db_now
    THEN
      RAISE EXCEPTION 'active lease renewal attempt is not admissible';
    END IF;
    NEW.lease_expires_at := db_now + INTERVAL '16 seconds';
    RETURN NEW;
  END IF;

  IF ROW(
    NEW.active_lease_renewal_attempt_id, NEW.active_lease_renewal_id,
    NEW.route_binding_id, NEW.expected_binding_generation, NEW.attempt_number,
    NEW.idempotency_key, NEW.request_hash, NEW.evidence_ref, NEW.observation_id,
    NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.active_lease_renewal_attempt_id, OLD.active_lease_renewal_id,
    OLD.route_binding_id, OLD.expected_binding_generation, OLD.attempt_number,
    OLD.idempotency_key, OLD.request_hash, OLD.evidence_ref, OLD.observation_id,
    OLD.created_at
  ) THEN
    RAISE EXCEPTION 'active lease renewal attempt authority is immutable';
  END IF;

  IF OLD.state = 'leased' AND NEW.state = 'released'
    AND NEW.fence_token = OLD.fence_token
    AND NEW.lease_expires_at = OLD.lease_expires_at
    AND NEW.consumption_kind IS NULL
  THEN
    NEW.updated_at := db_now;
    RETURN NEW;
  END IF;
  IF OLD.state IN ('released', 'leased') AND NEW.state = 'leased'
    AND NEW.fence_token = OLD.fence_token + 1
    AND NEW.lease_expires_at > db_now
    AND (OLD.state = 'released' OR OLD.lease_expires_at <= db_now)
    AND NEW.consumption_kind IS NULL
  THEN
    NEW.lease_expires_at := db_now + INTERVAL '16 seconds';
    NEW.updated_at := db_now;
    RETURN NEW;
  END IF;
  IF OLD.state = 'leased' AND NEW.state = 'consumed'
    AND NEW.fence_token = OLD.fence_token
    AND NEW.lease_expires_at = OLD.lease_expires_at
    AND NEW.terminal_at IS NOT NULL
    AND NEW.terminal_at <= db_now
    AND (
      OLD.lease_expires_at > db_now
      OR NEW.consumption_kind IN ('lease_expired_before_commit', 'stale_cas')
    )
    AND validate_hns_active_lease_renewal_terminal_document(
      NEW.terminal_result_document, NEW.result_hash, NEW.terminal_result_version,
      NEW.active_lease_renewal_id, NEW.active_lease_renewal_attempt_id,
      NEW.route_binding_id, NEW.expected_binding_generation, NEW.idempotency_key,
      NEW.request_hash, NEW.consumption_kind
    )
  THEN
    NEW.updated_at := db_now;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'active lease renewal attempt transition is not allowed';
END;
$$;

CREATE FUNCTION guard_community_route_attachment_intent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  community_record communities%ROWTYPE;
  grant_record community_route_authority_grants%ROWTYPE;
  binding_record community_canonical_route_bindings%ROWTYPE;
  evidence_record community_route_ownership_evidence%ROWTYPE;
  attempt_record community_route_attachment_ceremony_attempts%ROWTYPE;
  result_record community_route_attachment_ceremony_results%ROWTYPE;
  state_record community_route_attachment_requirement_states%ROWTYPE;
BEGIN
  IF TG_OP = 'UPDATE' AND ROW(
    NEW.attachment_intent_id,
    NEW.community_id,
    NEW.actor_id,
    NEW.authority_grant_id,
    NEW.create_idempotency_key,
    NEW.create_request_hash,
    NEW.family,
    NEW.root_label,
    NEW.root_label_display,
    NEW.requirement_hash,
    NEW.provider_id,
    NEW.provider_binding_hash,
    NEW.provider_configuration_kind,
    NEW.provider_configuration_ref,
    NEW.provider_configuration_version,
    NEW.protocol_version,
    NEW.expires_at,
    NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.attachment_intent_id,
    OLD.community_id,
    OLD.actor_id,
    OLD.authority_grant_id,
    OLD.create_idempotency_key,
    OLD.create_request_hash,
    OLD.family,
    OLD.root_label,
    OLD.root_label_display,
    OLD.requirement_hash,
    OLD.provider_id,
    OLD.provider_binding_hash,
    OLD.provider_configuration_kind,
    OLD.provider_configuration_ref,
    OLD.provider_configuration_version,
    OLD.protocol_version,
    OLD.expires_at,
    OLD.created_at
  ) THEN
    RAISE EXCEPTION 'route attachment authority and requested root are immutable';
  END IF;

  IF TG_OP = 'INSERT'
    AND (NEW.revision <> 1 OR NEW.status <> 'verification_required') THEN
    RAISE EXCEPTION 'route attachment must begin at revision one awaiting verification';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    NEW.revision <> OLD.revision + 1
    OR OLD.status IN ('committed', 'failed', 'expired', 'cancelled')
    OR NOT (
      (OLD.status = 'verification_required'
        AND NEW.status IN (
          'verification_required', 'commit_ready', 'failed', 'expired', 'cancelled'
        ))
      OR (OLD.status = 'commit_ready'
        AND NEW.status IN ('committed', 'failed', 'expired', 'cancelled'))
    )
  ) THEN
    RAISE EXCEPTION 'route attachment intent transition is not allowed: % -> %',
      OLD.status,
      NEW.status;
  END IF;

  SELECT * INTO community_record
    FROM communities
   WHERE community_id = NEW.community_id;
  SELECT * INTO grant_record
    FROM community_route_authority_grants
   WHERE grant_id = NEW.authority_grant_id;

  IF community_record.community_id IS NULL
    OR community_record.status <> 'active'
    OR community_record.route_authority_version <> 'optional_route_v2'
    OR grant_record.grant_id IS NULL
    OR grant_record.community_id <> NEW.community_id
    OR grant_record.principal_user_id <> NEW.actor_id
    OR grant_record.authority <> 'manage_routes'
    OR grant_record.status <> 'active' THEN
    RAISE EXCEPTION 'route attachment requires active community manage_routes authority';
  END IF;

  IF TG_OP = 'INSERT' AND community_record.canonical_route_binding_id IS NOT NULL THEN
    RAISE EXCEPTION 'route attachment is only available to an unrouted community';
  END IF;

  IF NEW.status <> 'committed' THEN
    RETURN NEW;
  END IF;

  SELECT * INTO binding_record
    FROM community_canonical_route_bindings
   WHERE route_binding_id = NEW.committed_route_binding_id
     AND community_id = NEW.community_id;
  SELECT * INTO evidence_record
    FROM community_route_ownership_evidence
   WHERE evidence_ref = binding_record.verified_evidence_ref;
  SELECT * INTO attempt_record
    FROM community_route_attachment_ceremony_attempts
   WHERE ceremony_intent_id = evidence_record.route_attachment_ceremony_intent_id;
  SELECT * INTO result_record
    FROM community_route_attachment_ceremony_results
   WHERE ceremony_intent_id = attempt_record.ceremony_intent_id;
  SELECT * INTO state_record
    FROM community_route_attachment_requirement_states
   WHERE attachment_intent_id = NEW.attachment_intent_id
     AND requirement_kind = 'namespace_ownership';
  IF binding_record.route_binding_id IS NULL
    OR community_record.canonical_route_binding_id <> binding_record.route_binding_id
    OR binding_record.family <> NEW.family
    OR binding_record.root_label <> NEW.root_label
    OR binding_record.root_label_display <> NEW.root_label_display
    OR binding_record.ownership_status <> 'verified'
    OR binding_record.route_lifecycle_status <> 'active'
    OR evidence_record.origin <> 'route_attachment'
    OR evidence_record.route_attachment_ceremony_intent_id IS NULL
    OR attempt_record.ceremony_intent_id IS NULL
    OR result_record.ceremony_intent_id IS NULL
    OR state_record.attachment_intent_id IS NULL
    OR attempt_record.attachment_intent_id <> NEW.attachment_intent_id
    OR attempt_record.actor_id <> NEW.actor_id
    OR result_record.attachment_intent_id <> NEW.attachment_intent_id
    OR result_record.outcome_status <> 'satisfied'
    OR result_record.evidence_ref <> evidence_record.evidence_ref
    OR result_record.evidence_digest <> evidence_record.evidence_digest
    OR result_record.provider_identity_digest <> evidence_record.provider_identity_digest
    OR state_record.status <> 'satisfied'
    OR state_record.generation <> attempt_record.generation
    OR state_record.current_ceremony_intent_id <> attempt_record.ceremony_intent_id
    OR evidence_record.family <> binding_record.family
    OR evidence_record.root_label <> binding_record.root_label
    OR evidence_record.root_label_display <> binding_record.root_label_display
    OR evidence_record.path_segment <> binding_record.path_segment
    OR evidence_record.binding_generation <> binding_record.binding_generation
    OR evidence_record.verified_at > clock_timestamp()
    OR (evidence_record.expires_at IS NOT NULL AND evidence_record.expires_at <= clock_timestamp())
    OR NEW.committed_resource <> jsonb_build_object(
      'authority_version', 'optional_route_v2',
      'community_id', NEW.community_id,
      'href', '/c/' || NEW.community_id,
      'canonical_route', jsonb_build_object(
        'family', binding_record.family,
        'root_label', binding_record.root_label,
        'root_label_display', binding_record.root_label_display,
        'path_segment', binding_record.path_segment,
        'href', binding_record.href,
        'app_host', NULL
      )
    ) THEN
    RAISE EXCEPTION 'committed route attachment lacks matching active verified authority';
  END IF;

  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_community_route_attachment_requirement_state() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'community route attachment requirement state cannot be deleted';
  END IF;
  IF ROW(
    NEW.attachment_intent_id, NEW.actor_id, NEW.requirement_kind,
    NEW.requirement_hash, NEW.provider_id, NEW.provider_binding_hash,
    NEW.provider_configuration_kind, NEW.provider_configuration_ref,
    NEW.provider_configuration_version, NEW.family, NEW.root_label,
    NEW.root_label_display, NEW.path_segment, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.attachment_intent_id, OLD.actor_id, OLD.requirement_kind,
    OLD.requirement_hash, OLD.provider_id, OLD.provider_binding_hash,
    OLD.provider_configuration_kind, OLD.provider_configuration_ref,
    OLD.provider_configuration_version, OLD.family, OLD.root_label,
    OLD.root_label_display, OLD.path_segment, OLD.created_at
  ) THEN
    RAISE EXCEPTION 'community route attachment requirement authority is immutable';
  END IF;
  IF NOT (
    (
      OLD.status IN ('unmet', 'failed', 'expired')
      AND NEW.status = 'pending'
      AND NEW.generation = OLD.generation + 1
      AND NEW.current_ceremony_intent_id IS NOT NULL
      AND NEW.satisfied_at IS NULL
    )
    OR (
      OLD.status = 'pending'
      AND NEW.status IN ('satisfied', 'failed', 'expired')
      AND NEW.generation = OLD.generation
      AND NEW.current_ceremony_intent_id = OLD.current_ceremony_intent_id
    )
  ) THEN
    RAISE EXCEPTION 'community route attachment requirement transition is not allowed: % -> %',
      OLD.status,
      NEW.status;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_community_route_authority_grant_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(
    NEW.grant_id,
    NEW.community_id,
    NEW.principal_user_id,
    NEW.authority,
    NEW.source_kind,
    NEW.source_policy_ref,
    NEW.granted_at,
    NEW.granted_by_user_id
  ) IS DISTINCT FROM ROW(
    OLD.grant_id,
    OLD.community_id,
    OLD.principal_user_id,
    OLD.authority,
    OLD.source_kind,
    OLD.source_policy_ref,
    OLD.granted_at,
    OLD.granted_by_user_id
  ) THEN
    RAISE EXCEPTION 'community route authority grant identity is immutable';
  END IF;
  IF OLD.status = 'revoked' THEN
    RAISE EXCEPTION 'revoked community route authority grants are terminal';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_community_route_authority_version() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.route_authority_version IS DISTINCT FROM OLD.route_authority_version THEN
    RAISE EXCEPTION 'community route authority version is immutable';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_community_route_revalidation_attempt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  db_now TIMESTAMPTZ;
  session_record community_route_revalidation_sessions%ROWTYPE;
  consumed_count INTEGER;
  semantic_contradiction BOOLEAN;
BEGIN
  db_now := clock_timestamp();
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'route revalidation completion attempts cannot be deleted';
  END IF;
  SELECT * INTO session_record
    FROM community_route_revalidation_sessions
   WHERE route_revalidation_id = COALESCE(NEW.route_revalidation_id, OLD.route_revalidation_id)
     AND revalidation_session_id = COALESCE(NEW.revalidation_session_id, OLD.revalidation_session_id)
   FOR UPDATE;
  IF session_record.revalidation_session_id IS NULL THEN
    RAISE EXCEPTION 'route revalidation completion attempt lacks its session';
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.created_at := db_now;
    NEW.updated_at := db_now;
    SELECT count(*)::integer INTO consumed_count
      FROM community_route_revalidation_completion_attempts
     WHERE route_revalidation_id = NEW.route_revalidation_id AND state = 'consumed';
    IF session_record.status <> 'pending'
      OR session_record.expires_at <= db_now
      OR NEW.route_binding_id IS DISTINCT FROM session_record.route_binding_id
      OR NEW.expected_binding_generation IS DISTINCT FROM session_record.expected_binding_generation
      OR NEW.expected_verified_evidence_ref IS DISTINCT FROM session_record.expected_verified_evidence_ref
      OR NEW.attempt_number IS DISTINCT FROM consumed_count + 1
      OR consumed_count >= 3
      OR NEW.state <> 'leased'
      OR NEW.fence_token <> 1
      OR NEW.lease_expires_at <= db_now
      OR NEW.lease_expires_at > db_now + INTERVAL '16 seconds'
      OR NEW.lease_expires_at > session_record.expires_at
      OR NEW.terminal_result_document IS NOT NULL
      OR NEW.terminal_observed_expires_at IS NOT NULL
    THEN RAISE EXCEPTION 'route revalidation completion attempt is not admissible'; END IF;
    RETURN NEW;
  END IF;

  IF ROW(
    NEW.route_revalidation_attempt_id, NEW.route_revalidation_id,
    NEW.revalidation_session_id, NEW.route_binding_id,
    NEW.expected_binding_generation, NEW.expected_verified_evidence_ref,
    NEW.attempt_number, NEW.idempotency_key, NEW.completion_request_hash,
    NEW.evidence_ref, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.route_revalidation_attempt_id, OLD.route_revalidation_id,
    OLD.revalidation_session_id, OLD.route_binding_id,
    OLD.expected_binding_generation, OLD.expected_verified_evidence_ref,
    OLD.attempt_number, OLD.idempotency_key, OLD.completion_request_hash,
    OLD.evidence_ref, OLD.created_at
  ) THEN RAISE EXCEPTION 'route revalidation completion attempt authority is immutable'; END IF;

  IF OLD.state = 'leased' AND NEW.state = 'released'
    AND NEW.fence_token = OLD.fence_token AND NEW.lease_expires_at = OLD.lease_expires_at
    AND NEW.consumption_kind IS NULL AND NEW.result_hash IS NULL
    AND NEW.terminal_result_document IS NULL
    AND NEW.terminal_observed_expires_at IS NULL AND NEW.terminal_at IS NULL
  THEN NEW.updated_at := db_now; RETURN NEW; END IF;
  IF OLD.state IN ('released', 'leased') AND NEW.state = 'leased'
    AND NEW.fence_token = OLD.fence_token + 1
    AND NEW.lease_expires_at > db_now
    AND NEW.lease_expires_at <= db_now + INTERVAL '16 seconds'
    AND NEW.lease_expires_at <= session_record.expires_at
    AND (OLD.state = 'released' OR OLD.lease_expires_at <= db_now)
    AND NEW.consumption_kind IS NULL AND NEW.result_hash IS NULL
    AND NEW.terminal_result_document IS NULL
    AND NEW.terminal_observed_expires_at IS NULL AND NEW.terminal_at IS NULL
  THEN NEW.updated_at := db_now; RETURN NEW; END IF;

  semantic_contradiction := OLD.state = 'leased' AND NEW.state = 'consumed'
    AND NEW.consumption_kind = 'challenge_mismatch' AND NEW.result_hash IS NULL
    AND NEW.terminal_result_document IS NULL
    AND NEW.terminal_observed_expires_at IS NULL
    AND session_record.status = 'pending';
  IF semantic_contradiction THEN
    IF NEW.fence_token <> OLD.fence_token OR NEW.lease_expires_at <> OLD.lease_expires_at
       OR OLD.lease_expires_at <= db_now OR NEW.terminal_at IS NULL OR NEW.terminal_at > db_now
    THEN RAISE EXCEPTION 'semantic contradiction attempt transition is not allowed'; END IF;
    NEW.updated_at := db_now;
    RETURN NEW;
  END IF;

  IF OLD.state = 'leased' AND NEW.state = 'consumed'
    AND NEW.fence_token = OLD.fence_token AND NEW.lease_expires_at = OLD.lease_expires_at
    AND NEW.consumption_kind IS NOT NULL AND NEW.result_hash IS NOT NULL
    AND NEW.terminal_result_document IS NOT NULL AND NEW.terminal_at IS NOT NULL
    AND (
      (NEW.consumption_kind = 'database_time_expired'
       AND NEW.terminal_observed_expires_at IS NOT NULL
       AND NEW.terminal_observed_expires_at <= db_now)
      OR (NEW.consumption_kind <> 'database_time_expired'
          AND NEW.terminal_observed_expires_at IS NULL)
    )
    AND NEW.terminal_at <= db_now
    AND ((NEW.consumption_kind <> 'session_expired' AND OLD.lease_expires_at > db_now
          AND session_record.status = 'pending' AND session_record.expires_at > db_now)
      OR (NEW.consumption_kind = 'session_expired' AND session_record.expires_at <= db_now))
    AND validate_community_route_revalidation_terminal_document(
      NEW.terminal_result_document, NEW.result_hash, NEW.consumption_kind,
      NEW.route_revalidation_id, NEW.revalidation_session_id,
      NEW.route_revalidation_attempt_id, NEW.route_binding_id,
      NEW.expected_binding_generation, NEW.idempotency_key,
      NEW.completion_request_hash)
  THEN NEW.updated_at := db_now; RETURN NEW; END IF;
  RAISE EXCEPTION 'route revalidation completion attempt transition is not allowed: % -> %',
    OLD.state, NEW.state;
END;
$$;

CREATE FUNCTION guard_community_route_revalidation_session_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'route revalidation sessions cannot be deleted';
  END IF;
  IF ROW(
    NEW.revalidation_session_id, NEW.route_revalidation_id, NEW.start_fence_token,
    NEW.community_id, NEW.route_binding_id, NEW.principal_kind, NEW.principal_id,
    NEW.expected_binding_generation, NEW.expected_verified_evidence_ref,
    NEW.requirement_hash, NEW.start_request_hash, NEW.provider_id,
    NEW.provider_binding_hash, NEW.provider_configuration_kind,
    NEW.provider_configuration_reference, NEW.provider_configuration_version,
    NEW.protocol_version, NEW.environment, NEW.family, NEW.root_label,
    NEW.root_label_display, NEW.path_segment, NEW.upstream_session_ref,
    NEW.start_presentation,
    NEW.started_at, NEW.expires_at, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.revalidation_session_id, OLD.route_revalidation_id, OLD.start_fence_token,
    OLD.community_id, OLD.route_binding_id, OLD.principal_kind, OLD.principal_id,
    OLD.expected_binding_generation, OLD.expected_verified_evidence_ref,
    OLD.requirement_hash, OLD.start_request_hash, OLD.provider_id,
    OLD.provider_binding_hash, OLD.provider_configuration_kind,
    OLD.provider_configuration_reference, OLD.provider_configuration_version,
    OLD.protocol_version, OLD.environment, OLD.family, OLD.root_label,
    OLD.root_label_display, OLD.path_segment, OLD.upstream_session_ref,
    OLD.start_presentation,
    OLD.started_at, OLD.expires_at, OLD.created_at
  ) THEN
    RAISE EXCEPTION 'route revalidation session authority is immutable';
  END IF;
  IF OLD.status = 'pending'
    AND NEW.status IN ('completed', 'failed', 'expired')
    AND NEW.terminal_at IS NOT NULL
    AND NEW.terminal_at <= clock_timestamp()
    AND (NEW.status <> 'expired' OR NEW.terminal_at >= NEW.expires_at)
  THEN
    NEW.updated_at := clock_timestamp();
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'route revalidation session transition is not allowed: % -> %',
    OLD.status, NEW.status;
END;
$$;

CREATE FUNCTION guard_community_route_revalidation_start() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  db_now TIMESTAMPTZ;
  community_record communities%ROWTYPE;
  binding_record community_canonical_route_bindings%ROWTYPE;
  evidence_record community_route_ownership_evidence%ROWTYPE;
  creation_session namespace_ownership_sessions%ROWTYPE;
  prior_session community_route_revalidation_sessions%ROWTYPE;
  prior_snapshot community_route_revalidation_evidence_snapshots%ROWTYPE;
BEGIN
  db_now := clock_timestamp();
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'route revalidation start reservations cannot be deleted';
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.created_at := db_now;
    NEW.updated_at := db_now;
    -- Common route lock order: community -> binding -> evidence/session authority.
    SELECT * INTO community_record
      FROM communities
     WHERE community_id = NEW.community_id
     FOR UPDATE;
    SELECT * INTO binding_record
      FROM community_canonical_route_bindings
     WHERE route_binding_id = NEW.route_binding_id
       AND community_id = NEW.community_id
     FOR UPDATE;

    IF community_record.community_id IS NULL
      OR binding_record.route_binding_id IS NULL
      OR community_record.status <> 'active'
      OR community_record.canonical_route_binding_id IS DISTINCT FROM NEW.route_binding_id
      OR binding_record.binding_generation IS DISTINCT FROM NEW.expected_binding_generation
      OR binding_record.verified_evidence_ref IS DISTINCT FROM NEW.expected_verified_evidence_ref
      OR binding_record.family IS DISTINCT FROM NEW.family
      OR binding_record.root_label IS DISTINCT FROM NEW.root_label
      OR binding_record.root_label_display IS DISTINCT FROM NEW.root_label_display
      OR binding_record.path_segment IS DISTINCT FROM NEW.path_segment
      OR NEW.state <> 'acquired'
      OR NEW.fence_token <> 1
      OR NEW.lease_expires_at <= db_now
      OR NEW.lease_expires_at > db_now + INTERVAL '16 seconds'
    THEN
      RAISE EXCEPTION 'route revalidation reservation does not match the canonical binding';
    END IF;

    IF NEW.expected_verified_evidence_ref IS NOT NULL THEN
      SELECT * INTO evidence_record
        FROM community_route_ownership_evidence
       WHERE evidence_ref = NEW.expected_verified_evidence_ref
       FOR SHARE;
      IF evidence_record.evidence_ref IS NULL
        OR evidence_record.family IS DISTINCT FROM NEW.family
        OR evidence_record.root_label IS DISTINCT FROM NEW.root_label
        OR evidence_record.root_label_display IS DISTINCT FROM NEW.root_label_display
        OR evidence_record.path_segment IS DISTINCT FROM NEW.path_segment
        OR evidence_record.binding_generation IS DISTINCT FROM NEW.expected_binding_generation
        OR evidence_record.provider_id IS DISTINCT FROM NEW.provider_id
        OR evidence_record.provider_binding_hash IS DISTINCT FROM NEW.provider_binding_hash
        OR evidence_record.provider_configuration_version IS DISTINCT FROM NEW.provider_configuration_version
      THEN
        RAISE EXCEPTION 'route revalidation reservation does not match current evidence';
      END IF;

      IF evidence_record.origin = 'creation_ceremony' THEN
        SELECT * INTO creation_session
          FROM namespace_ownership_sessions
         WHERE ceremony_intent_id = evidence_record.creation_ceremony_intent_id
         FOR SHARE;
        IF creation_session.namespace_session_id IS NULL
          OR creation_session.provider_configuration_kind IS DISTINCT FROM NEW.provider_configuration_kind
          OR creation_session.provider_configuration_ref IS DISTINCT FROM NEW.provider_configuration_reference
          OR creation_session.protocol_version IS DISTINCT FROM NEW.protocol_version
          OR creation_session.environment IS DISTINCT FROM NEW.environment
        THEN
          RAISE EXCEPTION 'route revalidation reservation lacks creation provider authority';
        END IF;
      ELSE
        SELECT * INTO prior_snapshot
          FROM community_route_revalidation_evidence_snapshots
         WHERE route_revalidation_attempt_id = evidence_record.route_revalidation_attempt_id
         FOR SHARE;
        IF prior_snapshot.evidence_ref IS NULL
          OR prior_snapshot.provider_configuration_kind IS DISTINCT FROM NEW.provider_configuration_kind
          OR prior_snapshot.provider_configuration_reference IS DISTINCT FROM NEW.provider_configuration_reference
          OR prior_snapshot.protocol_version IS DISTINCT FROM NEW.protocol_version
          OR prior_snapshot.environment IS DISTINCT FROM NEW.environment
        THEN
          RAISE EXCEPTION 'route revalidation reservation lacks prior snapshot authority';
        END IF;
      END IF;
    ELSE
      -- Same-root recovery inherits authority from the operation that moved the
      -- binding to this suspended generation; it never guesses from route text.
      SELECT session.* INTO prior_session
        FROM community_route_revalidation_completion_attempts AS attempt
        JOIN community_route_revalidation_sessions AS session
          ON session.route_revalidation_id = attempt.route_revalidation_id
         AND session.revalidation_session_id = attempt.revalidation_session_id
       WHERE attempt.route_binding_id = NEW.route_binding_id
         AND attempt.expected_binding_generation = NEW.expected_binding_generation - 1
         AND attempt.state = 'consumed'
         AND attempt.consumption_kind IN (
           'missing_root', 'control_failed', 'challenge_mismatch',
           'insufficient_expiry', 'disputed', 'revoked', 'database_time_expired'
         )
       ORDER BY attempt.terminal_at DESC
       LIMIT 1
       FOR SHARE OF session;
      IF prior_session.revalidation_session_id IS NULL
        OR binding_record.route_lifecycle_status <> 'suspended'
        OR prior_session.principal_kind IS DISTINCT FROM NEW.principal_kind
        OR prior_session.principal_id IS DISTINCT FROM NEW.principal_id
        OR prior_session.provider_id IS DISTINCT FROM NEW.provider_id
        OR prior_session.provider_binding_hash IS DISTINCT FROM NEW.provider_binding_hash
        OR prior_session.provider_configuration_kind IS DISTINCT FROM NEW.provider_configuration_kind
        OR prior_session.provider_configuration_reference IS DISTINCT FROM NEW.provider_configuration_reference
        OR prior_session.provider_configuration_version IS DISTINCT FROM NEW.provider_configuration_version
        OR prior_session.protocol_version IS DISTINCT FROM NEW.protocol_version
        OR prior_session.environment IS DISTINCT FROM NEW.environment
        OR prior_session.family IS DISTINCT FROM NEW.family
        OR prior_session.root_label IS DISTINCT FROM NEW.root_label
        OR prior_session.root_label_display IS DISTINCT FROM NEW.root_label_display
        OR prior_session.path_segment IS DISTINCT FROM NEW.path_segment
      THEN
        RAISE EXCEPTION 'route revalidation recovery lacks prior operation authority';
      END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF ROW(
    NEW.route_revalidation_id, NEW.revalidation_session_id, NEW.community_id,
    NEW.route_binding_id, NEW.principal_kind, NEW.principal_id,
    NEW.expected_binding_generation, NEW.expected_verified_evidence_ref,
    NEW.requirement_hash, NEW.provider_id, NEW.provider_binding_hash,
    NEW.provider_configuration_kind, NEW.provider_configuration_reference,
    NEW.provider_configuration_version, NEW.protocol_version, NEW.environment,
    NEW.family, NEW.root_label, NEW.root_label_display, NEW.path_segment,
    NEW.start_request_hash, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.route_revalidation_id, OLD.revalidation_session_id, OLD.community_id,
    OLD.route_binding_id, OLD.principal_kind, OLD.principal_id,
    OLD.expected_binding_generation, OLD.expected_verified_evidence_ref,
    OLD.requirement_hash, OLD.provider_id, OLD.provider_binding_hash,
    OLD.provider_configuration_kind, OLD.provider_configuration_reference,
    OLD.provider_configuration_version, OLD.protocol_version, OLD.environment,
    OLD.family, OLD.root_label, OLD.root_label_display, OLD.path_segment,
    OLD.start_request_hash, OLD.created_at
  ) THEN
    RAISE EXCEPTION 'route revalidation reservation authority is immutable';
  END IF;

  IF OLD.state = 'acquired'
    AND NEW.state IN ('released', 'finalized')
    AND NEW.fence_token = OLD.fence_token
    AND NEW.lease_expires_at = OLD.lease_expires_at
    AND OLD.lease_expires_at > db_now
  THEN
    NEW.updated_at := db_now;
    RETURN NEW;
  END IF;
  IF OLD.state IN ('released', 'acquired')
    AND NEW.state = 'acquired'
    AND NEW.fence_token = OLD.fence_token + 1
    AND NEW.lease_expires_at > db_now
    AND NEW.lease_expires_at <= db_now + INTERVAL '16 seconds'
    AND (OLD.state = 'released' OR OLD.lease_expires_at <= db_now)
  THEN
    NEW.updated_at := db_now;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'route revalidation reservation transition is not allowed: % -> %',
    OLD.state, NEW.state;
END;
$$;

CREATE FUNCTION guard_dance_attempt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target_upload dance_upload_reservations%ROWTYPE;
  target_session dance_sessions%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Dance attempts cannot be deleted'; END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT * INTO target_upload FROM dance_upload_reservations
     WHERE reservation_id = NEW.reservation_id FOR SHARE;
    SELECT * INTO target_session FROM dance_sessions
     WHERE session_id = NEW.session_id FOR UPDATE;
    IF target_upload.reservation_id IS NULL OR target_upload.state <> 'sealed'
       OR target_upload.session_id <> NEW.session_id
       OR target_upload.server_sha256 <> NEW.sealed_media_sha256
       OR target_session.state <> 'uploaded' THEN
      RAISE EXCEPTION 'Dance attempt requires the exact sealed session upload';
    END IF;
    UPDATE dance_sessions SET state = 'grading_pending', version = version + 1
     WHERE session_id = NEW.session_id AND state = 'uploaded';
    RETURN NEW;
  END IF;
  IF ROW(NEW.attempt_id, NEW.session_id, NEW.reservation_id,
    NEW.sealed_media_sha256, NEW.input_digest, NEW.created_at)
    IS DISTINCT FROM ROW(OLD.attempt_id, OLD.session_id, OLD.reservation_id,
    OLD.sealed_media_sha256, OLD.input_digest, OLD.created_at)
    OR OLD.state <> 'grading_pending'
    OR NEW.state NOT IN ('completed', 'rejected', 'processing_failed') THEN
    RAISE EXCEPTION 'Invalid Dance attempt transition';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_dance_attempt_action() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'Dance attempt actions are immutable'; END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_dance_attempt_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target_attempt dance_attempts%ROWTYPE;
  target_outbox dance_attempt_outbox%ROWTYPE;
  target_session dance_sessions%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'Dance attempt evidence is immutable'; END IF;
  SELECT * INTO target_attempt FROM dance_attempts WHERE attempt_id = NEW.attempt_id FOR UPDATE;
  SELECT * INTO target_outbox FROM dance_attempt_outbox
   WHERE attempt_id = NEW.attempt_id FOR UPDATE;
  SELECT * INTO target_session FROM dance_sessions
   WHERE session_id = NEW.session_id FOR UPDATE;
  IF target_attempt.attempt_id IS NULL OR target_attempt.state <> 'grading_pending'
     OR target_attempt.session_id <> NEW.session_id
     OR target_outbox.state <> 'running'
     OR target_outbox.claim_owner <> NEW.claim_owner
     OR target_outbox.claim_fence <> NEW.claim_fence
     OR target_outbox.lease_expires_at <= clock_timestamp()
     OR target_session.captured_admission_state <> 'shadow'
     OR NEW.qualification_outcome <> 'suppressed_shadow'
     OR NEW.scored_duration_ms <> target_session.expected_scored_duration_ms
     OR NEW.scored_window_start_ms < target_session.cue_observation_end_ms THEN
    RAISE EXCEPTION 'Dance terminal evidence lacks current shadow lease authority';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_dance_attempt_operator_item() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Dance attempt operator items are immutable';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_dance_choreography() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target dance_choreography_revisions%ROWTYPE;
  song posts%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Dance choreographies cannot be deleted';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NOT active_owned_persona(NEW.creator_account_id, NEW.creator_persona_id) THEN
      RAISE EXCEPTION 'Dance choreography requires an active owned persona';
    END IF;
    SELECT * INTO song FROM posts
     WHERE community_id = NEW.community_id AND post_id = NEW.song_post_id FOR SHARE;
    IF song.post_id IS NULL OR song.post_type <> 'song' OR song.status <> 'published' THEN
      RAISE EXCEPTION 'Dance choreography requires a published song';
    END IF;
  ELSE
    IF ROW(NEW.choreography_id, NEW.community_id, NEW.song_post_id,
      NEW.creator_account_id, NEW.creator_persona_id, NEW.created_at)
      IS DISTINCT FROM ROW(OLD.choreography_id, OLD.community_id, OLD.song_post_id,
      OLD.creator_account_id, OLD.creator_persona_id, OLD.created_at) THEN
      RAISE EXCEPTION 'Dance choreography identity is immutable';
    END IF;
    IF NEW IS NOT DISTINCT FROM OLD THEN
      RETURN NEW;
    END IF;
    IF NEW.version <> OLD.version + 1 OR NEW.updated_at <= OLD.updated_at THEN
      RAISE EXCEPTION 'Dance choreography update requires the next version';
    END IF;
    IF NOT (
      (OLD.status = 'draft' AND NEW.status IN ('processing', 'disabled', 'retired'))
      OR (OLD.status = 'processing' AND NEW.status IN ('processing', 'ready', 'disabled', 'retired'))
      OR (OLD.status = 'ready' AND NEW.status IN ('ready', 'disabled'))
      OR (OLD.status = 'disabled' AND NEW.status = 'retired')
    ) THEN
      RAISE EXCEPTION 'Invalid Dance choreography transition';
    END IF;
  END IF;
  IF NEW.active_revision IS NOT NULL THEN
    SELECT * INTO target FROM dance_choreography_revisions
     WHERE choreography_id = NEW.choreography_id AND revision = NEW.active_revision;
    IF target.choreography_id IS NULL OR target.status <> 'ready' THEN
      RAISE EXCEPTION 'Dance active revision must be ready';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_dance_choreography_revision() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  aggregate dance_choreographies%ROWTYPE;
  reference_post posts%ROWTYPE;
  selected_segment dance_song_segments%ROWTYPE;
  artifact dance_reference_artifacts%ROWTYPE;
  latest_revision BIGINT;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Dance choreography revisions cannot be deleted';
  END IF;
  SELECT * INTO aggregate FROM dance_choreographies
   WHERE choreography_id = NEW.choreography_id FOR SHARE;
  SELECT * INTO reference_post FROM posts
   WHERE community_id = NEW.community_id AND post_id = NEW.reference_video_post_id FOR SHARE;
  IF aggregate.choreography_id IS NULL
     OR aggregate.community_id <> NEW.community_id OR aggregate.song_post_id <> NEW.song_post_id
     OR reference_post.post_id IS NULL OR reference_post.post_type <> 'video'
     OR reference_post.status <> 'published' OR reference_post.visibility <> 'public' THEN
    RAISE EXCEPTION 'Dance revision requires exact aggregate and published reference video';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF aggregate.status NOT IN ('processing', 'ready') THEN
      RAISE EXCEPTION 'Dance choreography is not open for a revision append';
    END IF;
    IF NEW.aggregate_version <> aggregate.version THEN
      RAISE EXCEPTION 'Dance revision append requires the current aggregate version';
    END IF;
    SELECT max(existing.revision) INTO latest_revision
      FROM dance_choreography_revisions AS existing
     WHERE existing.choreography_id = NEW.choreography_id;
    IF NEW.revision <> COALESCE(latest_revision, 0) + 1 THEN
      RAISE EXCEPTION 'Dance revisions must append in order';
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF OLD.status = 'processing' AND aggregate.status IN ('disabled', 'retired') THEN
      RAISE EXCEPTION 'Disabled or retired Dance choreography rejects late processing';
    END IF;
    IF ROW(NEW.choreography_id, NEW.revision, NEW.aggregate_version,
      NEW.community_id, NEW.song_post_id,
      NEW.audio_revision, NEW.requested_start_ms, NEW.requested_end_ms,
      NEW.reference_video_post_id, NEW.reference_video_song_post_id,
      NEW.reference_video_audio_revision, NEW.reference_video_object_ref,
      NEW.reference_video_sha256, NEW.mirror_policy, NEW.alignment_policy_version,
      NEW.alignment_adapter, NEW.alignment_revision, NEW.pose_model_version,
      NEW.pose_runtime_version, NEW.feature_schema_version, NEW.scorer_contract_version,
      NEW.fingerprint_policy_version, NEW.integrity_policy_version,
      NEW.owner_policy_revision, NEW.owner_policy_hash, NEW.revision_terms_hash, NEW.created_at)
      IS DISTINCT FROM ROW(OLD.choreography_id, OLD.revision, OLD.aggregate_version,
      OLD.community_id,
      OLD.song_post_id, OLD.audio_revision, OLD.requested_start_ms, OLD.requested_end_ms,
      OLD.reference_video_post_id, OLD.reference_video_song_post_id,
      OLD.reference_video_audio_revision, OLD.reference_video_object_ref,
      OLD.reference_video_sha256, OLD.mirror_policy, OLD.alignment_policy_version,
      OLD.alignment_adapter, OLD.alignment_revision, OLD.pose_model_version,
      OLD.pose_runtime_version, OLD.feature_schema_version, OLD.scorer_contract_version,
      OLD.fingerprint_policy_version, OLD.integrity_policy_version,
      OLD.owner_policy_revision, OLD.owner_policy_hash, OLD.revision_terms_hash, OLD.created_at) THEN
      RAISE EXCEPTION 'Dance revision terms are immutable';
    END IF;
    IF NEW IS NOT DISTINCT FROM OLD THEN
      RETURN NEW;
    END IF;
    IF NOT (
      (OLD.status = 'processing' AND NEW.status IN ('ready', 'processing_failed'))
      OR (OLD.status = 'ready' AND NEW.status IN ('disabled', 'retired'))
    ) THEN
      RAISE EXCEPTION 'Invalid Dance revision transition';
    END IF;
  END IF;
  IF NEW.status IN ('ready', 'disabled', 'retired') THEN
    IF NEW.status = 'ready' AND aggregate.status IN ('disabled', 'retired') THEN
      RAISE EXCEPTION 'Disabled or retired Dance choreography cannot become ready';
    END IF;
    SELECT * INTO selected_segment FROM dance_song_segments WHERE segment_id = NEW.segment_id;
    SELECT * INTO artifact FROM dance_reference_artifacts
     WHERE choreography_id = NEW.choreography_id AND revision = NEW.revision;
    IF selected_segment.segment_id IS NULL
       OR selected_segment.community_id <> NEW.community_id
       OR selected_segment.song_post_id <> NEW.song_post_id
       OR selected_segment.audio_revision <> NEW.audio_revision
       OR selected_segment.start_ms <> NEW.requested_start_ms
       OR selected_segment.end_ms <> NEW.requested_end_ms
       OR NEW.reference_video_scored_end_ms - NEW.reference_video_scored_start_ms
          <> selected_segment.duration_ms
       OR artifact.artifact_id IS NULL THEN
      RAISE EXCEPTION 'Ready Dance revision lacks exact segment, window, or artifact';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_dance_media_cleanup_operation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Dance cleanup operations cannot be deleted'; END IF;
  IF TG_OP = 'INSERT' THEN RETURN NEW; END IF;
  IF ROW(NEW.cleanup_operation_id, NEW.session_id, NEW.artifact_kind,
    NEW.private_artifact_ref, NEW.created_at)
    IS DISTINCT FROM ROW(OLD.cleanup_operation_id, OLD.session_id, OLD.artifact_kind,
    OLD.private_artifact_ref, OLD.created_at)
    OR NOT (
      (OLD.state IN ('pending', 'failed') AND NEW.state = 'leased'
        AND NEW.lease_fence = OLD.lease_fence + 1 AND NEW.attempts = OLD.attempts + 1)
      OR (OLD.state = 'leased' AND OLD.lease_expires_at <= clock_timestamp()
        AND NEW.state = 'leased' AND NEW.lease_fence = OLD.lease_fence + 1
        AND NEW.attempts = OLD.attempts + 1)
      OR (OLD.state = 'leased' AND NEW.state IN ('completed', 'failed')
        AND NEW.lease_fence = OLD.lease_fence AND NEW.attempts = OLD.attempts)
    ) THEN
    RAISE EXCEPTION 'Invalid Dance cleanup transition';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_dance_processing_attempt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target dance_choreography_revisions%ROWTYPE;
  latest dance_reference_processing_attempts%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Dance processing attempts cannot be deleted';
  END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT * INTO target FROM dance_choreography_revisions
     WHERE choreography_id = NEW.choreography_id AND revision = NEW.revision FOR SHARE;
    SELECT * INTO latest FROM dance_reference_processing_attempts
     WHERE choreography_id = NEW.choreography_id AND revision = NEW.revision
     ORDER BY attempt_number DESC LIMIT 1 FOR SHARE;
    IF target.choreography_id IS NULL OR target.status <> 'processing'
       OR NEW.attempt_number <> COALESCE(latest.attempt_number, 0) + 1
       OR NEW.lease_expires_at <= clock_timestamp()
       OR (latest.processing_attempt_id IS NOT NULL
         AND (latest.state <> 'failed' OR latest.retryable IS NOT TRUE)) THEN
      RAISE EXCEPTION 'Dance processing attempt is not the exact next retry';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF ROW(NEW.processing_attempt_id, NEW.choreography_id, NEW.revision,
      NEW.attempt_number, NEW.adapter_id, NEW.adapter_revision,
      NEW.input_digest, NEW.created_at)
      IS DISTINCT FROM ROW(OLD.processing_attempt_id, OLD.choreography_id, OLD.revision,
      OLD.attempt_number, OLD.adapter_id, OLD.adapter_revision,
      OLD.input_digest, OLD.created_at) THEN
      RAISE EXCEPTION 'Dance processing attempt identity is immutable';
    END IF;
    IF OLD.prepared_operation IS NOT NULL AND ROW(
      NEW.prepared_operation, NEW.prepared_operation_bytes, NEW.prepared_operation_sha256
    ) IS DISTINCT FROM ROW(
      OLD.prepared_operation, OLD.prepared_operation_bytes, OLD.prepared_operation_sha256
    ) THEN
      RAISE EXCEPTION 'Dance prepared operation is immutable';
    END IF;
    IF NEW IS NOT DISTINCT FROM OLD THEN
      RETURN NEW;
    END IF;
    IF OLD.state = 'leased' AND NEW.state = 'leased' THEN
      IF OLD.prepared_operation IS NULL AND NEW.prepared_operation IS NOT NULL THEN
        IF NEW.lease_owner <> OLD.lease_owner OR NEW.lease_fence <> OLD.lease_fence
           OR NEW.lease_expires_at <> OLD.lease_expires_at
           OR OLD.lease_expires_at <= clock_timestamp() OR NEW.updated_at <= OLD.updated_at THEN
          RAISE EXCEPTION 'Dance prepared operation fence is stale';
        END IF;
      ELSIF OLD.lease_expires_at > clock_timestamp()
         AND NEW.lease_owner = OLD.lease_owner
         AND NEW.lease_fence = OLD.lease_fence
         AND NEW.lease_expires_at > OLD.lease_expires_at
         AND NEW.updated_at > OLD.updated_at THEN
        NULL;
      ELSIF OLD.lease_expires_at > clock_timestamp()
         OR NEW.lease_expires_at <= clock_timestamp()
         OR NEW.lease_fence <> OLD.lease_fence + 1
         OR NEW.updated_at <= OLD.updated_at THEN
        RAISE EXCEPTION 'Dance processing lease cannot be reclaimed';
      END IF;
    ELSIF OLD.state = 'leased' AND NEW.state IN ('succeeded', 'failed', 'exhausted') THEN
      IF OLD.lease_expires_at <= clock_timestamp()
         OR NEW.lease_fence <> OLD.lease_fence OR NEW.updated_at <= OLD.updated_at THEN
        RAISE EXCEPTION 'Dance processing terminal fence is stale';
      END IF;
    ELSE
      RAISE EXCEPTION 'Invalid Dance processing attempt transition';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_dance_reference_artifact() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target dance_choreography_revisions%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Dance reference artifacts are immutable';
  END IF;
  SELECT * INTO target FROM dance_choreography_revisions
   WHERE choreography_id = NEW.choreography_id AND revision = NEW.revision FOR SHARE;
  IF target.choreography_id IS NULL
     OR target.pose_model_version <> NEW.pose_model_version
     OR target.pose_runtime_version <> NEW.pose_runtime_version
     OR target.feature_schema_version <> NEW.feature_schema_version
     OR target.scorer_contract_version <> NEW.scorer_contract_version
     OR target.integrity_policy_version <> NEW.integrity_policy_version THEN
    RAISE EXCEPTION 'Dance reference artifact does not match revision terms';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_dance_reference_outbox() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target dance_choreography_revisions%ROWTYPE;
  payload_keys TEXT[];
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Dance reference outbox rows cannot be deleted';
  END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT * INTO target FROM dance_choreography_revisions
     WHERE choreography_id = NEW.choreography_id AND revision = NEW.revision FOR SHARE;
    SELECT array_agg(key ORDER BY key) INTO payload_keys FROM jsonb_object_keys(NEW.payload) AS key;
    IF target.choreography_id IS NULL OR target.status <> 'processing'
       OR payload_keys IS DISTINCT FROM
          ARRAY['choreography_id', 'effect_identity', 'revision', 'revision_terms_hash']::TEXT[]
       OR NEW.payload->>'choreography_id' <> NEW.choreography_id
       OR NEW.payload->>'effect_identity' <> NEW.effect_identity
       OR NEW.payload->>'revision' <> NEW.revision::TEXT
       OR NEW.payload->>'revision_terms_hash' <> target.revision_terms_hash THEN
      RAISE EXCEPTION 'Dance reference outbox payload is not exact processing authority';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF ROW(NEW.outbox_event_id, NEW.choreography_id, NEW.revision, NEW.event_type,
      NEW.effect_identity, NEW.payload, NEW.payload_sha256, NEW.created_at)
      IS DISTINCT FROM ROW(OLD.outbox_event_id, OLD.choreography_id, OLD.revision,
      OLD.event_type, OLD.effect_identity, OLD.payload, OLD.payload_sha256, OLD.created_at) THEN
      RAISE EXCEPTION 'Dance reference outbox identity is immutable';
    END IF;
    IF NEW IS NOT DISTINCT FROM OLD THEN
      RETURN NEW;
    END IF;
    IF OLD.state IN ('pending', 'failed') AND NEW.state = 'running' THEN
      IF (OLD.state = 'failed' AND OLD.next_eligible_at > clock_timestamp())
         OR NEW.lease_expires_at <= clock_timestamp()
         OR NEW.delivery_attempts <> OLD.delivery_attempts + 1
         OR NEW.claim_fence <> OLD.claim_fence + 1 OR NEW.updated_at <= OLD.updated_at THEN
        RAISE EXCEPTION 'Dance outbox claim fence is invalid';
      END IF;
    ELSIF OLD.state = 'running' AND NEW.state = 'running' THEN
      IF OLD.lease_expires_at > clock_timestamp()
         AND NEW.claim_owner = OLD.claim_owner
         AND NEW.delivery_attempts = OLD.delivery_attempts
         AND NEW.claim_fence = OLD.claim_fence
         AND NEW.lease_expires_at > OLD.lease_expires_at
         AND NEW.updated_at > OLD.updated_at THEN
        NULL;
      ELSIF OLD.lease_expires_at > clock_timestamp()
         OR NEW.lease_expires_at <= clock_timestamp()
         OR NEW.delivery_attempts <> OLD.delivery_attempts + 1
         OR NEW.claim_fence <> OLD.claim_fence + 1 OR NEW.updated_at <= OLD.updated_at THEN
        RAISE EXCEPTION 'Dance outbox lease cannot be reclaimed or renewed';
      END IF;
    ELSIF OLD.state = 'running' AND NEW.state IN ('delivered', 'failed', 'exhausted') THEN
      IF OLD.lease_expires_at <= clock_timestamp()
         OR NEW.delivery_attempts <> OLD.delivery_attempts
         OR NEW.claim_fence <> OLD.claim_fence OR NEW.updated_at <= OLD.updated_at THEN
        RAISE EXCEPTION 'Dance outbox terminal fence is invalid';
      END IF;
    ELSE
      RAISE EXCEPTION 'Invalid Dance reference outbox transition';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_dance_reference_processing_request() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target dance_choreography_revisions%ROWTYPE;
  outbox dance_reference_outbox%ROWTYPE;
  publication media_publication_projections%ROWTYPE;
  request_keys TEXT[];
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Dance reference processing requests are immutable';
  END IF;
  SELECT * INTO target FROM dance_choreography_revisions
   WHERE choreography_id = NEW.choreography_id AND revision = NEW.revision FOR SHARE;
  SELECT * INTO outbox FROM dance_reference_outbox
   WHERE effect_identity = NEW.effect_identity FOR SHARE;
  SELECT * INTO publication FROM media_publication_projections
   WHERE community_id = target.community_id AND post_id = target.song_post_id
     AND audio_revision = target.audio_revision FOR SHARE;
  SELECT array_agg(key ORDER BY key) INTO request_keys
    FROM jsonb_object_keys(NEW.request_material) AS key;
  IF target.choreography_id IS NULL OR target.status <> 'processing'
     OR outbox.choreography_id <> NEW.choreography_id OR outbox.revision <> NEW.revision
     OR request_keys IS DISTINCT FROM ARRAY[
       'alignment', 'canonicalAudio', 'choreographyId', 'choreographyRevision',
       'effectIdentity', 'extraction', 'mirrorPolicy', 'outputs', 'ownerPolicy', 'pose',
       'qualityLimits', 'referenceVideo', 'requestedEndMs', 'requestedStartMs', 'revisionTermsHash',
       'segmentTermsHash', 'version'
     ]::TEXT[]
     OR NEW.request_material->>'version' <> 'frozen-dance-reference-input-v1'
     OR NEW.request_material->>'effectIdentity' <> NEW.effect_identity
     OR NEW.request_material->>'choreographyId' <> NEW.choreography_id
     OR NEW.request_material->>'choreographyRevision' <> NEW.revision::TEXT
     OR NEW.request_material->>'revisionTermsHash' <> target.revision_terms_hash
     OR NEW.request_material->'canonicalAudio'->>'audioRevision' <> target.audio_revision::TEXT
     OR NEW.request_material->'canonicalAudio'->>'objectKey' <> publication.audio_asset_ref
     OR NEW.request_material->'canonicalAudio'->>'sha256' <> publication.canonical_audio_sha256
     OR NEW.request_material->'referenceVideo'->>'postId' <> target.reference_video_post_id
     OR NEW.request_material->'referenceVideo'->>'objectKey' <> target.reference_video_object_ref
     OR NEW.request_material->'referenceVideo'->>'sha256' <> target.reference_video_sha256
     OR NEW.request_material->>'requestedStartMs' <> target.requested_start_ms::TEXT
     OR NEW.request_material->>'requestedEndMs' <> target.requested_end_ms::TEXT
     OR NEW.request_material->>'mirrorPolicy' <> target.mirror_policy
     OR NEW.request_material->'alignment'->>'policyVersion' <> target.alignment_policy_version
     OR NEW.request_material->'alignment'->>'adapterId' <> target.alignment_adapter
     OR NEW.request_material->'alignment'->>'adapterRevision' <> target.alignment_revision
     OR NEW.request_material->'pose'->>'modelVersion' <> target.pose_model_version
     OR NEW.request_material->'pose'->>'runtimeVersion' <> target.pose_runtime_version
     OR NEW.request_material->'pose'->>'featureSchemaVersion' <> target.feature_schema_version
     OR NEW.request_material->'pose'->>'scorerContractVersion' <> target.scorer_contract_version
     OR NEW.request_material->'pose'->>'fingerprintPolicyVersion' <>
        target.fingerprint_policy_version
     OR NEW.request_material->'pose'->>'integrityPolicyVersion' <> target.integrity_policy_version
     OR NEW.request_material->'ownerPolicy'->>'revision' <> target.owner_policy_revision::TEXT
     OR NEW.request_material->'ownerPolicy'->>'hash' <> target.owner_policy_hash THEN
    RAISE EXCEPTION 'Dance reference processing request is not exact revision authority';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_dance_replay_fingerprint_claim() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN RAISE EXCEPTION 'Dance fingerprint claims are immutable'; END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_dance_session() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Dance sessions cannot be deleted'; END IF;
  IF TG_OP = 'INSERT' THEN RETURN NEW; END IF;
  IF ROW(NEW.session_id, NEW.account_id, NEW.persona_id, NEW.community_id,
    NEW.song_post_id, NEW.audio_revision, NEW.segment_id, NEW.choreography_id,
    NEW.choreography_revision, NEW.reward_mode, NEW.objective_snapshot,
    NEW.expected_scored_duration_ms, NEW.cue_kind, NEW.cue_hold_ms,
    NEW.cue_observation_start_ms, NEW.cue_observation_end_ms,
    NEW.qualification_policy_version_id, NEW.calibration_version_id,
    NEW.calibration_checksum, NEW.captured_admission_state, NEW.platform_floor_bps,
    NEW.pose_model_version, NEW.feature_schema_version, NEW.scorer_contract_version,
    NEW.mirror_policy_version, NEW.cue_policy_version, NEW.fingerprint_policy_version,
    NEW.fingerprint_key_version, NEW.integrity_policy_version,
    NEW.grader_adapter_version, NEW.session_terms_hash, NEW.created_at, NEW.expires_at)
    IS DISTINCT FROM ROW(OLD.session_id, OLD.account_id, OLD.persona_id, OLD.community_id,
    OLD.song_post_id, OLD.audio_revision, OLD.segment_id, OLD.choreography_id,
    OLD.choreography_revision, OLD.reward_mode, OLD.objective_snapshot,
    OLD.expected_scored_duration_ms, OLD.cue_kind, OLD.cue_hold_ms,
    OLD.cue_observation_start_ms, OLD.cue_observation_end_ms,
    OLD.qualification_policy_version_id, OLD.calibration_version_id,
    OLD.calibration_checksum, OLD.captured_admission_state, OLD.platform_floor_bps,
    OLD.pose_model_version, OLD.feature_schema_version, OLD.scorer_contract_version,
    OLD.mirror_policy_version, OLD.cue_policy_version, OLD.fingerprint_policy_version,
    OLD.fingerprint_key_version, OLD.integrity_policy_version,
    OLD.grader_adapter_version, OLD.session_terms_hash, OLD.created_at, OLD.expires_at) THEN
    RAISE EXCEPTION 'Dance session terms are immutable';
  END IF;
  IF NEW.version <> OLD.version + 1 OR NOT (
    (OLD.state = 'created' AND NEW.state IN ('consented', 'expired', 'abandoned'))
    OR (OLD.state = 'consented' AND NEW.state IN ('awaiting_upload', 'expired', 'abandoned'))
    OR (OLD.state = 'awaiting_upload' AND NEW.state IN ('uploaded', 'expired', 'abandoned'))
    OR (OLD.state = 'uploaded' AND NEW.state IN ('grading_pending', 'processing_failed'))
    OR (OLD.state = 'grading_pending'
      AND NEW.state IN ('completed', 'rejected', 'processing_failed'))
  ) THEN
    RAISE EXCEPTION 'Invalid Dance session transition';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_dance_session_consent() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target dance_sessions%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Dance consent receipts are immutable';
  END IF;
  SELECT * INTO target FROM dance_sessions WHERE session_id = NEW.session_id FOR UPDATE;
  IF target.session_id IS NULL OR target.state <> 'created'
     OR target.account_id <> NEW.account_id OR target.persona_id <> NEW.persona_id
     OR target.session_terms_hash <> NEW.session_terms_hash
     OR NEW.consented_at < target.created_at OR NEW.consented_at >= target.expires_at THEN
    RAISE EXCEPTION 'Dance consent does not bind the created session';
  END IF;
  UPDATE dance_sessions SET state = 'consented', version = version + 1
   WHERE session_id = NEW.session_id AND state = 'created';
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_dance_song_segment() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  publication media_publication_projections%ROWTYPE;
  song posts%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Dance song segments are immutable';
  END IF;
  SELECT * INTO publication FROM media_publication_projections
   WHERE submission_id = NEW.song_submission_id FOR SHARE;
  SELECT * INTO song FROM posts
   WHERE community_id = NEW.community_id AND post_id = NEW.song_post_id FOR SHARE;
  IF publication.submission_id IS NULL OR song.post_id IS NULL
     OR publication.community_id <> NEW.community_id
     OR publication.post_id <> NEW.song_post_id
     OR publication.audio_revision <> NEW.audio_revision
     OR publication.canonical_audio_sha256 <> NEW.source_media_sha256
     OR song.post_type <> 'song' OR song.status <> 'published' THEN
    RAISE EXCEPTION 'Dance segment requires exact published canonical song audio';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_dance_upload_reservation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target dance_sessions%ROWTYPE;
BEGIN
  SELECT * INTO target FROM dance_sessions WHERE session_id = NEW.session_id FOR UPDATE;
  IF TG_OP = 'INSERT' THEN
    IF target.session_id IS NULL OR target.state <> 'consented'
       OR NOT EXISTS (SELECT 1 FROM dance_session_consents WHERE session_id = NEW.session_id)
       OR NEW.expires_at > target.expires_at THEN
      RAISE EXCEPTION 'Dance upload reservation requires committed consent';
    END IF;
    UPDATE dance_sessions SET state = 'awaiting_upload', version = version + 1
     WHERE session_id = NEW.session_id AND state = 'consented';
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Dance upload reservations cannot be deleted'; END IF;
  IF OLD.state <> 'reserved' OR NEW.state NOT IN ('sealed', 'expired')
     OR ROW(NEW.reservation_id, NEW.session_id, NEW.private_object_key,
       NEW.expected_content_type, NEW.expected_size_bytes, NEW.expected_duration_ms,
       NEW.expected_sha256, NEW.created_at, NEW.expires_at)
       IS DISTINCT FROM ROW(OLD.reservation_id, OLD.session_id, OLD.private_object_key,
       OLD.expected_content_type, OLD.expected_size_bytes, OLD.expected_duration_ms,
       OLD.expected_sha256, OLD.created_at, OLD.expires_at) THEN
    RAISE EXCEPTION 'Invalid Dance upload reservation transition';
  END IF;
  IF NEW.state = 'sealed' THEN
    IF target.state <> 'awaiting_upload'
       OR NEW.sealed_duration_ms < target.cue_observation_end_ms
          + target.expected_scored_duration_ms THEN
      RAISE EXCEPTION 'Sealed Dance upload cannot contain the cue and scored interval';
    END IF;
    UPDATE dance_sessions SET state = 'uploaded', version = version + 1
     WHERE session_id = NEW.session_id AND state = 'awaiting_upload';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_data_registration_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION '% is append-only', TG_TABLE_NAME;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_data_registration_attempt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE prior data_registration_signing_attempts%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'DATA registration attempt cannot be deleted';
  END IF;
  IF TG_OP = 'INSERT' THEN
    IF NEW.state <> 'signing_intent'
       OR NOT data_registration_pins_are_ready(NEW.registration_operation_id) THEN
      RAISE EXCEPTION 'DATA registration attempt requires a verified Filebase pin and independent retrieval';
    END IF;
    IF NEW.supersedes_submission_attempt_id IS NOT NULL THEN
      SELECT * INTO prior FROM data_registration_signing_attempts
        WHERE submission_attempt_id=NEW.supersedes_submission_attempt_id FOR SHARE;
      IF prior.registration_operation_id IS DISTINCT FROM NEW.registration_operation_id
         OR prior.attempt_number >= NEW.attempt_number
         OR prior.state NOT IN ('broadcast', 'mined', 'replaced', 'reconciliation_required') THEN
        RAISE EXCEPTION 'DATA registration replacement lineage is invalid';
      END IF;
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(
    NEW.submission_attempt_id, NEW.registration_operation_id, NEW.chain_id,
    NEW.attempt_number, NEW.signer_namespace, NEW.signer_address,
    NEW.signing_intent_id, NEW.target_address, NEW.method_selector,
    NEW.calldata_hash, NEW.signing_deadline, NEW.value_wei, NEW.gas_limit,
    NEW.max_fee_per_gas, NEW.max_priority_fee_per_gas,
    NEW.supersedes_submission_attempt_id, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.submission_attempt_id, OLD.registration_operation_id, OLD.chain_id,
    OLD.attempt_number, OLD.signer_namespace, OLD.signer_address,
    OLD.signing_intent_id, OLD.target_address, OLD.method_selector,
    OLD.calldata_hash, OLD.signing_deadline, OLD.value_wei, OLD.gas_limit,
    OLD.max_fee_per_gas, OLD.max_priority_fee_per_gas,
    OLD.supersedes_submission_attempt_id, OLD.created_at
  ) THEN
    RAISE EXCEPTION 'DATA registration attempt identity is immutable';
  END IF;
  IF NEW.updated_at <= OLD.updated_at THEN
    RAISE EXCEPTION 'DATA registration attempt timestamp must advance';
  END IF;
  IF NOT (
    (OLD.state = 'signing_intent' AND NEW.state IN ('nonce_reserved', 'failed'))
    OR (OLD.state = 'nonce_reserved' AND NEW.state IN (
      'prepared', 'failed', 'reconciliation_required'
    ))
    OR (OLD.state = 'prepared' AND NEW.state IN ('broadcast', 'reconciliation_required'))
    OR (OLD.state = 'broadcast' AND NEW.state IN (
      'mined', 'replaced', 'reverted', 'reconciliation_required'
    ))
    OR (OLD.state = 'mined' AND NEW.state IN (
      'broadcast', 'confirmed', 'reverted', 'reconciliation_required'
    ))
    OR (OLD.state = 'confirmed' AND NEW.state = 'reconciliation_required')
    OR (OLD.state = 'reconciliation_required' AND NEW.state IN (
      'broadcast', 'mined', 'confirmed', 'replaced', 'reverted', 'failed'
    ))
  ) THEN
    RAISE EXCEPTION 'invalid DATA registration attempt transition';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_data_registration_operation_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'DATA registration operation cannot be deleted';
  END IF;
  IF ROW(
    NEW.registration_operation_id, NEW.community_id, NEW.actor_user_id,
    NEW.submission_id, NEW.media_operation_id, NEW.post_id, NEW.asset_id,
    NEW.chain_id, NEW.registration_revision, NEW.publication_creation_revision,
    NEW.publication_audio_revision, NEW.publication_analysis_revision,
    NEW.publication_decision_revision, NEW.canonical_audio_sha256,
    NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.registration_operation_id, OLD.community_id, OLD.actor_user_id,
    OLD.submission_id, OLD.media_operation_id, OLD.post_id, OLD.asset_id,
    OLD.chain_id, OLD.registration_revision, OLD.publication_creation_revision,
    OLD.publication_audio_revision, OLD.publication_analysis_revision,
    OLD.publication_decision_revision, OLD.canonical_audio_sha256,
    OLD.created_at
  ) THEN
    RAISE EXCEPTION 'DATA registration operation identity is immutable';
  END IF;
  IF NEW.updated_at <= OLD.updated_at THEN
    RAISE EXCEPTION 'DATA registration operation timestamp must advance';
  END IF;
  IF NEW.workflow_revision IS DISTINCT FROM OLD.workflow_revision
     OR NEW.workflow_instance_id IS DISTINCT FROM OLD.workflow_instance_id THEN
    IF OLD.state = 'registered'
       OR NEW.workflow_revision IS DISTINCT FROM OLD.workflow_revision + 1
       OR NEW.workflow_instance_id IS DISTINCT FROM
          'data-registration-workflow:' || NEW.registration_operation_id || ':r' || NEW.workflow_revision::text
       OR ROW(
         NEW.state, NEW.current_attempt_id, NEW.registered_ip_id,
         NEW.confirmed_transaction_hash, NEW.confirmed_block_number,
         NEW.confirmed_block_hash, NEW.confirmed_log_index, NEW.confirmed_at,
         NEW.failure_code, NEW.failure_evidence_ref
       ) IS DISTINCT FROM ROW(
         OLD.state, OLD.current_attempt_id, OLD.registered_ip_id,
         OLD.confirmed_transaction_hash, OLD.confirmed_block_number,
         OLD.confirmed_block_hash, OLD.confirmed_log_index, OLD.confirmed_at,
         OLD.failure_code, OLD.failure_evidence_ref
       ) THEN
      RAISE EXCEPTION 'DATA registration workflow replacement is invalid';
    END IF;
    RETURN NEW;
  END IF;
  IF NOT (
    (OLD.state = 'pending' AND NEW.state IN ('signing', 'failed'))
    OR (OLD.state = 'signing' AND NEW.state IN (
      'broadcast', 'failed', 'reconciliation_required'
    ))
    OR (OLD.state = 'broadcast' AND NEW.state IN (
      'signing', 'confirming', 'failed', 'reconciliation_required'
    ))
    OR (OLD.state = 'confirming' AND NEW.state IN (
      'signing', 'broadcast', 'registered', 'failed', 'reconciliation_required'
    ))
    OR (OLD.state = 'reconciliation_required' AND NEW.state IN (
      'signing', 'broadcast', 'confirming', 'registered', 'failed'
    ))
    OR (OLD.state = 'failed' AND NEW.state = 'registered')
    OR (OLD.state = 'registered' AND NEW.state IN ('failed', 'reconciliation_required'))
  ) THEN
    RAISE EXCEPTION 'invalid DATA registration operation transition';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_data_registration_outbox_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'DATA registration outbox cannot be deleted';
  END IF;
  IF ROW(
    NEW.outbox_id, NEW.registration_operation_id, NEW.workflow_revision,
    NEW.workflow_instance_id, NEW.event_type, NEW.effect_identity,
    NEW.payload, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.outbox_id, OLD.registration_operation_id, OLD.workflow_revision,
    OLD.workflow_instance_id, OLD.event_type, OLD.effect_identity,
    OLD.payload, OLD.created_at
  ) THEN
    RAISE EXCEPTION 'DATA registration outbox identity is immutable';
  END IF;
  IF NEW.updated_at <= OLD.updated_at OR NEW.claim_fence < OLD.claim_fence
     OR NEW.delivery_attempts < OLD.delivery_attempts THEN
    RAISE EXCEPTION 'DATA registration outbox fence must advance';
  END IF;
  IF OLD.state IN ('pending', 'failed') AND (
      NEW.state <> 'running'
      OR NEW.delivery_attempts <> OLD.delivery_attempts + 1
      OR NEW.claim_fence <> OLD.claim_fence + 1
      OR NEW.claim_owner IS NULL OR NEW.lease_expires_at <= clock_timestamp()
      OR (OLD.state = 'failed' AND (
        OLD.next_eligible_at IS NULL OR OLD.next_eligible_at > clock_timestamp()
      ))
    ) THEN
    RAISE EXCEPTION 'DATA registration outbox claim is not allowed';
  END IF;
  IF OLD.state = 'running' AND NEW.state IN ('delivered', 'failed', 'exhausted') AND (
      NEW.delivery_attempts <> OLD.delivery_attempts
      OR NEW.claim_fence <> OLD.claim_fence
      OR NEW.claim_owner IS NOT NULL OR OLD.lease_expires_at <= clock_timestamp()
      OR (NEW.state = 'failed' AND NEW.next_eligible_at IS NULL)
      OR (NEW.state = 'exhausted' AND (
        NEW.delivery_attempts <> 5 OR NEW.next_eligible_at IS NOT NULL
      ))
    ) THEN
    RAISE EXCEPTION 'DATA registration outbox completion is not allowed';
  END IF;
  IF OLD.state = 'running' AND NEW.state = 'running' AND (
      OLD.lease_expires_at > clock_timestamp()
      OR NEW.delivery_attempts <> OLD.delivery_attempts + 1
      OR NEW.claim_fence <> OLD.claim_fence + 1
      OR NEW.claim_owner IS NULL OR NEW.lease_expires_at <= clock_timestamp()
    ) THEN
    RAISE EXCEPTION 'DATA registration outbox reclaim is not allowed';
  END IF;
  IF OLD.state NOT IN ('pending', 'failed', 'running') THEN
    RAISE EXCEPTION 'DATA registration outbox is terminal';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_data_registration_receipt_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE attempt data_registration_signing_attempts%ROWTYPE;
BEGIN
  SELECT * INTO attempt FROM data_registration_signing_attempts
    WHERE registration_operation_id=NEW.registration_operation_id
      AND submission_attempt_id=NEW.submission_attempt_id FOR SHARE;
  IF attempt.submission_attempt_id IS NULL
     OR attempt.transaction_hash IS DISTINCT FROM NEW.transaction_hash
     OR attempt.state NOT IN (
       'broadcast', 'mined', 'confirmed', 'replaced', 'reconciliation_required'
     ) THEN
    RAISE EXCEPTION 'DATA receipt observation is not owned by a broadcast attempt';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_first_persona_handle_reservation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  handle_lock TEXT := 'handle-id:' || NEW.handle_id;
  label_lock TEXT := 'handle-label:' || NEW.label_normalized;
  collision_found BOOLEAN;
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(least(handle_lock, label_lock), 14000060));
  PERFORM pg_advisory_xact_lock(hashtextextended(greatest(handle_lock, label_lock), 14000060));

  IF TG_TABLE_NAME = 'persona_pending_first_handles' THEN
    SELECT EXISTS (
      SELECT 1 FROM public_handle_index AS published
       WHERE published.handle_id=NEW.handle_id
          OR published.label_normalized=NEW.label_normalized
    ) INTO collision_found;
  ELSE
    SELECT EXISTS (
      SELECT 1 FROM persona_pending_first_handles AS pending
       WHERE (pending.handle_id=NEW.handle_id
          OR pending.label_normalized=NEW.label_normalized)
         AND pending.persona_id IS DISTINCT FROM NEW.owner_persona_id
    ) INTO collision_found;
  END IF;

  IF collision_found THEN
    RAISE EXCEPTION 'first persona handle is already reserved'
      USING ERRCODE='23505', CONSTRAINT='first_persona_handle_reservation_unique';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_handle_grant_change_v2() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE'
    OR to_jsonb(NEW) - ARRAY['status','updated_at']
       IS DISTINCT FROM to_jsonb(OLD) - ARRAY['status','updated_at']
    OR OLD.status <> 'active'
    OR NEW.status NOT IN ('revoked','tombstoned')
    OR NEW.updated_at < OLD.updated_at THEN
    RAISE EXCEPTION 'handle grant transition is invalid';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_handle_persona_link_confirmation_change_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE'
    OR to_jsonb(NEW) - ARRAY['status','consumed_at','consumed_by_quote_id']
       IS DISTINCT FROM to_jsonb(OLD) - ARRAY['status','consumed_at','consumed_by_quote_id']
    OR OLD.status <> 'available'
    OR NEW.status NOT IN ('consumed','expired') THEN
    RAISE EXCEPTION 'handle persona-link confirmation transition is invalid';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_handle_quote_change_v2() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE'
    OR to_jsonb(NEW) - ARRAY['status','consumed_at']
       IS DISTINCT FROM to_jsonb(OLD) - ARRAY['status','consumed_at']
    OR OLD.status <> 'quoted'
    OR NEW.status NOT IN ('consumed','expired') THEN
    RAISE EXCEPTION 'handle quote transition is invalid';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_handle_recipient_token_action_change_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE'
    AND pg_trigger_depth() > 1
    AND NOT EXISTS (
      SELECT 1
        FROM handle_direct_grant_recipient_tokens AS token
       WHERE token.token_id = OLD.token_id
    ) THEN
    RETURN OLD;
  END IF;
  RAISE EXCEPTION 'handle recipient-token action is append-only';
END;
$$;

CREATE FUNCTION guard_handle_recipient_token_update_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF to_jsonb(NEW) - ARRAY[
       'token_ciphertext','token_envelope_key_version','status','superseded_at','consumed_at',
       'consumed_by_seller_account_id','consuming_idempotency_key','qualification_policy_id',
       'policy_request_hash'
     ] IS DISTINCT FROM to_jsonb(OLD) - ARRAY[
       'token_ciphertext','token_envelope_key_version','status','superseded_at','consumed_at',
       'consumed_by_seller_account_id','consuming_idempotency_key','qualification_policy_id',
       'policy_request_hash'
     ]
    OR OLD.status <> 'current'
    OR NEW.status NOT IN ('superseded','consumed') THEN
    RAISE EXCEPTION 'handle recipient-token transition is invalid';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_handle_reservation_change_v2() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE'
    OR to_jsonb(NEW) - ARRAY['status','transitioned_at']
       IS DISTINCT FROM to_jsonb(OLD) - ARRAY['status','transitioned_at']
    OR OLD.status <> 'reserved'
    OR NEW.status NOT IN ('consumed','expired','cancelled','blocked') THEN
    RAISE EXCEPTION 'handle reservation transition is invalid';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_hns_community_app_host_current_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'HNS app-host current authority cannot be deleted';
  END IF;
  IF NEW.app_host_activation_id <> OLD.app_host_activation_id
    OR NEW.normalized_host <> OLD.normalized_host
    OR NEW.community_id <> OLD.community_id
    OR NEW.current_generation <> OLD.current_generation + 1
    OR NEW.updated_at <= OLD.updated_at THEN
    RAISE EXCEPTION 'HNS app-host generation change is invalid';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_hns_control_observer_reservation_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  snapshot_record hns_control_observer_snapshots%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'HNS observer reservations cannot be deleted';
  END IF;

  IF NEW.observation_id <> OLD.observation_id
    OR NEW.reservation_lease_seconds <> OLD.reservation_lease_seconds
    OR NEW.created_at <> OLD.created_at THEN
    RAISE EXCEPTION 'HNS observer reservation identity is immutable';
  END IF;

  IF OLD.state = 'reserved' AND NEW.state = 'reserved' THEN
    IF OLD.lease_expires_at > NEW.reservation_database_time
      OR NEW.observer_fence <> OLD.observer_fence + 1
      OR NEW.reservation_database_time <= OLD.reservation_database_time
      OR NEW.lease_expires_at <> NEW.reservation_database_time
        + NEW.reservation_lease_seconds * INTERVAL '1 second'
      OR NEW.updated_at <> NEW.reservation_database_time THEN
      RAISE EXCEPTION 'HNS observer reservation reacquisition is not fenced';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.state = 'reserved' AND NEW.state = 'terminal' THEN
    IF NEW.observer_fence <> OLD.observer_fence
      OR NEW.reservation_database_time <> OLD.reservation_database_time
      OR NEW.lease_expires_at <> OLD.lease_expires_at
      OR OLD.lease_expires_at <= clock_timestamp()
      OR NEW.terminal_at IS NULL
      OR NEW.terminal_at > clock_timestamp()
      OR NEW.terminal_at >= OLD.lease_expires_at THEN
      RAISE EXCEPTION 'HNS observer terminal transition lost its lease or fence';
    END IF;
    SELECT * INTO snapshot_record
      FROM hns_control_observer_snapshots
     WHERE observation_id = NEW.observation_id
       AND snapshot_reference = NEW.terminal_snapshot_reference
       AND observer_fence = NEW.observer_fence;
    IF NOT FOUND OR snapshot_record.result_status <> NEW.terminal_status THEN
      RAISE EXCEPTION 'HNS observer terminal transition lacks its snapshot';
    END IF;
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'HNS observer reservation transition is not allowed';
END;
$$;

CREATE FUNCTION guard_hns_dns_zone_activation_current_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'HNS DNS activation current authority cannot be deleted';
  END IF;
  IF NEW.dns_zone_activation_id <> OLD.dns_zone_activation_id
    OR NEW.canonical_root <> OLD.canonical_root
    OR NEW.current_generation <> OLD.current_generation + 1
    OR NEW.updated_at <= OLD.updated_at THEN
    RAISE EXCEPTION 'HNS DNS activation generation change is invalid';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_hns_dns_zone_activation_operation_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'HNS DNS activation operations are retained';
  END IF;
  IF ROW(NEW.operation_id, NEW.idempotency_key, NEW.activation_document_digest,
         NEW.dns_zone_activation_id, NEW.expected_activation_generation,
         NEW.lease_seconds, NEW.created_at)
    IS DISTINCT FROM
     ROW(OLD.operation_id, OLD.idempotency_key, OLD.activation_document_digest,
         OLD.dns_zone_activation_id, OLD.expected_activation_generation,
         OLD.lease_seconds, OLD.created_at) THEN
    RAISE EXCEPTION 'HNS DNS activation operation identity is immutable';
  END IF;
  IF OLD.state = 'reserved' AND NEW.state = 'reserved' THEN
    IF OLD.lease_expires_at > clock_timestamp()
      OR NEW.fence_token <> OLD.fence_token + 1
      OR NEW.lease_expires_at <= OLD.lease_expires_at
      OR NEW.updated_at <= OLD.updated_at THEN
      RAISE EXCEPTION 'HNS DNS activation reacquisition is not fenced';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.state = 'reserved' AND NEW.state = 'finalized' THEN
    IF NEW.fence_token <> OLD.fence_token
      OR OLD.lease_expires_at <= clock_timestamp()
      OR NEW.updated_at > clock_timestamp()
      OR NEW.finalized_at <> NEW.updated_at THEN
      RAISE EXCEPTION 'HNS DNS activation finalizer lost its lease or fence';
    END IF;
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'HNS DNS activation operation transition is not allowed';
END;
$$;

CREATE FUNCTION guard_hns_owner_recovery_attempt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  db_now TIMESTAMPTZ := date_trunc('milliseconds', clock_timestamp());
  session_record community_route_revalidation_sessions%ROWTYPE;
  consumed_count INTEGER;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'owner recovery attempts cannot be deleted';
  END IF;
  SELECT * INTO session_record FROM community_route_revalidation_sessions
   WHERE route_revalidation_id = COALESCE(NEW.route_revalidation_id, OLD.route_revalidation_id)
     AND revalidation_session_id = COALESCE(
       NEW.revalidation_session_id, OLD.revalidation_session_id
     ) FOR UPDATE;
  IF session_record.revalidation_session_id IS NULL
    OR session_record.operation_mode <> 'same_root_recovery'
  THEN RAISE EXCEPTION 'owner recovery attempt lacks its session'; END IF;
  IF TG_OP = 'INSERT' THEN
    NEW.created_at := db_now;
    NEW.updated_at := db_now;
    SELECT count(*)::integer INTO consumed_count
      FROM community_route_revalidation_completion_attempts
     WHERE route_revalidation_id = NEW.route_revalidation_id
       AND operation_mode = 'same_root_recovery' AND state = 'consumed';
    IF session_record.status <> 'pending'
      OR NEW.route_binding_id IS DISTINCT FROM session_record.route_binding_id
      OR NEW.expected_binding_generation
           IS DISTINCT FROM session_record.expected_binding_generation
      OR NEW.expected_verified_evidence_ref IS NOT NULL
      OR NEW.attempt_number IS DISTINCT FROM consumed_count + 1
      OR consumed_count >= 3
      OR NEW.state <> 'leased' OR NEW.fence_token <> 1
      OR NEW.lease_expires_at <= db_now
      OR (
        session_record.expires_at > db_now
        AND db_now + INTERVAL '16 seconds' > session_record.expires_at
      )
    THEN RAISE EXCEPTION 'owner recovery attempt is not admissible'; END IF;
    NEW.lease_expires_at := db_now + INTERVAL '16 seconds';
    RETURN NEW;
  END IF;
  IF (to_jsonb(NEW)
        - 'state' - 'fence_token' - 'lease_expires_at' - 'consumption_kind'
        - 'result_hash' - 'terminal_result_document' - 'terminal_result_version'
        - 'target_observation_contract_version' - 'target_response_status'
        - 'provider_response_sha256' - 'raw_provider_response_bytes'
        - 'terminal_observed_expires_at' - 'terminal_at' - 'updated_at')
       IS DISTINCT FROM
     (to_jsonb(OLD)
        - 'state' - 'fence_token' - 'lease_expires_at' - 'consumption_kind'
        - 'result_hash' - 'terminal_result_document' - 'terminal_result_version'
        - 'target_observation_contract_version' - 'target_response_status'
        - 'provider_response_sha256' - 'raw_provider_response_bytes'
        - 'terminal_observed_expires_at' - 'terminal_at' - 'updated_at')
  THEN RAISE EXCEPTION 'owner recovery attempt authority is immutable'; END IF;
  IF OLD.state = 'leased' AND NEW.state = 'released'
    AND NEW.fence_token = OLD.fence_token
    AND NEW.lease_expires_at = OLD.lease_expires_at
  THEN NEW.updated_at := db_now; RETURN NEW; END IF;
  IF OLD.state IN ('released', 'leased') AND NEW.state = 'leased'
    AND NEW.fence_token = OLD.fence_token + 1
    AND (OLD.state = 'released' OR OLD.lease_expires_at <= db_now)
    AND NEW.lease_expires_at > db_now
    AND (
      session_record.expires_at <= db_now
      OR db_now + INTERVAL '16 seconds' <= session_record.expires_at
    )
  THEN
    NEW.lease_expires_at := db_now + INTERVAL '16 seconds';
    NEW.updated_at := db_now;
    RETURN NEW;
  END IF;
  IF OLD.state = 'leased' AND NEW.state = 'consumed'
    AND NEW.fence_token = OLD.fence_token
    AND NEW.lease_expires_at = OLD.lease_expires_at
    AND NEW.terminal_at IS NOT NULL AND NEW.terminal_at <= db_now
    AND (
      (NEW.consumption_kind = 'session_expired' AND session_record.expires_at <= db_now)
      OR (NEW.consumption_kind <> 'session_expired'
          AND OLD.lease_expires_at > db_now AND session_record.expires_at > db_now)
    )
    AND validate_hns_owner_recovery_terminal_document(
      NEW.terminal_result_document, NEW.result_hash, NEW.terminal_result_version,
      NEW.route_revalidation_id, NEW.revalidation_session_id,
      NEW.route_revalidation_attempt_id, NEW.route_binding_id,
      NEW.expected_binding_generation, NEW.idempotency_key,
      NEW.completion_request_hash, NEW.consumption_kind
    )
  THEN NEW.updated_at := db_now; RETURN NEW; END IF;
  RAISE EXCEPTION 'owner recovery attempt transition is not allowed';
END;
$$;

CREATE FUNCTION guard_hns_owner_recovery_session_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'owner recovery sessions cannot be deleted';
  END IF;
  IF (to_jsonb(NEW) - 'status' - 'terminal_at' - 'updated_at')
       IS DISTINCT FROM
     (to_jsonb(OLD) - 'status' - 'terminal_at' - 'updated_at')
  THEN RAISE EXCEPTION 'owner recovery session authority is immutable'; END IF;
  IF OLD.status = 'pending'
    AND NEW.status IN ('completed', 'failed', 'expired')
    AND NEW.terminal_at IS NOT NULL
    AND NEW.terminal_at <= clock_timestamp()
    AND (NEW.status <> 'expired' OR NEW.terminal_at >= NEW.expires_at)
  THEN
    NEW.updated_at := clock_timestamp();
    RETURN NEW;
  END IF;
  RAISE EXCEPTION 'owner recovery session transition is not allowed';
END;
$$;

CREATE FUNCTION guard_hns_owner_recovery_start() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
DECLARE
  db_now TIMESTAMPTZ := date_trunc('milliseconds', clock_timestamp());
  community_record communities%ROWTYPE;
  binding_record community_canonical_route_bindings%ROWTYPE;
  transition_record community_route_lifecycle_transitions%ROWTYPE;
  prior_attempt community_route_revalidation_completion_attempts%ROWTYPE;
  prior_session community_route_revalidation_sessions%ROWTYPE;
  renewal_attempt community_route_active_lease_renewal_attempts%ROWTYPE;
  renewal_record community_route_active_lease_renewals%ROWTYPE;
  provider_authority_exists BOOLEAN;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'owner recovery start reservations cannot be deleted';
  END IF;
  IF TG_OP = 'INSERT' THEN
    NEW.created_at := db_now;
    NEW.updated_at := db_now;
    NEW.challenge_expires_at := db_now + INTERVAL '1 hour';
    SELECT * INTO community_record FROM communities
     WHERE community_id = NEW.community_id FOR UPDATE;
    SELECT * INTO binding_record FROM community_canonical_route_bindings
     WHERE route_binding_id = NEW.route_binding_id
       AND community_id = NEW.community_id FOR UPDATE;
    SELECT (
      EXISTS (
        SELECT 1 FROM hns_control_observer_configurations
         WHERE provider_configuration_reference = NEW.provider_configuration_reference
           AND provider_configuration_version = NEW.provider_configuration_version
           AND provider_configuration_digest = NEW.provider_configuration_digest
      )
      OR EXISTS (
        SELECT 1
          FROM community_route_lifecycle_transitions AS transition
          JOIN community_route_ownership_evidence AS evidence
            ON evidence.evidence_ref = transition.expected_verified_evidence_ref
          JOIN hns_operator_control_promotion_receipts AS receipt
            ON receipt.receipt_id = evidence.operator_control_promotion_receipt_id
           AND receipt.evidence_ref = evidence.evidence_ref
          JOIN LATERAL (
            SELECT artifact,
                   convert_from(
                     decode(artifact ->> 'bytes_hex', 'hex'),
                     'UTF8'
                   )::jsonb AS value
              FROM jsonb_array_elements(
                     convert_from(receipt.candidate_bytes, 'UTF8')::jsonb -> 'artifacts'
                   ) AS artifact
             WHERE artifact ->> 'name' = 'observer_evidence'
          ) AS observer ON TRUE
         WHERE NEW.recovery_authority_kind = 'database_time_expiry_transition'
           AND transition.route_lifecycle_transition_id = NEW.recovery_authority_reference
           AND transition.community_id = NEW.community_id
           AND transition.route_binding_id = NEW.route_binding_id
           AND transition.resulting_binding_generation = NEW.expected_binding_generation
           AND evidence.origin = 'operator_control_observation'
           AND evidence.family = NEW.family
           AND evidence.root_label = NEW.root_label
           AND evidence.provider_id = NEW.provider_id
           AND evidence.provider_binding_hash = NEW.provider_binding_hash
           AND receipt.observer_evidence_sha256 = observer.artifact ->> 'sha256'
           AND receipt.observer_evidence_reference = observer.value ->> 'evidence_reference'
           AND observer.value ->> 'status' = 'verified'
           AND NEW.provider_configuration_kind = 'managed'
           AND observer.value ->> 'provider_configuration_reference'
                 = NEW.provider_configuration_reference
           AND observer.value ->> 'provider_configuration_version'
                 = NEW.provider_configuration_version
           AND observer.value ->> 'provider_configuration_digest'
                 = NEW.provider_configuration_digest
           AND observer.value ->> 'environment' = NEW.environment
      )
    ) INTO provider_authority_exists;
    IF community_record.community_id IS NULL
      OR community_record.status <> 'active'
      OR community_record.created_by_user_id IS DISTINCT FROM NEW.principal_id
      OR community_record.canonical_route_binding_id IS DISTINCT FROM NEW.route_binding_id
      OR binding_record.route_binding_id IS NULL
      OR binding_record.binding_generation IS DISTINCT FROM NEW.expected_binding_generation
      OR binding_record.verified_evidence_ref IS NOT NULL
      OR binding_record.route_lifecycle_status <> 'suspended'
      OR binding_record.family IS DISTINCT FROM NEW.family
      OR binding_record.root_label IS DISTINCT FROM NEW.root_label
      OR binding_record.root_label_display IS DISTINCT FROM NEW.root_label_display
      OR binding_record.path_segment IS DISTINCT FROM NEW.path_segment
      OR NEW.provider_id <> 'hns.owner.v1'
      OR NOT provider_authority_exists
      OR NEW.state <> 'acquired'
      OR NEW.fence_token <> 1
      OR NEW.lease_expires_at <= db_now
    THEN
      RAISE EXCEPTION 'owner recovery reservation does not match creator and route authority';
    END IF;
    NEW.lease_expires_at := db_now + INTERVAL '8 seconds';

    IF NEW.recovery_authority_kind = 'database_time_expiry_transition' THEN
      SELECT * INTO transition_record FROM community_route_lifecycle_transitions
       WHERE route_lifecycle_transition_id = NEW.recovery_authority_reference
       FOR SHARE;
      IF transition_record.route_lifecycle_transition_id IS NULL
        OR transition_record.transition_kind <> 'database_time_expired'
        OR transition_record.community_id IS DISTINCT FROM NEW.community_id
        OR transition_record.route_binding_id IS DISTINCT FROM NEW.route_binding_id
        OR transition_record.resulting_binding_generation
             IS DISTINCT FROM NEW.expected_binding_generation
      THEN RAISE EXCEPTION 'owner recovery lacks its database-expiry authority'; END IF;
    ELSIF NEW.recovery_authority_kind IN (
      'route_revalidation_terminal', 'owner_recovery_terminal'
    ) THEN
      SELECT * INTO prior_attempt FROM community_route_revalidation_completion_attempts
       WHERE route_revalidation_attempt_id = NEW.recovery_authority_reference
       FOR SHARE;
      SELECT * INTO prior_session FROM community_route_revalidation_sessions
       WHERE route_revalidation_id = prior_attempt.route_revalidation_id
         AND revalidation_session_id = prior_attempt.revalidation_session_id
       FOR SHARE;
      IF prior_attempt.route_revalidation_attempt_id IS NULL
        OR prior_attempt.state <> 'consumed'
        OR prior_attempt.route_binding_id IS DISTINCT FROM NEW.route_binding_id
        OR prior_attempt.expected_binding_generation + 1
             IS DISTINCT FROM NEW.expected_binding_generation
        OR prior_session.community_id IS DISTINCT FROM NEW.community_id
        OR prior_session.provider_id IS DISTINCT FROM NEW.provider_id
        OR prior_session.provider_binding_hash IS DISTINCT FROM NEW.provider_binding_hash
        OR prior_session.provider_configuration_kind
             IS DISTINCT FROM NEW.provider_configuration_kind
        OR prior_session.provider_configuration_reference
             IS DISTINCT FROM NEW.provider_configuration_reference
        OR prior_session.provider_configuration_version
             IS DISTINCT FROM NEW.provider_configuration_version
        OR prior_session.environment IS DISTINCT FROM NEW.environment
        OR (
          NEW.recovery_authority_kind = 'owner_recovery_terminal'
          AND prior_session.operation_mode <> 'same_root_recovery'
        )
        OR (
          NEW.recovery_authority_kind = 'route_revalidation_terminal'
          AND prior_session.operation_mode <> 'system_revalidation'
        )
      THEN RAISE EXCEPTION 'owner recovery lacks its revalidation authority'; END IF;
    ELSE
      SELECT * INTO renewal_attempt FROM community_route_active_lease_renewal_attempts
       WHERE active_lease_renewal_attempt_id = NEW.recovery_authority_reference
       FOR SHARE;
      SELECT * INTO renewal_record FROM community_route_active_lease_renewals
       WHERE active_lease_renewal_id = renewal_attempt.active_lease_renewal_id
       FOR SHARE;
      IF renewal_attempt.active_lease_renewal_attempt_id IS NULL
        OR renewal_attempt.state <> 'consumed'
        OR renewal_attempt.route_binding_id IS DISTINCT FROM NEW.route_binding_id
        OR renewal_attempt.expected_binding_generation + 1
             IS DISTINCT FROM NEW.expected_binding_generation
        OR renewal_record.community_id IS DISTINCT FROM NEW.community_id
        OR renewal_record.provider_id IS DISTINCT FROM NEW.provider_id
        OR renewal_record.provider_binding_hash IS DISTINCT FROM NEW.provider_binding_hash
        OR renewal_record.provider_configuration_kind
             IS DISTINCT FROM NEW.provider_configuration_kind
        OR renewal_record.provider_configuration_reference
             IS DISTINCT FROM NEW.provider_configuration_reference
        OR renewal_record.provider_configuration_version
             IS DISTINCT FROM NEW.provider_configuration_version
        OR renewal_record.provider_configuration_digest
             IS DISTINCT FROM NEW.provider_configuration_digest
        OR renewal_record.environment IS DISTINCT FROM NEW.environment
      THEN RAISE EXCEPTION 'owner recovery lacks its active-renewal authority'; END IF;
    END IF;
    RETURN NEW;
  END IF;

  IF ROW(
    NEW.route_revalidation_id, NEW.revalidation_session_id, NEW.community_id,
    NEW.route_binding_id, NEW.principal_kind, NEW.principal_id,
    NEW.expected_binding_generation, NEW.expected_verified_evidence_ref,
    NEW.requirement_hash, NEW.provider_id, NEW.provider_binding_hash,
    NEW.provider_configuration_kind, NEW.provider_configuration_reference,
    NEW.provider_configuration_version, NEW.protocol_version, NEW.environment,
    NEW.family, NEW.root_label, NEW.root_label_display, NEW.path_segment,
    NEW.start_request_hash, NEW.operation_mode, NEW.start_reservation_id,
    NEW.start_idempotency_key, NEW.recovery_authority_kind,
    NEW.recovery_authority_reference, NEW.public_start_hash,
    NEW.provider_configuration_digest, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.route_revalidation_id, OLD.revalidation_session_id, OLD.community_id,
    OLD.route_binding_id, OLD.principal_kind, OLD.principal_id,
    OLD.expected_binding_generation, OLD.expected_verified_evidence_ref,
    OLD.requirement_hash, OLD.provider_id, OLD.provider_binding_hash,
    OLD.provider_configuration_kind, OLD.provider_configuration_reference,
    OLD.provider_configuration_version, OLD.protocol_version, OLD.environment,
    OLD.family, OLD.root_label, OLD.root_label_display, OLD.path_segment,
    OLD.start_request_hash, OLD.operation_mode, OLD.start_reservation_id,
    OLD.start_idempotency_key, OLD.recovery_authority_kind,
    OLD.recovery_authority_reference, OLD.public_start_hash,
    OLD.provider_configuration_digest, OLD.created_at
  ) THEN RAISE EXCEPTION 'owner recovery start authority is immutable'; END IF;

  IF OLD.state = 'acquired' AND NEW.state = 'released'
    AND NEW.fence_token = OLD.fence_token
    AND NEW.lease_expires_at = OLD.lease_expires_at
    AND NEW.challenge_expires_at = OLD.challenge_expires_at
    AND NEW.provider_start_hash IS NULL
  THEN NEW.updated_at := db_now; RETURN NEW; END IF;
  IF OLD.state IN ('released', 'acquired') AND NEW.state = 'acquired'
    AND NEW.fence_token = OLD.fence_token + 1
    AND (OLD.state = 'released' OR OLD.lease_expires_at <= db_now)
    AND NEW.lease_expires_at > db_now
    AND NEW.provider_start_hash IS NULL
  THEN
    NEW.challenge_expires_at := db_now + INTERVAL '1 hour';
    NEW.lease_expires_at := db_now + INTERVAL '8 seconds';
    NEW.updated_at := db_now;
    RETURN NEW;
  END IF;
  IF OLD.state = 'acquired' AND NEW.state = 'finalized'
    AND OLD.lease_expires_at > db_now
    AND NEW.fence_token = OLD.fence_token
    AND NEW.lease_expires_at = OLD.lease_expires_at
    AND NEW.challenge_expires_at = OLD.challenge_expires_at
    AND NEW.provider_start_hash ~ '^[0-9a-f]{64}$'
  THEN NEW.updated_at := db_now; RETURN NEW; END IF;
  RAISE EXCEPTION 'owner recovery start transition is not allowed';
END;
$_$;

CREATE FUNCTION guard_hns_root_import_provision_authorization_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
BEGIN
  IF OLD.provision_authorization_kind IS NOT NULL
    AND (
      NEW.provision_authorization_kind IS DISTINCT FROM OLD.provision_authorization_kind
      OR NEW.provision_authorization_sha256
           IS DISTINCT FROM OLD.provision_authorization_sha256
    )
  THEN
    RAISE EXCEPTION 'HNS root-import provisioning authority changed';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_hns_root_import_session_change() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'HNS root-import sessions are retained';
  END IF;
  IF NEW.root_import_session_id <> OLD.root_import_session_id
    OR NEW.actor_id <> OLD.actor_id
    OR NEW.creation_intent_id <> OLD.creation_intent_id
    OR NEW.ceremony_intent_id <> OLD.ceremony_intent_id
    OR NEW.namespace_session_id <> OLD.namespace_session_id
    OR NEW.ownership_generation <> OLD.ownership_generation
    OR NEW.ownership_expected_revision <> OLD.ownership_expected_revision
    OR NEW.root_label <> OLD.root_label
    OR NEW.challenge_txt_value <> OLD.challenge_txt_value
    OR NEW.start_idempotency_key <> OLD.start_idempotency_key
    OR NEW.start_request_sha256 <> OLD.start_request_sha256
    OR NEW.provision_job_id <> OLD.provision_job_id
    OR NEW.expires_at <> OLD.expires_at
    OR NEW.created_at <> OLD.created_at
    OR NEW.revision <> OLD.revision + 1
    OR NEW.updated_at < OLD.updated_at
  THEN
    RAISE EXCEPTION 'HNS root-import session identity or revision changed';
  END IF;
  IF (
      OLD.ownership_result_sha256 IS NOT NULL
      AND NEW.ownership_result_sha256 IS DISTINCT FROM OLD.ownership_result_sha256
    )
    OR (
      OLD.provision_idempotency_key IS NOT NULL
      AND NEW.provision_idempotency_key IS DISTINCT FROM OLD.provision_idempotency_key
    )
    OR (
      OLD.provision_poll_request_sha256 IS NOT NULL
      AND NEW.provision_poll_request_sha256 IS DISTINCT FROM OLD.provision_poll_request_sha256
    )
    OR (
      OLD.observation_job_id IS NOT NULL
      AND NEW.observation_job_id IS DISTINCT FROM OLD.observation_job_id
    )
    OR (
      OLD.observation_idempotency_key IS NOT NULL
      AND NEW.observation_idempotency_key IS DISTINCT FROM OLD.observation_idempotency_key
    )
    OR (
      OLD.observation_request_sha256 IS NOT NULL
      AND NEW.observation_request_sha256 IS DISTINCT FROM OLD.observation_request_sha256
    )
    OR (
      OLD.readiness_result_bytes IS NOT NULL
      AND NEW.readiness_result_bytes IS DISTINCT FROM OLD.readiness_result_bytes
    )
    OR (
      OLD.readiness_result_sha256 IS NOT NULL
      AND NEW.readiness_result_sha256 IS DISTINCT FROM OLD.readiness_result_sha256
    )
  THEN
    RAISE EXCEPTION 'HNS root-import retained evidence changed';
  END IF;
  IF NOT (
    (
      OLD.status = 'awaiting_ownership'
      AND NEW.status IN ('provisioning', 'failed', 'expired')
    )
    OR (OLD.status = 'provisioning' AND NEW.status IN ('awaiting_owner_update', 'failed', 'expired'))
    OR (
      OLD.status IN ('awaiting_owner_update', 'observing')
      AND NEW.status IN ('observing', 'ready', 'failed', 'expired')
    )
    OR (OLD.status = 'ready' AND NEW.status IN ('activated', 'expired'))
  ) THEN
    RAISE EXCEPTION 'HNS root-import session transition is invalid';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_hns_root_import_session_insert() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
DECLARE
  ownership namespace_ownership_sessions%ROWTYPE;
BEGIN
  SELECT * INTO ownership
    FROM namespace_ownership_sessions
   WHERE namespace_session_id = NEW.namespace_session_id
   FOR SHARE;
  IF NOT FOUND
    OR ownership.actor_id <> NEW.actor_id
    OR ownership.creation_intent_id <> NEW.creation_intent_id
    OR ownership.ceremony_intent_id <> NEW.ceremony_intent_id
    OR ownership.requirement_kind <> 'namespace_ownership'
    OR ownership.generation <> NEW.ownership_generation
    OR ownership.expected_revision <> NEW.ownership_expected_revision
    OR ownership.route_family <> 'hns'
    OR ownership.route_root_label <> NEW.root_label
    OR ownership.status <> 'pending'
    OR ownership.expires_at <> NEW.expires_at
    OR NEW.status <> 'awaiting_ownership'
    OR NEW.revision <> 1
  THEN
    RAISE EXCEPTION 'HNS root-import session does not match ownership authority';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_karaoke_attempt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  session_record karaoke_sessions%ROWTYPE;
  policy_kind_record TEXT;
  expected_evidence JSONB;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Karaoke attempts are append-only';
  END IF;
  SELECT * INTO session_record FROM karaoke_sessions
   WHERE session_id = NEW.session_id AND attempt_id = NEW.attempt_id FOR SHARE;
  SELECT policy_kind INTO policy_kind_record FROM qualification_policy_versions
   WHERE qualification_policy_version_id = session_record.qualification_policy_version_id;
  IF session_record.session_id IS NULL OR session_record.status <> 'active'
     OR NEW.created_at IS DISTINCT FROM session_record.created_at
     OR NEW.completed_at < session_record.created_at THEN
    RAISE EXCEPTION 'Karaoke attempt is not bound to its active session';
  END IF;
  expected_evidence := jsonb_build_object(
    'kind', policy_kind_record,
    'scored_line_count', NEW.scored_line_count,
    'line_count', NEW.line_count,
    'coverage_bps', floor(10000.0 * NEW.scored_line_count / NEW.line_count)::integer,
    'final_score_bps', NEW.final_score_bps,
    'scoring_version', NEW.scoring_version,
    'scoring_provider', NEW.scoring_provider,
    'karaoke_revision_id', session_record.karaoke_revision_id
  );
  IF policy_kind_record = 'karaoke_qualification_v2' THEN
    expected_evidence := expected_evidence || jsonb_build_object(
      'playback_kind', session_record.playback_kind
    );
  ELSIF policy_kind_record <> 'karaoke_qualification_v1' THEN
    RAISE EXCEPTION 'Karaoke attempt policy is unsupported';
  END IF;
  IF NEW.evidence_summary <> expected_evidence THEN
    RAISE EXCEPTION 'Karaoke attempt evidence summary is not exact';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_karaoke_recording() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Karaoke recording rows cannot be deleted';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF ROW(NEW.session_id, NEW.attempt_id, NEW.account_id, NEW.artifact_id, NEW.created_at)
      IS DISTINCT FROM
       ROW(OLD.session_id, OLD.attempt_id, OLD.account_id, OLD.artifact_id, OLD.created_at) THEN
      RAISE EXCEPTION 'Karaoke recording identity is immutable';
    END IF;
    IF OLD.state <> 'pending' OR NEW.state NOT IN ('stored', 'failed') THEN
      IF OLD.state <> 'stored' OR NEW.state <> 'deleted' THEN
        RAISE EXCEPTION 'Invalid Karaoke recording transition';
      END IF;
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_karaoke_runtime_session_authority() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(
    NEW.lyrics_revision, NEW.scoring_version, NEW.scoring_provider,
    NEW.scoring_model, NEW.line_snapshot, NEW.client_context
  ) IS DISTINCT FROM ROW(
    OLD.lyrics_revision, OLD.scoring_version, OLD.scoring_provider,
    OLD.scoring_model, OLD.line_snapshot, OLD.client_context
  ) THEN
    RAISE EXCEPTION 'Karaoke runtime session authority is immutable';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_karaoke_session() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  attempt_record karaoke_attempts%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Karaoke sessions cannot be deleted';
  END IF;
  IF NOT active_owned_persona(NEW.account_id, NEW.persona_id)
     OR NOT active_community_effect(NEW.community_id, NEW.account_id)
     OR NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = NEW.timezone)
     OR NOT EXISTS (
       SELECT 1 FROM account_streak_clocks
        WHERE account_id = NEW.account_id AND timezone = NEW.timezone
     ) THEN
    RAISE EXCEPTION 'Karaoke session account, persona, community, or timezone is ineligible';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM posts
     WHERE community_id = NEW.community_id AND post_id = NEW.post_id
       AND post_type = 'song' AND status = 'published' AND visibility = 'public'
  ) THEN
    RAISE EXCEPTION 'Karaoke sessions require a public published song';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF ROW(
      NEW.session_id, NEW.attempt_id, NEW.account_id, NEW.persona_id,
      NEW.community_id, NEW.post_id, NEW.audio_revision, NEW.karaoke_revision_id,
      NEW.qualification_policy_version_id, NEW.endpoint_template,
      NEW.idempotency_key, NEW.request_hash, NEW.timezone, NEW.created_at, NEW.expires_at
    ) IS DISTINCT FROM ROW(
      OLD.session_id, OLD.attempt_id, OLD.account_id, OLD.persona_id,
      OLD.community_id, OLD.post_id, OLD.audio_revision, OLD.karaoke_revision_id,
      OLD.qualification_policy_version_id, OLD.endpoint_template,
      OLD.idempotency_key, OLD.request_hash, OLD.timezone, OLD.created_at, OLD.expires_at
    ) THEN
      RAISE EXCEPTION 'Karaoke session authority is immutable';
    END IF;
    IF OLD.status = 'completed' AND NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'completed Karaoke sessions are immutable';
    END IF;
    IF OLD.status = 'active' AND NEW.status = 'completed' THEN
      SELECT * INTO attempt_record FROM karaoke_attempts
       WHERE session_id = NEW.session_id AND attempt_id = NEW.attempt_id;
      IF attempt_record.attempt_id IS NULL
         OR NEW.completed_at IS DISTINCT FROM attempt_record.completed_at THEN
        RAISE EXCEPTION 'Karaoke completion requires exact terminal attempt evidence';
      END IF;
    ELSIF NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'invalid Karaoke session transition';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_karaoke_session_playback_kind() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.playback_kind IS DISTINCT FROM OLD.playback_kind THEN
    RAISE EXCEPTION 'Karaoke session playback kind is immutable';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_localization_lyric_line_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.community_id IS DISTINCT FROM NEW.community_id
     OR OLD.post_id IS DISTINCT FROM NEW.post_id
     OR OLD.lyric_line_id IS DISTINCT FROM NEW.lyric_line_id
     OR OLD.lifecycle_status <> 'active'
     OR NEW.lifecycle_status <> 'retired'
     OR NEW.retirement_reason IS NULL
     OR NEW.retired_at IS NULL THEN
    RAISE EXCEPTION 'lyric line lifecycle permits only one active-to-retired transition';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_media_finalize_fence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  expected media_post_submissions%ROWTYPE;
  community_active BOOLEAN;
  membership_active BOOLEAN;
BEGIN
  IF OLD.status IS DISTINCT FROM 'processing'
     OR OLD.phase IS DISTINCT FROM 'awaiting_upload'
     OR OLD.audio_revision IS DISTINCT FROM 0
     OR OLD.current_immutable_ref IS NOT NULL
     OR NEW.status IS DISTINCT FROM 'processing'
     OR NEW.phase IS DISTINCT FROM 'finalize' THEN
    RAISE EXCEPTION 'media finalize fence transition is not allowed';
  END IF;

  expected := OLD;
  expected.phase := 'finalize';
  expected.event_sequence := OLD.event_sequence + 1;
  expected.updated_at := NEW.updated_at;
  IF (to_jsonb(NEW) - 'actor_account_id') IS DISTINCT FROM
       (to_jsonb(expected) - 'actor_account_id')
     OR NEW.updated_at <= OLD.updated_at THEN
    RAISE EXCEPTION 'media finalize fence transition evidence is not exact';
  END IF;

  SELECT status = 'active'
    INTO community_active
    FROM communities
   WHERE community_id = NEW.community_id
   FOR SHARE;
  SELECT status = 'member'
    INTO membership_active
    FROM community_memberships
   WHERE community_id = NEW.community_id
     AND user_id = NEW.actor_user_id
   FOR SHARE;
  IF community_active IS DISTINCT FROM TRUE OR membership_active IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION 'media submission requires active community membership';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_media_finalize_sealed() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  expected media_post_submissions%ROWTYPE;
  audio_record media_audio_revisions%ROWTYPE;
  community_active BOOLEAN;
  membership_active BOOLEAN;
BEGIN
  IF OLD.status IS DISTINCT FROM 'processing'
     OR OLD.phase IS DISTINCT FROM 'finalize'
     OR OLD.audio_revision IS DISTINCT FROM 0
     OR OLD.current_immutable_ref IS NOT NULL
     OR NEW.status IS DISTINCT FROM 'processing'
     OR NEW.phase IS DISTINCT FROM 'analysis'
     OR NEW.audio_revision IS DISTINCT FROM 1
     OR NEW.current_immutable_ref IS NULL THEN
    RAISE EXCEPTION 'media finalized seal transition is not allowed';
  END IF;

  expected := OLD;
  expected.phase := 'analysis';
  expected.audio_revision := 1;
  expected.current_immutable_ref := NEW.current_immutable_ref;
  expected.workflow_revision := OLD.workflow_revision + 1;
  expected.event_sequence := OLD.event_sequence + 1;
  expected.updated_at := NEW.updated_at;
  IF (to_jsonb(NEW) - 'actor_account_id') IS DISTINCT FROM
       (to_jsonb(expected) - 'actor_account_id')
     OR NEW.updated_at <= OLD.updated_at THEN
    RAISE EXCEPTION 'media finalized seal transition evidence is not exact';
  END IF;

  SELECT *
    INTO audio_record
    FROM media_audio_revisions
   WHERE community_id = NEW.community_id
     AND actor_user_id = NEW.actor_user_id
     AND author_persona_id = NEW.author_persona_id
     AND submission_id = NEW.submission_id
     AND operation_id = NEW.operation_id
     AND audio_revision = NEW.audio_revision
   FOR SHARE;
  IF audio_record.submission_id IS NULL
     OR audio_record.immutable_ref IS DISTINCT FROM NEW.current_immutable_ref THEN
    RAISE EXCEPTION 'media finalized seal requires its exact audio revision';
  END IF;

  SELECT status = 'active'
    INTO community_active
    FROM communities
   WHERE community_id = NEW.community_id
   FOR SHARE;
  SELECT status = 'member'
    INTO membership_active
    FROM community_memberships
   WHERE community_id = NEW.community_id
     AND user_id = NEW.actor_user_id
   FOR SHARE;
  IF community_active IS DISTINCT FROM TRUE OR membership_active IS DISTINCT FROM TRUE THEN
    RAISE EXCEPTION 'media submission requires active community membership';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_media_lyrics_append_only() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'media song lyrics revisions are append-only';
END;
$$;

CREATE FUNCTION guard_media_lyrics_or_workflow_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE community_active BOOLEAN; membership_active BOOLEAN;
BEGIN
  IF NEW.current_lyrics_revision IS DISTINCT FROM OLD.current_lyrics_revision THEN
    SELECT status = 'active' INTO community_active FROM communities
      WHERE community_id=NEW.community_id FOR SHARE;
    SELECT status = 'member' INTO membership_active FROM community_memberships
      WHERE community_id=NEW.community_id AND user_id=NEW.actor_user_id FOR SHARE;
    IF community_active IS DISTINCT FROM TRUE OR membership_active IS DISTINCT FROM TRUE
       OR OLD.audio_revision = 0
       OR NOT (
         (OLD.status = 'processing' AND OLD.phase IN ('analysis','decision'))
         OR (OLD.status IN ('action_required','manual_review') AND OLD.phase IS NULL)
       )
       OR NEW.lyrics_revision IS DISTINCT FROM OLD.lyrics_revision + 1
       OR NEW.current_lyrics_revision IS DISTINCT FROM NEW.lyrics_revision
       OR NEW.creation_revision IS DISTINCT FROM OLD.creation_revision + 1
       OR NEW.current_terms_revision IS DISTINCT FROM
          (CASE WHEN OLD.current_terms_revision IS NULL THEN NULL ELSE NEW.creation_revision END)
       OR NEW.analysis_revision IS DISTINCT FROM OLD.analysis_revision
       OR NEW.current_analysis_revision IS NOT NULL
       OR NEW.decision_revision IS DISTINCT FROM 0
       OR NEW.current_decision_revision IS NOT NULL
       OR NEW.status IS DISTINCT FROM 'processing'
       OR NEW.phase IS DISTINCT FROM 'analysis'
       OR NEW.action_kind IS NOT NULL
       OR NEW.action_reference_request_ref IS NOT NULL
       OR NEW.action_expires_at IS NOT NULL
       OR NEW.review_ref IS NOT NULL
       OR NEW.review_reason_code IS NOT NULL
       OR NEW.review_exhaustion_code IS NOT NULL
       OR NEW.review_exhaustion_attempt_id IS NOT NULL
       OR NEW.held_revision IS NOT NULL
       OR NEW.moderator_action_id IS NOT NULL
       OR NEW.moderator_actor_id IS NOT NULL
       OR NEW.moderator_evidence_ref IS NOT NULL
       OR NEW.moderator_approval_kind IS NOT NULL
       OR NEW.moderator_reason_code IS NOT NULL
       OR NEW.failure_code IS NOT NULL
       OR NEW.failure_retry_count IS NOT NULL
       OR NEW.retryable IS NOT NULL
       OR NEW.last_safe_phase IS NOT NULL
       OR NEW.abandonment_reason IS NOT NULL
       OR NEW.retention_disposition IS NOT NULL
       OR NEW.event_sequence IS DISTINCT FROM OLD.event_sequence + 1
       OR NEW.updated_at <= OLD.updated_at
       OR (to_jsonb(NEW) - ARRAY[
         'lyrics_revision','current_lyrics_revision','creation_revision','current_terms_revision','current_analysis_revision',
         'decision_revision','current_decision_revision','status','phase','event_sequence','updated_at',
         'action_kind','action_reference_request_ref','action_expires_at','review_ref',
         'review_reason_code','review_exhaustion_code','review_exhaustion_attempt_id','held_revision',
         'moderator_action_id','moderator_actor_id','moderator_evidence_ref','moderator_approval_kind',
         'moderator_reason_code','failure_code','failure_retry_count','retryable','last_safe_phase',
         'actor_account_id'
       ]) IS DISTINCT FROM (to_jsonb(OLD) - ARRAY[
         'lyrics_revision','current_lyrics_revision','creation_revision','current_terms_revision','current_analysis_revision',
         'decision_revision','current_decision_revision','status','phase','event_sequence','updated_at',
         'action_kind','action_reference_request_ref','action_expires_at','review_ref',
         'review_reason_code','review_exhaustion_code','review_exhaustion_attempt_id','held_revision',
         'moderator_action_id','moderator_actor_id','moderator_evidence_ref','moderator_approval_kind',
         'moderator_reason_code','failure_code','failure_retry_count','retryable','last_safe_phase',
         'actor_account_id'
       ]) THEN
      RAISE EXCEPTION 'lyrics projection transition is not exact';
    END IF;
  ELSIF NEW.workflow_replacement_sequence IS DISTINCT FROM OLD.workflow_replacement_sequence THEN
    IF NEW.workflow_replacement_sequence IS DISTINCT FROM OLD.workflow_replacement_sequence + 1
       OR NEW.workflow_revision IS DISTINCT FROM OLD.workflow_revision + 1
       OR NEW.event_sequence IS DISTINCT FROM OLD.event_sequence + 1
       OR NEW.updated_at <= OLD.updated_at
       OR (to_jsonb(NEW) - ARRAY['workflow_replacement_sequence','workflow_revision','event_sequence','updated_at','actor_account_id'])
          IS DISTINCT FROM
          (to_jsonb(OLD) - ARRAY['workflow_replacement_sequence','workflow_revision','event_sequence','updated_at','actor_account_id']) THEN
      RAISE EXCEPTION 'workflow replacement transition is not exact';
    END IF;
  ELSE
    RAISE EXCEPTION 'specialized media transition has no owned mutation';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_media_moderation_projection_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE submission_record media_post_submissions%ROWTYPE;
BEGIN
  IF ROW(NEW.submission_id,NEW.community_id,NEW.actor_user_id,NEW.operation_id) IS DISTINCT FROM ROW(OLD.submission_id,OLD.community_id,OLD.actor_user_id,OLD.operation_id) THEN RAISE EXCEPTION 'moderation projection identity is immutable'; END IF;
  IF NEW.status = 'none' THEN RAISE EXCEPTION 'moderation projection cannot return to none'; END IF;
  SELECT * INTO submission_record FROM media_post_submissions WHERE community_id=NEW.community_id AND actor_user_id=NEW.actor_user_id AND submission_id=NEW.submission_id AND operation_id=NEW.operation_id FOR SHARE;
  IF submission_record.submission_id IS NULL THEN RAISE EXCEPTION 'moderation projection submission is missing'; END IF;
  IF NEW.status = 'open' AND (OLD.status IS DISTINCT FROM 'none' OR submission_record.status <> 'manual_review' OR NEW.review_ref IS DISTINCT FROM submission_record.review_ref OR NEW.held_revision IS DISTINCT FROM submission_record.held_revision OR NEW.review_exhaustion_code IS DISTINCT FROM submission_record.review_exhaustion_code OR NEW.review_exhaustion_attempt_id IS DISTINCT FROM submission_record.review_exhaustion_attempt_id OR NEW.action_kind IS NOT NULL OR NEW.moderator_action_id IS NOT NULL OR NEW.moderator_actor_id IS NOT NULL OR NEW.action_evidence_ref IS NOT NULL) THEN RAISE EXCEPTION 'open moderation projection does not match its held submission'; END IF;
  IF NEW.status = 'approved' AND (OLD.status IS DISTINCT FROM 'open' OR submission_record.status <> 'processing' OR submission_record.phase <> 'publish' OR NEW.decision_revision IS DISTINCT FROM submission_record.decision_revision OR NEW.review_ref IS NOT NULL OR NEW.held_revision IS NOT NULL OR NEW.review_exhaustion_code IS NOT NULL OR NEW.review_exhaustion_attempt_id IS NOT NULL OR NEW.moderator_action_id IS DISTINCT FROM submission_record.moderator_action_id OR NEW.moderator_actor_id IS DISTINCT FROM submission_record.moderator_actor_id OR NEW.action_evidence_ref IS DISTINCT FROM submission_record.moderator_evidence_ref OR NEW.action_kind IS DISTINCT FROM 'approve') THEN RAISE EXCEPTION 'approved moderation projection does not match its submission action'; END IF;
  IF NEW.status = 'blocked' AND (OLD.status IS DISTINCT FROM 'open' OR submission_record.status <> 'blocked' OR NEW.decision_revision IS DISTINCT FROM submission_record.decision_revision OR NEW.review_ref IS DISTINCT FROM OLD.review_ref OR NEW.held_revision IS DISTINCT FROM OLD.held_revision OR NEW.review_ref IS NULL OR NEW.held_revision IS NULL OR NEW.review_exhaustion_code IS NOT NULL OR NEW.review_exhaustion_attempt_id IS NOT NULL OR NEW.moderator_action_id IS DISTINCT FROM submission_record.moderator_action_id OR NEW.moderator_actor_id IS DISTINCT FROM submission_record.moderator_actor_id OR NEW.action_evidence_ref IS DISTINCT FROM submission_record.moderator_evidence_ref OR NEW.action_kind IS DISTINCT FROM 'block') THEN RAISE EXCEPTION 'blocked moderation projection does not match its submission action'; END IF;
  IF NEW.status = 'closed' AND (OLD.status IS DISTINCT FROM 'open' OR submission_record.status NOT IN ('processing','action_required','manual_review') OR NEW.decision_revision IS NOT NULL OR NEW.review_ref IS NOT NULL OR NEW.held_revision IS NOT NULL OR NEW.review_exhaustion_code IS NOT NULL OR NEW.review_exhaustion_attempt_id IS NOT NULL OR NEW.action_kind IS NOT NULL OR NEW.moderator_action_id IS NOT NULL OR NEW.moderator_actor_id IS NOT NULL OR NEW.action_evidence_ref IS NOT NULL) THEN RAISE EXCEPTION 'closed moderation projection is not an exact supersession'; END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_media_outbox_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(NEW.outbox_event_id, NEW.submission_id, NEW.community_id, NEW.actor_user_id, NEW.operation_id, NEW.creation_revision, NEW.audio_revision, NEW.analysis_revision, NEW.lyrics_revision, NEW.workflow_revision, NEW.workflow_instance_id, NEW.event_type, NEW.effect_identity, NEW.payload, NEW.created_at) IS DISTINCT FROM ROW(OLD.outbox_event_id, OLD.submission_id, OLD.community_id, OLD.actor_user_id, OLD.operation_id, OLD.creation_revision, OLD.audio_revision, OLD.analysis_revision, OLD.lyrics_revision, OLD.workflow_revision, OLD.workflow_instance_id, OLD.event_type, OLD.effect_identity, OLD.payload, OLD.created_at) THEN RAISE EXCEPTION 'media outbox effect identity is immutable'; END IF;
  IF NEW.updated_at <= OLD.updated_at OR NEW.claim_fence < OLD.claim_fence OR NEW.delivery_attempts < OLD.delivery_attempts OR NEW.delivery_attempts > 3 THEN RAISE EXCEPTION 'media outbox fence must advance'; END IF;
  IF (OLD.state = 'pending' AND (OLD.delivery_attempts >= 3 OR NEW.state <> 'running' OR NEW.delivery_attempts <> OLD.delivery_attempts + 1 OR NEW.claim_fence <> OLD.claim_fence + 1 OR NEW.claim_owner IS NULL OR NEW.lease_expires_at <= clock_timestamp())) THEN RAISE EXCEPTION 'media outbox claim is not allowed'; END IF;
  IF (OLD.state = 'failed' AND (OLD.delivery_attempts >= 3 OR OLD.next_eligible_at IS NULL OR OLD.next_eligible_at > clock_timestamp() OR NEW.state <> 'running' OR NEW.delivery_attempts <> OLD.delivery_attempts + 1 OR NEW.claim_fence <> OLD.claim_fence + 1 OR NEW.claim_owner IS NULL OR NEW.lease_expires_at <= clock_timestamp())) THEN RAISE EXCEPTION 'media outbox claim is not allowed'; END IF;
  IF OLD.state = 'running' AND NEW.state = 'running' AND (OLD.lease_expires_at > clock_timestamp() OR NEW.delivery_attempts <> CASE WHEN OLD.delivery_attempts < 3 THEN OLD.delivery_attempts + 1 ELSE OLD.delivery_attempts END OR NEW.claim_fence <> OLD.claim_fence + 1 OR NEW.claim_owner IS NULL OR NEW.lease_expires_at <= clock_timestamp()) THEN RAISE EXCEPTION 'media outbox reclaim is not allowed'; END IF;
  IF OLD.state = 'running' AND NEW.state IN ('delivered', 'failed', 'exhausted') AND (NEW.delivery_attempts <> OLD.delivery_attempts OR OLD.lease_expires_at <= clock_timestamp() OR NEW.claim_fence <> OLD.claim_fence OR NEW.claim_owner IS NOT NULL OR (NEW.state = 'exhausted' AND OLD.delivery_attempts <> 3) OR (NEW.state = 'failed' AND OLD.delivery_attempts >= 3) OR (NEW.state = 'failed' AND NEW.next_eligible_at IS NULL) OR (NEW.state = 'exhausted' AND NEW.next_eligible_at IS NOT NULL)) THEN RAISE EXCEPTION 'media outbox completion is not allowed'; END IF;
  IF OLD.state NOT IN ('pending', 'failed', 'running') THEN RAISE EXCEPTION 'media outbox is terminal'; END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_media_processing_attempt_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(NEW.attempt_id, NEW.submission_id, NEW.community_id, NEW.actor_user_id,
      NEW.operation_id, NEW.audio_revision, NEW.analysis_revision, NEW.stage,
      NEW.attempt_number, NEW.input_hash, NEW.provider_idempotency_key, NEW.input_kind,
      NEW.input_revision, NEW.policy_revision, NEW.adapter_revision, NEW.created_at)
    IS DISTINCT FROM
    ROW(OLD.attempt_id, OLD.submission_id, OLD.community_id, OLD.actor_user_id,
      OLD.operation_id, OLD.audio_revision, OLD.analysis_revision, OLD.stage,
      OLD.attempt_number, OLD.input_hash, OLD.provider_idempotency_key, OLD.input_kind,
      OLD.input_revision, OLD.policy_revision, OLD.adapter_revision, OLD.created_at) THEN
    RAISE EXCEPTION 'media processing attempt identity is immutable';
  END IF;
  IF NEW.updated_at <= OLD.updated_at THEN
    RAISE EXCEPTION 'media processing attempt timestamp must advance';
  END IF;
  IF NEW.state = 'retry_wait' AND NEW.attempt_number >= 3 THEN
    RAISE EXCEPTION 'media processing attempt retry bound is exhausted';
  END IF;
  IF OLD.state IN ('retry_wait', 'poll_wait') AND
      (OLD.next_eligible_at IS NULL OR OLD.next_eligible_at > clock_timestamp()) THEN
    RAISE EXCEPTION 'media processing attempt retry is not yet eligible';
  END IF;
  IF OLD.state IN ('pending', 'retry_wait', 'poll_wait') AND
      (NEW.state <> 'running' OR NEW.claim_fence <> OLD.claim_fence + 1
       OR NEW.claim_owner IS NULL OR NEW.lease_expires_at <= clock_timestamp()) THEN
    RAISE EXCEPTION 'media processing attempt claim is not allowed';
  END IF;
  IF OLD.state = 'running' AND NEW.state = 'running' AND
      (OLD.lease_expires_at > clock_timestamp() OR NEW.claim_fence <> OLD.claim_fence + 1
       OR NEW.claim_owner IS NULL OR NEW.lease_expires_at <= clock_timestamp()) THEN
    RAISE EXCEPTION 'media processing attempt reclaim is not allowed';
  END IF;
  IF OLD.state = 'running' AND NEW.state IN ('succeeded', 'retry_wait', 'poll_wait', 'failed', 'exhausted') AND
      (OLD.lease_expires_at <= clock_timestamp() OR NEW.claim_fence <> OLD.claim_fence
       OR NEW.claim_owner IS NOT NULL) THEN
    RAISE EXCEPTION 'media processing attempt completion is not allowed';
  END IF;
  IF OLD.state NOT IN ('pending', 'retry_wait', 'poll_wait', 'running') THEN
    RAISE EXCEPTION 'media processing attempt is terminal';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_media_publication_projection_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE alignment_record media_alignment_projections%ROWTYPE;
        registration_record data_registration_operations%ROWTYPE;
BEGIN
  IF ROW(
    NEW.submission_id, NEW.community_id, NEW.actor_user_id, NEW.operation_id,
    NEW.post_id, NEW.creation_revision, NEW.audio_revision, NEW.analysis_revision,
    NEW.decision_revision, NEW.canonical_audio_sha256, NEW.title,
    NEW.audio_asset_ref, NEW.cover_artifact_ref, NEW.language_status,
    NEW.primary_language_bcp47, NEW.secondary_language_bcp47,
    NEW.lyrics_explicitness, NEW.analysis_badges, NEW.locked_delivery,
    NEW.author_persona_id, NEW.lyrics_status, NEW.lyrics_revision,
    NEW.lyrics_text, NEW.projected_at
  ) IS DISTINCT FROM ROW(
    OLD.submission_id, OLD.community_id, OLD.actor_user_id, OLD.operation_id,
    OLD.post_id, OLD.creation_revision, OLD.audio_revision, OLD.analysis_revision,
    OLD.decision_revision, OLD.canonical_audio_sha256, OLD.title,
    OLD.audio_asset_ref, OLD.cover_artifact_ref, OLD.language_status,
    OLD.primary_language_bcp47, OLD.secondary_language_bcp47,
    OLD.lyrics_explicitness, OLD.analysis_badges, OLD.locked_delivery,
    OLD.author_persona_id, OLD.lyrics_status, OLD.lyrics_revision,
    OLD.lyrics_text, OLD.projected_at
  ) THEN
    RAISE EXCEPTION 'media publication accepted evidence is immutable';
  END IF;
  IF NEW.alignment IS DISTINCT FROM OLD.alignment THEN
    SELECT * INTO alignment_record FROM media_alignment_projections
      WHERE community_id=NEW.community_id AND actor_user_id=NEW.actor_user_id
        AND submission_id=NEW.submission_id AND operation_id=NEW.operation_id
        AND post_id=NEW.post_id FOR SHARE;
    IF alignment_record.submission_id IS NULL
       OR alignment_record.status IS DISTINCT FROM NEW.alignment
       OR alignment_record.audio_revision IS DISTINCT FROM NEW.audio_revision
       OR alignment_record.analysis_revision IS DISTINCT FROM NEW.analysis_revision
       OR alignment_record.canonical_audio_sha256 IS DISTINCT FROM NEW.canonical_audio_sha256 THEN
      RAISE EXCEPTION 'publication alignment is not owned by the exact alignment projection';
    END IF;
  END IF;
  IF NEW.data_registration IS DISTINCT FROM OLD.data_registration THEN
    SELECT * INTO registration_record FROM data_registration_operations
      WHERE community_id=NEW.community_id AND actor_user_id=NEW.actor_user_id
        AND post_id=NEW.post_id
      ORDER BY registration_revision DESC LIMIT 1 FOR SHARE;
    IF registration_record.registration_operation_id IS NULL
       OR registration_record.community_id IS DISTINCT FROM NEW.community_id
       OR registration_record.actor_user_id IS DISTINCT FROM NEW.actor_user_id
       OR registration_record.submission_id IS DISTINCT FROM NEW.submission_id
       OR registration_record.media_operation_id IS DISTINCT FROM NEW.operation_id
       OR registration_record.publication_creation_revision IS DISTINCT FROM NEW.creation_revision
       OR registration_record.publication_audio_revision IS DISTINCT FROM NEW.audio_revision
       OR registration_record.publication_analysis_revision IS DISTINCT FROM NEW.analysis_revision
       OR registration_record.publication_decision_revision IS DISTINCT FROM NEW.decision_revision
       OR registration_record.canonical_audio_sha256 IS DISTINCT FROM NEW.canonical_audio_sha256
       OR NEW.data_registration IS DISTINCT FROM (CASE registration_record.state
         WHEN 'registered' THEN 'registered'
         WHEN 'failed' THEN 'failed'
         ELSE 'pending'
       END) THEN
      RAISE EXCEPTION 'publication DATA state is not owned by the exact registration operation';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_media_reservation_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE submission_record media_post_submissions%ROWTYPE;
BEGIN
  IF ROW(NEW.reservation_id, NEW.community_id, NEW.actor_user_id, NEW.endpoint_template, NEW.idempotency_key, NEW.request_hash, NEW.expected_content_type, NEW.expected_size_bytes, NEW.expected_sha256, NEW.upload_url, NEW.upload_headers, NEW.expires_at, NEW.response_snapshot_bytes, NEW.response_snapshot_sha256, NEW.created_at) IS DISTINCT FROM ROW(OLD.reservation_id, OLD.community_id, OLD.actor_user_id, OLD.endpoint_template, OLD.idempotency_key, OLD.request_hash, OLD.expected_content_type, OLD.expected_size_bytes, OLD.expected_sha256, OLD.upload_url, OLD.upload_headers, OLD.expires_at, OLD.response_snapshot_bytes, OLD.response_snapshot_sha256, OLD.created_at) THEN RAISE EXCEPTION 'media reservation authority is immutable'; END IF;
  IF OLD.state IN ('sealed', 'rejected', 'expired') OR NOT ((OLD.state = 'issued' AND NEW.state = 'claimed') OR (OLD.state = 'issued' AND NEW.state = 'expired' AND OLD.expires_at <= clock_timestamp()) OR (OLD.state = 'claimed' AND NEW.state IN ('sealed', 'rejected')) OR (OLD.state = 'claimed' AND NEW.state = 'expired' AND OLD.expires_at <= clock_timestamp())) OR NEW.updated_at <= OLD.updated_at THEN RAISE EXCEPTION 'media reservation transition is not allowed'; END IF;
  IF OLD.state = 'issued' AND NEW.state = 'claimed' AND (NEW.claim_fence <> OLD.claim_fence + 1 OR NEW.terminal_reason IS NOT NULL OR NEW.terminal_evidence_ref IS NOT NULL OR NEW.terminal_evidence_digest IS NOT NULL OR NEW.terminal_at IS NOT NULL OR NEW.terminal_fence IS NOT NULL) THEN RAISE EXCEPTION 'media reservation claim fence is not exact'; END IF;
  IF OLD.state = 'claimed' AND (NEW.submission_id IS DISTINCT FROM OLD.submission_id OR NEW.operation_id IS DISTINCT FROM OLD.operation_id) THEN RAISE EXCEPTION 'media reservation claim identity is immutable'; END IF;
  IF OLD.state = 'claimed' AND NEW.state = 'rejected' THEN
    SELECT * INTO submission_record FROM media_post_submissions
      WHERE community_id=NEW.community_id AND actor_user_id=NEW.actor_user_id
        AND submission_id=NEW.submission_id AND operation_id=NEW.operation_id FOR SHARE;
    IF submission_record.submission_id IS NULL
       OR NEW.claim_fence IS DISTINCT FROM OLD.claim_fence
       OR NEW.terminal_fence IS DISTINCT FROM submission_record.event_sequence
       OR NEW.terminal_at IS NULL
       OR NEW.terminal_evidence_ref IS NULL
       OR NEW.terminal_evidence_digest IS DISTINCT FROM encode(sha256(NEW.terminal_evidence_ref::bytea), 'hex')
       OR (submission_record.status = 'abandoned' AND NEW.terminal_reason IS DISTINCT FROM CASE submission_record.abandonment_reason WHEN 'upload_expectation_mismatch' THEN 'expectation_mismatch' WHEN 'upload_source_changed_before_finalize' THEN 'source_precondition_failed' ELSE NULL END)
       OR (submission_record.status = 'processing_failed' AND (NEW.terminal_reason IS DISTINCT FROM 'destination_conflict' OR submission_record.failure_code IS DISTINCT FROM 'upload_seal_conflict'))
       OR submission_record.status NOT IN ('abandoned', 'processing_failed')
       THEN
      RAISE EXCEPTION 'media reservation rejection is not bound to its terminal submission';
    END IF;
  END IF;
  IF OLD.state = 'claimed' AND NEW.state = 'expired' THEN
    SELECT * INTO submission_record FROM media_post_submissions
      WHERE community_id=NEW.community_id AND actor_user_id=NEW.actor_user_id
        AND submission_id=NEW.submission_id AND operation_id=NEW.operation_id FOR SHARE;
    IF submission_record.submission_id IS NULL
       OR submission_record.status IS DISTINCT FROM 'abandoned'
       OR submission_record.abandonment_reason IS DISTINCT FROM 'reservation_expired'
       OR NEW.claim_fence IS DISTINCT FROM OLD.claim_fence
       OR NEW.submission_id IS NULL OR NEW.operation_id IS NULL
       OR NEW.terminal_reason IS NOT NULL OR NEW.terminal_evidence_ref IS NOT NULL
       OR NEW.terminal_evidence_digest IS NOT NULL OR NEW.terminal_at IS NOT NULL
       OR NEW.terminal_fence IS NOT NULL
       OR NEW.expires_at > clock_timestamp() THEN
      RAISE EXCEPTION 'media reservation expiry is not bound to its terminal submission';
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_media_submission_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE allowed BOOLEAN := FALSE; community_active BOOLEAN; membership_active BOOLEAN; analysis_record media_analysis_evidence%ROWTYPE; decision_record media_publication_decisions%ROWTYPE; post_record posts%ROWTYPE; audio_record media_audio_revisions%ROWTYPE; terms_record media_submission_terms%ROWTYPE; moderation_action media_moderation_actions%ROWTYPE;
BEGIN
  IF ROW(NEW.submission_id, NEW.community_id, NEW.actor_user_id, NEW.operation_id, NEW.endpoint_template, NEW.idempotency_key, NEW.request_hash, NEW.title, NEW.song_type, NEW.start_input, NEW.audio_reservation_id, NEW.response_snapshot_bytes, NEW.response_snapshot_sha256, NEW.created_at) IS DISTINCT FROM ROW(OLD.submission_id, OLD.community_id, OLD.actor_user_id, OLD.operation_id, OLD.endpoint_template, OLD.idempotency_key, OLD.request_hash, OLD.title, OLD.song_type, OLD.start_input, OLD.audio_reservation_id, OLD.response_snapshot_bytes, OLD.response_snapshot_sha256, OLD.created_at) THEN RAISE EXCEPTION 'media submission authority is immutable'; END IF;
  IF NEW.event_sequence <> OLD.event_sequence + 1 OR NEW.updated_at <= OLD.updated_at THEN RAISE EXCEPTION 'media submission transition fence did not advance'; END IF;
  SELECT status = 'active' INTO community_active FROM communities WHERE community_id = NEW.community_id FOR SHARE;
  SELECT status = 'member' INTO membership_active FROM community_memberships WHERE community_id = NEW.community_id AND user_id = NEW.actor_user_id FOR SHARE;
  IF community_active IS DISTINCT FROM TRUE OR membership_active IS DISTINCT FROM TRUE THEN RAISE EXCEPTION 'media submission requires active community membership'; END IF;
  allowed :=
    (OLD.status = 'processing' AND OLD.phase = 'reserve' AND NEW.status = 'processing' AND NEW.phase = 'awaiting_upload'
      AND NEW.creation_revision = 1 AND NEW.audio_revision = 0 AND NEW.analysis_revision = 0 AND NEW.decision_revision = 0
      AND NEW.workflow_revision = 0 AND NEW.current_terms_revision IS NULL AND NEW.current_immutable_ref IS NULL
      AND NEW.current_analysis_revision IS NULL AND NEW.current_decision_revision IS NULL AND NEW.post_id IS NULL)
    OR ((OLD.status = 'processing' AND OLD.phase IN ('awaiting_upload', 'finalize', 'analysis', 'decision')) OR (OLD.status IN ('action_required', 'manual_review') AND OLD.phase IS NULL))
      AND NEW.status = 'processing' AND NEW.phase = CASE WHEN OLD.audio_revision = 0 THEN 'awaiting_upload' ELSE 'analysis' END
      AND NEW.creation_revision = OLD.creation_revision + 1 AND NEW.audio_revision = OLD.audio_revision AND NEW.analysis_revision = OLD.analysis_revision
      AND NEW.decision_revision = 0 AND NEW.current_decision_revision IS NULL AND NEW.current_terms_revision = NEW.creation_revision
      AND NEW.workflow_revision = OLD.workflow_revision AND NEW.post_id IS NULL
    OR (OLD.status = 'processing' AND OLD.phase = 'awaiting_upload' AND OLD.audio_revision = 0 AND NEW.status = 'processing' AND NEW.phase = 'analysis'
      AND NEW.audio_revision = 1 AND NEW.analysis_revision = OLD.analysis_revision AND NEW.workflow_revision = OLD.workflow_revision + 1 AND NEW.creation_revision = OLD.creation_revision)
    OR (OLD.status = 'processing' AND OLD.phase = 'analysis' AND NEW.status = 'processing' AND NEW.phase IN ('analysis', 'decision')
      AND NEW.analysis_revision = OLD.analysis_revision + 1 AND NEW.audio_revision = OLD.audio_revision AND NEW.creation_revision = OLD.creation_revision
      AND NEW.decision_revision = 0 AND NEW.current_decision_revision IS NULL AND NEW.workflow_revision = OLD.workflow_revision)
    OR (OLD.status = 'processing' AND OLD.phase = 'decision' AND NEW.status = 'processing' AND NEW.phase = 'publish'
      AND NEW.decision_revision = OLD.decision_revision + 1 AND NEW.current_decision_revision = NEW.decision_revision AND NEW.creation_revision = OLD.creation_revision
      AND NEW.audio_revision = OLD.audio_revision AND NEW.analysis_revision = OLD.analysis_revision AND NEW.post_id IS NULL)
    OR (OLD.status = 'processing' AND OLD.phase IN ('analysis', 'decision') AND NEW.status = 'manual_review' AND NEW.phase IS NULL
      AND NEW.decision_revision = OLD.decision_revision + 1 AND NEW.current_decision_revision = NEW.decision_revision AND NEW.creation_revision = OLD.creation_revision
      AND NEW.audio_revision = OLD.audio_revision AND NEW.analysis_revision = OLD.analysis_revision AND NEW.post_id IS NULL)
    OR (OLD.status = 'processing' AND OLD.phase = 'decision' AND NEW.status = 'blocked' AND NEW.phase IS NULL
      AND NEW.decision_revision = OLD.decision_revision + 1 AND NEW.current_decision_revision = NEW.decision_revision AND NEW.creation_revision = OLD.creation_revision
      AND NEW.audio_revision = OLD.audio_revision AND NEW.analysis_revision = OLD.analysis_revision AND NEW.post_id IS NULL)
    OR (OLD.status = 'processing' AND (OLD.phase = 'analysis' OR (OLD.phase = 'decision' AND NEW.review_reason_code = 'moderation_unavailable' AND NEW.review_exhaustion_code IS NULL AND NEW.review_exhaustion_attempt_id IS NULL)) AND NEW.status = 'manual_review' AND NEW.phase IS NULL
      AND NEW.decision_revision = 0 AND NEW.current_decision_revision IS NULL AND NEW.creation_revision = OLD.creation_revision AND NEW.audio_revision = OLD.audio_revision
      AND NEW.analysis_revision = OLD.analysis_revision AND NEW.review_ref IS NOT NULL
      AND ((NEW.review_reason_code = 'review_required' AND NEW.review_exhaustion_code = 'acr_exhausted' AND NEW.review_exhaustion_attempt_id IS NOT NULL)
        OR (NEW.review_reason_code = 'moderation_unavailable' AND NEW.review_exhaustion_code IS NULL AND NEW.review_exhaustion_attempt_id IS NULL))
      AND NEW.held_revision = OLD.creation_revision AND NEW.post_id IS NULL)
    OR (OLD.status = 'processing' AND OLD.phase = 'decision' AND NEW.status = 'action_required' AND NEW.phase IS NULL
      AND NEW.action_kind = 'reference_required' AND NEW.action_expires_at > clock_timestamp() AND NEW.held_revision = OLD.creation_revision
      AND NEW.creation_revision = OLD.creation_revision AND NEW.audio_revision = OLD.audio_revision AND NEW.analysis_revision = OLD.analysis_revision
      AND NEW.decision_revision = 0 AND NEW.current_decision_revision IS NULL AND NEW.post_id IS NULL)
    OR (OLD.status = 'action_required' AND OLD.phase IS NULL AND NEW.status = 'processing' AND NEW.phase = 'analysis'
      AND NEW.creation_revision = OLD.creation_revision + 1 AND NEW.audio_revision = OLD.audio_revision AND NEW.analysis_revision = OLD.analysis_revision
      AND NEW.decision_revision = 0 AND NEW.current_decision_revision IS NULL AND NEW.workflow_revision = OLD.workflow_revision AND NEW.bound_reference_asset_id IS NOT NULL AND NEW.post_id IS NULL)
    OR (OLD.status = 'manual_review' AND OLD.phase IS NULL AND NEW.status = 'processing' AND NEW.phase = 'publish'
      AND NEW.creation_revision = OLD.creation_revision AND NEW.decision_revision = OLD.decision_revision + 1 AND NEW.current_decision_revision = NEW.decision_revision AND NEW.post_id IS NULL)
    OR (OLD.status = 'manual_review' AND OLD.phase IS NULL AND NEW.status = 'blocked' AND NEW.phase IS NULL
      AND NEW.creation_revision = OLD.creation_revision AND NEW.decision_revision = OLD.decision_revision AND NEW.post_id IS NULL)
    OR (OLD.status = 'processing' AND OLD.phase = 'publish' AND NEW.status = 'published' AND NEW.phase IS NULL
      AND NEW.workflow_revision = OLD.workflow_revision + 1 AND NEW.post_id IS NOT NULL AND NEW.decision_revision = OLD.decision_revision AND NEW.current_decision_revision = NEW.decision_revision AND NEW.creation_revision = OLD.creation_revision)
    OR (OLD.status = 'processing' AND OLD.phase IN ('reserve', 'awaiting_upload', 'finalize', 'analysis', 'decision', 'publish') AND NEW.status = 'processing_failed' AND NEW.phase IS NULL
      AND NEW.creation_revision = OLD.creation_revision AND NEW.audio_revision = OLD.audio_revision AND NEW.analysis_revision = OLD.analysis_revision AND NEW.decision_revision = 0 AND NEW.current_decision_revision IS NULL AND NEW.workflow_revision = OLD.workflow_revision
      AND NEW.failure_code IS NOT NULL AND NEW.failure_retry_count IS NOT NULL AND NEW.last_safe_phase IS NOT NULL
      AND (NEW.failure_code IS DISTINCT FROM 'upload_seal_conflict' OR OLD.phase = 'finalize'))
    OR (OLD.status = 'processing_failed' AND OLD.phase IS NULL AND OLD.retryable = TRUE AND OLD.failure_retry_count < 3 AND OLD.retry_count < 3 AND NEW.status = 'processing' AND NEW.phase = OLD.last_safe_phase
      AND NEW.creation_revision = OLD.creation_revision + 1 AND NEW.retry_count = OLD.retry_count + 1 AND NEW.audio_revision = OLD.audio_revision AND NEW.analysis_revision = OLD.analysis_revision
      AND NEW.decision_revision = 0 AND NEW.current_decision_revision IS NULL AND NEW.workflow_revision = OLD.workflow_revision)
    OR (OLD.status = 'action_required' AND OLD.phase IS NULL AND NEW.status = 'abandoned' AND NEW.phase IS NULL AND OLD.action_kind = 'reference_required'
      AND OLD.action_expires_at <= clock_timestamp() AND NEW.abandonment_reason = 'action_deadline_elapsed' AND NEW.post_id IS NULL)
    OR (OLD.status = 'processing' AND OLD.phase IN ('reserve', 'awaiting_upload') AND OLD.audio_revision = 0 AND NEW.status = 'abandoned' AND NEW.phase IS NULL
      AND NEW.abandonment_reason = 'author_cancelled' AND NEW.post_id IS NULL)
    OR (OLD.status = 'processing' AND OLD.phase = 'awaiting_upload' AND OLD.audio_revision = 0 AND NEW.status = 'abandoned' AND NEW.phase IS NULL
      AND NEW.abandonment_reason = 'reservation_expired' AND NEW.post_id IS NULL)
    OR (OLD.status = 'processing' AND OLD.phase IN ('awaiting_upload', 'finalize') AND OLD.audio_revision = 0 AND NEW.status = 'abandoned' AND NEW.phase IS NULL
      AND NEW.abandonment_reason = 'upload_expectation_mismatch' AND NEW.post_id IS NULL)
    OR (OLD.status = 'processing' AND OLD.phase = 'finalize' AND OLD.audio_revision = 0 AND NEW.status = 'abandoned' AND NEW.phase IS NULL
      AND NEW.abandonment_reason = 'upload_source_changed_before_finalize' AND NEW.post_id IS NULL);
  IF allowed IS NOT TRUE THEN RAISE EXCEPTION 'media submission transition is not allowed'; END IF;
  IF OLD.status = 'processing' AND OLD.phase = 'reserve' AND NEW.status = 'processing' AND NEW.phase = 'awaiting_upload' THEN
    IF NEW.creation_revision IS DISTINCT FROM OLD.creation_revision OR NEW.audio_revision IS DISTINCT FROM OLD.audio_revision OR NEW.analysis_revision IS DISTINCT FROM OLD.analysis_revision OR NEW.decision_revision IS DISTINCT FROM OLD.decision_revision OR NEW.workflow_revision IS DISTINCT FROM OLD.workflow_revision OR NEW.current_terms_revision IS DISTINCT FROM OLD.current_terms_revision OR NEW.current_immutable_ref IS DISTINCT FROM OLD.current_immutable_ref OR NEW.current_analysis_revision IS DISTINCT FROM OLD.current_analysis_revision OR NEW.current_decision_revision IS DISTINCT FROM OLD.current_decision_revision OR NEW.post_id IS DISTINCT FROM OLD.post_id OR NEW.retry_count IS DISTINCT FROM OLD.retry_count OR NEW.failure_code IS DISTINCT FROM OLD.failure_code OR NEW.failure_retry_count IS DISTINCT FROM OLD.failure_retry_count OR NEW.retryable IS DISTINCT FROM OLD.retryable OR NEW.last_safe_phase IS DISTINCT FROM OLD.last_safe_phase OR NEW.action_kind IS DISTINCT FROM OLD.action_kind OR NEW.action_reference_request_ref IS DISTINCT FROM OLD.action_reference_request_ref OR NEW.action_expires_at IS DISTINCT FROM OLD.action_expires_at OR NEW.held_revision IS DISTINCT FROM OLD.held_revision OR NEW.review_ref IS DISTINCT FROM OLD.review_ref OR NEW.review_reason_code IS DISTINCT FROM OLD.review_reason_code OR NEW.review_exhaustion_code IS DISTINCT FROM OLD.review_exhaustion_code OR NEW.review_exhaustion_attempt_id IS DISTINCT FROM OLD.review_exhaustion_attempt_id OR NEW.moderator_action_id IS DISTINCT FROM OLD.moderator_action_id OR NEW.moderator_actor_id IS DISTINCT FROM OLD.moderator_actor_id OR NEW.moderator_evidence_ref IS DISTINCT FROM OLD.moderator_evidence_ref OR NEW.moderator_approval_kind IS DISTINCT FROM OLD.moderator_approval_kind OR NEW.moderator_reason_code IS DISTINCT FROM OLD.moderator_reason_code OR NEW.abandonment_reason IS DISTINCT FROM OLD.abandonment_reason OR NEW.retention_disposition IS DISTINCT FROM OLD.retention_disposition OR ROW(NEW.bound_reference_asset_id,NEW.bound_reference_evidence_ref,NEW.bound_reference_audio_revision,NEW.bound_reference_analysis_revision,NEW.bound_reference_audio_sha256,NEW.bound_reference_upstream_share_bps) IS DISTINCT FROM ROW(OLD.bound_reference_asset_id,OLD.bound_reference_evidence_ref,OLD.bound_reference_audio_revision,OLD.bound_reference_analysis_revision,OLD.bound_reference_audio_sha256,OLD.bound_reference_upstream_share_bps) THEN RAISE EXCEPTION 'reservation issued transition evidence is not exact'; END IF;
  ELSIF (((OLD.status = 'processing' AND OLD.phase IN ('awaiting_upload', 'finalize', 'analysis', 'decision')) OR (OLD.status IN ('action_required', 'manual_review') AND OLD.phase IS NULL)) AND NEW.status = 'processing' AND NEW.creation_revision = OLD.creation_revision + 1 AND NEW.current_terms_revision = NEW.creation_revision) THEN
    SELECT * INTO terms_record FROM media_submission_terms WHERE community_id=NEW.community_id AND actor_user_id=NEW.actor_user_id AND submission_id=NEW.submission_id AND operation_id=NEW.operation_id AND creation_revision=NEW.creation_revision FOR SHARE;
    IF terms_record.submission_id IS NULL OR NEW.audio_revision <> OLD.audio_revision OR NEW.analysis_revision <> OLD.analysis_revision OR NEW.decision_revision <> 0 OR NEW.current_decision_revision IS NOT NULL OR NEW.workflow_revision <> OLD.workflow_revision OR NEW.current_immutable_ref IS DISTINCT FROM OLD.current_immutable_ref OR NEW.current_analysis_revision IS DISTINCT FROM OLD.current_analysis_revision OR ROW(NEW.bound_reference_asset_id,NEW.bound_reference_evidence_ref,NEW.bound_reference_audio_revision,NEW.bound_reference_analysis_revision,NEW.bound_reference_audio_sha256,NEW.bound_reference_upstream_share_bps) IS DISTINCT FROM ROW(OLD.bound_reference_asset_id,OLD.bound_reference_evidence_ref,OLD.bound_reference_audio_revision,OLD.bound_reference_analysis_revision,OLD.bound_reference_audio_sha256,OLD.bound_reference_upstream_share_bps) OR NEW.review_ref IS NOT NULL OR NEW.review_reason_code IS NOT NULL OR NEW.review_exhaustion_code IS NOT NULL OR NEW.review_exhaustion_attempt_id IS NOT NULL OR NEW.held_revision IS NOT NULL OR NEW.action_kind IS NOT NULL OR NEW.action_reference_request_ref IS NOT NULL OR NEW.action_expires_at IS NOT NULL OR NEW.moderator_action_id IS NOT NULL OR NEW.moderator_actor_id IS NOT NULL OR NEW.moderator_evidence_ref IS NOT NULL OR NEW.moderator_approval_kind IS NOT NULL OR NEW.moderator_reason_code IS NOT NULL OR NEW.post_id IS NOT NULL OR terms_record.license_preset IS NULL OR terms_record.access_mode <> 'public' THEN RAISE EXCEPTION 'terms transition evidence is not exact'; END IF;
  ELSIF OLD.status = 'processing' AND OLD.phase = 'awaiting_upload' AND NEW.status = 'processing' AND NEW.audio_revision = OLD.audio_revision + 1 THEN
    SELECT * INTO audio_record FROM media_audio_revisions WHERE community_id=NEW.community_id AND actor_user_id=NEW.actor_user_id AND submission_id=NEW.submission_id AND operation_id=NEW.operation_id AND audio_revision=NEW.audio_revision FOR SHARE;
    IF audio_record.submission_id IS NULL OR NEW.creation_revision <> OLD.creation_revision OR NEW.analysis_revision <> OLD.analysis_revision OR NEW.decision_revision <> OLD.decision_revision OR NEW.current_decision_revision IS DISTINCT FROM OLD.current_decision_revision OR NEW.workflow_revision <> OLD.workflow_revision + 1 OR NEW.current_immutable_ref IS DISTINCT FROM audio_record.immutable_ref OR NEW.phase <> 'analysis' OR NEW.review_ref IS NOT NULL OR NEW.review_reason_code IS NOT NULL OR NEW.review_exhaustion_code IS NOT NULL OR NEW.review_exhaustion_attempt_id IS NOT NULL OR NEW.held_revision IS NOT NULL OR NEW.action_kind IS NOT NULL OR NEW.action_reference_request_ref IS NOT NULL OR NEW.action_expires_at IS NOT NULL OR NEW.moderator_action_id IS NOT NULL OR NEW.moderator_actor_id IS NOT NULL OR NEW.moderator_evidence_ref IS NOT NULL OR NEW.moderator_approval_kind IS NOT NULL OR NEW.moderator_reason_code IS NOT NULL OR NEW.post_id IS NOT NULL THEN RAISE EXCEPTION 'audio transition evidence is not exact'; END IF;
    IF NEW.current_terms_revision IS DISTINCT FROM OLD.current_terms_revision OR NEW.current_analysis_revision IS DISTINCT FROM OLD.current_analysis_revision OR ROW(NEW.bound_reference_asset_id,NEW.bound_reference_evidence_ref,NEW.bound_reference_audio_revision,NEW.bound_reference_analysis_revision,NEW.bound_reference_audio_sha256,NEW.bound_reference_upstream_share_bps) IS DISTINCT FROM ROW(OLD.bound_reference_asset_id,OLD.bound_reference_evidence_ref,OLD.bound_reference_audio_revision,OLD.bound_reference_analysis_revision,OLD.bound_reference_audio_sha256,OLD.bound_reference_upstream_share_bps) OR NEW.workflow_revision <> OLD.workflow_revision + 1 OR NEW.retry_count <> OLD.retry_count OR NEW.failure_code IS DISTINCT FROM OLD.failure_code OR NEW.failure_retry_count IS DISTINCT FROM OLD.failure_retry_count OR NEW.retryable IS DISTINCT FROM OLD.retryable OR NEW.last_safe_phase IS DISTINCT FROM OLD.last_safe_phase OR NEW.abandonment_reason IS DISTINCT FROM OLD.abandonment_reason OR NEW.retention_disposition IS DISTINCT FROM OLD.retention_disposition THEN RAISE EXCEPTION 'audio transition pointers are not exact'; END IF;
  ELSIF OLD.status = 'processing' AND OLD.phase = 'analysis' AND NEW.status = 'processing' AND NEW.analysis_revision = OLD.analysis_revision + 1 THEN
    SELECT * INTO analysis_record FROM media_analysis_evidence WHERE community_id=NEW.community_id AND actor_user_id=NEW.actor_user_id AND submission_id=NEW.submission_id AND operation_id=NEW.operation_id AND analysis_revision=NEW.analysis_revision FOR SHARE;
    IF analysis_record.submission_id IS NULL OR NEW.creation_revision <> OLD.creation_revision OR NEW.audio_revision <> OLD.audio_revision OR NEW.current_analysis_revision <> NEW.analysis_revision OR NEW.decision_revision <> 0 OR NEW.current_decision_revision IS NOT NULL OR NEW.workflow_revision <> OLD.workflow_revision OR NEW.current_immutable_ref IS DISTINCT FROM OLD.current_immutable_ref OR NEW.phase NOT IN ('analysis','decision') OR NEW.review_ref IS NOT NULL OR NEW.review_reason_code IS NOT NULL OR NEW.review_exhaustion_code IS NOT NULL OR NEW.review_exhaustion_attempt_id IS NOT NULL OR NEW.held_revision IS NOT NULL OR NEW.action_kind IS NOT NULL OR NEW.action_reference_request_ref IS NOT NULL OR NEW.action_expires_at IS NOT NULL OR NEW.moderator_action_id IS NOT NULL OR NEW.moderator_actor_id IS NOT NULL OR NEW.moderator_evidence_ref IS NOT NULL OR NEW.moderator_approval_kind IS NOT NULL OR NEW.moderator_reason_code IS NOT NULL OR NEW.post_id IS NOT NULL OR analysis_record.audio_revision <> NEW.audio_revision OR analysis_record.canonical_audio_sha256 IS DISTINCT FROM (SELECT canonical_sha256 FROM media_audio_revisions WHERE community_id=NEW.community_id AND actor_user_id=NEW.actor_user_id AND submission_id=NEW.submission_id AND operation_id=NEW.operation_id AND audio_revision=NEW.audio_revision) THEN RAISE EXCEPTION 'analysis transition evidence is not exact'; END IF;
    IF NEW.current_terms_revision IS DISTINCT FROM OLD.current_terms_revision OR ROW(NEW.bound_reference_asset_id,NEW.bound_reference_evidence_ref,NEW.bound_reference_audio_revision,NEW.bound_reference_analysis_revision,NEW.bound_reference_audio_sha256,NEW.bound_reference_upstream_share_bps) IS DISTINCT FROM ROW(OLD.bound_reference_asset_id,OLD.bound_reference_evidence_ref,OLD.bound_reference_audio_revision,OLD.bound_reference_analysis_revision,OLD.bound_reference_audio_sha256,OLD.bound_reference_upstream_share_bps) OR NEW.retry_count <> OLD.retry_count OR NEW.failure_code IS DISTINCT FROM OLD.failure_code OR NEW.failure_retry_count IS DISTINCT FROM OLD.failure_retry_count OR NEW.retryable IS DISTINCT FROM OLD.retryable OR NEW.last_safe_phase IS DISTINCT FROM OLD.last_safe_phase OR NEW.abandonment_reason IS DISTINCT FROM OLD.abandonment_reason OR NEW.retention_disposition IS DISTINCT FROM OLD.retention_disposition THEN RAISE EXCEPTION 'analysis transition pointers are not exact'; END IF;
  ELSIF OLD.status = 'processing' AND (OLD.phase = 'decision' OR (OLD.phase = 'analysis' AND NEW.status = 'manual_review')) AND NEW.decision_revision = OLD.decision_revision + 1 THEN
    SELECT * INTO decision_record FROM media_publication_decisions WHERE community_id=NEW.community_id AND actor_user_id=NEW.actor_user_id AND submission_id=NEW.submission_id AND operation_id=NEW.operation_id AND decision_revision=NEW.decision_revision FOR SHARE;
    IF decision_record.submission_id IS NULL
       OR NEW.creation_revision <> OLD.creation_revision
       OR NEW.audio_revision <> OLD.audio_revision
       OR NEW.analysis_revision <> OLD.analysis_revision
       OR NEW.current_immutable_ref IS DISTINCT FROM OLD.current_immutable_ref
       OR NEW.current_analysis_revision IS DISTINCT FROM OLD.current_analysis_revision
       OR NEW.current_terms_revision IS DISTINCT FROM OLD.current_terms_revision
