    IF OLD.retryable IS DISTINCT FROM TRUE OR OLD.failure_retry_count IS NULL OR OLD.failure_retry_count >= 3 OR OLD.retry_count >= 3 OR NEW.creation_revision <> OLD.creation_revision + 1 OR NEW.retry_count <> OLD.retry_count + 1 OR NEW.audio_revision <> OLD.audio_revision OR NEW.analysis_revision <> OLD.analysis_revision OR NEW.decision_revision <> 0 OR NEW.current_decision_revision IS NOT NULL OR NEW.workflow_revision <> OLD.workflow_revision OR NEW.phase IS DISTINCT FROM OLD.last_safe_phase OR NEW.failure_code IS NOT NULL OR NEW.failure_retry_count IS NOT NULL OR NEW.retryable IS NOT NULL OR NEW.last_safe_phase IS NOT NULL OR NEW.action_kind IS NOT NULL OR NEW.action_reference_request_ref IS NOT NULL OR NEW.action_expires_at IS NOT NULL OR NEW.review_ref IS NOT NULL OR NEW.review_reason_code IS NOT NULL OR NEW.review_exhaustion_code IS NOT NULL OR NEW.review_exhaustion_attempt_id IS NOT NULL OR NEW.held_revision IS NOT NULL OR NEW.moderator_action_id IS NOT NULL OR NEW.moderator_actor_id IS NOT NULL OR NEW.moderator_evidence_ref IS NOT NULL OR NEW.moderator_approval_kind IS NOT NULL OR NEW.moderator_reason_code IS NOT NULL THEN RAISE EXCEPTION 'retry transition evidence is not exact'; END IF;
  END IF;
  IF NEW.bound_reference_asset_id IS NOT NULL AND NOT EXISTS (SELECT 1 FROM media_reference_evidence r WHERE r.community_id = NEW.community_id AND r.actor_user_id = NEW.actor_user_id AND r.submission_id = NEW.submission_id AND r.operation_id = NEW.operation_id AND r.asset_id = NEW.bound_reference_asset_id AND r.evidence_ref = NEW.bound_reference_evidence_ref AND r.evidence_audio_revision = NEW.bound_reference_audio_revision AND r.evidence_analysis_revision = NEW.bound_reference_analysis_revision AND r.evidence_audio_sha256 = NEW.bound_reference_audio_sha256 AND r.upstream_commercial_rev_share_bps IS NOT DISTINCT FROM NEW.bound_reference_upstream_share_bps) THEN RAISE EXCEPTION 'bound reference evidence is missing'; END IF;
  IF (NEW.status = 'processing' AND NEW.phase = 'publish') OR NEW.status = 'published' THEN
    SELECT * INTO analysis_record FROM media_analysis_evidence WHERE community_id=NEW.community_id AND actor_user_id=NEW.actor_user_id AND submission_id = NEW.submission_id AND operation_id=NEW.operation_id AND analysis_revision = NEW.analysis_revision FOR SHARE;
    SELECT * INTO decision_record FROM media_publication_decisions WHERE community_id=NEW.community_id AND actor_user_id=NEW.actor_user_id AND submission_id = NEW.submission_id AND operation_id=NEW.operation_id AND decision_revision = NEW.decision_revision FOR SHARE;
    IF analysis_record.submission_id IS NULL OR decision_record.submission_id IS NULL OR decision_record.outcome <> 'allow' OR decision_record.creation_revision <> NEW.creation_revision OR decision_record.audio_revision <> NEW.audio_revision OR decision_record.analysis_revision <> NEW.analysis_revision OR decision_record.canonical_audio_sha256 <> analysis_record.canonical_audio_sha256 OR analysis_record.media_safety NOT IN ('allow', 'not_applicable', 'cover_withheld', 'visual_provider_unavailable') OR analysis_record.lyrics_safety NOT IN ('not_applicable', 'allow') OR analysis_record.speech_status = 'unavailable' OR COALESCE(analysis_record.explicitness, 'not_applicable') NOT IN ('not_explicit', 'explicit', 'not_applicable') OR (analysis_record.acr_decision = 'inconclusive' AND NOT EXISTS (SELECT 1 FROM media_moderation_actions m WHERE m.community_id=NEW.community_id AND m.actor_user_id=NEW.actor_user_id AND m.submission_id=NEW.submission_id AND m.operation_id=NEW.operation_id AND m.action_id=NEW.moderator_action_id AND m.approval_kind='acr_override' AND m.reason_code IN ('acr_inconclusive','acr_exhausted'))) OR (analysis_record.acr_decision = 'skipped' AND NOT EXISTS (SELECT 1 FROM media_moderation_actions m WHERE m.community_id=NEW.community_id AND m.actor_user_id=NEW.actor_user_id AND m.submission_id=NEW.submission_id AND m.operation_id=NEW.operation_id AND m.action_id=NEW.moderator_action_id AND m.approval_kind='acr_override' AND m.reason_code='acr_skipped')) OR (analysis_record.acr_decision = 'requires_reference' AND NEW.bound_reference_asset_id IS NULL) OR NOT EXISTS (SELECT 1 FROM media_submission_terms WHERE community_id=NEW.community_id AND actor_user_id=NEW.actor_user_id AND submission_id = NEW.submission_id AND operation_id=NEW.operation_id AND creation_revision = NEW.creation_revision) THEN RAISE EXCEPTION 'media publication evidence is not ratified'; END IF;
  END IF;
  IF NEW.status = 'published' THEN
    SELECT * INTO post_record FROM posts WHERE community_id = NEW.community_id AND post_id = NEW.post_id FOR SHARE;
    IF post_record.post_id IS NULL OR post_record.author_user_id <> NEW.actor_user_id OR post_record.post_type <> 'song' OR post_record.status <> 'published' OR post_record.visibility <> 'public' OR post_record.title <> NEW.title THEN RAISE EXCEPTION 'media publication Post is not owned by submission'; END IF;
  END IF;
  IF NEW.status = 'abandoned' AND NEW.abandonment_reason = 'reservation_expired' AND NOT EXISTS (SELECT 1 FROM media_upload_reservations r WHERE r.community_id=NEW.community_id AND r.actor_user_id=NEW.actor_user_id AND r.reservation_id=NEW.audio_reservation_id AND r.expires_at <= clock_timestamp()) THEN RAISE EXCEPTION 'reservation is not expired'; END IF;
  IF NEW.status = 'abandoned' AND NEW.abandonment_reason IN ('author_cancelled', 'reservation_expired') AND NEW.retention_disposition IS DISTINCT FROM 'no_object' THEN RAISE EXCEPTION 'pre-finalize abandonment retention is not exact'; END IF;
  IF NEW.status = 'abandoned' AND NEW.abandonment_reason IN ('upload_expectation_mismatch', 'upload_source_changed_before_finalize') AND NEW.retention_disposition IS DISTINCT FROM 'retain_for_reconciliation' THEN RAISE EXCEPTION 'upload precondition abandonment retention is not exact'; END IF;
  IF NEW.status = 'abandoned' AND NEW.abandonment_reason = 'action_deadline_elapsed' AND NEW.retention_disposition IS DISTINCT FROM (CASE WHEN NEW.audio_revision > 0 THEN 'retain_until_expiry' ELSE 'no_object' END) THEN RAISE EXCEPTION 'action deadline retention is not exact'; END IF;
  IF NEW.status = 'abandoned' THEN
    IF NEW.phase IS NOT NULL OR NEW.post_id IS NOT NULL OR NEW.audio_revision IS DISTINCT FROM OLD.audio_revision OR NEW.analysis_revision IS DISTINCT FROM OLD.analysis_revision OR NEW.decision_revision <> 0 OR NEW.current_decision_revision IS NOT NULL OR NEW.current_immutable_ref IS DISTINCT FROM OLD.current_immutable_ref OR NEW.current_analysis_revision IS DISTINCT FROM OLD.current_analysis_revision OR NEW.current_terms_revision IS DISTINCT FROM OLD.current_terms_revision OR ROW(NEW.bound_reference_asset_id, NEW.bound_reference_evidence_ref, NEW.bound_reference_audio_revision, NEW.bound_reference_analysis_revision, NEW.bound_reference_audio_sha256, NEW.bound_reference_upstream_share_bps) IS DISTINCT FROM ROW(OLD.bound_reference_asset_id, OLD.bound_reference_evidence_ref, OLD.bound_reference_audio_revision, OLD.bound_reference_analysis_revision, OLD.bound_reference_audio_sha256, OLD.bound_reference_upstream_share_bps) OR NEW.workflow_revision <> OLD.workflow_revision OR NEW.retry_count <> OLD.retry_count OR NEW.failure_code IS NOT NULL OR NEW.failure_retry_count IS NOT NULL OR NEW.retryable IS NOT NULL OR NEW.last_safe_phase IS NOT NULL OR NEW.action_kind IS NOT NULL OR NEW.action_reference_request_ref IS NOT NULL OR NEW.action_expires_at IS NOT NULL OR NEW.review_ref IS NOT NULL OR NEW.review_reason_code IS NOT NULL OR NEW.review_exhaustion_code IS NOT NULL OR NEW.review_exhaustion_attempt_id IS NOT NULL OR NEW.held_revision IS NOT NULL OR NEW.moderator_action_id IS NOT NULL OR NEW.moderator_actor_id IS NOT NULL OR NEW.moderator_evidence_ref IS NOT NULL OR NEW.moderator_approval_kind IS NOT NULL OR NEW.moderator_reason_code IS NOT NULL THEN RAISE EXCEPTION 'abandoned cleanup is not exact'; END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_megapot_allocation_batch_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Megapot allocation batches cannot be deleted';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    ROW(
      NEW.allocation_batch_id, NEW.pool_leg_id, NEW.drawing_id, NEW.snapshot_id,
      NEW.claim_effect_id, NEW.algorithm_version, NEW.net_winnings_atomic,
      NEW.allocation_count, NEW.allocation_hash, NEW.created_at
    ) IS DISTINCT FROM ROW(
      OLD.allocation_batch_id, OLD.pool_leg_id, OLD.drawing_id, OLD.snapshot_id,
      OLD.claim_effect_id, OLD.algorithm_version, OLD.net_winnings_atomic,
      OLD.allocation_count, OLD.allocation_hash, OLD.created_at
    ) OR OLD.state <> 'prepared' OR NEW.state <> 'credited'
  ) THEN
    RAISE EXCEPTION 'invalid Megapot allocation batch transition';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_attestation_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Megapot deployment attestations cannot be deleted';
  END IF;
  IF ROW(
    NEW.attestation_id, NEW.environment, NEW.chain_id, NEW.jackpot_address,
    NEW.usdc_address, NEW.ticket_nft_address, NEW.custody_address,
    NEW.referrer_address, NEW.source_tag, NEW.jackpot_code_hash,
    NEW.usdc_code_hash, NEW.ticket_nft_code_hash, NEW.attestation_block_number,
    NEW.attestation_block_hash, NEW.abi_version, NEW.verified_at, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.attestation_id, OLD.environment, OLD.chain_id, OLD.jackpot_address,
    OLD.usdc_address, OLD.ticket_nft_address, OLD.custody_address,
    OLD.referrer_address, OLD.source_tag, OLD.jackpot_code_hash,
    OLD.usdc_code_hash, OLD.ticket_nft_code_hash, OLD.attestation_block_number,
    OLD.attestation_block_hash, OLD.abi_version, OLD.verified_at, OLD.created_at
  ) OR OLD.status <> 'active' OR NEW.status <> 'retired' THEN
    RAISE EXCEPTION 'Megapot deployment attestation only permits retirement';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_claim_effect() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  chain_record reward_chain_effects%ROWTYPE;
  attestation_record megapot_deployment_attestations%ROWTYPE;
  ticket_record megapot_ticket_inventory%ROWTYPE;
  sweep_record megapot_drawing_sweeps%ROWTYPE;
  sweep_evidence megapot_sweep_ticket_evidence%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Megapot claim effects are append-only';
  END IF;
  SELECT * INTO chain_record FROM reward_chain_effects
   WHERE effect_id = NEW.claim_effect_id FOR SHARE;
  SELECT * INTO attestation_record FROM megapot_deployment_attestations
   WHERE attestation_id = NEW.attestation_id FOR SHARE;
  SELECT * INTO ticket_record FROM megapot_ticket_inventory
   WHERE attestation_id = NEW.attestation_id AND ticket_id = NEW.ticket_id FOR SHARE;
  SELECT * INTO sweep_record FROM megapot_drawing_sweeps
   WHERE sweep_id = NEW.sweep_id FOR SHARE;
  SELECT * INTO sweep_evidence FROM megapot_sweep_ticket_evidence
   WHERE sweep_id = NEW.sweep_id AND ticket_id = NEW.ticket_id FOR SHARE;
  IF chain_record.effect_kind <> 'winnings_claim'
     OR chain_record.chain_id <> attestation_record.chain_id
     OR chain_record.signer_address <> attestation_record.custody_address
     OR chain_record.target_address <> attestation_record.jackpot_address
     OR ticket_record.pool_leg_id <> NEW.pool_leg_id
     OR ticket_record.drawing_id <> NEW.drawing_id
     OR ticket_record.status <> 'claim_pending'
     OR sweep_record.state <> 'complete'
     OR sweep_record.pool_leg_id <> NEW.pool_leg_id
     OR sweep_record.drawing_id <> NEW.drawing_id
     OR sweep_evidence.attestation_id <> NEW.attestation_id
     OR sweep_evidence.tier_id IN (0, 2)
     OR sweep_evidence.gross_winnings_atomic <> NEW.expected_gross_winnings_atomic
     OR sweep_evidence.net_winnings_atomic <> NEW.expected_net_winnings_atomic
     OR sweep_evidence.referral_accrual_atomic <>
          NEW.expected_referral_accrual_atomic THEN
    RAISE EXCEPTION 'Megapot claim effect does not match custody ticket';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_claim_effect_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  chain_record reward_chain_effects%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Megapot claim effects cannot be deleted';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF ROW(
      NEW.claim_effect_id, NEW.attestation_id, NEW.ticket_id, NEW.pool_leg_id,
      NEW.drawing_id, NEW.sweep_id, NEW.expected_gross_winnings_atomic,
      NEW.expected_net_winnings_atomic, NEW.expected_referral_accrual_atomic,
      NEW.custody_balance_before_atomic, NEW.referral_balance_before_atomic,
      NEW.preflight_block_number, NEW.preflight_block_hash, NEW.created_at
    ) IS DISTINCT FROM ROW(
      OLD.claim_effect_id, OLD.attestation_id, OLD.ticket_id, OLD.pool_leg_id,
      OLD.drawing_id, OLD.sweep_id, OLD.expected_gross_winnings_atomic,
      OLD.expected_net_winnings_atomic, OLD.expected_referral_accrual_atomic,
      OLD.custody_balance_before_atomic, OLD.referral_balance_before_atomic,
      OLD.preflight_block_number, OLD.preflight_block_hash, OLD.created_at
    ) OR OLD.received_atomic IS NOT NULL OR OLD.referral_accrual_atomic IS NOT NULL
       OR OLD.claim_log_index IS NOT NULL OR OLD.burn_log_index IS NOT NULL
       OR OLD.referral_log_index IS NOT NULL OR OLD.transfer_log_index IS NOT NULL
       OR NEW.received_atomic IS NULL OR NEW.referral_accrual_atomic IS NULL
       OR NEW.claim_log_index IS NULL OR NEW.burn_log_index IS NULL
       OR NEW.referral_log_index IS NULL OR NEW.transfer_log_index IS NULL THEN
      RAISE EXCEPTION 'invalid Megapot claim observation update';
    END IF;
    SELECT * INTO chain_record FROM reward_chain_effects
     WHERE effect_id = NEW.claim_effect_id FOR SHARE;
    IF chain_record.state <> 'confirmed'
       OR chain_record.settled_amount_atomic <> NEW.received_atomic THEN
      RAISE EXCEPTION 'Megapot claim observation requires confirmed exact receipt';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_commitment_effect() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Megapot commitment effects cannot be deleted';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF ROW(
      NEW.commitment_effect_id, NEW.snapshot_id, NEW.payload_hash,
      NEW.signing_key_id, NEW.signature, NEW.prepared_at, NEW.created_at
    ) IS DISTINCT FROM ROW(
      OLD.commitment_effect_id, OLD.snapshot_id, OLD.payload_hash,
      OLD.signing_key_id, OLD.signature, OLD.prepared_at, OLD.created_at
    ) OR OLD.state <> 'prepared' OR NEW.state <> 'published' THEN
      RAISE EXCEPTION 'invalid Megapot commitment publication';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_drawing_sweep() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Megapot drawing sweeps cannot be deleted';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    ROW(
      NEW.sweep_id, NEW.pool_leg_id, NEW.attestation_id, NEW.drawing_id,
      NEW.observation_block_number, NEW.observation_block_hash,
      NEW.drawing_state_hash, NEW.ticket_count, NEW.winning_ticket_count,
      NEW.observed_at, NEW.created_at
    ) IS DISTINCT FROM ROW(
      OLD.sweep_id, OLD.pool_leg_id, OLD.attestation_id, OLD.drawing_id,
      OLD.observation_block_number, OLD.observation_block_hash,
      OLD.drawing_state_hash, OLD.ticket_count, OLD.winning_ticket_count,
      OLD.observed_at, OLD.created_at
    ) OR OLD.state <> 'observed'
       OR NEW.state NOT IN ('complete', 'reconciliation_required')
  ) THEN
    RAISE EXCEPTION 'invalid Megapot drawing sweep transition';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_pool_drawing() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  leg_record song_reward_offer_legs%ROWTYPE;
  offer_record song_reward_offers%ROWTYPE;
  observation_record megapot_drawing_observations%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Megapot pool drawings cannot be deleted';
  END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT * INTO leg_record FROM song_reward_offer_legs
     WHERE leg_id = NEW.pool_leg_id FOR SHARE;
    SELECT * INTO offer_record FROM song_reward_offers
     WHERE offer_id = leg_record.offer_id FOR SHARE;
    SELECT * INTO observation_record FROM megapot_drawing_observations
     WHERE observation_id = NEW.observation_id FOR SHARE;
    IF NEW.status <> 'entry_open' OR leg_record.kind <> 'megapot_pool'
       OR leg_record.status <> 'active'
       OR offer_record.offer_id IS NULL
       OR offer_record.status <> 'active'
       OR NEW.drawing_id < leg_record.participation_starts_drawing_id
       OR observation_record.observation_id IS NULL
       OR observation_record.attestation_id <> leg_record.attestation_id
       OR observation_record.drawing_id <> NEW.drawing_id
       OR observation_record.drawing_locked
       OR observation_record.expires_at <= clock_timestamp()
       OR NEW.entry_cutoff_at <> observation_record.drawing_time
            - make_interval(secs => leg_record.entry_cutoff_seconds)
       OR NEW.entry_cutoff_at <= clock_timestamp()
       OR NEW.entry_cutoff_at > offer_record.ends_at
       OR NEW.ticket_price_ceiling_atomic <> leg_record.max_ticket_price_atomic THEN
      RAISE EXCEPTION 'Megapot pool drawing does not match live leg and observation';
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(
    NEW.pool_leg_id, NEW.drawing_id, NEW.observation_id, NEW.entry_cutoff_at,
    NEW.ticket_price_ceiling_atomic, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.pool_leg_id, OLD.drawing_id, OLD.observation_id, OLD.entry_cutoff_at,
    OLD.ticket_price_ceiling_atomic, OLD.created_at
  ) THEN
    RAISE EXCEPTION 'Megapot pool drawing identity is immutable';
  END IF;
  IF OLD.status IN (
    'no_win', 'credited', 'closed_no_entries', 'closed_unfunded',
    'closed_fallback_ineligible', 'closed_fallback_unavailable',
    'closed_fallback_ceiling', 'closed_purchase_unavailable', 'operational_hold'
  ) AND NEW IS DISTINCT FROM OLD THEN
    RAISE EXCEPTION 'terminal Megapot pool drawing is immutable';
  END IF;
  IF NEW.version <> OLD.version + 1 OR NEW.updated_at <= OLD.updated_at THEN
    RAISE EXCEPTION 'Megapot pool drawing transition requires next version and time';
  END IF;
  IF NOT (
    (OLD.status = 'entry_open' AND NEW.status IN (
      'cutoff_frozen', 'closed_no_entries', 'closed_unfunded',
      'closed_fallback_ineligible', 'closed_fallback_unavailable',
      'closed_fallback_ceiling', 'operational_hold'
    ))
    OR (OLD.status = 'cutoff_frozen' AND NEW.status IN ('committed', 'operational_hold'))
    OR (OLD.status = 'committed' AND NEW.status IN (
      'purchase_pending', 'closed_purchase_unavailable', 'operational_hold'
    ))
    OR (OLD.status = 'purchase_pending' AND NEW.status IN ('tickets_confirmed', 'operational_hold'))
    OR (OLD.status = 'tickets_confirmed' AND NEW.status IN ('drawing_pending', 'operational_hold'))
    OR (OLD.status = 'drawing_pending' AND NEW.status IN (
      'no_win', 'winnings_detected', 'operational_hold'
    ))
    OR (OLD.status = 'winnings_detected' AND NEW.status IN ('claim_pending', 'operational_hold'))
    OR (OLD.status = 'claim_pending' AND NEW.status IN ('claimed', 'operational_hold'))
    OR (OLD.status = 'claimed' AND NEW.status IN ('allocated', 'operational_hold'))
    OR (OLD.status = 'allocated' AND NEW.status IN ('credited', 'operational_hold'))
  ) THEN
    RAISE EXCEPTION 'invalid Megapot pool drawing transition';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_pool_share() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  drawing_record megapot_pool_drawings%ROWTYPE;
  leg_record song_reward_offer_legs%ROWTYPE;
  offer_record song_reward_offers%ROWTYPE;
  qualification_record activity_qualifications%ROWTYPE;
  eligibility_record reward_eligibility_decisions%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Megapot pool shares are append-only';
  END IF;
  SELECT * INTO drawing_record FROM megapot_pool_drawings
   WHERE pool_leg_id = NEW.pool_leg_id AND drawing_id = NEW.drawing_id FOR UPDATE;
  SELECT * INTO leg_record FROM song_reward_offer_legs
   WHERE leg_id = NEW.pool_leg_id FOR SHARE;
  SELECT * INTO offer_record FROM song_reward_offers
   WHERE offer_id = leg_record.offer_id FOR SHARE;
  SELECT * INTO qualification_record FROM activity_qualifications
   WHERE qualification_id = NEW.qualification_id FOR SHARE;
  SELECT * INTO eligibility_record FROM reward_eligibility_decisions
   WHERE eligibility_decision_id = NEW.eligibility_decision_id FOR SHARE;
  IF drawing_record.status <> 'entry_open'
     OR clock_timestamp() >= drawing_record.entry_cutoff_at
     OR qualification_record.account_id <> NEW.account_id
     OR qualification_record.persona_id <> NEW.persona_id
     OR qualification_record.community_id <> offer_record.community_id
     OR qualification_record.post_id <> offer_record.post_id
     OR qualification_record.audio_revision <> offer_record.audio_revision
     OR NOT qualification_record.activity_key = ANY(leg_record.eligible_activities)
     OR qualification_record.score_bps < leg_record.min_score_bps
     OR qualification_record.qualified_at >= drawing_record.entry_cutoff_at
     OR qualification_record.qualified_at < leg_record.participation_starts_at
     OR NEW.qualified_at <> qualification_record.qualified_at
     OR eligibility_record.leg_id <> NEW.pool_leg_id
     OR eligibility_record.account_id <> NEW.account_id
     OR eligibility_record.persona_id <> NEW.persona_id
     OR eligibility_record.purpose <> 'pool_share'
     OR eligibility_record.qualification_id <> NEW.qualification_id
     OR eligibility_record.drawing_id <> NEW.drawing_id
     OR eligibility_record.outcome <> 'eligible'
     OR eligibility_record.expires_at <= clock_timestamp() THEN
    RAISE EXCEPTION 'Megapot pool share is not exact eligible qualification output';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_purchase_effect() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  chain_record reward_chain_effects%ROWTYPE;
  attestation_record megapot_deployment_attestations%ROWTYPE;
  observation_record megapot_drawing_observations%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Megapot purchase effects are append-only';
  END IF;
  SELECT * INTO chain_record FROM reward_chain_effects
   WHERE effect_id = NEW.purchase_effect_id FOR SHARE;
  SELECT * INTO attestation_record FROM megapot_deployment_attestations
   WHERE attestation_id = NEW.attestation_id FOR SHARE;
  SELECT * INTO observation_record FROM megapot_drawing_observations
   WHERE observation_id = NEW.drawing_observation_id FOR SHARE;
  IF chain_record.effect_kind <> 'ticket_purchase'
     OR chain_record.chain_id <> attestation_record.chain_id
     OR chain_record.signer_address <> attestation_record.custody_address
     OR chain_record.target_address <> attestation_record.jackpot_address
     OR chain_record.reserved_amount_atomic <> NEW.ticket_price_atomic
     OR NEW.recipient_address <> attestation_record.custody_address
     OR NEW.source_tag <> attestation_record.source_tag
     OR observation_record.attestation_id <> NEW.attestation_id
     OR observation_record.drawing_id <> NEW.drawing_id
     OR observation_record.ticket_price_atomic <> NEW.ticket_price_atomic
     OR NEW.normal_five > observation_record.ball_max
     OR NEW.bonusball > observation_record.bonusball_max THEN
    RAISE EXCEPTION 'Megapot purchase effect does not match deployment and drawing';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_ticket_inventory() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  purchase_record megapot_ticket_purchase_effects%ROWTYPE;
  chain_record reward_chain_effects%ROWTYPE;
  attestation_record megapot_deployment_attestations%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Megapot ticket inventory cannot be deleted';
  END IF;
  IF TG_OP = 'INSERT' THEN
    SELECT * INTO purchase_record FROM megapot_ticket_purchase_effects
     WHERE purchase_effect_id = NEW.purchase_effect_id FOR SHARE;
    SELECT * INTO chain_record FROM reward_chain_effects
     WHERE effect_id = NEW.purchase_effect_id FOR SHARE;
    SELECT * INTO attestation_record FROM megapot_deployment_attestations
     WHERE attestation_id = NEW.attestation_id FOR SHARE;
    IF chain_record.state <> 'confirmed' OR chain_record.receipt_status <> 'success'
       OR chain_record.transaction_hash <> NEW.minted_transaction_hash
       OR purchase_record.pool_leg_id <> NEW.pool_leg_id
       OR purchase_record.drawing_id <> NEW.drawing_id
       OR purchase_record.attestation_id <> NEW.attestation_id
       OR NEW.custody_address <> attestation_record.custody_address
       OR NEW.status <> 'custodied' THEN
      RAISE EXCEPTION 'Megapot ticket inventory requires confirmed custody mint';
    END IF;
    RETURN NEW;
  END IF;
  IF ROW(
    NEW.attestation_id, NEW.ticket_id, NEW.purchase_effect_id,
    NEW.pool_leg_id, NEW.drawing_id, NEW.custody_address,
    NEW.owner_observation_block_number, NEW.owner_observation_block_hash,
    NEW.minted_transaction_hash, NEW.minted_log_index, NEW.acquired_at
  ) IS DISTINCT FROM ROW(
    OLD.attestation_id, OLD.ticket_id, OLD.purchase_effect_id,
    OLD.pool_leg_id, OLD.drawing_id, OLD.custody_address,
    OLD.owner_observation_block_number, OLD.owner_observation_block_hash,
    OLD.minted_transaction_hash, OLD.minted_log_index, OLD.acquired_at
  ) THEN
    RAISE EXCEPTION 'Megapot ticket inventory identity is immutable';
  END IF;
  IF NOT (
    (OLD.status = 'custodied' AND NEW.status IN ('claim_pending', 'no_win', 'needs_review'))
    OR (OLD.status = 'claim_pending' AND NEW.status IN ('claimed', 'needs_review'))
  ) THEN
    RAISE EXCEPTION 'invalid Megapot ticket inventory transition';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_ticket_review_evidence() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  ticket_record megapot_ticket_inventory%ROWTYPE;
  drawing_record megapot_pool_drawings%ROWTYPE;
  claim_record megapot_claim_effects%ROWTYPE;
  chain_record reward_chain_effects%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Megapot ticket review evidence is append-only';
  END IF;
  SELECT * INTO ticket_record FROM megapot_ticket_inventory
   WHERE attestation_id=NEW.attestation_id AND ticket_id=NEW.ticket_id FOR SHARE;
  SELECT * INTO drawing_record FROM megapot_pool_drawings
   WHERE pool_leg_id=NEW.pool_leg_id AND drawing_id=NEW.drawing_id FOR SHARE;
  IF ticket_record.attestation_id IS NULL
     OR ticket_record.pool_leg_id <> NEW.pool_leg_id
     OR ticket_record.drawing_id <> NEW.drawing_id
     OR ticket_record.status <> 'needs_review'
     OR drawing_record.status <> 'operational_hold'
     OR drawing_record.terminal_reason <> NEW.reason THEN
    RAISE EXCEPTION 'Megapot ticket review evidence identity mismatch';
  END IF;
  IF NEW.claim_effect_id IS NOT NULL THEN
    SELECT * INTO claim_record FROM megapot_claim_effects
     WHERE claim_effect_id=NEW.claim_effect_id FOR SHARE;
    SELECT * INTO chain_record FROM reward_chain_effects
     WHERE effect_id=NEW.claim_effect_id FOR SHARE;
    IF claim_record.claim_effect_id IS NULL
       OR claim_record.attestation_id <> NEW.attestation_id
       OR claim_record.ticket_id <> NEW.ticket_id
       OR claim_record.pool_leg_id <> NEW.pool_leg_id
       OR claim_record.drawing_id <> NEW.drawing_id
       OR chain_record.state <> 'terminal_failed' THEN
      RAISE EXCEPTION 'Megapot ticket review claim evidence mismatch';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_usdc_approval_effect() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  chain_record reward_chain_effects%ROWTYPE;
  attestation_record megapot_deployment_attestations%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Megapot USDC approval effects are append-only';
  END IF;
  SELECT * INTO chain_record FROM reward_chain_effects
   WHERE effect_id = NEW.approval_effect_id FOR SHARE;
  SELECT * INTO attestation_record FROM megapot_deployment_attestations
   WHERE attestation_id = NEW.attestation_id FOR SHARE;
  IF chain_record.effect_kind <> 'usdc_approval'
     OR chain_record.chain_id <> attestation_record.chain_id
     OR chain_record.signer_address <> attestation_record.custody_address
     OR chain_record.target_address <> attestation_record.usdc_address
     OR chain_record.reserved_amount_atomic <> 0
     OR NEW.spender_address <> attestation_record.jackpot_address THEN
    RAISE EXCEPTION 'Megapot USDC approval effect does not match deployment';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_megapot_usdc_approval_receipt() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  chain_record reward_chain_effects%ROWTYPE;
  approval_record megapot_usdc_approval_effects%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Megapot USDC approval receipt evidence is append-only';
  END IF;
  SELECT * INTO chain_record FROM reward_chain_effects
   WHERE effect_id = NEW.approval_effect_id FOR SHARE;
  SELECT * INTO approval_record FROM megapot_usdc_approval_effects
   WHERE approval_effect_id = NEW.approval_effect_id FOR SHARE;
  IF chain_record.state <> 'confirmed'
     OR chain_record.receipt_status <> 'success'
     OR chain_record.transaction_hash <> NEW.transaction_hash
     OR chain_record.receipt_block_number <> NEW.block_number
     OR chain_record.receipt_block_hash <> NEW.block_hash
     OR chain_record.receipt_hash <> NEW.receipt_hash
     OR chain_record.confirmations <> NEW.confirmations
     OR approval_record.attestation_id <> NEW.attestation_id
     OR approval_record.approved_amount_atomic <> NEW.approved_amount_atomic
     OR NEW.allowance_after_atomic < approval_record.minimum_allowance_atomic THEN
    RAISE EXCEPTION 'Megapot USDC approval receipt does not prove allowance';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_moderation_platform_floor_current_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  prior_revision BIGINT;
  next_revision BIGINT;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'moderation platform floor current pointer cannot be deleted';
  END IF;
  IF NEW.singleton IS DISTINCT FROM OLD.singleton THEN
    RAISE EXCEPTION 'moderation platform floor current identity is immutable';
  END IF;
  IF NEW.updated_at <= OLD.updated_at THEN
    RAISE EXCEPTION 'moderation platform floor current timestamp must advance';
  END IF;

  SELECT revision INTO prior_revision
    FROM moderation_platform_floor_revisions
   WHERE policy_revision_id = OLD.policy_revision_id
     AND policy_hash = OLD.policy_hash;
  SELECT revision INTO next_revision
    FROM moderation_platform_floor_revisions
   WHERE policy_revision_id = NEW.policy_revision_id
     AND policy_hash = NEW.policy_hash;
  IF prior_revision IS NULL OR next_revision IS NULL OR next_revision <= prior_revision THEN
    RAISE EXCEPTION 'moderation platform floor current revision must advance';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_namespace_ownership_completion_attempt_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  session_record namespace_ownership_sessions%ROWTYPE;
  intent_record community_creation_intents%ROWTYPE;
  state_record community_creation_requirement_states%ROWTYPE;
  transition_at TIMESTAMPTZ;
BEGIN
  transition_at := clock_timestamp();
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'namespace ownership completion attempts are append-only';
  END IF;

  IF TG_OP = 'INSERT' THEN
    NEW.created_at := transition_at;
    NEW.updated_at := transition_at;
    PERFORM 1 FROM users WHERE user_id = NEW.actor_id FOR SHARE;
    SELECT ci.* INTO intent_record
      FROM community_creation_intents AS ci
     WHERE ci.actor_id = NEW.actor_id
       AND ci.intent_id = (
         SELECT ns0.creation_intent_id
           FROM namespace_ownership_sessions AS ns0
          WHERE ns0.namespace_session_id = NEW.namespace_session_id
            AND ns0.actor_id = NEW.actor_id
       )
     FOR SHARE;
    SELECT crs.* INTO state_record
      FROM community_creation_requirement_states AS crs
     WHERE crs.actor_id = NEW.actor_id
       AND crs.intent_id = intent_record.intent_id
       AND crs.requirement_kind = 'namespace_ownership'
     FOR SHARE;
    SELECT ns.* INTO session_record
      FROM namespace_ownership_sessions AS ns
     WHERE ns.namespace_session_id = NEW.namespace_session_id
       AND ns.actor_id = NEW.actor_id
     FOR UPDATE;
    IF session_record.namespace_session_id IS NULL
      OR intent_record.intent_id IS NULL
      OR state_record.intent_id IS NULL
      OR session_record.status <> 'pending'
      OR session_record.expires_at <= transition_at
      OR NEW.state <> 'leased'
      OR NEW.consumption_kind IS NOT NULL
      OR NEW.fence_token <> 1
      OR NEW.lease_expires_at <= transition_at
    THEN
      RAISE EXCEPTION 'namespace ownership completion attempt requires a live pending session';
    END IF;
    IF NEW.lease_expires_at > session_record.expires_at THEN
      RAISE EXCEPTION 'completion lease exceeds its namespace session expiry';
    END IF;
    RETURN NEW;
  END IF;

  IF ROW(
    NEW.completion_attempt_id, NEW.namespace_session_id, NEW.actor_id,
    NEW.idempotency_key, NEW.completion_request_hash, NEW.evidence_ref,
    NEW.submission_channel, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.completion_attempt_id, OLD.namespace_session_id, OLD.actor_id,
    OLD.idempotency_key, OLD.completion_request_hash, OLD.evidence_ref,
    OLD.submission_channel, OLD.created_at
  ) THEN
    RAISE EXCEPTION 'namespace ownership completion attempt identity is immutable';
  END IF;

  IF OLD.state = NEW.state
    AND OLD.fence_token = NEW.fence_token
    AND OLD.lease_expires_at = NEW.lease_expires_at
    AND OLD.consumption_kind IS NOT DISTINCT FROM NEW.consumption_kind
    AND OLD.updated_at = NEW.updated_at
  THEN
    RETURN NEW;
  END IF;

  SELECT * INTO session_record
    FROM namespace_ownership_sessions
   WHERE namespace_session_id = NEW.namespace_session_id
     AND actor_id = NEW.actor_id;
  IF session_record.namespace_session_id IS NULL
    OR session_record.status NOT IN ('pending', 'expired')
  THEN
    RAISE EXCEPTION 'completion attempt requires its pending or expired session';
  END IF;

  IF OLD.state = 'leased'
    AND NEW.state = 'released'
    AND NEW.fence_token = OLD.fence_token
    AND NEW.lease_expires_at = OLD.lease_expires_at
    AND NEW.consumption_kind IS NULL
  THEN
    IF session_record.status = 'pending'
      AND session_record.expires_at > transition_at
    THEN
      NEW.updated_at := transition_at;
      RETURN NEW;
    END IF;
    RETURN NULL;
  END IF;

  IF OLD.state = 'leased'
    AND NEW.state = 'consumed'
    AND NEW.fence_token = OLD.fence_token
    AND NEW.lease_expires_at = OLD.lease_expires_at
    AND OLD.consumption_kind IS NULL
  THEN
    IF NEW.consumption_kind IN ('semantic_contradiction', 'verified', 'rejected') THEN
      IF session_record.status = 'pending'
        AND OLD.lease_expires_at > transition_at
        AND session_record.expires_at > transition_at
      THEN
        NEW.updated_at := transition_at;
        RETURN NEW;
      END IF;
      RETURN NULL;
    END IF;
    IF NEW.consumption_kind = 'expired' THEN
      IF session_record.status IN ('pending', 'expired')
        AND session_record.expires_at <= transition_at
      THEN
        NEW.updated_at := transition_at;
        RETURN NEW;
      END IF;
      RETURN NULL;
    END IF;
  END IF;

  IF OLD.state IN ('released', 'leased')
    AND NEW.state = 'leased'
    AND NEW.fence_token = OLD.fence_token + 1
    AND NEW.lease_expires_at <= session_record.expires_at
    AND NEW.consumption_kind IS NULL
  THEN
    IF session_record.status = 'pending'
      AND session_record.expires_at > transition_at
      AND NEW.lease_expires_at > transition_at
      AND (
        OLD.state = 'released'
        OR OLD.lease_expires_at <= transition_at
      )
    THEN
      NEW.updated_at := transition_at;
      RETURN NEW;
    END IF;
    RETURN NULL;
  END IF;

  RAISE EXCEPTION 'namespace ownership completion attempt transition is not allowed: % -> %',
    OLD.state, NEW.state;
END;
$$;

CREATE FUNCTION guard_namespace_ownership_session_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'namespace ownership sessions are append-only';
  END IF;

  IF ROW(
    NEW.namespace_session_id, NEW.actor_id, NEW.creation_intent_id,
    NEW.ceremony_intent_id, NEW.start_reservation_id, NEW.start_fence_token,
    NEW.expected_revision, NEW.requirement_kind, NEW.generation,
    NEW.requirement_hash, NEW.request_hash, NEW.provider_id,
    NEW.provider_binding_hash, NEW.provider_configuration_kind,
    NEW.provider_configuration_ref, NEW.provider_configuration_version,
    NEW.protocol_version, NEW.environment, NEW.route_family,
    NEW.route_root_label, NEW.route_root_label_display, NEW.route_path_segment,
    NEW.route_href, NEW.route_app_host, NEW.upstream_session_ref,
    NEW.presentation_kind, NEW.presentation_payload, NEW.started_at, NEW.expires_at,
    NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.namespace_session_id, OLD.actor_id, OLD.creation_intent_id,
    OLD.ceremony_intent_id, OLD.start_reservation_id, OLD.start_fence_token,
    OLD.expected_revision, OLD.requirement_kind, OLD.generation,
    OLD.requirement_hash, OLD.request_hash, OLD.provider_id,
    OLD.provider_binding_hash, OLD.provider_configuration_kind,
    OLD.provider_configuration_ref, OLD.provider_configuration_version,
    OLD.protocol_version, OLD.environment, OLD.route_family,
    OLD.route_root_label, OLD.route_root_label_display, OLD.route_path_segment,
    OLD.route_href, OLD.route_app_host, OLD.upstream_session_ref,
    OLD.presentation_kind, OLD.presentation_payload, OLD.started_at, OLD.expires_at,
    OLD.created_at
  ) THEN
    RAISE EXCEPTION 'namespace ownership session identity and launch fields are immutable';
  END IF;

  IF NOT (
    OLD.status = 'pending'
    AND NEW.status IN ('completed', 'failed', 'expired')
    AND NEW.generation = OLD.generation
  ) THEN
    RAISE EXCEPTION 'namespace ownership session transition is not allowed: % -> %',
      OLD.status, NEW.status;
  END IF;

  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_namespace_ownership_start_reservation_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  intent_record community_creation_intents%ROWTYPE;
  state_record community_creation_requirement_states%ROWTYPE;
  ceremony_record community_creation_ceremony_attempts%ROWTYPE;
  session_record namespace_ownership_sessions%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'namespace ownership start reservations are append-only';
  END IF;

  IF TG_OP = 'INSERT' THEN
    -- Lock order: actor -> intent -> requirement state -> start reservation.
    PERFORM 1 FROM users WHERE user_id = NEW.actor_id FOR SHARE;
    SELECT * INTO intent_record
      FROM community_creation_intents
     WHERE actor_id = NEW.actor_id AND intent_id = NEW.creation_intent_id
     FOR SHARE;
    SELECT * INTO state_record
      FROM community_creation_requirement_states
     WHERE actor_id = NEW.actor_id
       AND intent_id = NEW.creation_intent_id
       AND requirement_kind = NEW.requirement_kind
     FOR UPDATE;
    SELECT * INTO ceremony_record
      FROM community_creation_ceremony_attempts
     WHERE actor_id = NEW.actor_id
       AND intent_id = NEW.creation_intent_id
       AND requirement_kind = NEW.requirement_kind
       AND generation = NEW.generation
       AND ceremony_intent_id = NEW.ceremony_intent_id
     FOR SHARE;
    SELECT * INTO session_record
      FROM namespace_ownership_sessions
     WHERE namespace_session_id = NEW.namespace_session_id
       AND actor_id = NEW.actor_id
     FOR SHARE;

    IF intent_record.intent_id IS NULL
      OR state_record.intent_id IS NULL
      OR ceremony_record.ceremony_intent_id IS NULL
      OR state_record.status <> 'pending'
      OR intent_record.revision <> NEW.expected_revision
      OR state_record.current_ceremony_intent_id <> NEW.ceremony_intent_id
      OR state_record.generation <> NEW.generation
      OR state_record.requirement_hash <> NEW.requirement_hash
      OR state_record.provider_id <> NEW.provider_id
      OR state_record.provider_binding_hash <> NEW.provider_binding_hash
      OR state_record.provider_configuration_kind <> NEW.provider_configuration_kind
      OR state_record.provider_configuration_ref <> NEW.provider_configuration_ref
      OR state_record.provider_configuration_version <> NEW.provider_configuration_version
      OR state_record.route_family <> NEW.route_family
      OR state_record.route_root_label <> NEW.route_root_label
      OR state_record.route_root_label_display <> NEW.route_root_label_display
      OR state_record.route_path_segment <> NEW.route_path_segment
      OR ceremony_record.requirement_hash <> NEW.requirement_hash
      OR ceremony_record.provider_id <> NEW.provider_id
      OR ceremony_record.provider_binding_hash <> NEW.provider_binding_hash
      OR ceremony_record.provider_configuration_kind <> NEW.provider_configuration_kind
      OR ceremony_record.provider_configuration_ref <> NEW.provider_configuration_ref
      OR ceremony_record.provider_configuration_version <> NEW.provider_configuration_version
      OR ceremony_record.route_family IS DISTINCT FROM NEW.route_family
      OR ceremony_record.route_root_label IS DISTINCT FROM NEW.route_root_label
      OR ceremony_record.route_root_label_display IS DISTINCT FROM NEW.route_root_label_display
      OR ceremony_record.route_path_segment IS DISTINCT FROM NEW.route_path_segment
      OR NEW.state <> 'acquired'
      OR NEW.fence_token <> 1
      OR NEW.lease_expires_at <= clock_timestamp()
      OR (
        session_record.namespace_session_id IS NOT NULL
        AND NEW.lease_expires_at > session_record.expires_at
      )
    THEN
      RAISE EXCEPTION 'namespace ownership start reservation does not match its ceremony';
    END IF;

    IF session_record.namespace_session_id IS NOT NULL
      AND (
        session_record.start_reservation_id <> NEW.reservation_id
        OR session_record.start_fence_token <> NEW.fence_token
        OR session_record.expected_revision <> NEW.expected_revision
        OR session_record.requirement_hash <> NEW.requirement_hash
        OR session_record.request_hash <> NEW.request_hash
        OR session_record.provider_id <> NEW.provider_id
        OR session_record.provider_binding_hash <> NEW.provider_binding_hash
        OR session_record.provider_configuration_kind <> NEW.provider_configuration_kind
        OR session_record.provider_configuration_ref <> NEW.provider_configuration_ref
        OR session_record.provider_configuration_version <> NEW.provider_configuration_version
        OR session_record.protocol_version <> NEW.protocol_version
        OR session_record.environment <> NEW.environment
        OR session_record.route_family <> NEW.route_family
        OR session_record.route_root_label <> NEW.route_root_label
        OR session_record.route_root_label_display <> NEW.route_root_label_display
        OR session_record.route_path_segment <> NEW.route_path_segment
        OR session_record.route_href <> NEW.route_href
        OR session_record.route_app_host IS DISTINCT FROM NEW.route_app_host
      )
    THEN
      RAISE EXCEPTION 'namespace ownership start reservation does not match its session';
    END IF;
    RETURN NEW;
  END IF;

  IF ROW(
    NEW.reservation_id, NEW.namespace_session_id, NEW.actor_id,
    NEW.creation_intent_id, NEW.ceremony_intent_id, NEW.requirement_kind,
    NEW.generation, NEW.requirement_hash, NEW.expected_revision,
    NEW.client_idempotency_key, NEW.request_hash, NEW.provider_id,
    NEW.provider_binding_hash, NEW.provider_configuration_kind,
    NEW.provider_configuration_ref, NEW.provider_configuration_version,
    NEW.protocol_version, NEW.environment, NEW.route_family,
    NEW.route_root_label, NEW.route_root_label_display, NEW.route_path_segment,
    NEW.route_href, NEW.route_app_host, NEW.created_at
  ) IS DISTINCT FROM ROW(
    OLD.reservation_id, OLD.namespace_session_id, OLD.actor_id,
    OLD.creation_intent_id, OLD.ceremony_intent_id, OLD.requirement_kind,
    OLD.generation, OLD.requirement_hash, OLD.expected_revision,
    OLD.client_idempotency_key, OLD.request_hash, OLD.provider_id,
    OLD.provider_binding_hash, OLD.provider_configuration_kind,
    OLD.provider_configuration_ref, OLD.provider_configuration_version,
    OLD.protocol_version, OLD.environment, OLD.route_family,
    OLD.route_root_label, OLD.route_root_label_display, OLD.route_path_segment,
    OLD.route_href, OLD.route_app_host, OLD.created_at
  ) THEN
    RAISE EXCEPTION 'namespace ownership start reservation authority is immutable';
  END IF;

  IF OLD.state = NEW.state
    AND OLD.fence_token = NEW.fence_token
    AND OLD.lease_expires_at = NEW.lease_expires_at
  THEN
    RETURN NEW;
  END IF;

  SELECT * INTO session_record
    FROM namespace_ownership_sessions
   WHERE namespace_session_id = NEW.namespace_session_id
     AND actor_id = NEW.actor_id
   FOR SHARE;
  IF session_record.namespace_session_id IS NOT NULL
    AND NEW.lease_expires_at > session_record.expires_at
  THEN
    RAISE EXCEPTION 'namespace ownership start lease exceeds its session expiry';
  END IF;

  IF OLD.state = 'acquired'
    AND NEW.state IN ('released', 'finalized')
    AND NEW.fence_token = OLD.fence_token
    AND NEW.lease_expires_at > clock_timestamp()
  THEN
    RETURN NEW;
  END IF;

  IF OLD.state = 'released'
    AND NEW.state = 'acquired'
    AND NEW.fence_token = OLD.fence_token + 1
    AND NEW.lease_expires_at > clock_timestamp()
  THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'namespace ownership start reservation transition is not allowed: % -> %',
    OLD.state, NEW.state;
END;
$$;

CREATE FUNCTION guard_operator_managed_root_registry_current_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'operator-managed root registry current authority cannot be deleted';
  END IF;
  IF NEW.registry_kind <> OLD.registry_kind
    OR NEW.activated_at < OLD.activated_at THEN
    RAISE EXCEPTION 'operator-managed root registry current identity is invalid';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM operator_managed_route_activations AS activation
     WHERE activation.status = 'active'
       AND NOT operator_managed_registry_has_active_root(
         NEW.registry_reference,
         NEW.registry_version,
         NEW.registry_digest,
         activation.canonical_root
       )
  ) THEN
    RAISE EXCEPTION 'current operator-managed registry cannot remove an active route';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_operator_managed_route_activation_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'operator-managed route activations are retained';
  END IF;
  IF ROW(
    NEW.operator_route_activation_id,
    NEW.community_id,
    NEW.route_binding_id,
    NEW.family,
    NEW.canonical_root,
    NEW.operator_principal_id,
    NEW.operator_authority_grant_id,
    NEW.operator_managed_root_registry_reference,
    NEW.operator_managed_root_registry_version,
    NEW.operator_managed_root_registry_digest,
    NEW.activated_at
  ) IS DISTINCT FROM ROW(
    OLD.operator_route_activation_id,
    OLD.community_id,
    OLD.route_binding_id,
    OLD.family,
    OLD.canonical_root,
    OLD.operator_principal_id,
    OLD.operator_authority_grant_id,
    OLD.operator_managed_root_registry_reference,
    OLD.operator_managed_root_registry_version,
    OLD.operator_managed_root_registry_digest,
    OLD.activated_at
  ) THEN
    RAISE EXCEPTION 'operator-managed route activation identity is immutable';
  END IF;
  IF OLD.status = 'revoked' THEN
    RAISE EXCEPTION 'revoked operator-managed route activation is terminal';
  END IF;
  IF NEW.status <> 'revoked'
    OR NEW.operator_route_activation_generation <> OLD.operator_route_activation_generation + 1 THEN
    RAISE EXCEPTION 'operator-managed route revocation must advance exactly once';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_persona_activity_presentation() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'activity presentation selection cannot be deleted';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    NEW.community_id IS DISTINCT FROM OLD.community_id
    OR NEW.account_id IS DISTINCT FROM OLD.account_id
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
    OR NEW.updated_at < OLD.updated_at
  ) THEN
    RAISE EXCEPTION 'activity presentation identity is immutable';
  END IF;
  RETURN NEW;
END
$$;

