CREATE FUNCTION guard_song_rating_lowering_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF OLD.resulting_content_rating = 'adult_18'
     AND NEW.resulting_content_rating IS DISTINCT FROM 'adult_18' THEN
    RAISE EXCEPTION 'song content rating cannot be lowered';
  END IF;
  IF NEW.author_declared_rating = 'adult_18'
     AND NEW.resulting_content_rating IS DISTINCT FROM 'adult_18' THEN
    RAISE EXCEPTION 'adult author declaration cannot resolve as general';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_song_reward_bundle_claim() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  qualification_record activity_qualifications%ROWTYPE;
  offer_record song_reward_offers%ROWTYPE;
  eligibility_record reward_eligibility_decisions%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'song reward bundle claims are append-only';
  END IF;
  SELECT * INTO qualification_record FROM activity_qualifications
   WHERE qualification_id = NEW.qualification_id FOR SHARE;
  SELECT * INTO offer_record FROM song_reward_offers
   WHERE offer_id = NEW.offer_id FOR SHARE;
  SELECT * INTO eligibility_record FROM reward_eligibility_decisions
   WHERE eligibility_decision_id = NEW.eligibility_decision_id FOR SHARE;
  IF qualification_record.qualification_id IS NULL
     OR offer_record.offer_id IS NULL
     OR qualification_record.account_id <> NEW.account_id
     OR qualification_record.persona_id <> NEW.persona_id
     OR qualification_record.community_id <> offer_record.community_id
     OR qualification_record.post_id <> offer_record.post_id
     OR qualification_record.audio_revision <> offer_record.audio_revision
     OR qualification_record.qualified_at < offer_record.starts_at
     OR qualification_record.qualified_at >= offer_record.ends_at
     OR eligibility_record.account_id <> NEW.account_id
     OR eligibility_record.persona_id <> NEW.persona_id
     OR eligibility_record.qualification_id <> NEW.qualification_id
     OR eligibility_record.purpose <> 'asset_claim'
     OR eligibility_record.drawing_id IS NOT NULL
     OR eligibility_record.expires_at <= NEW.created_at
     OR (NEW.state = 'credited' AND eligibility_record.outcome <> 'eligible')
     OR (NEW.state = 'ineligible' AND eligibility_record.outcome <> 'ineligible')
     OR NEW.state = 'reserved' THEN
    RAISE EXCEPTION 'song reward bundle claim is not exact qualification output';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_song_reward_bundle_claim_leg() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  claim_record song_reward_bundle_claims%ROWTYPE;
  leg_record song_reward_offer_legs%ROWTYPE;
  credit_record reward_ledger_credits%ROWTYPE;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'song reward bundle claim legs are append-only';
  END IF;
  SELECT * INTO claim_record FROM song_reward_bundle_claims
   WHERE account_id = NEW.account_id AND offer_id = NEW.offer_id FOR SHARE;
  SELECT * INTO leg_record FROM song_reward_offer_legs
   WHERE leg_id = NEW.leg_id FOR SHARE;
  IF claim_record.account_id IS NULL OR leg_record.leg_id IS NULL
     OR leg_record.offer_id <> NEW.offer_id OR leg_record.kind <> 'asset_bonus'
     OR NEW.amount_atomic <> leg_record.amount_per_claim_atomic
     OR (claim_record.state = 'credited' AND NEW.state <> 'credited')
     OR (claim_record.state = 'ineligible' AND NEW.state <> 'unavailable') THEN
    RAISE EXCEPTION 'song reward bundle claim leg is not exact';
  END IF;
  IF NEW.state = 'credited' THEN
    SELECT * INTO credit_record FROM reward_ledger_credits
     WHERE credit_id = NEW.credit_id FOR SHARE;
    IF credit_record.credit_id IS NULL
       OR credit_record.account_id <> NEW.account_id
       OR credit_record.payout_persona_id <> claim_record.persona_id
       OR credit_record.chain_id <> leg_record.chain_id
       OR credit_record.token_address <> leg_record.token_address
       OR credit_record.amount_atomic <> NEW.amount_atomic
       OR credit_record.source_kind <> 'asset_bonus'
       OR credit_record.source_reference <>
          (NEW.leg_id || ':' || claim_record.qualification_id) THEN
      RAISE EXCEPTION 'song reward bundle claim leg lacks exact credit';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_song_reward_funding_effect() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  leg_record song_reward_offer_legs%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'song reward funding effects cannot be deleted';
  END IF;
  SELECT * INTO leg_record FROM song_reward_offer_legs
   WHERE leg_id = NEW.leg_id FOR SHARE;
  IF leg_record.leg_id IS NULL OR NEW.chain_id <> leg_record.chain_id
     OR NEW.token_address <> leg_record.token_address THEN
    RAISE EXCEPTION 'song reward funding asset does not match leg';
  END IF;
  IF leg_record.kind = 'megapot_pool'
     AND leg_record.empty_pool_policy = 'funder_fallback'
     AND NEW.funder_account_id <> leg_record.funder_account_id THEN
    RAISE EXCEPTION 'fallback_sponsor_mismatch';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF ROW(
      NEW.funding_effect_id, NEW.leg_id, NEW.funder_account_id, NEW.chain_id,
      NEW.token_address, NEW.sender_address, NEW.recipient_address,
      NEW.expected_amount_atomic, NEW.required_confirmations, NEW.created_at
    ) IS DISTINCT FROM ROW(
      OLD.funding_effect_id, OLD.leg_id, OLD.funder_account_id, OLD.chain_id,
      OLD.token_address, OLD.sender_address, OLD.recipient_address,
      OLD.expected_amount_atomic, OLD.required_confirmations, OLD.created_at
    ) THEN
      RAISE EXCEPTION 'song reward funding identity is immutable';
    END IF;
    IF NOT (
      NEW.state = OLD.state
      OR (OLD.state = 'planned' AND NEW.state IN (
        'confirming', 'reclaimable_failed', 'reconciliation_required'
      ))
      OR (OLD.state = 'confirming' AND NEW.state IN (
        'confirmed', 'reverted', 'reclaimable_failed', 'reconciliation_required'
      ))
      OR (OLD.state = 'reconciliation_required' AND NEW.state IN (
        'confirming', 'confirmed', 'reverted'
      ))
    ) THEN
      RAISE EXCEPTION 'invalid song reward funding transition';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_song_reward_offer() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  post_record posts%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'song reward offers cannot be deleted';
  END IF;
  SELECT * INTO post_record FROM posts
   WHERE community_id = NEW.community_id AND post_id = NEW.post_id FOR SHARE;
  IF post_record.post_id IS NULL OR post_record.post_type <> 'song'
     OR NOT EXISTS (
       SELECT 1 FROM media_publication_projections publication
        WHERE publication.community_id = NEW.community_id
          AND publication.post_id = NEW.post_id
          AND publication.audio_revision = NEW.audio_revision
     ) THEN
    RAISE EXCEPTION 'song reward offer requires exact published song revision';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.status <> 'draft' THEN
    RAISE EXCEPTION 'song reward offer must begin as draft';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF ROW(
      NEW.offer_id, NEW.community_id, NEW.post_id, NEW.audio_revision,
      NEW.created_by_account_id, NEW.starts_at, NEW.ends_at,
      NEW.owner_policy_snapshot, NEW.terms_hash, NEW.created_at
    ) IS DISTINCT FROM ROW(
      OLD.offer_id, OLD.community_id, OLD.post_id, OLD.audio_revision,
      OLD.created_by_account_id, OLD.starts_at, OLD.ends_at,
      OLD.owner_policy_snapshot, OLD.terms_hash, OLD.created_at
    ) THEN
      RAISE EXCEPTION 'song reward offer terms are immutable';
    END IF;
    IF OLD.status IN ('exhausted', 'expired', 'ended') AND NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'terminal song reward offer is immutable';
    END IF;
    IF NOT (
      NEW.status = OLD.status
      OR (OLD.status = 'draft' AND NEW.status IN ('active', 'ended'))
      OR (OLD.status = 'active' AND NEW.status IN (
        'paused', 'exhausted', 'expired', 'ended', 'operational_hold'
      ))
      OR (OLD.status = 'paused' AND NEW.status IN ('active', 'expired', 'ended', 'operational_hold'))
      OR (OLD.status = 'operational_hold' AND NEW.status IN ('active', 'ended'))
    ) THEN
      RAISE EXCEPTION 'invalid song reward offer transition';
    END IF;
    IF NEW.status <> OLD.status AND NEW.updated_at <= OLD.updated_at THEN
      RAISE EXCEPTION 'song reward offer transition time must advance';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_song_reward_offer_action() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'song reward offer actions are append-only';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM song_reward_offers offer
     WHERE offer.offer_id = NEW.offer_id
       AND offer.created_by_account_id = CASE
         WHEN NEW.endpoint_template = '/communities/:communityId/posts/:postId/reward-offers'
         THEN NEW.account_id
         ELSE offer.created_by_account_id
       END
  ) OR (NEW.leg_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM song_reward_offer_legs leg
     WHERE leg.leg_id = NEW.leg_id AND leg.offer_id = NEW.offer_id
  )) OR (NEW.funding_effect_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM song_reward_leg_funding_effects funding
     WHERE funding.funding_effect_id = NEW.funding_effect_id
       AND funding.leg_id = NEW.leg_id
       AND funding.funder_account_id = NEW.account_id
  )) THEN
    RAISE EXCEPTION 'song reward offer action result is not exact';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_song_reward_offer_leg() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  offer_record song_reward_offers%ROWTYPE;
  attestation_record megapot_deployment_attestations%ROWTYPE;
  activity TEXT;
  confirmed_refund_total NUMERIC(78, 0);
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'song reward offer legs cannot be deleted';
  END IF;
  SELECT * INTO offer_record FROM song_reward_offers
   WHERE offer_id = NEW.offer_id FOR SHARE;
  IF offer_record.offer_id IS NULL THEN
    RAISE EXCEPTION 'song reward offer leg requires offer';
  END IF;
  IF TG_OP = 'INSERT' AND NEW.status <> 'draft' THEN
    RAISE EXCEPTION 'song reward offer leg must begin as draft';
  END IF;
  IF NEW.kind = 'megapot_pool' THEN
    SELECT * INTO attestation_record FROM megapot_deployment_attestations
     WHERE attestation_id = NEW.attestation_id FOR SHARE;
    IF attestation_record.attestation_id IS NULL
       OR attestation_record.chain_id <> NEW.chain_id
       OR attestation_record.usdc_address <> NEW.token_address
       OR attestation_record.status <> 'active' THEN
      RAISE EXCEPTION 'Megapot pool leg requires active exact deployment attestation';
    END IF;
    FOREACH activity IN ARRAY NEW.eligible_activities
    LOOP
      IF NOT EXISTS (
        SELECT 1 FROM activity_registry registry
         WHERE registry.activity_key = activity AND registry.status = 'active'
      ) THEN
        RAISE EXCEPTION 'Megapot pool leg activity is not active';
      END IF;
    END LOOP;
    IF NEW.status = 'active' THEN
      IF offer_record.status <> 'active' THEN
        RAISE EXCEPTION 'Megapot pool leg requires active offer';
      END IF;
      IF attestation_record.environment = 'production'
         AND NEW.legal_activation_gate <> 'production_approved' THEN
        RAISE EXCEPTION 'production Megapot pool activation is not legally approved';
      END IF;
      IF NEW.empty_pool_policy = 'funder_fallback'
         AND NEW.funding_source = 'leg_budget' THEN
        IF NOT EXISTS (
          SELECT 1 FROM posts post
           WHERE post.community_id = offer_record.community_id
             AND post.post_id = offer_record.post_id
             AND post.post_type = 'song' AND post.status = 'published'
             AND post.visibility = 'public'
        ) THEN
          RAISE EXCEPTION 'external fallback requires discoverable song';
        END IF;
        FOREACH activity IN ARRAY NEW.eligible_activities
        LOOP
          IF NOT EXISTS (
            SELECT 1 FROM reward_activity_availability_observations availability
             WHERE availability.community_id = offer_record.community_id
               AND availability.post_id = offer_record.post_id
               AND availability.audio_revision = offer_record.audio_revision
               AND availability.activity_key = activity
               AND availability.state = 'available'
               AND availability.expires_at > clock_timestamp()
          ) THEN
            RAISE EXCEPTION 'external fallback activity is unavailable';
          END IF;
        END LOOP;
      END IF;
    END IF;
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF ROW(
      NEW.leg_id, NEW.offer_id, NEW.kind, NEW.funder_account_id, NEW.refund_policy,
      NEW.leg_terms_hash, NEW.participation_starts_at, NEW.chain_id, NEW.token_address,
      NEW.token_decimals, NEW.amount_per_claim_atomic, NEW.max_claims,
      NEW.tickets_per_drawing, NEW.max_ticket_price_atomic, NEW.entry_cutoff_seconds,
      NEW.beneficiary_algorithm_version, NEW.ticket_selection_version, NEW.attestation_id,
      NEW.participation_starts_drawing_id, NEW.eligible_activities, NEW.min_score_bps,
      NEW.empty_pool_policy, NEW.funding_source, NEW.fallback_beneficiary_account_id,
      NEW.fallback_payout_persona_id, NEW.referral_allocation_version,
      NEW.referral_policy_hash, NEW.referral_disclosed_at, NEW.legal_activation_gate,
      NEW.created_at
    ) IS DISTINCT FROM ROW(
      OLD.leg_id, OLD.offer_id, OLD.kind, OLD.funder_account_id, OLD.refund_policy,
      OLD.leg_terms_hash, OLD.participation_starts_at, OLD.chain_id, OLD.token_address,
      OLD.token_decimals, OLD.amount_per_claim_atomic, OLD.max_claims,
      OLD.tickets_per_drawing, OLD.max_ticket_price_atomic, OLD.entry_cutoff_seconds,
      OLD.beneficiary_algorithm_version, OLD.ticket_selection_version, OLD.attestation_id,
      OLD.participation_starts_drawing_id, OLD.eligible_activities, OLD.min_score_bps,
      OLD.empty_pool_policy, OLD.funding_source, OLD.fallback_beneficiary_account_id,
      OLD.fallback_payout_persona_id, OLD.referral_allocation_version,
      OLD.referral_policy_hash, OLD.referral_disclosed_at, OLD.legal_activation_gate,
      OLD.created_at
    ) THEN
      RAISE EXCEPTION 'song reward offer leg terms are immutable';
    END IF;
    IF NEW.funded_atomic < OLD.funded_atomic OR NEW.reserved_atomic < 0
       OR NEW.spent_atomic < OLD.spent_atomic OR NEW.fulfilled_atomic < OLD.fulfilled_atomic
       OR NEW.refunded_atomic < OLD.refunded_atomic THEN
      RAISE EXCEPTION 'song reward offer leg accounting cannot reverse';
    END IF;
    IF NEW.refunded_atomic > OLD.refunded_atomic THEN
      SELECT COALESCE(sum(refund.amount_atomic), 0) INTO confirmed_refund_total
        FROM reward_refund_effects refund
        JOIN reward_erc20_transfer_receipt_evidence receipt
          ON receipt.effect_id=refund.refund_effect_id
       WHERE refund.leg_id=NEW.leg_id AND receipt.transfer_purpose='reward_refund';
      IF NEW.refunded_atomic <> confirmed_refund_total THEN
        RAISE EXCEPTION 'song reward offer leg refund accounting requires exact receipts';
      END IF;
    END IF;
    IF OLD.status IN ('exhausted', 'ended') AND (
      ROW(
        NEW.status, NEW.funded_atomic, NEW.reserved_atomic, NEW.spent_atomic,
        NEW.fulfilled_atomic, NEW.participation_ends_at, NEW.activated_at
      ) IS DISTINCT FROM ROW(
        OLD.status, OLD.funded_atomic, OLD.reserved_atomic, OLD.spent_atomic,
        OLD.fulfilled_atomic, OLD.participation_ends_at, OLD.activated_at
      )
      OR NEW.refunded_atomic < OLD.refunded_atomic
    ) THEN
      RAISE EXCEPTION 'terminal song reward offer leg only permits refund settlement';
    END IF;
    IF NOT (
      NEW.status = OLD.status
      OR (OLD.status = 'draft' AND NEW.status IN ('funding', 'active', 'ended'))
      OR (OLD.status = 'funding' AND NEW.status IN ('active', 'ended', 'operational_hold'))
      OR (OLD.status = 'active' AND NEW.status IN (
        'paused', 'exhausted', 'ended', 'operational_hold'
      ))
      OR (OLD.status = 'paused' AND NEW.status IN ('active', 'ended', 'operational_hold'))
      OR (OLD.status = 'operational_hold' AND NEW.status IN ('active', 'ended'))
    ) THEN
      RAISE EXCEPTION 'invalid song reward offer leg transition';
    END IF;
    IF NEW.updated_at < OLD.updated_at THEN
      RAISE EXCEPTION 'song reward offer leg update time cannot reverse';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_song_streak_day_activity() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'song streak day activity rows cannot be deleted';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    ROW(NEW.account_id, NEW.community_id, NEW.post_id, NEW.streak_day,
      NEW.activity_key, NEW.first_qualified_at)
    IS DISTINCT FROM
    ROW(OLD.account_id, OLD.community_id, OLD.post_id, OLD.streak_day,
      OLD.activity_key, OLD.first_qualified_at)
    OR NEW.qualification_count <> OLD.qualification_count + 1
    OR NEW.last_qualified_at < OLD.last_qualified_at
    OR NEW.last_qualification_id IS NOT DISTINCT FROM OLD.last_qualification_id
  ) THEN
    RAISE EXCEPTION 'song streak day activity updates must append one qualification';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_sponsor_daily_totals() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'sponsor daily totals cannot be deleted';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    ROW(NEW.sponsor_account_id, NEW.sponsor_day, NEW.sponsor_kind,
      NEW.ticket_ceiling, NEW.spend_ceiling_atomic, NEW.created_at)
    IS DISTINCT FROM
    ROW(OLD.sponsor_account_id, OLD.sponsor_day, OLD.sponsor_kind,
      OLD.ticket_ceiling, OLD.spend_ceiling_atomic, OLD.created_at)
    OR NEW.reserved_ticket_count < OLD.reserved_ticket_count
    OR NEW.confirmed_ticket_count < OLD.confirmed_ticket_count
    OR NEW.released_ticket_count < OLD.released_ticket_count
    OR NEW.reserved_spend_atomic < OLD.reserved_spend_atomic
    OR NEW.confirmed_spend_atomic < OLD.confirmed_spend_atomic
    OR NEW.released_spend_atomic < OLD.released_spend_atomic
    OR NEW.updated_at <= OLD.updated_at
  ) THEN
    RAISE EXCEPTION 'invalid sponsor daily total update';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_streak_projection() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'streak projections cannot be deleted';
  END IF;
  IF TG_OP = 'UPDATE' AND NEW.recomputed_at < OLD.recomputed_at THEN
    RAISE EXCEPTION 'streak projection recompute time cannot move backward';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_study_session() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  item_count INTEGER;
  answered_count INTEGER;
  correct_count INTEGER;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Study sessions cannot be deleted';
  END IF;
  IF NOT active_owned_persona(NEW.account_id, NEW.persona_id)
     OR NOT active_community_effect(NEW.community_id, NEW.account_id)
     OR NOT EXISTS (SELECT 1 FROM pg_timezone_names WHERE name = NEW.timezone)
     OR NOT EXISTS (
       SELECT 1 FROM account_streak_clocks
        WHERE account_id = NEW.account_id AND timezone = NEW.timezone
     ) THEN
    RAISE EXCEPTION 'Study session account, persona, community, or timezone is ineligible';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM posts
     WHERE community_id = NEW.community_id AND post_id = NEW.post_id
       AND post_type = 'song' AND status = 'published' AND visibility = 'public'
  ) THEN
    RAISE EXCEPTION 'Study sessions require a public published song';
  END IF;
  IF TG_OP = 'UPDATE' THEN
    IF ROW(
      NEW.session_id, NEW.account_id, NEW.persona_id, NEW.community_id, NEW.post_id,
      NEW.audio_revision, NEW.lyrics_revision, NEW.source_revision,
      NEW.source_producer_id, NEW.source_producer_revision, NEW.source_snapshot_hash,
      NEW.qualification_policy_version_id, NEW.endpoint_template,
      NEW.idempotency_key, NEW.request_hash, NEW.timezone,
      NEW.qualifying_exercise_count, NEW.required_correct, NEW.created_at
    ) IS DISTINCT FROM ROW(
      OLD.session_id, OLD.account_id, OLD.persona_id, OLD.community_id, OLD.post_id,
      OLD.audio_revision, OLD.lyrics_revision, OLD.source_revision,
      OLD.source_producer_id, OLD.source_producer_revision, OLD.source_snapshot_hash,
      OLD.qualification_policy_version_id, OLD.endpoint_template,
      OLD.idempotency_key, OLD.request_hash, OLD.timezone,
      OLD.qualifying_exercise_count, OLD.required_correct, OLD.created_at
    ) THEN
      RAISE EXCEPTION 'Study session authority is immutable';
    END IF;
    IF OLD.status = 'completed' AND NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'completed Study sessions are immutable';
    END IF;
    IF OLD.status = 'active' AND NEW.status = 'completed' THEN
      SELECT count(*),
             count(*) FILTER (WHERE answer_count > 0),
             count(*) FILTER (WHERE first_pass_outcome = 'correct')
        INTO item_count, answered_count, correct_count
        FROM study_session_items WHERE session_id = NEW.session_id;
      IF item_count <> NEW.qualifying_exercise_count
         OR answered_count <> NEW.answered_exercise_count
         OR correct_count <> NEW.first_pass_correct
         OR NEW.streak_day <> (NEW.completed_at AT TIME ZONE NEW.timezone)::date THEN
        RAISE EXCEPTION 'Study completion is not derived from frozen item evidence';
      END IF;
    ELSIF NEW IS DISTINCT FROM OLD THEN
      RAISE EXCEPTION 'invalid Study session transition';
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_study_session_answer() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  item_record study_session_items%ROWTYPE;
  session_record study_sessions%ROWTYPE;
  expected_outcome TEXT;
BEGIN
  IF TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION 'Study answers are append-only';
  END IF;
  SELECT * INTO session_record FROM study_sessions WHERE session_id = NEW.session_id FOR SHARE;
  SELECT * INTO item_record FROM study_session_items
   WHERE session_id = NEW.session_id AND session_item_id = NEW.session_item_id FOR SHARE;
  IF session_record.status <> 'active' OR item_record.session_item_id IS NULL THEN
    RAISE EXCEPTION 'Study answers require an active bound item';
  END IF;
  IF NEW.attempt_number <> item_record.answer_count + 1
     OR NEW.first_pass IS DISTINCT FROM (NEW.attempt_number = 1)
     OR NOT valid_study_answer_v1(NEW.answer, item_record.prompt->>'kind') THEN
    RAISE EXCEPTION 'Study answer sequence or shape is invalid';
  END IF;
  expected_outcome := CASE
    WHEN grade_study_answer_v1(NEW.answer, item_record.answer_key) THEN 'correct'
    ELSE 'incorrect'
  END;
  IF NEW.outcome <> expected_outcome THEN
    RAISE EXCEPTION 'Study answer outcome is not server-derived';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_study_session_item() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  session_record study_sessions%ROWTYPE;
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'Study session items cannot be deleted';
  END IF;
  SELECT * INTO session_record FROM study_sessions WHERE session_id = NEW.session_id FOR SHARE;
  IF session_record.session_id IS NULL OR session_record.status <> 'active' THEN
    RAISE EXCEPTION 'Study items require an active session';
  END IF;
  IF NOT valid_study_item_v1(NEW.prompt, NEW.answer_key) THEN
    RAISE EXCEPTION 'Study item prompt and answer key are invalid';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    NEW.session_id IS DISTINCT FROM OLD.session_id
    OR NEW.session_item_id IS DISTINCT FROM OLD.session_item_id
    OR NEW.ordinal IS DISTINCT FROM OLD.ordinal
    OR NEW.source_item_key IS DISTINCT FROM OLD.source_item_key
    OR NEW.prompt IS DISTINCT FROM OLD.prompt
    OR NEW.answer_key IS DISTINCT FROM OLD.answer_key
    OR NEW.presentation_count IS DISTINCT FROM OLD.presentation_count
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
    OR NEW.answer_count < OLD.answer_count
    OR (OLD.first_pass_outcome IS NOT NULL
      AND NEW.first_pass_outcome IS DISTINCT FROM OLD.first_pass_outcome)
  ) THEN
    RAISE EXCEPTION 'Study session item evidence is immutable';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION guard_text_content_submission_response_snapshot() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.response_snapshot_bytes IS DISTINCT FROM OLD.response_snapshot_bytes
    OR NEW.response_snapshot_sha256 IS DISTINCT FROM OLD.response_snapshot_sha256
  THEN
    RAISE EXCEPTION 'text content submission response snapshot is immutable';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_text_content_submission_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(
    NEW.community_id, NEW.submission_id, NEW.operation_id, NEW.actor_user_id,
    NEW.author_persona_id, NEW.surface, NEW.target_post_id,
    NEW.target_parent_comment_id, NEW.idempotency_key, NEW.request_hash,
    NEW.moderation_decision, NEW.policy_revision_id, NEW.policy_hash,
    NEW.platform_policy_revision_id, NEW.platform_policy_hash,
    NEW.community_policy_revision_id, NEW.community_policy_hash,
    NEW.input_sha256, NEW.internal_reason_codes, NEW.evidence_ref,
    NEW.created_at, NEW.response_snapshot_bytes, NEW.response_snapshot_sha256,
    NEW.author_declared_rating, NEW.matched_categories,
    NEW.category_decisions, NEW.effective_policy_decision
  ) IS DISTINCT FROM ROW(
    OLD.community_id, OLD.submission_id, OLD.operation_id, OLD.actor_user_id,
    OLD.author_persona_id, OLD.surface, OLD.target_post_id,
    OLD.target_parent_comment_id, OLD.idempotency_key, OLD.request_hash,
    OLD.moderation_decision, OLD.policy_revision_id, OLD.policy_hash,
    OLD.platform_policy_revision_id, OLD.platform_policy_hash,
    OLD.community_policy_revision_id, OLD.community_policy_hash,
    OLD.input_sha256, OLD.internal_reason_codes, OLD.evidence_ref,
    OLD.created_at, OLD.response_snapshot_bytes, OLD.response_snapshot_sha256,
    OLD.author_declared_rating, OLD.matched_categories,
    OLD.category_decisions, OLD.effective_policy_decision
  ) THEN
    RAISE EXCEPTION 'text content submission evidence and creation snapshot are immutable';
  END IF;
  IF NEW.updated_at <= OLD.updated_at THEN
    RAISE EXCEPTION 'text content submission updated_at must advance';
  END IF;
  IF OLD.status = 'published' AND NEW.status = 'published' THEN
    IF OLD.resulting_content_rating <> 'general'
      OR NEW.resulting_content_rating <> 'adult_18'
      OR ROW(NEW.public_reason_code, NEW.published_post_id,
             NEW.published_comment_id, NEW.review_ref)
         IS DISTINCT FROM
         ROW(OLD.public_reason_code, OLD.published_post_id,
             OLD.published_comment_id, OLD.review_ref) THEN
      RAISE EXCEPTION 'published text submission permits only an adult rating raise';
    END IF;
    RETURN NEW;
  END IF;
  IF OLD.status <> 'manual_review' OR NEW.status NOT IN ('published', 'blocked') THEN
    RAISE EXCEPTION 'text content submission transition is not allowed: % -> %',
      OLD.status, NEW.status;
  END IF;
  IF OLD.resulting_content_rating = 'adult_18'
    AND NEW.resulting_content_rating <> 'adult_18' THEN
    RAISE EXCEPTION 'text content submission rating cannot be lowered';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION guard_text_moderation_case_update() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF ROW(
    NEW.community_id,
    NEW.case_id,
    NEW.submission_id,
    NEW.created_at,
    NEW.platform_policy_revision_id,
    NEW.platform_policy_hash,
    NEW.community_policy_revision_id,
    NEW.community_policy_hash
  ) IS DISTINCT FROM ROW(
    OLD.community_id,
    OLD.case_id,
    OLD.submission_id,
    OLD.created_at,
    OLD.platform_policy_revision_id,
    OLD.platform_policy_hash,
    OLD.community_policy_revision_id,
    OLD.community_policy_hash
  ) THEN
    RAISE EXCEPTION 'text moderation case identity and policy evidence are immutable';
  END IF;
  IF OLD.status <> 'open' OR NEW.status NOT IN ('approved', 'dismissed', 'blocked') THEN
    RAISE EXCEPTION 'text moderation case transition is not allowed: % -> %',
      OLD.status,
      NEW.status;
  END IF;
  IF NEW.updated_at <= OLD.updated_at THEN
    RAISE EXCEPTION 'text moderation case updated_at must advance';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION has_community_handle_sales_authority(expected_community_id text, expected_principal_account_id text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM community_handle_sales_authority_grants AS authority_grant
     WHERE authority_grant.community_id = expected_community_id
       AND authority_grant.principal_account_id = expected_principal_account_id
       AND authority_grant.authority = 'manage_handle_sales'
       AND authority_grant.status = 'active'
  )
$$;

CREATE FUNCTION has_community_moderation_capability_v1(input_account_id text, input_community_id text, input_capability text) RETURNS boolean
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  SELECT input_capability IN ('moderation.view', 'moderation.act')
    AND EXISTS (
      SELECT 1
        FROM community_role_assignments AS assignment
        JOIN communities AS community
          ON community.community_id = assignment.community_id
         AND community.status = 'active'
        JOIN users AS account
          ON account.user_id = assignment.account_id
         AND account.status = 'active'
       WHERE assignment.community_id = input_community_id
         AND assignment.account_id = input_account_id
         AND assignment.role = 'owner'
         AND assignment.status = 'active'
    );
$$;

CREATE FUNCTION has_community_route_authority(expected_community_id text, expected_principal_user_id text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM community_route_authority_grants AS authority_grant
     WHERE authority_grant.community_id = expected_community_id
       AND authority_grant.principal_user_id = expected_principal_user_id
       AND authority_grant.authority = 'manage_routes'
       AND authority_grant.status = 'active'
  )
$$;

CREATE FUNCTION identity_credentials_enforce_lifecycle() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'identity credentials cannot be deleted'
      USING ERRCODE = '23514', CONSTRAINT = 'identity_credentials_delete_forbidden';
  END IF;

  IF TG_OP = 'INSERT' THEN
    IF NEW.status <> 'active' OR NEW.tombstoned_at IS NOT NULL THEN
      RAISE EXCEPTION 'identity credentials must be inserted active'
        USING ERRCODE = '23514', CONSTRAINT = 'identity_credentials_insert_active';
    END IF;
    RETURN NEW;
  END IF;

  IF NEW.credential_id IS DISTINCT FROM OLD.credential_id
    OR NEW.provider IS DISTINCT FROM OLD.provider
    OR NEW.provider_app_id IS DISTINCT FROM OLD.provider_app_id
    OR NEW.provider_subject IS DISTINCT FROM OLD.provider_subject
    OR NEW.canonical_user_id IS DISTINCT FROM OLD.canonical_user_id
    OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'identity credential ownership and identity are immutable'
      USING ERRCODE = '23514', CONSTRAINT = 'identity_credentials_identity_immutable';
  END IF;

  IF OLD.status = 'tombstoned' THEN
    RAISE EXCEPTION 'identity credential tombstones are immutable'
      USING ERRCODE = '23514', CONSTRAINT = 'identity_credentials_tombstone_terminal';
  END IF;

  IF NEW.status = 'tombstoned' THEN
    NEW.tombstoned_at := now();
  ELSIF NEW.status <> 'active' OR NEW.tombstoned_at IS NOT NULL THEN
    RAISE EXCEPTION 'invalid identity credential lifecycle transition'
      USING ERRCODE = '23514', CONSTRAINT = 'identity_credentials_lifecycle';
  END IF;

  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

CREATE FUNCTION initial_community_policy_decision_v1(input_category text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT CASE
    WHEN moderation_policy_category_ordinal_v1(input_category) IS NULL THEN NULL
    WHEN input_category = 'sexual/minors' THEN 'block'
    ELSE 'review'
  END;
$$;

CREATE FUNCTION initial_platform_floor_decision_v1(input_category text) RETURNS text
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT CASE input_category
    WHEN 'harassment' THEN 'permit'
    WHEN 'harassment/threatening' THEN 'review'
    WHEN 'hate' THEN 'review'
    WHEN 'hate/threatening' THEN 'review'
    WHEN 'illicit' THEN 'permit'
    WHEN 'illicit/violent' THEN 'review'
    WHEN 'self-harm' THEN 'permit'
    WHEN 'self-harm/intent' THEN 'review'
    WHEN 'self-harm/instructions' THEN 'review'
    WHEN 'sexual' THEN 'permit'
    WHEN 'sexual/minors' THEN 'block'
    WHEN 'violence' THEN 'permit'
    WHEN 'violence/graphic' THEN 'permit'
    ELSE NULL
  END;
$$;

CREATE FUNCTION initialize_community_moderation_policy_v1(input_community_id text, input_created_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  expected_revision_id TEXT;
  expected_preimage TEXT;
  expected_hash TEXT;
  floor_revision_id TEXT;
  floor_hash TEXT;
  persisted community_moderation_policy_revisions%ROWTYPE;
BEGIN
  SELECT current.policy_revision_id, current.policy_hash
    INTO floor_revision_id, floor_hash
    FROM moderation_platform_floor_current AS current
   WHERE current.singleton
   FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'initial community moderation policy requires a current platform floor';
  END IF;

  expected_revision_id := 'community-moderation-policy:' || input_community_id || ':r1';

  SELECT format(
    '["community-moderation-policy-v1",%s,%s,1,%s,%s,[%s]]',
    to_json(input_community_id)::text,
    to_json(expected_revision_id)::text,
    to_json(floor_revision_id)::text,
    to_json(floor_hash)::text,
    string_agg(
      format(
        '[%s,%s]',
        to_json(category)::text,
        to_json(initial_community_policy_decision_v1(category))::text
      ),
      ',' ORDER BY moderation_policy_category_ordinal_v1(category)
    )
  )
    INTO expected_preimage
    FROM (
      VALUES
        ('harassment'),
        ('harassment/threatening'),
        ('hate'),
        ('hate/threatening'),
        ('illicit'),
        ('illicit/violent'),
        ('self-harm'),
        ('self-harm/intent'),
        ('self-harm/instructions'),
        ('sexual'),
        ('sexual/minors'),
        ('violence'),
        ('violence/graphic')
    ) AS categories(category);
  expected_hash := encode(sha256(convert_to(expected_preimage, 'UTF8')), 'hex');

  INSERT INTO community_moderation_policy_revisions (
    community_id,
    policy_revision_id,
    revision,
    platform_floor_revision_id,
    platform_floor_hash,
    policy_preimage,
    policy_hash,
    created_at
  ) VALUES (
    input_community_id,
    expected_revision_id,
    1,
    floor_revision_id,
    floor_hash,
    expected_preimage,
    expected_hash,
    input_created_at
  )
  ON CONFLICT (community_id, policy_revision_id) DO NOTHING;

  SELECT *
    INTO persisted
    FROM community_moderation_policy_revisions
   WHERE community_id = input_community_id
     AND policy_revision_id = expected_revision_id;
  IF NOT FOUND
    OR persisted.revision IS DISTINCT FROM 1
    OR persisted.platform_floor_revision_id IS DISTINCT FROM floor_revision_id
    OR persisted.platform_floor_hash IS DISTINCT FROM floor_hash
    OR persisted.policy_preimage IS DISTINCT FROM expected_preimage
    OR persisted.policy_hash IS DISTINCT FROM expected_hash
    OR persisted.created_at IS DISTINCT FROM input_created_at
  THEN
    RAISE EXCEPTION 'initial community moderation policy conflicts with deterministic revision';
  END IF;

  INSERT INTO community_moderation_policy_category_decisions (
    community_id,
    policy_revision_id,
    category,
    decision
  )
  SELECT
    input_community_id,
    expected_revision_id,
    category,
    initial_community_policy_decision_v1(category)
  FROM (
    VALUES
      ('harassment'),
      ('harassment/threatening'),
      ('hate'),
      ('hate/threatening'),
      ('illicit'),
      ('illicit/violent'),
      ('self-harm'),
      ('self-harm/intent'),
      ('self-harm/instructions'),
      ('sexual'),
      ('sexual/minors'),
      ('violence'),
      ('violence/graphic')
  ) AS categories(category)
  ON CONFLICT (community_id, policy_revision_id, category) DO NOTHING;

  IF (
    SELECT count(*) = 13
      AND bool_and(decision = initial_community_policy_decision_v1(category))
      FROM community_moderation_policy_category_decisions
     WHERE community_id = input_community_id
       AND policy_revision_id = expected_revision_id
  ) IS NOT TRUE THEN
    RAISE EXCEPTION 'initial community moderation policy category conflict';
  END IF;

  INSERT INTO community_moderation_policy_current (
    community_id,
    policy_revision_id,
    policy_hash,
    updated_at
  ) VALUES (
    input_community_id,
    expected_revision_id,
    expected_hash,
    input_created_at
  )
  ON CONFLICT (community_id) DO NOTHING;

  IF NOT EXISTS (
    SELECT 1
      FROM community_moderation_policy_current
     WHERE community_id = input_community_id
       AND policy_revision_id = expected_revision_id
       AND policy_hash = expected_hash
       AND updated_at = input_created_at
  ) THEN
    RAISE EXCEPTION 'initial community moderation policy current pointer conflict';
  END IF;
END;
$$;

CREATE FUNCTION initialize_community_owner_v1(input_community_id text, input_creator_account_id text, input_created_at timestamp with time zone) RETURNS void
    LANGUAGE plpgsql
    AS $$
DECLARE
  expected_assignment_id TEXT;
  persisted community_role_assignments%ROWTYPE;
BEGIN
  IF input_creator_account_id IS NULL OR btrim(input_creator_account_id) = ''
    OR NOT EXISTS (
      SELECT 1
        FROM users
       WHERE user_id = input_creator_account_id
         AND status = 'active'
    )
  THEN
    RAISE EXCEPTION 'initial community owner requires an active creator account';
  END IF;

  expected_assignment_id := 'community-role:' || input_community_id || ':owner:v1';

  INSERT INTO community_role_assignments (
    role_assignment_id,
    community_id,
    account_id,
    role,
    status,
    assigned_at
  ) VALUES (
    expected_assignment_id,
    input_community_id,
    input_creator_account_id,
    'owner',
    'active',
    input_created_at
  )
  ON CONFLICT (role_assignment_id) DO NOTHING;

  SELECT *
    INTO persisted
    FROM community_role_assignments
   WHERE role_assignment_id = expected_assignment_id;

  IF NOT FOUND
    OR persisted.community_id IS DISTINCT FROM input_community_id
    OR persisted.account_id IS DISTINCT FROM input_creator_account_id
    OR persisted.role IS DISTINCT FROM 'owner'
    OR persisted.status IS DISTINCT FROM 'active'
    OR persisted.assigned_at IS DISTINCT FROM input_created_at
    OR persisted.deactivated_at IS NOT NULL
  THEN
    RAISE EXCEPTION 'initial community owner conflicts with deterministic assignment';
  END IF;

  IF (
    SELECT count(*)
      FROM community_role_assignments
     WHERE community_id = input_community_id
       AND role = 'owner'
       AND status = 'active'
  ) <> 1 THEN
    RAISE EXCEPTION 'community must have exactly one active owner';
  END IF;
END;
$$;

CREATE FUNCTION initialize_handle_persona_public_linkage_state_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  INSERT INTO handle_persona_public_linkage_states (
    persona_id,
    account_id,
    public_linkage_generation,
    updated_at
  ) VALUES (NEW.persona_id, NEW.account_id, 0, clock_timestamp())
  ON CONFLICT (persona_id) DO NOTHING;
  RETURN NEW;
END;
$$;

CREATE FUNCTION initialize_inserted_community_moderation_policy_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM initialize_community_moderation_policy_v1(NEW.community_id, NEW.created_at);
  RETURN NEW;
END;
$$;

CREATE FUNCTION initialize_inserted_community_owner_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  PERFORM initialize_community_owner_v1(
    NEW.community_id,
    NEW.created_by_user_id,
    NEW.created_at
  );
  RETURN NEW;
END;
$$;

CREATE FUNCTION initialize_platform_pirate_identity_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $_$
BEGIN
  IF NEW.status = 'active' THEN
    INSERT INTO platform_pirate_handles (
      platform_handle_id,actor_account_id,owner_persona_id,generation,
      active_handle_id,cleanup_rename_consumed,created_at,updated_at
    ) VALUES (
      NEW.platform_handle_id,NEW.owner_user_id,NEW.owner_persona_id,NEW.generation,
      NEW.handle_id,NEW.label_normalized !~ '^new-[0-9a-f]{20}$',NEW.created_at,NEW.updated_at
    )
    ON CONFLICT (platform_handle_id) DO NOTHING;
  END IF;
  RETURN NEW;
END;
$_$;

CREATE FUNCTION initialize_song_owner_policy_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path FROM CURRENT
    AS $$
DECLARE
  publication_post posts%ROWTYPE;
  song_terms media_submission_terms%ROWTYPE;
  initial_derivative_video TEXT;
  initial_hash TEXT;
  database_now TIMESTAMPTZ := clock_timestamp();
BEGIN
  SELECT * INTO publication_post
    FROM posts
   WHERE community_id = NEW.community_id
     AND post_id = NEW.post_id
   FOR SHARE;
  IF publication_post.post_id IS NULL THEN
    RAISE EXCEPTION 'song owner policy requires a canonical Post';
  END IF;
  IF publication_post.post_type <> 'song' THEN
    RETURN NEW;
  END IF;
  IF publication_post.status <> 'published'
    OR publication_post.author_user_id IS DISTINCT FROM NEW.actor_account_id
  THEN
    RAISE EXCEPTION 'song owner policy requires the canonical published song owner';
  END IF;

  SELECT * INTO song_terms
    FROM media_submission_terms
   WHERE submission_id = NEW.submission_id
     AND community_id = NEW.community_id
     AND actor_user_id = NEW.actor_account_id
     AND operation_id = NEW.operation_id
     AND creation_revision = NEW.creation_revision
   FOR SHARE;
  IF song_terms.submission_id IS NULL THEN
    RAISE EXCEPTION 'song owner policy requires immutable publication terms';
  END IF;

  initial_derivative_video := CASE song_terms.license_preset
    WHEN 'commercial-remix' THEN 'allowed'
    WHEN 'non-commercial' THEN 'allowed'
    WHEN 'commercial-use' THEN 'owner_only'
    ELSE NULL
  END;
  IF initial_derivative_video IS NULL THEN
    RAISE EXCEPTION 'song owner policy license preset is unsupported';
  END IF;

  initial_hash := song_owner_policy_hash_v1(
    NEW.community_id,
    NEW.post_id,
    NEW.audio_revision,
    NEW.actor_account_id,
    1,
    'allowed',
    'allowed',
    initial_derivative_video
  );

  INSERT INTO song_owner_policy_revisions (
    community_id,
    post_id,
    audio_revision,
    owner_account_id,
    policy_revision,
    third_party_reward_legs,
    pool_leg,
    derivative_video,
    policy_hash,
    effective_at
  ) VALUES (
    NEW.community_id,
    NEW.post_id,
    NEW.audio_revision,
    NEW.actor_account_id,
    1,
    'allowed',
    'allowed',
    initial_derivative_video,
    initial_hash,
    database_now
  );

  INSERT INTO song_owner_policies (
    community_id,
    post_id,
    audio_revision,
    owner_account_id,
    current_policy_revision,
    current_policy_hash,
    created_at,
    updated_at
  ) VALUES (
    NEW.community_id,
    NEW.post_id,
    NEW.audio_revision,
    NEW.actor_account_id,
    1,
    initial_hash,
    database_now,
    database_now
  );
  RETURN NEW;
END;
$$;

CREATE FUNCTION is_dance_identifier(value text, maximum_octets integer DEFAULT 256) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    AS $$
  SELECT btrim(value) <> ''
     AND value = btrim(value)
     AND octet_length(value) <= maximum_octets
$$;

CREATE FUNCTION is_dance_sha256_array(value text[]) RETURNS boolean
    LANGUAGE sql IMMUTABLE STRICT
    AS $_$
  SELECT cardinality(value) > 0
    AND bool_and(fingerprint ~ '^[0-9a-f]{64}$')
  FROM unnest(value) AS fingerprint
$_$;

CREATE FUNCTION is_hns_host_persistence_identity(input_value text, maximum_bytes integer) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    AS $$
  SELECT input_value IS NOT NULL
    AND btrim(input_value) <> ''
    AND input_value = btrim(input_value)
    AND octet_length(input_value) <= maximum_bytes
    AND input_value !~ '[[:cntrl:]]'
$$;

CREATE FUNCTION is_operator_managed_root_registry_document(exact_bytes bytea, expected_reference text, expected_version bigint) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    AS $_$
DECLARE
  document JSONB;
  entries JSONB;
  canonical_entries TEXT;
  canonical_document TEXT;
  invalid_entries BIGINT;
  reordered_entries BIGINT;
BEGIN
  IF exact_bytes IS NULL
    OR octet_length(exact_bytes) = 0
    OR octet_length(exact_bytes) > 65536
    OR btrim(expected_reference) = ''
    OR expected_reference <> btrim(expected_reference)
    OR expected_version <= 0 THEN
    RETURN FALSE;
  END IF;

  document := convert_from(exact_bytes, 'UTF8')::jsonb;
  IF jsonb_typeof(document) <> 'array'
    OR jsonb_array_length(document) <> 4
    OR document ->> 0 <> 'pirate-operator-managed-root-registry-v1'
    OR document ->> 1 <> expected_reference
    OR jsonb_typeof(document -> 2) <> 'number'
    OR document ->> 2 !~ '^[1-9][0-9]*$'
    OR (document ->> 2)::numeric <> expected_version
    OR jsonb_typeof(document -> 3) <> 'array'
    OR jsonb_array_length(document -> 3) > 256 THEN
    RETURN FALSE;
  END IF;

  entries := document -> 3;
  SELECT COUNT(*) INTO invalid_entries
    FROM jsonb_array_elements(entries) AS item(entry)
   WHERE jsonb_typeof(entry) <> 'array'
      OR jsonb_array_length(entry) <> 3
      OR entry ->> 0 <> 'hns'
      OR is_community_route_root_label('hns', entry ->> 1) IS NOT TRUE
      OR entry ->> 2 <> 'active';
  IF invalid_entries <> 0 THEN
    RETURN FALSE;
  END IF;

  SELECT COALESCE(
           '[' || string_agg(
             format(
               '[%s,%s,%s]',
               to_jsonb(entry ->> 0)::TEXT,
               to_jsonb(entry ->> 1)::TEXT,
               to_jsonb(entry ->> 2)::TEXT
             ),
             ',' ORDER BY ordinal
           ) || ']',
           '[]'
         )
    INTO canonical_entries
    FROM jsonb_array_elements(entries) WITH ORDINALITY AS item(entry, ordinal);
  canonical_document := format(
    '[%s,%s,%s,%s]',
    to_jsonb(document ->> 0)::TEXT,
    to_jsonb(document ->> 1)::TEXT,
    expected_version::TEXT,
    canonical_entries
  );
  IF convert_from(exact_bytes, 'UTF8') <> canonical_document THEN
    RETURN FALSE;
  END IF;

  SELECT COUNT(*) INTO reordered_entries
    FROM (
      SELECT entry ->> 1 AS root_label,
             lag(entry ->> 1) OVER (ORDER BY ordinal) AS previous_root
        FROM jsonb_array_elements(entries) WITH ORDINALITY AS item(entry, ordinal)
    ) AS ordered
   WHERE previous_root IS NOT NULL
     AND convert_to(previous_root, 'UTF8') >= convert_to(root_label, 'UTF8');
  RETURN reordered_entries = 0;
EXCEPTION WHEN OTHERS THEN
  RETURN FALSE;
END;
$_$;

CREATE FUNCTION moderation_platform_floor_preimage_v1(input_policy_revision_id text) RETURNS text
    LANGUAGE sql STABLE PARALLEL SAFE
    AS $$
  SELECT format(
    '["moderation-platform-floor-v1",%s,[%s]]',
    to_json(input_policy_revision_id)::text,
    string_agg(
      format('[%s,%s]', to_json(category)::text, to_json(decision)::text),
      ',' ORDER BY moderation_policy_category_ordinal_v1(category)
    )
  )
  FROM moderation_platform_floor_category_decisions
  WHERE policy_revision_id = input_policy_revision_id;
$$;

CREATE FUNCTION moderation_policy_category_ordinal_v1(input_category text) RETURNS integer
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT CASE input_category
    WHEN 'harassment' THEN 1
    WHEN 'harassment/threatening' THEN 2
    WHEN 'hate' THEN 3
    WHEN 'hate/threatening' THEN 4
    WHEN 'illicit' THEN 5
    WHEN 'illicit/violent' THEN 6
    WHEN 'self-harm' THEN 7
    WHEN 'self-harm/intent' THEN 8
    WHEN 'self-harm/instructions' THEN 9
    WHEN 'sexual' THEN 10
    WHEN 'sexual/minors' THEN 11
    WHEN 'violence' THEN 12
    WHEN 'violence/graphic' THEN 13
    ELSE NULL
  END;
$$;

CREATE FUNCTION moderation_policy_decision_severity_v1(input_decision text) RETURNS integer
    LANGUAGE sql IMMUTABLE PARALLEL SAFE
    AS $$
  SELECT CASE input_decision
    WHEN 'permit' THEN 1
    WHEN 'review' THEN 2
    WHEN 'block' THEN 3
    ELSE NULL
  END;
$$;

CREATE TABLE song_derivative_video_policy_observations (
    operation_id text NOT NULL,
    observed_at_transition text NOT NULL,
    creation_revision bigint NOT NULL,
    community_id text NOT NULL,
    post_id text NOT NULL,
    audio_revision bigint NOT NULL,
    actor_account_id text NOT NULL,
    owner_policy_revision bigint NOT NULL,
    owner_policy_hash text NOT NULL,
    derivative_video text NOT NULL,
    permitted boolean NOT NULL,
    denial_reason text,
    observed_at timestamp with time zone DEFAULT clock_timestamp() NOT NULL,
    CONSTRAINT song_derivative_video_policy_obser_observed_at_transition_check CHECK ((observed_at_transition = ANY (ARRAY['media_reservation_issued'::text, 'publication_allowed'::text, 'publication_committed'::text]))),
    CONSTRAINT song_derivative_video_policy_observ_owner_policy_revision_check CHECK (((owner_policy_revision >= 1) AND (owner_policy_revision <= '9007199254740991'::bigint))),
    CONSTRAINT song_derivative_video_policy_observatio_creation_revision_check CHECK (((creation_revision >= 1) AND (creation_revision <= '9007199254740991'::bigint))),
    CONSTRAINT song_derivative_video_policy_observatio_owner_policy_hash_check CHECK ((owner_policy_hash ~ '^[0-9a-f]{64}$'::text)),
    CONSTRAINT song_derivative_video_policy_observation_derivative_video_check CHECK ((derivative_video = ANY (ARRAY['allowed'::text, 'owner_only'::text, 'blocked'::text]))),
    CONSTRAINT song_derivative_video_policy_observation_outcome CHECK (((permitted AND (denial_reason IS NULL)) OR ((NOT permitted) AND (denial_reason =
CASE derivative_video
    WHEN 'blocked'::text THEN 'derivative_video_blocked'::text
    WHEN 'owner_only'::text THEN 'derivative_video_owner_only'::text
    ELSE NULL::text
END)))),
    CONSTRAINT song_derivative_video_policy_observations_audio_revision_check CHECK (((audio_revision >= 1) AND (audio_revision <= '9007199254740991'::bigint))),
    CONSTRAINT song_derivative_video_policy_observations_denial_reason_check CHECK (((denial_reason IS NULL) OR (denial_reason = ANY (ARRAY['derivative_video_blocked'::text, 'derivative_video_owner_only'::text])))),
    CONSTRAINT song_derivative_video_policy_observations_operation_id_check CHECK (((btrim(operation_id) <> ''::text) AND (operation_id = btrim(operation_id)) AND (octet_length(operation_id) <= 128) AND (operation_id !~ '[[:cntrl:]]'::text)))
);

CREATE FUNCTION observe_song_derivative_video_policy_v1(input_operation_id text, input_transition text, input_creation_revision bigint, input_community_id text, input_post_id text, input_audio_revision bigint, input_actor_account_id text) RETURNS SETOF song_derivative_video_policy_observations
    LANGUAGE plpgsql STRICT SECURITY DEFINER
    SET search_path FROM CURRENT
    AS $$
DECLARE
  policy_head song_owner_policies%ROWTYPE;
  policy_record song_owner_policy_revisions%ROWTYPE;
  existing_observation song_derivative_video_policy_observations%ROWTYPE;
  is_permitted BOOLEAN;
  reason TEXT;
BEGIN
  IF input_transition NOT IN (
    'media_reservation_issued',
    'publication_allowed',
    'publication_committed'
  ) THEN
    RAISE EXCEPTION 'invalid song derivative video policy transition';
  END IF;

  SELECT * INTO existing_observation
    FROM song_derivative_video_policy_observations
   WHERE operation_id = input_operation_id
     AND observed_at_transition = input_transition
     AND creation_revision = input_creation_revision;
  IF existing_observation.operation_id IS NOT NULL THEN
    IF existing_observation.community_id <> input_community_id
      OR existing_observation.post_id <> input_post_id
      OR existing_observation.audio_revision <> input_audio_revision
      OR existing_observation.actor_account_id <> input_actor_account_id
    THEN
      RAISE EXCEPTION 'song derivative video policy observation replay conflict';
    END IF;
    RETURN NEXT existing_observation;
    RETURN;
  END IF;

  SELECT * INTO policy_head
    FROM song_owner_policies
   WHERE community_id = input_community_id
     AND post_id = input_post_id
   FOR SHARE;
  IF policy_head.post_id IS NULL
    OR policy_head.audio_revision <> input_audio_revision
  THEN
    RAISE EXCEPTION 'song reference is not policy-addressable';
  END IF;

  SELECT revision.* INTO policy_record
    FROM song_owner_policy_revisions AS revision
   WHERE revision.community_id = policy_head.community_id
     AND revision.post_id = policy_head.post_id
     AND revision.policy_revision = policy_head.current_policy_revision;
  IF policy_record.post_id IS NULL
    OR policy_record.policy_hash <> policy_head.current_policy_hash
  THEN
    RAISE EXCEPTION 'song owner policy head is invalid';
  END IF;

  is_permitted := policy_record.derivative_video = 'allowed'
    OR (
      policy_record.derivative_video = 'owner_only'
      AND policy_head.owner_account_id = input_actor_account_id
    );
  reason := CASE
    WHEN is_permitted THEN NULL
    WHEN policy_record.derivative_video = 'blocked' THEN 'derivative_video_blocked'
    ELSE 'derivative_video_owner_only'
  END;

  INSERT INTO song_derivative_video_policy_observations (
    operation_id,
    observed_at_transition,
    creation_revision,
    community_id,
    post_id,
    audio_revision,
    actor_account_id,
    owner_policy_revision,
    owner_policy_hash,
    derivative_video,
    permitted,
    denial_reason
  ) VALUES (
    input_operation_id,
    input_transition,
    input_creation_revision,
    policy_head.community_id,
    policy_head.post_id,
    policy_head.audio_revision,
    input_actor_account_id,
    policy_record.policy_revision,
    policy_record.policy_hash,
    policy_record.derivative_video,
    is_permitted,
    reason
  )
  ON CONFLICT (operation_id, observed_at_transition, creation_revision) DO NOTHING;

  SELECT * INTO existing_observation
    FROM song_derivative_video_policy_observations
   WHERE operation_id = input_operation_id
     AND observed_at_transition = input_transition
     AND creation_revision = input_creation_revision;
  IF existing_observation.operation_id IS NULL
    OR existing_observation.community_id <> input_community_id
    OR existing_observation.post_id <> input_post_id
    OR existing_observation.audio_revision <> input_audio_revision
    OR existing_observation.actor_account_id <> input_actor_account_id
  THEN
    RAISE EXCEPTION 'song derivative video policy observation replay conflict';
  END IF;
  RETURN NEXT existing_observation;
END;
$$;

CREATE FUNCTION operator_managed_registry_has_active_root(expected_reference text, expected_version bigint, expected_digest text, expected_root text) RETURNS boolean
    LANGUAGE sql STABLE
    AS $$
  SELECT EXISTS (
    SELECT 1
      FROM operator_managed_root_registry_versions AS registry
      CROSS JOIN LATERAL jsonb_array_elements(
        convert_from(registry.registry_bytes, 'UTF8')::jsonb -> 3
      ) AS item(entry)
     WHERE registry.registry_reference = expected_reference
       AND registry.registry_version = expected_version
       AND registry.registry_digest = expected_digest
       AND item.entry = jsonb_build_array('hns', expected_root, 'active')
  )
$$;

CREATE FUNCTION persona_community_binding_evidence_digest_v1() RETURNS text
    LANGUAGE sql STABLE
    AS $$
  SELECT encode(
    sha256(
      convert_to(
        coalesce(
          string_agg(
            evidence.persona_id || ':' || evidence.account_id || ':' ||
              evidence.community_id || ':' || evidence.evidence_count::text,
            E'\n'
            ORDER BY evidence.persona_id, evidence.account_id, evidence.community_id
          ),
          ''
        ),
        'UTF8'
      )
    ),
    'hex'
  )
    FROM persona_community_binding_evidence_v1() AS evidence
$$;

CREATE FUNCTION persona_community_binding_evidence_v1() RETURNS TABLE(persona_id text, account_id text, community_id text, evidence_count bigint)
    LANGUAGE plpgsql STABLE
    AS $$
BEGIN
  RETURN QUERY
  SELECT source.persona_id, source.account_id, source.community_id,
         count(*)::BIGINT AS evidence_count
    FROM (
      SELECT post.author_persona_id AS persona_id,
             post.author_user_id AS account_id,
             post.community_id
        FROM posts AS post
      UNION ALL
      SELECT comment.author_persona_id,
             comment.author_user_id,
             comment.community_id
        FROM comments AS comment
      UNION ALL
      SELECT submission.author_persona_id,
             submission.actor_user_id,
             submission.community_id
        FROM text_content_submissions AS submission
      UNION ALL
      SELECT submission.author_persona_id,
             submission.actor_user_id,
             submission.community_id
        FROM media_post_submissions AS submission
      UNION ALL
      SELECT reservation.actor_persona_id,
             reservation.actor_user_id,
             reservation.community_id
        FROM media_upload_reservations AS reservation
      UNION ALL
      SELECT grant_row.owner_persona_id,
             grant_row.owner_account_id,
             grant_row.community_id
        FROM handle_grants AS grant_row
      UNION ALL
      SELECT role_presentation.persona_id,
             role_presentation.account_id,
             role_presentation.community_id
        FROM persona_role_presentations AS role_presentation
      UNION ALL
      SELECT activity_presentation.persona_id,
             activity_presentation.account_id,
             activity_presentation.community_id
        FROM persona_activity_presentations AS activity_presentation
      UNION ALL
      SELECT study_session.persona_id,
             study_session.account_id,
             study_session.community_id
        FROM study_sessions AS study_session
      UNION ALL
      SELECT karaoke_session.persona_id,
             karaoke_session.account_id,
             karaoke_session.community_id
        FROM karaoke_sessions AS karaoke_session
      UNION ALL
      SELECT qualification.persona_id,
             qualification.account_id,
             qualification.community_id
        FROM activity_qualifications AS qualification
    ) AS source
   GROUP BY source.persona_id, source.account_id, source.community_id;
  IF to_regclass('dance_choreographies') IS NOT NULL THEN
    RETURN QUERY
    SELECT choreography.creator_persona_id,
           choreography.creator_account_id,
           choreography.community_id,
           1::BIGINT AS evidence_count
      FROM dance_choreographies AS choreography;
  END IF;
  IF to_regclass('dance_sessions') IS NOT NULL THEN
    RETURN QUERY
    SELECT dance_session.persona_id,
           dance_session.account_id,
           dance_session.community_id,
           1::BIGINT AS evidence_count
      FROM dance_sessions AS dance_session;
  END IF;
  IF to_regclass('study_sessions_v2') IS NOT NULL THEN
    RETURN QUERY
    SELECT study_session.persona_id,
           study_session.account_id,
           study_session.community_id,
           1::BIGINT AS evidence_count
      FROM study_sessions_v2 AS study_session;
  END IF;
END
$$;

CREATE FUNCTION populate_media_persona_lineage() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_TABLE_NAME = 'media_submission_command_replays' THEN
    IF NEW.submission_author_persona_id IS NULL THEN
      SELECT submission.author_persona_id INTO NEW.submission_author_persona_id
        FROM media_post_submissions AS submission
       WHERE submission.community_id = NEW.community_id
         AND submission.actor_user_id = NEW.submission_actor_user_id
         AND submission.submission_id = NEW.submission_id
         AND submission.operation_id = NEW.operation_id;
    END IF;
  ELSE
    IF NEW.author_persona_id IS NULL THEN
      SELECT submission.author_persona_id INTO NEW.author_persona_id
        FROM media_post_submissions AS submission
       WHERE submission.community_id = NEW.community_id
         AND submission.actor_user_id = NEW.actor_user_id
         AND submission.submission_id = NEW.submission_id
         AND submission.operation_id = NEW.operation_id;
    END IF;
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION post_slug_utf16_code_units(value text) RETURNS integer
    LANGUAGE sql IMMUTABLE STRICT PARALLEL SAFE
    AS $$
  SELECT COALESCE(
    SUM(CASE WHEN ascii(character) > 65535 THEN 2 ELSE 1 END),
    0
  )::INTEGER
  FROM regexp_split_to_table(value, '') AS characters(character);
$$;

CREATE FUNCTION prepare_hns_control_observer_operation_insert() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  configuration_record hns_control_observer_configurations%ROWTYPE;
BEGIN
  IF NEW.snapshot_reference IS NOT NULL THEN
    RAISE EXCEPTION 'HNS observer snapshot reference is database-generated';
  END IF;

  SELECT * INTO configuration_record
    FROM hns_control_observer_configurations
   WHERE provider_configuration_reference = NEW.provider_configuration_reference
     AND provider_configuration_version = NEW.provider_configuration_version;
  IF NOT FOUND
    OR configuration_record.provider_configuration_digest <> NEW.provider_configuration_digest
    OR configuration_record.configuration_bytes IS DISTINCT FROM NEW.configuration_bytes THEN
    RAISE EXCEPTION 'HNS observer operation configuration authority mismatch';
  END IF;

  NEW.snapshot_reference := 'hns-observer:postgres:' || gen_random_uuid()::text;
  RETURN NEW;
END;
$$;

CREATE FUNCTION prepare_platform_pirate_label_insert_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  target public_handle_index%ROWTYPE;
BEGIN
  IF NEW.platform_handle_id IS NULL THEN
    IF NEW.status = 'redirect' THEN
      SELECT * INTO target
        FROM public_handle_index
       WHERE handle_id=NEW.redirect_target_handle_id;
      IF target.handle_id IS NULL THEN
        NEW.platform_handle_id := NEW.handle_id;
        NEW.generation := 1;
        RETURN NEW;
      END IF;
      NEW.platform_handle_id := target.platform_handle_id;
      NEW.generation := GREATEST(1, target.generation - 1);
    ELSE
      NEW.platform_handle_id := NEW.handle_id;
      NEW.generation := 1;
    END IF;
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION prevent_persona_create_action_change() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'persona create action is append-only';
END
$$;

CREATE FUNCTION prevent_persona_identity_rewrite() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'persona identity cannot be deleted';
  END IF;
  IF NEW.persona_id IS DISTINCT FROM OLD.persona_id
     OR NEW.account_id IS DISTINCT FROM OLD.account_id
     OR NEW.is_first_persona IS DISTINCT FROM OLD.is_first_persona THEN
    RAISE EXCEPTION 'persona identity is immutable';
  END IF;
  IF OLD.status = 'retired' AND NEW IS DISTINCT FROM OLD THEN
    RAISE EXCEPTION 'retired persona is immutable';
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION prevent_persona_profile_delete() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  RAISE EXCEPTION 'persona profile cannot be deleted';
END
$$;

CREATE FUNCTION prevent_platform_pirate_identity_rewrite_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'platform Pirate identity cannot be deleted';
  END IF;
  IF NEW.platform_handle_id IS DISTINCT FROM OLD.platform_handle_id
     OR NEW.actor_account_id IS DISTINCT FROM OLD.actor_account_id
     OR NEW.owner_persona_id IS DISTINCT FROM OLD.owner_persona_id
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'platform Pirate identity ownership is immutable';
  END IF;
  IF NEW.generation < OLD.generation
     OR (OLD.cleanup_rename_consumed AND NOT NEW.cleanup_rename_consumed) THEN
    RAISE EXCEPTION 'platform Pirate identity state is append-only';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION prevent_platform_pirate_label_rewrite_v1() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION 'platform Pirate label history cannot be deleted';
  END IF;
  IF NEW.handle_id IS DISTINCT FROM OLD.handle_id
     OR NEW.platform_handle_id IS DISTINCT FROM OLD.platform_handle_id
     OR NEW.owner_user_id IS DISTINCT FROM OLD.owner_user_id
     OR NEW.owner_persona_id IS DISTINCT FROM OLD.owner_persona_id
     OR NEW.label_normalized IS DISTINCT FROM OLD.label_normalized
     OR NEW.label_display IS DISTINCT FROM OLD.label_display
     OR NEW.generation IS DISTINCT FROM OLD.generation
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION 'platform Pirate label identity is immutable';
  END IF;
  IF OLD.status <> 'active'
     AND current_setting('pirate.platform_handle_rename', true) IS DISTINCT FROM 'on'
     AND NEW IS DISTINCT FROM OLD THEN
    RAISE EXCEPTION 'historical platform Pirate label is immutable';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION project_asset_bonus_claim_from_qualification() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  candidate RECORD;
  asset_leg RECORD;
  evidence RECORD;
  existing_consumption reward_subject_consumptions%ROWTYPE;
  decided_at TIMESTAMPTZ := clock_timestamp();
  reason TEXT;
  decision_outcome TEXT;
  decision_id TEXT;
  eligibility_id TEXT;
  consumption_id TEXT;
  identity_digest TEXT;
  credit_id TEXT;
BEGIN
  SELECT offer.offer_id, offer.community_id, offer.reward_policy_version_id,
         offer.ends_at, policy.policy_hash, leg.leg_id
    INTO candidate
    FROM song_reward_offers offer
    JOIN song_reward_offer_legs leg ON leg.offer_id = offer.offer_id
    JOIN policy_versions policy
      ON policy.community_id = offer.community_id
     AND policy.policy_version_id = offer.reward_policy_version_id
     AND policy.policy_purpose = 'reward'
     AND policy.uniqueness_authority_id = offer.offer_id
   WHERE offer.community_id = NEW.community_id
     AND offer.post_id = NEW.post_id
     AND offer.audio_revision = NEW.audio_revision
     AND offer.status = 'active'
     AND decided_at < offer.ends_at
     AND NEW.qualified_at >= offer.starts_at
     AND NEW.qualified_at < offer.ends_at
     AND leg.kind = 'asset_bonus' AND leg.status = 'active'
     AND NEW.qualified_at >= leg.participation_starts_at
     AND leg.fulfilled_atomic / leg.amount_per_claim_atomic < leg.max_claims
     AND leg.funded_atomic - leg.reserved_atomic - leg.spent_atomic
       - leg.fulfilled_atomic - leg.refunded_atomic >= leg.amount_per_claim_atomic
   ORDER BY leg.leg_id
   LIMIT 1
   FOR UPDATE OF leg;

  IF candidate.offer_id IS NULL THEN
    RETURN NEW;
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(
    NEW.account_id || chr(31) || candidate.offer_id, 53000002
  ));
  IF EXISTS (
    SELECT 1 FROM song_reward_bundle_claims claim
     WHERE claim.account_id = NEW.account_id AND claim.offer_id = candidate.offer_id
  ) THEN
    RETURN NEW;
  END IF;

  identity_digest := md5(NEW.qualification_id || chr(31) || candidate.offer_id);
  decision_id := 'reward_decision_' || identity_digest;
  eligibility_id := 'reward_eligibility_' || identity_digest;
  consumption_id := 'reward_subject_' || identity_digest;

  WITH exact_evidence AS (
    SELECT DISTINCT ON (subject.subject_key_id)
           subject.subject_key_id, active_binding.binding_event_id,
           active_binding.binding_epoch, receipt.evidence_receipt_id,
           receipt.evidence_hash,
           LEAST(candidate.ends_at, receipt.expires_at,
             personhood.expires_at, subject_unique.expires_at) AS evidence_expires_at,
           receipt.observed_at
      FROM subject_keys subject
      JOIN active_subject_key_bindings active_binding
        ON active_binding.subject_key_id = subject.subject_key_id
       AND active_binding.user_id = NEW.account_id
      JOIN assertion_bindings binding
        ON binding.user_id = NEW.account_id AND binding.binding_mode = 'same_subject'
       AND binding.subject_key_id = subject.subject_key_id
       AND binding.subject_binding_event_id = active_binding.binding_event_id
       AND binding.subject_binding_epoch = active_binding.binding_epoch
      JOIN assertions personhood
        ON personhood.binding_group_id = binding.binding_group_id
       AND personhood.user_id = NEW.account_id
       AND personhood.subject_key_id = subject.subject_key_id
       AND personhood.claim_id = 'human.personhood'
       AND personhood.assertion_value = '{"personhood": true}'::jsonb
       AND personhood.assurance = 'provider_attested'
      JOIN assertions subject_unique
        ON subject_unique.binding_group_id = binding.binding_group_id
       AND subject_unique.user_id = NEW.account_id
       AND subject_unique.subject_key_id = subject.subject_key_id
       AND subject_unique.evidence_receipt_id = personhood.evidence_receipt_id
       AND subject_unique.claim_id = 'credential.subject_unique'
       AND subject_unique.assertion_value = '{"subject_unique": true}'::jsonb
       AND subject_unique.assurance = 'provider_attested'
      JOIN evidence_receipts receipt
        ON receipt.evidence_receipt_id = personhood.evidence_receipt_id
       AND receipt.user_id = NEW.account_id
       AND receipt.subject_key_id = subject.subject_key_id
       AND receipt.subject_binding_event_id = active_binding.binding_event_id
       AND receipt.subject_binding_epoch = active_binding.binding_epoch
       AND receipt.provider_id = 'very.web'
       AND receipt.issuer = 'https://verify.very.org'
       AND receipt.method = 'palm_web'
       AND receipt.scope_kind = 'issuer_rp_scope'
       AND receipt.issuer_rp_scope = 'pirate-social'
       AND receipt.issuer_rp_action_scope IS NULL
       AND receipt.protocol_version = 'very-web-v1'
       AND receipt.evidence_kind = 'very.web.server-verified.v1'
       AND receipt.provenance_kind = 'proof_session'
      JOIN proof_sessions session
        ON session.proof_session_id = receipt.proof_session_id
       AND session.actor_id = NEW.account_id
       AND session.status = 'completed' AND session.completed_at = session.terminal_at
       AND session.provider_id = receipt.provider_id AND session.issuer = receipt.issuer
       AND session.method = receipt.method AND session.scope_kind = receipt.scope_kind
       AND session.issuer_rp_scope = receipt.issuer_rp_scope
       AND session.issuer_rp_action_scope IS NOT DISTINCT FROM receipt.issuer_rp_action_scope
       AND session.protocol_version = receipt.protocol_version
       AND session.requested_requirements =
         '[{"claim_id":"credential.subject_unique"},{"claim_id":"human.personhood"}]'::jsonb
       AND session.requested_claim_ids =
         '["credential.subject_unique","human.personhood"]'::jsonb
     WHERE subject.issuer = 'https://verify.very.org'
       AND subject.method = 'palm_web' AND subject.scope_kind = 'issuer_rp_scope'
       AND subject.issuer_rp_scope = 'pirate-social'
       AND subject.issuer_rp_action_scope IS NULL
       AND (receipt.expires_at IS NULL OR receipt.expires_at > decided_at + interval '5 seconds')
       AND (personhood.expires_at IS NULL OR personhood.expires_at > decided_at + interval '5 seconds')
       AND (subject_unique.expires_at IS NULL OR subject_unique.expires_at > decided_at + interval '5 seconds')
       AND COALESCE((SELECT revalidation.outcome
          FROM assertion_revalidation_events revalidation
         WHERE revalidation.assertion_id = personhood.assertion_id
         ORDER BY revalidation.observed_at DESC,
                  revalidation.assertion_revalidation_event_id DESC LIMIT 1), 'accepted') = 'accepted'
       AND COALESCE((SELECT revalidation.outcome
          FROM assertion_revalidation_events revalidation
         WHERE revalidation.assertion_id = subject_unique.assertion_id
         ORDER BY revalidation.observed_at DESC,
                  revalidation.assertion_revalidation_event_id DESC LIMIT 1), 'accepted') = 'accepted'
     ORDER BY subject.subject_key_id, receipt.observed_at DESC,
              receipt.evidence_receipt_id DESC
  )
  SELECT exact_evidence.*, count(*) OVER () AS evidence_count
    INTO evidence FROM exact_evidence
   ORDER BY exact_evidence.observed_at DESC, exact_evidence.subject_key_id LIMIT 1;

  IF evidence.subject_key_id IS NULL THEN
    IF EXISTS (
      SELECT 1 FROM subject_keys subject
      JOIN active_subject_key_bindings active_binding
        ON active_binding.subject_key_id = subject.subject_key_id
       AND active_binding.user_id = NEW.account_id
      JOIN assertions personhood ON personhood.subject_key_id = subject.subject_key_id
       AND personhood.user_id = NEW.account_id AND personhood.claim_id = 'human.personhood'
       AND personhood.assertion_value = '{"personhood": true}'::jsonb
      JOIN assertions subject_unique
        ON subject_unique.binding_group_id = personhood.binding_group_id
       AND subject_unique.evidence_receipt_id = personhood.evidence_receipt_id
       AND subject_unique.subject_key_id = subject.subject_key_id
       AND subject_unique.user_id = NEW.account_id
       AND subject_unique.claim_id = 'credential.subject_unique'
       AND subject_unique.assertion_value = '{"subject_unique": true}'::jsonb
      WHERE subject.issuer = 'https://verify.very.org' AND subject.method = 'palm_web'
        AND subject.scope_kind = 'issuer_rp_scope'
        AND subject.issuer_rp_scope = 'pirate-social'
    ) THEN
      reason := 'verification_stale'; decision_outcome := 'needs_evidence';
    ELSIF EXISTS (
      SELECT 1 FROM subject_keys subject
      JOIN active_subject_key_bindings active_binding
        ON active_binding.subject_key_id = subject.subject_key_id
       AND active_binding.user_id = NEW.account_id
      WHERE subject.issuer = 'https://verify.very.org' AND subject.method = 'palm_web'
        AND subject.scope_kind = 'issuer_rp_scope'
        AND subject.issuer_rp_scope = 'pirate-social'
    ) THEN
      reason := 'verification_failed'; decision_outcome := 'fail';
    ELSE
      reason := 'verification_missing'; decision_outcome := 'needs_evidence';
    END IF;
  ELSIF evidence.evidence_count <> 1 THEN
    reason := 'verification_failed'; decision_outcome := 'fail';
  ELSE
    PERFORM 1 FROM subject_keys WHERE subject_key_id = evidence.subject_key_id FOR UPDATE;
    SELECT * INTO existing_consumption FROM reward_subject_consumptions
     WHERE campaign_id = candidate.offer_id AND subject_key_id = evidence.subject_key_id
     FOR UPDATE;
    IF existing_consumption.reward_subject_consumption_id IS NULL THEN
      INSERT INTO reward_subject_consumptions (
        reward_subject_consumption_id,campaign_id,subject_key_id,user_id,
        binding_event_id,binding_epoch,evidence_receipt_id,consumed_at,created_at
      ) VALUES (
        consumption_id,candidate.offer_id,evidence.subject_key_id,NEW.account_id,
        evidence.binding_event_id,evidence.binding_epoch,evidence.evidence_receipt_id,
        decided_at,decided_at
      );
    ELSIF existing_consumption.user_id <> NEW.account_id THEN
      reason := 'subject_already_consumed'; decision_outcome := 'fail';
    END IF;
  END IF;

  IF reason IS NOT NULL THEN
    INSERT INTO decision_records (
      decision_record_id,community_id,user_id,policy_version_id,policy_hash,
      evaluation_mode,outcome,winning_witness,trace,indeterminate_reason,request_id,created_at
    ) VALUES (
      decision_id,candidate.community_id,NEW.account_id,candidate.reward_policy_version_id,
      candidate.policy_hash,'enforce',decision_outcome,'[]'::jsonb,
      jsonb_build_array(jsonb_build_object('reason',reason)),reason,
      'asset-claim:' || identity_digest,decided_at
    );
    INSERT INTO reward_eligibility_decisions (
      eligibility_decision_id,leg_id,account_id,persona_id,purpose,qualification_id,
      decision_record_id,outcome,reason,policy_version,evidence_hash,decided_at,expires_at
    ) VALUES (
      eligibility_id,candidate.leg_id,NEW.account_id,NEW.persona_id,'asset_claim',
      NEW.qualification_id,decision_id,'ineligible',reason,
      candidate.reward_policy_version_id,COALESCE(evidence.evidence_hash,candidate.policy_hash),
      decided_at,candidate.ends_at
    );
    INSERT INTO song_reward_bundle_claims (
      account_id,offer_id,persona_id,qualification_id,eligibility_decision_id,
      state,terminal_reason,created_at,updated_at
    ) VALUES (
      NEW.account_id,candidate.offer_id,NEW.persona_id,NEW.qualification_id,
      eligibility_id,'ineligible',reason,decided_at,decided_at
    );
    FOR asset_leg IN
      SELECT leg.* FROM song_reward_offer_legs leg
       WHERE leg.offer_id = candidate.offer_id AND leg.kind = 'asset_bonus'
         AND leg.status = 'active' AND NEW.qualified_at >= leg.participation_starts_at
         AND leg.fulfilled_atomic / leg.amount_per_claim_atomic < leg.max_claims
         AND leg.funded_atomic - leg.reserved_atomic - leg.spent_atomic
           - leg.fulfilled_atomic - leg.refunded_atomic >= leg.amount_per_claim_atomic
       ORDER BY leg.leg_id FOR UPDATE
    LOOP
      INSERT INTO song_reward_bundle_claim_legs (
        account_id,offer_id,leg_id,amount_atomic,state,terminal_reason,created_at
      ) VALUES (
        NEW.account_id,candidate.offer_id,asset_leg.leg_id,
        asset_leg.amount_per_claim_atomic,'unavailable',reason,decided_at
      );
    END LOOP;
    RETURN NEW;
  END IF;

  INSERT INTO decision_records (
    decision_record_id,community_id,user_id,policy_version_id,policy_hash,
    evaluation_mode,outcome,winning_witness,trace,request_id,created_at
  ) VALUES (
    decision_id,candidate.community_id,NEW.account_id,candidate.reward_policy_version_id,
    candidate.policy_hash,'enforce','pass',
    jsonb_build_array(jsonb_build_object('subject_key_id',evidence.subject_key_id,
      'evidence_receipt_id',evidence.evidence_receipt_id)),
    jsonb_build_array(jsonb_build_object('result','eligible')),
    'asset-claim:' || identity_digest,decided_at
  );
  INSERT INTO reward_eligibility_decisions (
    eligibility_decision_id,leg_id,account_id,persona_id,purpose,qualification_id,
    decision_record_id,outcome,policy_version,evidence_hash,decided_at,expires_at
  ) VALUES (
    eligibility_id,candidate.leg_id,NEW.account_id,NEW.persona_id,'asset_claim',
    NEW.qualification_id,decision_id,'eligible',candidate.reward_policy_version_id,
    evidence.evidence_hash,decided_at,evidence.evidence_expires_at
  );
  INSERT INTO song_reward_bundle_claims (
    account_id,offer_id,persona_id,qualification_id,eligibility_decision_id,
    state,created_at,updated_at
  ) VALUES (
    NEW.account_id,candidate.offer_id,NEW.persona_id,NEW.qualification_id,
    eligibility_id,'credited',decided_at,decided_at
  );

  FOR asset_leg IN
    SELECT leg.* FROM song_reward_offer_legs leg
     WHERE leg.offer_id = candidate.offer_id AND leg.kind = 'asset_bonus'
       AND leg.status = 'active' AND NEW.qualified_at >= leg.participation_starts_at
       AND leg.fulfilled_atomic / leg.amount_per_claim_atomic < leg.max_claims
       AND leg.funded_atomic - leg.reserved_atomic - leg.spent_atomic
         - leg.fulfilled_atomic - leg.refunded_atomic >= leg.amount_per_claim_atomic
     ORDER BY leg.leg_id FOR UPDATE
  LOOP
    credit_id := 'reward_credit_' || md5(
      NEW.account_id || chr(31) || asset_leg.leg_id || chr(31) || NEW.qualification_id
    );
    INSERT INTO reward_ledger_credits (
      credit_id,account_id,payout_persona_id,chain_id,token_address,amount_atomic,
      source_kind,source_reference,state,created_at,updated_at
    ) VALUES (
      credit_id,NEW.account_id,NEW.persona_id,asset_leg.chain_id,
      asset_leg.token_address,asset_leg.amount_per_claim_atomic,'asset_bonus',
      asset_leg.leg_id || ':' || NEW.qualification_id,'credited',decided_at,decided_at
    );
    INSERT INTO song_reward_bundle_claim_legs (
      account_id,offer_id,leg_id,amount_atomic,credit_id,state,created_at
    ) VALUES (
      NEW.account_id,candidate.offer_id,asset_leg.leg_id,
      asset_leg.amount_per_claim_atomic,credit_id,'credited',decided_at
    );
    UPDATE song_reward_offer_legs
       SET fulfilled_atomic = fulfilled_atomic + asset_leg.amount_per_claim_atomic,
           status = CASE
             WHEN (fulfilled_atomic + asset_leg.amount_per_claim_atomic)
                    / amount_per_claim_atomic >= max_claims
               OR funded_atomic - reserved_atomic - spent_atomic - refunded_atomic
                    - (fulfilled_atomic + asset_leg.amount_per_claim_atomic)
                    < amount_per_claim_atomic
             THEN 'exhausted' ELSE status END,
           participation_ends_at = CASE
             WHEN (fulfilled_atomic + asset_leg.amount_per_claim_atomic)
                    / amount_per_claim_atomic >= max_claims
               OR funded_atomic - reserved_atomic - spent_atomic - refunded_atomic
                    - (fulfilled_atomic + asset_leg.amount_per_claim_atomic)
                    < amount_per_claim_atomic
             THEN decided_at ELSE participation_ends_at END,
           updated_at = decided_at
     WHERE leg_id = asset_leg.leg_id;
  END LOOP;
  RETURN NEW;
END
$$;

CREATE FUNCTION project_megapot_pool_share_from_qualification() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  candidate RECORD;
  evidence RECORD;
  existing_consumption reward_subject_consumptions%ROWTYPE;
  decided_at TIMESTAMPTZ := clock_timestamp();
  reason TEXT;
  decision_outcome TEXT;
  decision_id TEXT;
  eligibility_id TEXT;
  consumption_id TEXT;
  identity_digest TEXT;
BEGIN
  SELECT leg.leg_id, leg.offer_id, drawing.drawing_id, drawing.entry_cutoff_at,
         offer.community_id, offer.reward_policy_version_id,
         policy.policy_hash
    INTO candidate
    FROM song_reward_offers offer
    JOIN song_reward_offer_legs leg ON leg.offer_id = offer.offer_id
    JOIN megapot_pool_drawings drawing ON drawing.pool_leg_id = leg.leg_id
    JOIN policy_versions policy
      ON policy.community_id = offer.community_id
     AND policy.policy_version_id = offer.reward_policy_version_id
     AND policy.policy_purpose = 'reward'
     AND policy.uniqueness_authority_id = offer.offer_id
   WHERE offer.community_id = NEW.community_id
     AND offer.post_id = NEW.post_id
     AND offer.audio_revision = NEW.audio_revision
     AND offer.status = 'active'
     AND NEW.qualified_at >= offer.starts_at
     AND NEW.qualified_at < offer.ends_at
     AND leg.kind = 'megapot_pool'
     AND leg.status = 'active'
     AND NEW.qualified_at >= leg.participation_starts_at
     AND NEW.activity_key = ANY(leg.eligible_activities)
     AND NEW.score_bps >= leg.min_score_bps
     AND drawing.status = 'entry_open'
     AND drawing.drawing_id >= leg.participation_starts_drawing_id
     AND NEW.qualified_at < drawing.entry_cutoff_at
     AND decided_at < drawing.entry_cutoff_at
     AND NOT EXISTS (
       SELECT 1 FROM megapot_pool_shares share
        WHERE share.pool_leg_id = leg.leg_id
          AND share.drawing_id = drawing.drawing_id
          AND share.account_id = NEW.account_id
     )
   ORDER BY drawing.drawing_id DESC
   LIMIT 1
   FOR UPDATE OF drawing;

  IF candidate.leg_id IS NULL THEN
    RETURN NEW;
  END IF;

  -- The drawing lock serializes Study/Karaoke producers that qualify the same
  -- account concurrently. Recheck after acquiring it so only the first commit
  -- emits an eligibility decision and share.
  IF EXISTS (
    SELECT 1 FROM megapot_pool_shares share
     WHERE share.pool_leg_id = candidate.leg_id
       AND share.drawing_id = candidate.drawing_id
       AND share.account_id = NEW.account_id
  ) THEN
    RETURN NEW;
  END IF;

  identity_digest := md5(
    NEW.qualification_id || chr(31) || candidate.leg_id || chr(31) || candidate.drawing_id::text
  );
  decision_id := 'reward_decision_' || identity_digest;
  eligibility_id := 'reward_eligibility_' || identity_digest;
  consumption_id := 'reward_subject_' || identity_digest;

  WITH exact_evidence AS (
    SELECT DISTINCT ON (subject.subject_key_id)
           subject.subject_key_id,
           active_binding.binding_event_id,
           active_binding.binding_epoch,
           receipt.evidence_receipt_id,
           receipt.evidence_hash,
           LEAST(
             candidate.entry_cutoff_at,
             receipt.expires_at,
             personhood.expires_at,
             subject_unique.expires_at
           ) AS evidence_expires_at,
           receipt.observed_at
      FROM subject_keys subject
      JOIN active_subject_key_bindings active_binding
        ON active_binding.subject_key_id = subject.subject_key_id
       AND active_binding.user_id = NEW.account_id
      JOIN assertion_bindings binding
        ON binding.user_id = NEW.account_id
       AND binding.binding_mode = 'same_subject'
       AND binding.subject_key_id = subject.subject_key_id
       AND binding.subject_binding_event_id = active_binding.binding_event_id
       AND binding.subject_binding_epoch = active_binding.binding_epoch
      JOIN assertions personhood
        ON personhood.binding_group_id = binding.binding_group_id
       AND personhood.user_id = NEW.account_id
       AND personhood.subject_key_id = subject.subject_key_id
       AND personhood.claim_id = 'human.personhood'
       AND personhood.assertion_value = '{"personhood": true}'::jsonb
       AND personhood.assurance = 'provider_attested'
      JOIN assertions subject_unique
        ON subject_unique.binding_group_id = binding.binding_group_id
       AND subject_unique.user_id = NEW.account_id
       AND subject_unique.subject_key_id = subject.subject_key_id
       AND subject_unique.evidence_receipt_id = personhood.evidence_receipt_id
       AND subject_unique.claim_id = 'credential.subject_unique'
       AND subject_unique.assertion_value = '{"subject_unique": true}'::jsonb
       AND subject_unique.assurance = 'provider_attested'
      JOIN evidence_receipts receipt
        ON receipt.evidence_receipt_id = personhood.evidence_receipt_id
       AND receipt.user_id = NEW.account_id
       AND receipt.subject_key_id = subject.subject_key_id
       AND receipt.subject_binding_event_id = active_binding.binding_event_id
       AND receipt.subject_binding_epoch = active_binding.binding_epoch
       AND receipt.provider_id = 'very.web'
       AND receipt.issuer = 'https://verify.very.org'
       AND receipt.method = 'palm_web'
       AND receipt.scope_kind = 'issuer_rp_scope'
       AND receipt.issuer_rp_scope = 'pirate-social'
       AND receipt.issuer_rp_action_scope IS NULL
       AND receipt.protocol_version = 'very-web-v1'
       AND receipt.evidence_kind = 'very.web.server-verified.v1'
       AND receipt.provenance_kind = 'proof_session'
      JOIN proof_sessions session
        ON session.proof_session_id = receipt.proof_session_id
       AND session.actor_id = NEW.account_id
       AND session.status = 'completed'
       AND session.completed_at = session.terminal_at
       AND session.provider_id = receipt.provider_id
       AND session.issuer = receipt.issuer
       AND session.method = receipt.method
       AND session.scope_kind = receipt.scope_kind
       AND session.issuer_rp_scope = receipt.issuer_rp_scope
       AND session.issuer_rp_action_scope IS NOT DISTINCT FROM receipt.issuer_rp_action_scope
       AND session.protocol_version = receipt.protocol_version
       AND session.requested_requirements =
         '[{"claim_id":"credential.subject_unique"},{"claim_id":"human.personhood"}]'::jsonb
       AND session.requested_claim_ids =
         '["credential.subject_unique","human.personhood"]'::jsonb
     WHERE subject.issuer = 'https://verify.very.org'
       AND subject.method = 'palm_web'
       AND subject.scope_kind = 'issuer_rp_scope'
       AND subject.issuer_rp_scope = 'pirate-social'
       AND subject.issuer_rp_action_scope IS NULL
       AND (receipt.expires_at IS NULL OR receipt.expires_at > decided_at + interval '5 seconds')
       AND (personhood.expires_at IS NULL OR personhood.expires_at > decided_at + interval '5 seconds')
       AND (subject_unique.expires_at IS NULL OR subject_unique.expires_at > decided_at + interval '5 seconds')
       AND COALESCE((
         SELECT revalidation.outcome
           FROM assertion_revalidation_events revalidation
          WHERE revalidation.assertion_id = personhood.assertion_id
          ORDER BY revalidation.observed_at DESC,
                   revalidation.assertion_revalidation_event_id DESC LIMIT 1
       ), 'accepted') = 'accepted'
       AND COALESCE((
         SELECT revalidation.outcome
           FROM assertion_revalidation_events revalidation
          WHERE revalidation.assertion_id = subject_unique.assertion_id
          ORDER BY revalidation.observed_at DESC,
                   revalidation.assertion_revalidation_event_id DESC LIMIT 1
       ), 'accepted') = 'accepted'
     ORDER BY subject.subject_key_id, receipt.observed_at DESC, receipt.evidence_receipt_id DESC
  )
  SELECT exact_evidence.*, count(*) OVER () AS evidence_count
    INTO evidence
    FROM exact_evidence
   ORDER BY exact_evidence.observed_at DESC, exact_evidence.subject_key_id
   LIMIT 1;

  IF evidence.subject_key_id IS NULL THEN
    IF EXISTS (
      SELECT 1
        FROM subject_keys subject
        JOIN active_subject_key_bindings active_binding
          ON active_binding.subject_key_id = subject.subject_key_id
         AND active_binding.user_id = NEW.account_id
        JOIN assertions personhood
          ON personhood.subject_key_id = subject.subject_key_id
         AND personhood.user_id = NEW.account_id
         AND personhood.claim_id = 'human.personhood'
         AND personhood.assertion_value = '{"personhood": true}'::jsonb
        JOIN assertions subject_unique
          ON subject_unique.binding_group_id = personhood.binding_group_id
         AND subject_unique.evidence_receipt_id = personhood.evidence_receipt_id
         AND subject_unique.subject_key_id = subject.subject_key_id
         AND subject_unique.user_id = NEW.account_id
         AND subject_unique.claim_id = 'credential.subject_unique'
         AND subject_unique.assertion_value = '{"subject_unique": true}'::jsonb
       WHERE subject.issuer = 'https://verify.very.org'
         AND subject.method = 'palm_web'
         AND subject.scope_kind = 'issuer_rp_scope'
         AND subject.issuer_rp_scope = 'pirate-social'
    ) THEN
      reason := 'verification_stale';
      decision_outcome := 'needs_evidence';
    ELSIF EXISTS (
      SELECT 1
        FROM subject_keys subject
        JOIN active_subject_key_bindings active_binding
          ON active_binding.subject_key_id = subject.subject_key_id
         AND active_binding.user_id = NEW.account_id
       WHERE subject.issuer = 'https://verify.very.org'
         AND subject.method = 'palm_web'
         AND subject.scope_kind = 'issuer_rp_scope'
         AND subject.issuer_rp_scope = 'pirate-social'
    ) THEN
      reason := 'verification_failed';
      decision_outcome := 'fail';
    ELSE
      reason := 'verification_missing';
      decision_outcome := 'needs_evidence';
    END IF;

    INSERT INTO decision_records (
      decision_record_id,community_id,user_id,policy_version_id,policy_hash,
      evaluation_mode,outcome,winning_witness,trace,indeterminate_reason,request_id,created_at
    ) VALUES (
      decision_id,candidate.community_id,NEW.account_id,candidate.reward_policy_version_id,
      candidate.policy_hash,'enforce',decision_outcome,'[]'::jsonb,
      jsonb_build_array(jsonb_build_object('reason',reason)),reason,
      'pool-share:' || identity_digest,decided_at
    );
    INSERT INTO reward_eligibility_decisions (
      eligibility_decision_id,leg_id,account_id,persona_id,purpose,qualification_id,
      drawing_id,decision_record_id,outcome,reason,policy_version,evidence_hash,
      decided_at,expires_at
    ) VALUES (
      eligibility_id,candidate.leg_id,NEW.account_id,NEW.persona_id,'pool_share',
      NEW.qualification_id,candidate.drawing_id,decision_id,'ineligible',reason,
      candidate.reward_policy_version_id,candidate.policy_hash,decided_at,
      candidate.entry_cutoff_at
    );
    RETURN NEW;
  END IF;

  IF evidence.evidence_count <> 1 THEN
    reason := 'verification_failed';
  ELSE
    PERFORM 1 FROM subject_keys
     WHERE subject_key_id = evidence.subject_key_id FOR UPDATE;
    SELECT * INTO existing_consumption
      FROM reward_subject_consumptions
     WHERE campaign_id = candidate.offer_id
       AND subject_key_id = evidence.subject_key_id
     FOR UPDATE;
    IF existing_consumption.reward_subject_consumption_id IS NULL THEN
      INSERT INTO reward_subject_consumptions (
        reward_subject_consumption_id,campaign_id,subject_key_id,user_id,
        binding_event_id,binding_epoch,evidence_receipt_id,consumed_at,created_at
      ) VALUES (
        consumption_id,candidate.offer_id,evidence.subject_key_id,NEW.account_id,
        evidence.binding_event_id,evidence.binding_epoch,evidence.evidence_receipt_id,
        decided_at,decided_at
      );
    ELSIF existing_consumption.user_id <> NEW.account_id THEN
      reason := 'subject_already_consumed';
    END IF;
  END IF;

  IF reason IS NOT NULL THEN
    INSERT INTO decision_records (
      decision_record_id,community_id,user_id,policy_version_id,policy_hash,
      evaluation_mode,outcome,winning_witness,trace,indeterminate_reason,request_id,created_at
    ) VALUES (
      decision_id,candidate.community_id,NEW.account_id,candidate.reward_policy_version_id,
      candidate.policy_hash,'enforce','fail','[]'::jsonb,
      jsonb_build_array(jsonb_build_object('reason',reason)),reason,
      'pool-share:' || identity_digest,decided_at
    );
    INSERT INTO reward_eligibility_decisions (
      eligibility_decision_id,leg_id,account_id,persona_id,purpose,qualification_id,
      drawing_id,decision_record_id,outcome,reason,policy_version,evidence_hash,
      decided_at,expires_at
    ) VALUES (
      eligibility_id,candidate.leg_id,NEW.account_id,NEW.persona_id,'pool_share',
      NEW.qualification_id,candidate.drawing_id,decision_id,'ineligible',reason,
      candidate.reward_policy_version_id,evidence.evidence_hash,decided_at,
      candidate.entry_cutoff_at
    );
    RETURN NEW;
  END IF;

  INSERT INTO decision_records (
    decision_record_id,community_id,user_id,policy_version_id,policy_hash,
    evaluation_mode,outcome,winning_witness,trace,request_id,created_at
  ) VALUES (
    decision_id,candidate.community_id,NEW.account_id,candidate.reward_policy_version_id,
    candidate.policy_hash,'enforce','pass',
    jsonb_build_array(jsonb_build_object(
      'subject_key_id',evidence.subject_key_id,
      'evidence_receipt_id',evidence.evidence_receipt_id
    )),jsonb_build_array(jsonb_build_object('result','eligible')),
    'pool-share:' || identity_digest,decided_at
  );
  INSERT INTO reward_eligibility_decisions (
    eligibility_decision_id,leg_id,account_id,persona_id,purpose,qualification_id,
    drawing_id,decision_record_id,outcome,policy_version,evidence_hash,decided_at,expires_at
  ) VALUES (
    eligibility_id,candidate.leg_id,NEW.account_id,NEW.persona_id,'pool_share',
    NEW.qualification_id,candidate.drawing_id,decision_id,'eligible',
    candidate.reward_policy_version_id,evidence.evidence_hash,decided_at,
    evidence.evidence_expires_at
  );
  INSERT INTO megapot_pool_shares (
    pool_leg_id,drawing_id,account_id,persona_id,qualification_id,
    eligibility_decision_id,qualified_at
  ) VALUES (
    candidate.leg_id,candidate.drawing_id,NEW.account_id,NEW.persona_id,
    NEW.qualification_id,eligibility_id,NEW.qualified_at
  ) ON CONFLICT (account_id,pool_leg_id,drawing_id) DO NOTHING;
  RETURN NEW;
END
$$;

CREATE FUNCTION promote_operator_managed_route_from_hns_candidate_v1(input_receipt_id text, input_operation_id text, input_operator_principal_id text, input_operator_authority_grant_id text, input_idempotency_key text, input_request_hash text, input_community_id text, input_route_binding_id text, input_operator_route_activation_id text, input_evidence_ref text, input_candidate_bytes bytea) RETURNS TABLE(outcome text, receipt_id text, evidence_ref text, route_binding_id text, binding_generation bigint, app_host_activation_generation bigint)
    LANGUAGE plpgsql
    AS $_$
DECLARE
  database_now TIMESTAMPTZ := clock_timestamp();
  candidate JSONB;
  dns_artifact JSONB;
  app_artifact JSONB;
  health_artifact JSONB;
  inventory_artifact JSONB;
  evidence_artifact JSONB;
  dns_document JSONB;
  app_document JSONB;
  health_document JSONB;
  observer_evidence JSONB;
  dns_artifact_bytes BYTEA;
  app_artifact_bytes BYTEA;
  health_artifact_bytes BYTEA;
  inventory_artifact_bytes BYTEA;
  evidence_artifact_bytes BYTEA;
  candidate_digest TEXT;
  evidence_digest TEXT;
  candidate_root TEXT;
  candidate_dns_generation BIGINT;
  candidate_app_generation BIGINT;
  candidate_health_generation BIGINT;
  evidence_expiry TIMESTAMPTZ;
  retained_receipt hns_operator_control_promotion_receipts%ROWTYPE;
  authority_grant platform_operator_route_authority_grants%ROWTYPE;
  activation operator_managed_route_activations%ROWTYPE;
  binding community_canonical_route_bindings%ROWTYPE;
  dns_current hns_dns_zone_activation_current%ROWTYPE;
  dns_revision hns_dns_zone_activation_revisions%ROWTYPE;
  app_current hns_community_app_host_activation_current%ROWTYPE;
  app_revision hns_community_app_host_activation_revisions%ROWTYPE;
  health hns_dns_zone_health_observations%ROWTYPE;
  inventory hns_authority_inventories%ROWTYPE;
  app_refresh RECORD;
BEGIN
  SELECT * INTO retained_receipt
    FROM hns_operator_control_promotion_receipts
   WHERE operator_principal_id = input_operator_principal_id
     AND idempotency_key = input_idempotency_key;
  IF retained_receipt.receipt_id IS NOT NULL THEN
    IF retained_receipt.receipt_id <> input_receipt_id
      OR retained_receipt.operation_id <> input_operation_id
      OR retained_receipt.operator_authority_grant_id <> input_operator_authority_grant_id
      OR retained_receipt.request_hash <> input_request_hash
      OR retained_receipt.community_id <> input_community_id
      OR retained_receipt.route_binding_id <> input_route_binding_id
      OR retained_receipt.operator_route_activation_id <> input_operator_route_activation_id
      OR retained_receipt.evidence_ref <> input_evidence_ref
      OR retained_receipt.candidate_bytes <> input_candidate_bytes THEN
      RAISE EXCEPTION 'HNS operator control promotion idempotency conflict';
    END IF;
    RETURN QUERY SELECT
      'replayed'::TEXT,
      retained_receipt.receipt_id,
      retained_receipt.evidence_ref,
      retained_receipt.route_binding_id,
      retained_receipt.promoted_binding_generation,
      retained_receipt.promoted_app_host_activation_generation;
    RETURN;
  END IF;

  IF NOT is_hns_host_persistence_identity(input_receipt_id, 256)
    OR NOT is_hns_host_persistence_identity(input_operation_id, 256)
    OR NOT is_hns_host_persistence_identity(input_operator_principal_id, 512)
    OR NOT is_hns_host_persistence_identity(input_idempotency_key, 512)
    OR input_request_hash !~ '^[0-9a-f]{64}$'
    OR NOT is_hns_host_persistence_identity(input_evidence_ref, 512)
    OR input_candidate_bytes IS NULL
    OR octet_length(input_candidate_bytes) NOT BETWEEN 1 AND 1048576 THEN
    RAISE EXCEPTION 'HNS operator control promotion input is invalid';
  END IF;

  candidate_digest := encode(sha256(input_candidate_bytes), 'hex');
  BEGIN
    candidate := convert_from(input_candidate_bytes, 'UTF8')::jsonb;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'HNS operator control promotion candidate is invalid';
  END;
  IF jsonb_typeof(candidate) <> 'object'
    OR candidate ->> 'version' <> 'pirate-hns-authority-successor-candidate-v1'
    OR candidate ->> 'source_commit' !~ '^[0-9a-f]{40}$'
    OR candidate ->> 'root_label' IS NULL
    OR candidate ->> 'observed_at' IS NULL
    OR (candidate ->> 'observed_at')::TIMESTAMPTZ > database_now
    OR jsonb_typeof(candidate -> 'generations') <> 'object'
    OR (candidate -> 'generations' ->> 'dns_activation_generation') !~ '^[1-9][0-9]*$'
    OR (candidate -> 'generations' ->> 'app_host_activation_generation') !~ '^[1-9][0-9]*$'
    OR (candidate -> 'generations' ->> 'health_generation') !~ '^[1-9][0-9]*$'
    OR jsonb_typeof(candidate -> 'artifacts') <> 'array'
    OR jsonb_array_length(candidate -> 'artifacts') <> 5
    OR (SELECT count(DISTINCT artifact ->> 'name')
          FROM jsonb_array_elements(candidate -> 'artifacts') AS artifact) <> 5
    OR EXISTS (
      SELECT 1
        FROM jsonb_array_elements(candidate -> 'artifacts') AS artifact
       WHERE artifact ->> 'name' NOT IN (
         'authority_inventory',
         'dns_zone_activation',
         'app_host_activation',
         'health_observation',
         'observer_evidence'
       )
          OR artifact ->> 'sha256' !~ '^[0-9a-f]{64}$'
          OR artifact ->> 'bytes_hex' !~ '^([0-9a-f]{2})+$'
          OR encode(sha256(decode(artifact ->> 'bytes_hex', 'hex')), 'hex')
             <> artifact ->> 'sha256'
    ) THEN
    RAISE EXCEPTION 'HNS operator control promotion candidate is invalid';
  END IF;

  SELECT artifact INTO inventory_artifact
    FROM jsonb_array_elements(candidate -> 'artifacts') AS artifact
   WHERE artifact ->> 'name' = 'authority_inventory';
  SELECT artifact INTO dns_artifact
    FROM jsonb_array_elements(candidate -> 'artifacts') AS artifact
   WHERE artifact ->> 'name' = 'dns_zone_activation';
  SELECT artifact INTO app_artifact
    FROM jsonb_array_elements(candidate -> 'artifacts') AS artifact
   WHERE artifact ->> 'name' = 'app_host_activation';
  SELECT artifact INTO health_artifact
    FROM jsonb_array_elements(candidate -> 'artifacts') AS artifact
   WHERE artifact ->> 'name' = 'health_observation';
  SELECT artifact INTO evidence_artifact
    FROM jsonb_array_elements(candidate -> 'artifacts') AS artifact
   WHERE artifact ->> 'name' = 'observer_evidence';
  inventory_artifact_bytes := decode(inventory_artifact ->> 'bytes_hex', 'hex');
  dns_artifact_bytes := decode(dns_artifact ->> 'bytes_hex', 'hex');
  app_artifact_bytes := decode(app_artifact ->> 'bytes_hex', 'hex');
  health_artifact_bytes := decode(health_artifact ->> 'bytes_hex', 'hex');
  evidence_artifact_bytes := decode(evidence_artifact ->> 'bytes_hex', 'hex');
  evidence_digest := evidence_artifact ->> 'sha256';
  BEGIN
    dns_document := convert_from(dns_artifact_bytes, 'UTF8')::jsonb;
    app_document := convert_from(app_artifact_bytes, 'UTF8')::jsonb;
    health_document := convert_from(health_artifact_bytes, 'UTF8')::jsonb;
    observer_evidence := convert_from(evidence_artifact_bytes, 'UTF8')::jsonb;
  EXCEPTION WHEN OTHERS THEN
    RAISE EXCEPTION 'HNS operator control promotion artifact is invalid';
  END;

  candidate_root := candidate ->> 'root_label';
  candidate_dns_generation :=
    (candidate -> 'generations' ->> 'dns_activation_generation')::BIGINT;
  candidate_app_generation :=
    (candidate -> 'generations' ->> 'app_host_activation_generation')::BIGINT;
  candidate_health_generation :=
    (candidate -> 'generations' ->> 'health_generation')::BIGINT;

  IF dns_document ->> 'version' <> 'pirate-hns-dns-zone-persistence-document-v1'
    OR app_document ->> 'version' <> 'pirate-hns-app-host-transition-document-v1'
    OR health_document ->> 'version' <> 'pirate-hns-dns-health-document-v1'
    OR observer_evidence ->> 'version'
       <> 'pirate-hns-authority-detached-observer-evidence-v1'
    OR observer_evidence ->> 'status' <> 'verified'
    OR observer_evidence ->> 'root_label' <> candidate_root
    OR observer_evidence ->> 'root_exists' <> 'true'
    OR observer_evidence ->> 'root_control_verified' <> 'true'
    OR observer_evidence ->> 'expiry_horizon_sufficient' <> 'true'
    OR observer_evidence ->> 'chain_authority_digest'
       <> candidate ->> 'chain_authority_digest'
    OR observer_evidence ->> 'chain_anchor_height' <> candidate ->> 'chain_height'
    OR dns_document ->> 'canonical_root' <> candidate_root
    OR dns_document ->> 'stable_chain_delegation_snapshot_reference'
       <> observer_evidence ->> 'evidence_reference'
    OR dns_document ->> 'stable_chain_delegation_snapshot_digest'
       <> observer_evidence ->> 'chain_authority_digest'
    OR (dns_document ->> 'dns_authority_generation')::BIGINT
       <> candidate_dns_generation
    OR (app_document ->> 'expected_activation_generation')::BIGINT + 1
       <> candidate_app_generation
    OR app_document ->> 'target_status' <> 'active'
    OR (health_document ->> 'activation_generation')::BIGINT
       <> candidate_dns_generation
    OR (health_document ->> 'expected_health_generation')::BIGINT + 1
       <> candidate_health_generation
    OR health_document ->> 'delegation_matches' <> 'true'
    OR health_document ->> 'ds_authenticates_zone' <> 'true'
    OR health_document ->> 'retained_zone_digest_matches' <> 'true'
    OR health_document ->> 'gateway_healthy' <> 'true' THEN
    RAISE EXCEPTION 'HNS operator control promotion artifact semantics mismatch';
  END IF;

  SELECT * INTO authority_grant
    FROM platform_operator_route_authority_grants
   WHERE grant_id = input_operator_authority_grant_id
   FOR SHARE;
  IF authority_grant.grant_id IS NULL
    OR authority_grant.operator_principal_id <> input_operator_principal_id
    OR authority_grant.authority <> 'manage_operator_routes'
    OR authority_grant.status <> 'active' THEN
    RAISE EXCEPTION 'HNS operator control promotion authority is unavailable';
  END IF;

  SELECT * INTO activation
    FROM operator_managed_route_activations
   WHERE operator_route_activation_id = input_operator_route_activation_id
   FOR UPDATE;
  SELECT * INTO binding
    FROM community_canonical_route_bindings AS selected_binding
   WHERE selected_binding.route_binding_id = input_route_binding_id
   FOR UPDATE;
  IF activation.operator_route_activation_id IS NULL
    OR activation.status <> 'active'
    OR activation.operator_principal_id <> input_operator_principal_id
    OR activation.operator_authority_grant_id <> input_operator_authority_grant_id
    OR activation.community_id <> input_community_id
    OR activation.route_binding_id <> input_route_binding_id
    OR activation.canonical_root <> candidate_root
    OR binding.route_binding_id IS NULL
    OR binding.community_id <> input_community_id
    OR binding.family <> 'hns'
    OR binding.root_label <> candidate_root
    OR binding.route_authority_kind <> 'operator_managed_route_v1'
    OR binding.authority_reference <> input_operator_route_activation_id
    OR binding.authority_generation <> activation.operator_route_activation_generation
    OR binding.route_lifecycle_status <> 'active'
    OR binding.verified_evidence_ref IS NOT NULL THEN
    RAISE EXCEPTION 'HNS operator control promotion route fence does not match';
  END IF;

  SELECT * INTO dns_current
    FROM hns_dns_zone_activation_current
   WHERE dns_zone_activation_id = dns_document ->> 'dns_zone_activation_id'
     AND canonical_root = candidate_root
   FOR SHARE;
  SELECT * INTO dns_revision
    FROM hns_dns_zone_activation_revisions
   WHERE dns_zone_activation_id = dns_current.dns_zone_activation_id
     AND dns_zone_activation_generation = dns_current.current_generation
   FOR SHARE;
  SELECT * INTO inventory
    FROM hns_authority_inventories
   WHERE authority_inventory_reference =
         dns_revision.pirate_dns_authority_inventory_reference
     AND authority_inventory_version =
         dns_revision.pirate_dns_authority_inventory_version
     AND authority_inventory_digest =
         dns_revision.pirate_dns_authority_inventory_digest
   FOR SHARE;
  SELECT * INTO health
    FROM hns_dns_zone_health_observations
   WHERE dns_zone_activation_id = dns_current.dns_zone_activation_id
     AND activation_generation = dns_current.current_generation
   ORDER BY health_generation DESC
   LIMIT 1
   FOR SHARE;
  SELECT * INTO app_current
    FROM hns_community_app_host_activation_current
   WHERE normalized_host = 'app.' || candidate_root
     AND community_id = input_community_id
   FOR UPDATE;
  SELECT * INTO app_revision
    FROM hns_community_app_host_activation_revisions AS selected_app_revision
   WHERE selected_app_revision.app_host_activation_id = app_current.app_host_activation_id
     AND selected_app_revision.app_host_activation_generation = app_current.current_generation
   FOR SHARE;

  IF dns_current.dns_zone_activation_id IS NULL
    OR dns_current.current_generation <> candidate_dns_generation
    OR dns_revision.status <> 'active'
    OR dns_revision.activation_document_bytes
       <> decode(dns_document ->> 'activation_document_bytes_hex', 'hex')
    OR dns_revision.zone_bytes <> decode(dns_document ->> 'zone_bytes_hex', 'hex')
    OR dns_revision.zone_bytes_digest <> dns_document ->> 'zone_bytes_digest'
    OR dns_revision.stable_chain_delegation_snapshot_reference
       <> observer_evidence ->> 'evidence_reference'
    OR dns_revision.stable_chain_delegation_snapshot_digest
       <> observer_evidence ->> 'chain_authority_digest'
    OR inventory.inventory_bytes <> inventory_artifact_bytes
    OR inventory.expires_at <= database_now
    OR health.health_generation <> candidate_health_generation
    OR health.valid_until <= database_now
    OR health.observed_zone_bytes_digest <> dns_revision.zone_bytes_digest
    OR health.observed_dnssec_keyset_reference <> dns_revision.dnssec_keyset_reference
    OR health.observed_dnssec_keyset_version <> dns_revision.dnssec_keyset_version
    OR health.observed_gateway_deployment_reference
       <> dns_revision.gateway_deployment_reference
    OR health.observed_gateway_certificate_spki_sha256
       <> dns_revision.gateway_certificate_spki_sha256
    OR NOT health.delegation_matches
    OR NOT health.ds_authenticates_zone
    OR NOT health.retained_zone_digest_matches
    OR NOT health.gateway_healthy
    OR app_current.app_host_activation_id IS NULL
    OR app_current.current_generation <> candidate_app_generation
    OR app_revision.status <> 'active'
    OR app_revision.dns_zone_activation_id <> dns_current.dns_zone_activation_id
    OR app_revision.dns_zone_activation_generation <> dns_current.current_generation
    OR app_revision.gateway_deployment_reference <> dns_revision.gateway_deployment_reference THEN
    RAISE EXCEPTION 'HNS operator control promotion current authority mismatch';
  END IF;

  evidence_expiry := LEAST(inventory.expires_at, health.valid_until);
  IF evidence_expiry <= database_now THEN
    RAISE EXCEPTION 'HNS operator control promotion evidence is expired';
  END IF;

  INSERT INTO hns_operator_control_promotion_receipts (
    receipt_id,
    operation_id,
    operator_principal_id,
    operator_authority_grant_id,
    idempotency_key,
    request_hash,
    community_id,
    route_binding_id,
    operator_route_activation_id,
    canonical_root,
    candidate_sha256,
    candidate_bytes,
    observer_evidence_sha256,
    observer_evidence_reference,
    dns_zone_activation_id,
    dns_zone_activation_generation,
    app_host_activation_id,
    prior_app_host_activation_generation,
    promoted_app_host_activation_generation,
    promoted_binding_generation,
    evidence_ref,
    verified_at,
    expires_at,
    committed_at
  ) VALUES (
    input_receipt_id,
    input_operation_id,
    input_operator_principal_id,
    input_operator_authority_grant_id,
    input_idempotency_key,
    input_request_hash,
    input_community_id,
    input_route_binding_id,
    input_operator_route_activation_id,
    candidate_root,
    candidate_digest,
    input_candidate_bytes,
    evidence_digest,
    observer_evidence ->> 'evidence_reference',
    dns_current.dns_zone_activation_id,
    dns_current.current_generation,
    app_current.app_host_activation_id,
    app_current.current_generation,
    app_current.current_generation + 1,
    binding.binding_generation + 1,
    input_evidence_ref,
    database_now,
    evidence_expiry,
    database_now
  );

  INSERT INTO community_route_ownership_evidence (
    evidence_ref,
    creation_ceremony_intent_id,
    verified_by_actor_id,
    family,
    root_label,
    root_label_display,
    path_segment,
    requirement_hash,
    provider_id,
    provider_binding_hash,
    provider_configuration_version,
    provider_identity_digest,
    evidence_digest,
    evidence_receipt_id,
    binding_generation,
    verified_at,
    expires_at,
    created_at,
    origin,
    route_revalidation_attempt_id,
    route_attachment_ceremony_intent_id,
    operator_control_promotion_receipt_id
  ) VALUES (
    input_evidence_ref,
    NULL,
    NULL,
    'hns',
    candidate_root,
    binding.root_label_display,
    binding.path_segment,
    observer_evidence ->> 'expected_txt_value_sha256',
    observer_evidence ->> 'provider_id',
    observer_evidence ->> 'provider_configuration_digest',
    observer_evidence ->> 'provider_configuration_version',
    observer_evidence ->> 'control_identity_digest',
    evidence_digest,
    NULL,
    binding.binding_generation + 1,
    database_now,
    evidence_expiry,
    database_now,
    'operator_control_observation',
    NULL,
    NULL,
    input_receipt_id
  );

  UPDATE operator_managed_route_activations
     SET status = 'revoked',
         reason_code = 'promoted-to-verified',
         revoked_at = database_now,
         operator_route_activation_generation = operator_route_activation_generation + 1
   WHERE operator_route_activation_id = input_operator_route_activation_id;

  UPDATE community_canonical_route_bindings AS promoted_binding
     SET route_authority_kind = 'verified_namespace_v1',
         authority_reference = NULL,
         authority_generation = NULL,
         ownership_status = 'verified',
         verified_evidence_ref = input_evidence_ref,
         binding_generation = promoted_binding.binding_generation + 1,
         updated_at = database_now
   WHERE promoted_binding.route_binding_id = input_route_binding_id;

  SELECT * INTO app_refresh
    FROM change_hns_community_app_host_status_v1(
      'hns-root-promotion:app:' || candidate_digest,
      'hns-root-promotion:app:' || candidate_digest,
      candidate_digest,
      app_current.app_host_activation_id,
      app_current.current_generation,
      'active',
      'verified-authority-promotion'
    );
  IF app_refresh.outcome NOT IN ('changed', 'replayed')
    OR app_refresh.app_host_activation_generation <> app_current.current_generation + 1 THEN
    RAISE EXCEPTION 'HNS operator control promotion app-host refresh failed';
  END IF;

  INSERT INTO community_route_operator_override_audit (
    override_audit_id,
    community_id,
    operator_principal_id,
    action_kind,
    reason,
    request_hash,
    occurred_at
  ) VALUES (
    input_operation_id,
    input_community_id,
    input_operator_principal_id,
    'operator_route_promoted',
    'reviewed-authority-candidate',
    input_request_hash,
    database_now
  );

  RETURN QUERY SELECT
    'promoted'::TEXT,
    input_receipt_id,
    input_evidence_ref,
    input_route_binding_id,
    binding.binding_generation + 1,
    app_current.current_generation + 1;
END;
$_$;

CREATE FUNCTION provision_first_persona_for_new_account() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
DECLARE
  first_persona_id TEXT := 'persona_' || replace(gen_random_uuid()::text, '-', '');
  first_assignment_id TEXT := 'persona_wallet_' || replace(gen_random_uuid()::text, '-', '');
  handle_label TEXT := lower(NEW.account #>> '{global_handle,label_display}');
BEGIN
  IF NEW.status <> 'active' THEN RETURN NEW; END IF;
  INSERT INTO personas (
    persona_id, account_id, status, is_first_persona, created_at, retired_at
  ) VALUES (first_persona_id, NEW.user_id, 'pending_wallet', true, NEW.created_at, NULL);
  INSERT INTO persona_pending_profiles (
    persona_id, display_name, avatar_ref, cover_ref, bio, preferred_locale, created_at
  ) VALUES (
    first_persona_id,
    NEW.account #>> '{profile,display_name}', NEW.account #>> '{profile,avatar_ref}',
    NEW.account #>> '{profile,cover_ref}', NEW.account #>> '{profile,bio}',
    NEW.account #>> '{profile,preferred_locale}', NEW.created_at
  );
  INSERT INTO persona_wallet_assignments (
    assignment_id, persona_id, account_id, chain_account_kind, privy_wallet_id,
    hd_wallet_index, address, status, reservation_idempotency_key,
    assigned_at, tombstoned_at, created_at, updated_at
  ) VALUES (
    first_assignment_id, first_persona_id, NEW.user_id, 'evm', NULL,
    0, NULL, 'pending', 'first-persona-wallet-onboarding',
    NULL, NULL, NEW.created_at, NEW.created_at
  );
  IF handle_label IS NOT NULL
     AND NEW.account #>> '{global_handle,global_handle_id}' IS NOT NULL THEN
    INSERT INTO persona_pending_first_handles (
      persona_id, handle_id, label_normalized, label_display, created_at
    ) VALUES (
      first_persona_id, NEW.account #>> '{global_handle,global_handle_id}',
      left(handle_label, -length('.pirate')), handle_label, NEW.created_at
    );
  END IF;
  RETURN NEW;
END
$$;

CREATE FUNCTION public_handle_index_validate_redirects() RETURNS trigger
    LANGUAGE plpgsql
    AS $$
BEGIN
  IF NEW.status = 'redirect' AND NOT EXISTS (
    SELECT 1
      FROM public_handle_index AS target
     WHERE target.handle_id = NEW.redirect_target_handle_id
       AND target.status = 'active'
       AND target.owner_user_id = NEW.owner_user_id
       AND target.owner_persona_id = NEW.owner_persona_id
       AND target.platform_handle_id = NEW.platform_handle_id
  ) THEN
    RAISE EXCEPTION 'redirect target must be the direct active label for the same stable identity'
      USING ERRCODE = '23514', CONSTRAINT = 'public_handle_index_redirect_integrity';
  END IF;
  IF NEW.status = 'active' AND EXISTS (
    SELECT 1
      FROM public_handle_index AS source
     WHERE source.redirect_target_handle_id = NEW.handle_id
       AND (
         source.owner_user_id <> NEW.owner_user_id
         OR source.owner_persona_id <> NEW.owner_persona_id
         OR source.platform_handle_id <> NEW.platform_handle_id
       )
  ) THEN
    RAISE EXCEPTION 'active target has a cross-identity redirect'
      USING ERRCODE = '23514', CONSTRAINT = 'public_handle_index_redirect_integrity';
  END IF;
  RETURN NEW;
END;
$$;

CREATE FUNCTION public_persona_projection(expected_persona_id text) RETURNS jsonb
    LANGUAGE sql STABLE
    AS $$
  SELECT jsonb_build_object(
    'persona_id', persona.persona_id,
    'object', 'persona',
    'display_name', profile.display_name,
    'avatar_ref', profile.avatar_ref,
    'primary_public_handle', handle.label_display
  )
    FROM personas AS persona
    JOIN persona_profiles AS profile ON profile.persona_id = persona.persona_id
    LEFT JOIN LATERAL (
      SELECT candidate.label_display
        FROM public_handle_index AS candidate
       WHERE candidate.owner_persona_id = persona.persona_id
         AND candidate.status = 'active'
       ORDER BY candidate.updated_at DESC, candidate.handle_id
       LIMIT 1
    ) AS handle ON true
   WHERE persona.persona_id = expected_persona_id
     AND persona.status = 'active'
$$;

CREATE FUNCTION raise_text_rating_with_descendants_v1(target_community_id text, target_kind text, target_resource_id text, transition_at timestamp with time zone) RETURNS integer
    LANGUAGE plpgsql
    AS $$
DECLARE
  changed_count INTEGER := 0;
  latest_count INTEGER := 0;
BEGIN
  IF target_kind = 'text_post' THEN
    UPDATE posts
       SET content_rating = 'adult_18', updated_at = transition_at
     WHERE community_id = target_community_id
       AND post_id = target_resource_id
       AND post_type = 'text';
    GET DIAGNOSTICS changed_count = ROW_COUNT;
    UPDATE comments
       SET content_rating = 'adult_18', updated_at = transition_at
     WHERE community_id = target_community_id
       AND post_id = target_resource_id
       AND content_rating <> 'adult_18';
    GET DIAGNOSTICS latest_count = ROW_COUNT;
    changed_count := changed_count + latest_count;
  ELSIF target_kind IN ('comment', 'reply') THEN
    WITH RECURSIVE descendants AS (
      SELECT comment_id
        FROM comments
       WHERE community_id = target_community_id
         AND comment_id = target_resource_id
      UNION ALL
      SELECT child.comment_id
        FROM comments AS child
        JOIN descendants AS parent ON parent.comment_id = child.parent_comment_id
       WHERE child.community_id = target_community_id
    )
    UPDATE comments AS comment
       SET content_rating = 'adult_18', updated_at = transition_at
      FROM descendants
     WHERE comment.community_id = target_community_id
       AND comment.comment_id = descendants.comment_id
       AND comment.content_rating <> 'adult_18';
    GET DIAGNOSTICS changed_count = ROW_COUNT;
  ELSE
    RAISE EXCEPTION 'unsupported text rating target kind';
  END IF;

  UPDATE comment_publication_projection AS projection
     SET content_rating = comment.content_rating, updated_at = transition_at
    FROM comments AS comment
   WHERE projection.community_id = target_community_id
     AND comment.community_id = projection.community_id
     AND comment.comment_id = projection.comment_id
     AND projection.content_rating IS DISTINCT FROM comment.content_rating;
  RETURN changed_count;
END;
$$;

CREATE FUNCTION record_hns_dns_zone_health_v1(input_operation_id text, input_idempotency_key text, input_request_hash text, input_dns_zone_activation_id text, input_activation_generation bigint, input_expected_health_generation bigint, input_delegation_snapshot_reference text, input_delegation_snapshot_digest text, input_observed_zone_bytes_digest text, input_observed_dnssec_keyset_reference text, input_observed_dnssec_keyset_version text, input_observed_gateway_deployment_reference text, input_observed_gateway_certificate_spki_sha256 text, input_delegation_matches boolean, input_ds_authenticates_zone boolean, input_retained_zone_digest_matches boolean, input_gateway_healthy boolean, input_valid_for_seconds integer) RETURNS TABLE(outcome text, dns_zone_activation_id text, activation_generation bigint, health_generation bigint)
    LANGUAGE plpgsql
    AS $$
DECLARE
  replay hns_dns_zone_health_operations%ROWTYPE;
  current_record hns_dns_zone_activation_current%ROWTYPE;
  latest_generation BIGINT;
  database_now TIMESTAMPTZ := clock_timestamp();
  new_generation BIGINT := input_expected_health_generation + 1;
BEGIN
  SELECT * INTO replay FROM hns_dns_zone_health_operations AS operation
   WHERE operation.idempotency_key = input_idempotency_key;
  IF FOUND THEN
    IF replay.operation_id <> input_operation_id OR replay.request_hash <> input_request_hash
      OR replay.dns_zone_activation_id <> input_dns_zone_activation_id
      OR replay.activation_generation <> input_activation_generation
      OR replay.expected_health_generation <> input_expected_health_generation THEN
      RAISE EXCEPTION 'HNS DNS health idempotency conflict';
    END IF;
    RETURN QUERY SELECT 'replayed'::TEXT, replay.dns_zone_activation_id,
      replay.activation_generation, replay.result_health_generation;
    RETURN;
  END IF;
  IF input_valid_for_seconds < 1 OR input_valid_for_seconds > 604800 THEN
    RAISE EXCEPTION 'HNS DNS health lifetime is invalid';
  END IF;
  SELECT * INTO current_record FROM hns_dns_zone_activation_current AS current_authority
   WHERE current_authority.dns_zone_activation_id = input_dns_zone_activation_id FOR SHARE;
  IF NOT FOUND OR current_record.current_generation <> input_activation_generation THEN
    RAISE EXCEPTION 'HNS DNS health activation generation is stale';
  END IF;
  SELECT COALESCE(max(observation.health_generation), 0) INTO latest_generation
    FROM hns_dns_zone_health_observations AS observation
   WHERE observation.dns_zone_activation_id = input_dns_zone_activation_id
     AND observation.activation_generation = input_activation_generation;
  IF latest_generation <> input_expected_health_generation THEN
    RAISE EXCEPTION 'HNS DNS health generation fence does not match';
  END IF;
  INSERT INTO hns_dns_zone_health_observations VALUES (
    input_dns_zone_activation_id, input_activation_generation, new_generation,
    input_delegation_snapshot_reference, input_delegation_snapshot_digest,
    input_observed_zone_bytes_digest, input_observed_dnssec_keyset_reference,
    input_observed_dnssec_keyset_version, input_observed_gateway_deployment_reference,
    input_observed_gateway_certificate_spki_sha256, input_delegation_matches,
    input_ds_authenticates_zone, input_retained_zone_digest_matches,
    input_gateway_healthy, database_now,
    database_now + input_valid_for_seconds * INTERVAL '1 second'
  );
  INSERT INTO hns_dns_zone_health_operations VALUES (
    input_operation_id, input_idempotency_key, input_request_hash,
    input_dns_zone_activation_id, input_activation_generation,
    input_expected_health_generation, new_generation, database_now
  );
  RETURN QUERY SELECT 'recorded'::TEXT, input_dns_zone_activation_id,
    input_activation_generation, new_generation;
END;
$$;

