    CONSTRAINT study_review_items_learning_language_check CHECK ((learning_language = 'en'::text)),
    CONSTRAINT study_review_items_lifecycle_status_check CHECK ((lifecycle_status = ANY (ARRAY['active'::text, 'retired'::text]))),
